		public void TestGenerateLocalJobReferenceNumber_ConcurrencyIssue()
		{
			var jobReferenceNumberGenerator = ObjectFactory.Get<IJobReferenceNumberGenerator>();

			var customisationCollection = AccountingConfigurationRegistry.Instance.JobsNumberSequenceCustomisation.Value
				.Cast<TransactionNumberSequenceCustomisation>()
				.OrderBy(x => x.Order);

			var thread = new Thread(() =>
			{
				for (int i = 0; i < 500; i++)
				{
					SimulateGetKey();
				}
			});
			thread.Start();

			for (int i = 0; i < 500; i++)
			{
				jobReferenceNumberGenerator.GenerateLocalJobReferenceNumber(GlbCompany.CurrentCompany.PK, GlbBranch.CurrentBranch.PK, GlbDepartment.CurrentDepartment.PK, Factory);
			}
			Assert("Expect no error during the concurrency test(After the Sort changed to be called at the beginning).", true);

			void SimulateGetKey()
			{
				foreach (TransactionNumberSequenceCustomisation element in customisationCollection)
				{
					Assert(true);
				}
			}
		}

		public void TestGenerateLocalJobReferenceNumberWithCompany()
		{
			var company1 = GlbCompany.CurrentCompany;
			var branch1 = GlbBranch.CurrentBranch;
			var company2 = TestObjectCreator.NonCurrentCompany;
			var branch2 = TestObjectCreator.NonCurrentBranch;
			var department = GlbDepartment.CurrentDepartment;

			var generator = ObjectFactory.Get<IJobReferenceNumberGenerator>();
			var customisationCollection1 = AccountingConfigurationRegistry.Instance.JobsNumberSequenceCustomisation.GetValueWithoutFallback(company1.PK.ToGuid(), Guid.Empty, Guid.Empty);
			customisationCollection1[0].Include = true;
			customisationCollection1[0].Order = 2;
			AccountingConfigurationRegistry.Instance.JobsNumberSequenceCustomisation.SetValue(company1.PK.ToGuid(), Guid.Empty, Guid.Empty, customisationCollection1);
			var customisationCollection2 = AccountingConfigurationRegistry.Instance.JobsNumberSequenceCustomisation.GetValueWithoutFallback(company2.PK.ToGuid(), Guid.Empty, Guid.Empty);
			customisationCollection1[0].Include = false;
			AccountingConfigurationRegistry.Instance.JobsNumberSequenceCustomisation.SetValue(company2.PK.ToGuid(), Guid.Empty, Guid.Empty, customisationCollection2);

			AssertEquals("00000001BNE", generator.GenerateLocalJobReferenceNumber(company1.PK, branch1.PK, department.PK, Factory));
			AssertEquals("00000002BNE", generator.GenerateLocalJobReferenceNumber(company1.PK, branch1.PK, department.PK, Factory));
			AssertEquals("00000003", generator.GenerateLocalJobReferenceNumber(company2.PK, branch2.PK, department.PK, Factory));
		}

		public void TestChargeGroupValidationDoesNotThrowNullReferenceException()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001");
			var job = TestObjectCreator.CreateJob(shipment);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1);
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var jobInNewFactory = newFactory.Load<Job>(job.PK);
			var chargeInNewFactory = newFactory.Load<Charge>(charge.PK);
			AssertNoExceptionThrown(() => jobInNewFactory.HasSameRelatedJobNumberAndSellReferenceNumberMoreThanOnce(chargeInNewFactory));
		}

