		void AssertClosingJobWhenThereAreActiveUnInvoicedCashAdvanceRequests(bool isARCashAdvance, bool isCashAdvanceFunctionalityEnabled)
		{
			using (AccountingConfigurationRegistry.Instance.EnableReceivablesCashAdvanceFunctionality.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, isCashAdvanceFunctionalityEnabled))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001011");
				var job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "", TestObjectCreator.AUD, 100m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 100m, TestObjectCreator.ABIGAS);
				var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, "", TestObjectCreator.AUD, 200m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 200m, TestObjectCreator.ABIGAS);
				Factory.Save();

				var expectedError = "Unable to close job with active Advance Payment.";
				var initialJobStatus = job.JH_Status;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;
				job.OnCloseJobError += new ErrorMessageHandler(job_OnCloseJobError);

				job.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals("Status should be changed - Advance Payment Request is not created yet.", JobHeaderStatus.Closed.Code, job.JH_Status);
				Assert("Error handler should not be called", !IsOnCloseJobErrorEventHandlerCalled);
				AssertNull(LastErrorMessageOnCloseJob);
				job.JH_Status = initialJobStatus;

				if (isARCashAdvance)
				{
					charge1.JR_IsARCashAdvance = true;
					charge2.JR_IsARCashAdvance = true;
				}
				else
				{
					charge1.JR_IsAPCashAdvance = true;
					charge2.JR_IsAPCashAdvance = true;
				}
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals("Status should be changed - Advance Payment Request is not created yet.", JobHeaderStatus.Closed.Code, job.JH_Status);
				Assert("Error handler should not be called", !IsOnCloseJobErrorEventHandlerCalled);
				AssertNull(LastErrorMessageOnCloseJob);
				job.JH_Status = initialJobStatus;

				var ledger = isARCashAdvance ? LedgerTypes.AccountsReceivable : LedgerTypes.AccountsPayable;
				var organization = isARCashAdvance ? TestObjectCreator.ABIGAS : TestObjectCreator.AALSHI;
				var cashAdvanceHeader = TestObjectCreator.CreateCashAdvanceRequestHeader(job.PK, organization.PK, ledger, 300m, 300m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
				var cashAdvanceLine1 = TestObjectCreator.CreateCashAdvanceRequestLine(cashAdvanceHeader.PK, 100m, 100m, CashAdvanceStatusCodes.RequestLine.Requested);
				var cashAdvanceLine2 = TestObjectCreator.CreateCashAdvanceRequestLine(cashAdvanceHeader.PK, 200m, 200m, CashAdvanceStatusCodes.RequestLine.Requested);
				if (isARCashAdvance)
				{
					charge1.JR_CAL_ARLine = cashAdvanceLine1.PK;
					charge2.JR_CAL_ARLine = cashAdvanceLine2.PK;
				}
				else
				{
					charge1.JR_CAL_APLine = cashAdvanceLine1.PK;
					charge2.JR_CAL_APLine = cashAdvanceLine2.PK;
				}
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				if (isCashAdvanceFunctionalityEnabled)
				{
					AssertEquals("Status should not be changed - cashAdvanceHeader is in REQ status.", initialJobStatus, job.JH_Status);
					Assert("Error handler should be called", IsOnCloseJobErrorEventHandlerCalled);
					AssertEquals(expectedError, LastErrorMessageOnCloseJob);
				}
				else
				{
					AssertEquals(JobHeaderStatus.Closed.Code, job.JH_Status);
					Assert(!IsOnCloseJobErrorEventHandlerCalled);
					AssertNull(LastErrorMessageOnCloseJob);
				}

				job.JH_Status = initialJobStatus;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;

				cashAdvanceLine1.CAL_Status = CashAdvanceStatusCodes.RequestLine.Paid;
				cashAdvanceLine1.CAL_LocalPaidAmount = cashAdvanceLine1.CAL_OSPaidAmount = 100m;
				cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.PartiallyPaid;
				cashAdvanceHeader.CAH_LocalPaidAmount = cashAdvanceHeader.CAH_OSPaidAmount = 100m;
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				if (isCashAdvanceFunctionalityEnabled)
				{
					AssertEquals("Status should not be changed - cashAdvanceHeader is in PPA status.", initialJobStatus, job.JH_Status);
					Assert("Error handler should be called", IsOnCloseJobErrorEventHandlerCalled);
					AssertEquals(expectedError, LastErrorMessageOnCloseJob);
				}
				else
				{
					AssertEquals(JobHeaderStatus.Closed.Code, job.JH_Status);
					Assert(!IsOnCloseJobErrorEventHandlerCalled);
					AssertNull(LastErrorMessageOnCloseJob);
				}

				job.JH_Status = initialJobStatus;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;

				cashAdvanceLine2.CAL_Status = CashAdvanceStatusCodes.RequestLine.Paid;
				cashAdvanceLine2.CAL_LocalPaidAmount = cashAdvanceLine2.CAL_OSPaidAmount = 200m;
				cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.Paid;
				cashAdvanceHeader.CAH_LocalPaidAmount = cashAdvanceHeader.CAH_OSPaidAmount = 300m;
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				if (isCashAdvanceFunctionalityEnabled)
				{
					AssertEquals("Status should not be changed - cashAdvanceHeader is in PAI status.", initialJobStatus, job.JH_Status);
					Assert("Error handler should be called", IsOnCloseJobErrorEventHandlerCalled);
					AssertEquals(expectedError, LastErrorMessageOnCloseJob);
				}
				else
				{
					AssertEquals(JobHeaderStatus.Closed.Code, job.JH_Status);
					Assert(!IsOnCloseJobErrorEventHandlerCalled);
					AssertNull(LastErrorMessageOnCloseJob);
				}
				job.JH_Status = initialJobStatus;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;

				cashAdvanceLine1.CAL_Status = CashAdvanceStatusCodes.RequestLine.Invoiced;
				cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.PartiallyInvoiced;
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				if (isCashAdvanceFunctionalityEnabled)
				{
					AssertEquals("Status should not be changed - cashAdvanceHeader is in PIN status.", initialJobStatus, job.JH_Status);
					Assert("Error handler should be called", IsOnCloseJobErrorEventHandlerCalled);
					AssertEquals(expectedError, LastErrorMessageOnCloseJob);
				}
				else
				{
					AssertEquals(JobHeaderStatus.Closed.Code, job.JH_Status);
					Assert(!IsOnCloseJobErrorEventHandlerCalled);
					AssertNull(LastErrorMessageOnCloseJob);
				}
				job.JH_Status = initialJobStatus;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;

				cashAdvanceLine2.CAL_Status = CashAdvanceStatusCodes.RequestLine.Invoiced;
				cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.Invoiced;
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals("Status should be changed - cashAdvanceHeader is in INV status.", JobHeaderStatus.Closed.Code, job.JH_Status);
				Assert("Error handler should not be called", !IsOnCloseJobErrorEventHandlerCalled);
				AssertNull(LastErrorMessageOnCloseJob);
				job.JH_Status = initialJobStatus;
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;

				cashAdvanceLine1.CAL_Status = CashAdvanceStatusCodes.RequestLine.Cancelled;
				cashAdvanceLine1.CAL_LocalPaidAmount = cashAdvanceLine1.CAL_OSPaidAmount = 0m;
				cashAdvanceLine2.CAL_Status = CashAdvanceStatusCodes.RequestLine.Cancelled;
				cashAdvanceLine2.CAL_LocalPaidAmount = cashAdvanceLine2.CAL_OSPaidAmount = 0m;
				cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.Cancelled;
				cashAdvanceHeader.CAH_LocalPaidAmount = cashAdvanceHeader.CAH_OSPaidAmount = 0m;
				Factory.Save();

				job.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals("Status should be changed - cashAdvanceHeader is in CAN status.", JobHeaderStatus.Closed.Code, job.JH_Status);
				Assert("Error handler should not be called", !IsOnCloseJobErrorEventHandlerCalled);
				AssertNull(LastErrorMessageOnCloseJob);
				IsOnCloseJobErrorEventHandlerCalled = false;
				LastErrorMessageOnCloseJob = null;
			}
		}

		public void TestCashAdvanceRequestsAreReloadedBeforeCheckingHasActiveUnInvoicedCashAdvanceRequests()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001011");
			var job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "", TestObjectCreator.AUD, 100m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 100m, TestObjectCreator.ABIGAS);
			Factory.Save();

			var cashAdvanceHeader = TestObjectCreator.CreateCashAdvanceRequestHeader(job.PK, TestObjectCreator.ABIGAS.PK, LedgerTypes.AccountsReceivable, 100m, 100m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
			var cashAdvanceLine1 = TestObjectCreator.CreateCashAdvanceRequestLine(cashAdvanceHeader.PK, 100m, 100m, CashAdvanceStatusCodes.RequestLine.Requested);
			charge1.JR_IsARCashAdvance = true;
			charge1.JR_CAL_ARLine = cashAdvanceLine1.PK;
			Factory.Save();

			Assert(job.HasActiveUnInvoicedCashAdvanceRequests);

			cashAdvanceLine1.CAL_Status = CashAdvanceStatusCodes.RequestLine.Cancelled;
			cashAdvanceHeader.CAH_Status = CashAdvanceStatusCodes.RequestHeader.Cancelled;

			Assert(!job.HasActiveUnInvoicedCashAdvanceRequests);

			var otherFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var jobInOtherFactory = otherFactory.Load<Job>(job.PK);
			var charge2 = TestObjectCreator.CreateCharge(jobInOtherFactory, TestObjectCreator.CC2, "", TestObjectCreator.AUD, 200m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 200m, TestObjectCreator.ABIGAS);
			var cashAdvanceHeader2 = TestObjectCreator.CreateCashAdvanceRequestHeader(jobInOtherFactory.PK, TestObjectCreator.ABIGAS.PK, LedgerTypes.AccountsReceivable, 200m, 200m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested, otherFactory);
			var cashAdvanceLine2 = TestObjectCreator.CreateCashAdvanceRequestLine(cashAdvanceHeader2.PK, 200m, 200m, CashAdvanceStatusCodes.RequestLine.Requested, otherFactory);
			charge2.JR_IsARCashAdvance = true;
			charge2.JR_CAL_ARLine = cashAdvanceLine2.PK;
			otherFactory.Save();

			Assert(jobInOtherFactory.HasActiveUnInvoicedCashAdvanceRequests);
			Assert(job.HasActiveUnInvoicedCashAdvanceRequests);
		}

		public void TestCashAdvanceRequests()
		{
			var job1 = TestObjectCreator.CreateJobHeader();
			var cashAdvanceRequestHeader1 = TestObjectCreator.CreateCashAdvanceRequestHeader(job1.PK, TestObjectCreator.AALSHI.PK, LedgerTypes.AccountsReceivable, 100m, 100m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
			var cashAdvanceRequestHeader2 = TestObjectCreator.CreateCashAdvanceRequestHeader(job1.PK, TestObjectCreator.ABIGAS.PK, LedgerTypes.AccountsPayable, 200m, 200m, TestObjectCreator.USD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);

			var job2 = TestObjectCreator.CreateJobHeader();
			var cashAdvanceRequestHeader3 = TestObjectCreator.CreateCashAdvanceRequestHeader(job2.PK, TestObjectCreator.AALSHI.PK, LedgerTypes.AccountsReceivable, 300m, 300m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
			var cashAdvanceRequestHeader4 = TestObjectCreator.CreateCashAdvanceRequestHeader(job2.PK, TestObjectCreator.ABIGAS.PK, LedgerTypes.AccountsPayable, 400m, 400m, TestObjectCreator.USD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);

			Factory.Save();

			AssertContainsExactElementsInAnyOrder(new[] { cashAdvanceRequestHeader1, cashAdvanceRequestHeader2 }, job1.CashAdvanceRequests);
			AssertContainsExactElementsInAnyOrder(new[] { cashAdvanceRequestHeader3, cashAdvanceRequestHeader4 }, job2.CashAdvanceRequests);
		}

		public void TestResetCashAdvanceRequests()
		{
			var job1 = TestObjectCreator.CreateJobHeader();
			var cashAdvanceRequestHeader1 = TestObjectCreator.CreateCashAdvanceRequestHeader(job1.PK, TestObjectCreator.AALSHI.PK, LedgerTypes.AccountsReceivable, 100m, 100m, TestObjectCreator.AUD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
			Factory.Save();

			AssertContainsExactElementsInAnyOrder(new[] { cashAdvanceRequestHeader1 }, job1.CashAdvanceRequests);

			var cashAdvanceRequestHeader2 = TestObjectCreator.CreateCashAdvanceRequestHeader(job1.PK, TestObjectCreator.ABIGAS.PK, LedgerTypes.AccountsPayable, 200m, 200m, TestObjectCreator.USD.RX_Code, CashAdvanceStatusCodes.RequestHeader.Requested);
			Factory.Save();

			AssertContainsExactElementsInAnyOrder(new[] { cashAdvanceRequestHeader1 }, job1.CashAdvanceRequests);
			job1.ResetCashAdvanceRequests();
			AssertContainsExactElementsInAnyOrder(new[] { cashAdvanceRequestHeader1, cashAdvanceRequestHeader2 }, job1.CashAdvanceRequests);
		}

		public void TestGetShouldJobBeClosedByDsbBatchWithChargeCode()
		{
			using (AccountingConfigurationRegistry.Instance.EnableBulkDisbursementJobsClosure.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var job = TestObjectCreator.CreateJobHeader();
				job.JH_JobNum = "J001";

				//Create non disbursement charges
				var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge1", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction1 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction1.Lines.Add(TestObjectCreator.CreateRevenueLine(charge1, transaction1.PK));

				var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge2", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR002", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction2.Lines.Add(TestObjectCreator.CreateRevenueLine(charge2, transaction2.PK));

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return false as not exist DSB charges", !job.GetShouldJobBeClosedByDsbBatch());

				//Create disbursement charges which are not balanced for different charge codes
				var surplusGLAccount1 = TestObjectCreator.CreateGLHeader("99991001");
				var shortfallGLAccount1 = TestObjectCreator.CreateGLHeader("99991002");

				var costRevenueGLAccount = TestObjectCreator.CreateGLHeader("39991001");

				Factory.Save();

				var chargeCode1 = TestObjectCreator.DSBChargeCode;
				chargeCode1.AC_AG_CostAccount = costRevenueGLAccount.PK;
				chargeCode1.AC_AG_RevenueAccount = costRevenueGLAccount.PK;
				chargeCode1.AC_AG_DisbursementShortfallAccount = shortfallGLAccount1.PK;
				chargeCode1.AC_AG_DisbursementSurplusAccount = surplusGLAccount1.PK;

				var chargeCode2 = TestObjectCreator.DSBChargeCode1;
				chargeCode2.AC_AG_CostAccount = costRevenueGLAccount.PK;
				chargeCode2.AC_AG_RevenueAccount = costRevenueGLAccount.PK;
				chargeCode2.AC_AG_DisbursementShortfallAccount = shortfallGLAccount1.PK;
				chargeCode2.AC_AG_DisbursementSurplusAccount = surplusGLAccount1.PK;

				Factory.Save();

				var charge3 = TestObjectCreator.CreateCharge(job, chargeCode1, 100m, 100m);
				var charge4 = TestObjectCreator.CreateCharge(job, chargeCode2, 100m, 100m);

				var header1 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line11 = TestObjectCreator.CreateCostLine(charge3, header1.PK);
				line11.AL_AG = charge3.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				var header2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line21 = TestObjectCreator.CreateRevenueLine(charge4, header2.PK);
				line21.AL_AG = charge4.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create line related to disbursement charges which are not balanced for one charge code
				var header3 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line31 = TestObjectCreator.CreateRevenueLine(charge3, header3.PK);
				line31.AL_AG = charge3.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create line related to disbursement charges which are balanced
				var header4 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line41 = TestObjectCreator.CreateCostLine(charge4, header4.PK);
				line41.AL_AG = charge4.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are balanced", !job.GetShouldJobBeClosedByDsbBatch());
			}
		}

		public void TestGetShouldJobBeClosedByDsbBatchWithLineGLAccount()
		{
			using (AccountingConfigurationRegistry.Instance.EnableBulkDisbursementJobsClosure.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var job = TestObjectCreator.CreateJobHeader();
				job.JH_JobNum = "J001";

				//Create non disbursement charges
				var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge1", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction1 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction1.Lines.Add(TestObjectCreator.CreateRevenueLine(charge1, transaction1.PK));

				var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge2", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR002", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction2.Lines.Add(TestObjectCreator.CreateRevenueLine(charge2, transaction2.PK));

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return false as not exist DSB charges", !job.GetShouldJobBeClosedByDsbBatch());

				//Create disbursement charges which are not balanced for two Line GL Accounts
				var surplusGLAccount1 = TestObjectCreator.CreateGLHeader("99991001");
				var shortfallGLAccount1 = TestObjectCreator.CreateGLHeader("99991002");

				var costGLAccount1 = TestObjectCreator.CreateGLHeader("39991001");
				var revenueGLAccount1 = TestObjectCreator.CreateGLHeader("39991002");

				Factory.Save();

				var chargeCode1 = TestObjectCreator.DSBChargeCode;
				chargeCode1.AC_AG_CostAccount = costGLAccount1.PK;
				chargeCode1.AC_AG_RevenueAccount = revenueGLAccount1.PK;
				chargeCode1.AC_AG_DisbursementShortfallAccount = shortfallGLAccount1.PK;
				chargeCode1.AC_AG_DisbursementSurplusAccount = surplusGLAccount1.PK;

				Factory.Save();

				var charge1Cst = TestObjectCreator.CreateCharge(job, chargeCode1, 100m, 100m);
				var charge1Rev = TestObjectCreator.CreateCharge(job, chargeCode1, 200m, 200m);

				var header1 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line11 = TestObjectCreator.CreateCostLine(charge1Cst, header1.PK);
				line11.AL_AG = charge1Cst.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				var header2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line21 = TestObjectCreator.CreateRevenueLine(charge1Rev, header2.PK);
				line21.AL_AG = charge1Rev.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create line related to disbursement charges which are not balanced for one Line GL Accounts
				var header3 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line31 = TestObjectCreator.CreateRevenueLine(charge1Cst, header3.PK);
				line31.AL_AG = charge1Rev.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create line related to disbursement charges which are balanced
				var header4 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line41 = TestObjectCreator.CreateCostLine(charge1Rev, header4.PK);
				line41.AL_AG = charge1Rev.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				var chargeForBalance = TestObjectCreator.CreateCharge(job, chargeCode1, -300m, -300m);

				var header5 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line51 = TestObjectCreator.CreateCostLine(chargeForBalance, header5.PK);
				line51.AL_AG = charge1Cst.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				var header6 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line61 = TestObjectCreator.CreateRevenueLine(chargeForBalance, header6.PK);
				line61.AL_AG = charge1Rev.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return false as exist DSB charges which are balanced", !job.GetShouldJobBeClosedByDsbBatch());
			}
		}

