		void AssertGetShouldJobBeClosedByDsbBatchForBranchAndDepartment(bool isTestBranch, bool isTestDepartment)
		{
			Assert("isTestBranch and isTestDepartment should be one to true for each test", isTestBranch ^ isTestDepartment);

			using (AccountingConfigurationRegistry.Instance.EnableBulkDisbursementJobsClosure.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var branch1 = TestObjectCreator.CreateBranch("AAA", GlbCompany.CurrentCompany);
				var branch2 = TestObjectCreator.CreateBranch("BBB", GlbCompany.CurrentCompany);
				var department1 = TestObjectCreator.CreateDepartment("CCC");
				var department2 = TestObjectCreator.CreateDepartment("DDD");

				var job = TestObjectCreator.CreateJobHeader();
				job.JH_JobNum = "J001";

				//Create non disbursement charges
				var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge1", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction1 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR001", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction1.Lines.Add(TestObjectCreator.CreateRevenueLine(charge1, transaction1.PK));

				var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "charge2", TestObjectCreator.AUD, 10m, TestObjectCreator.Creditor1, TestObjectCreator.AUD, 10m, TestObjectCreator.AALSHI);
				var transaction2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR002", TestObjectCreator.AUD, 1m, TestObjectCreator.AALSHI);
				transaction2.Lines.Add(TestObjectCreator.CreateRevenueLine(charge2, transaction2.PK));

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return false as not exist DSB charges", !job.GetShouldJobBeClosedByDsbBatch());

				//Create disbursement charges which are not balanced for two branchs/departments
				var surplusGLAccount1 = TestObjectCreator.CreateGLHeader("99991001");
				var shortfallGLAccount1 = TestObjectCreator.CreateGLHeader("99991002");

				var costRevenueGLAccount = TestObjectCreator.CreateGLHeader("39991001");

				Factory.Save();

				var chargeCode1 = TestObjectCreator.DSBChargeCode;
				chargeCode1.AC_AG_CostAccount = costRevenueGLAccount.PK;
				chargeCode1.AC_AG_RevenueAccount = costRevenueGLAccount.PK;
				chargeCode1.AC_AG_DisbursementShortfallAccount = shortfallGLAccount1.PK;
				chargeCode1.AC_AG_DisbursementSurplusAccount = surplusGLAccount1.PK;

				Factory.Save();

				var charge3 = TestObjectCreator.CreateCharge(job, chargeCode1, 300m, 300m);
				var charge4 = TestObjectCreator.CreateCharge(job, chargeCode1, 400m, 400m);
				if (isTestBranch)
				{
					charge3.JR_GB = branch1.PK;
					charge4.JR_GB = branch2.PK;
				}
				if (isTestDepartment)
				{
					charge3.JR_GE = department1.PK;
					charge4.JR_GE = department2.PK;
				}

				var header1 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line11 = TestObjectCreator.CreateCostLine(charge3, header1.PK);
				line11.AL_AG = charge3.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				var header2 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line21 = TestObjectCreator.CreateRevenueLine(charge4, header2.PK);
				line21.AL_AG = charge4.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create disbursement charges which are not balanced for one branch/department
				var header3 = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
				var line31 = TestObjectCreator.CreateRevenueLine(charge3, header3.PK);
				line31.AL_AG = charge3.ChargeCode.AC_AG_RevenueAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return true as exist DSB charges which are not balanced", job.GetShouldJobBeClosedByDsbBatch());

				//Create disbursement charges which are not balanced for one branch/department
				var header4 = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				var line41 = TestObjectCreator.CreateCostLine(charge4, header4.PK);
				line41.AL_AG = charge4.ChargeCode.AC_AG_CostAccount;

				Factory.Save();

				Assert("GetShouldJobBeClosedByDsbBatch should return false as exist DSB charges which are balanced", !job.GetShouldJobBeClosedByDsbBatch());
			}
		}

		public void TestValidationIsSuspendedWhenJobChargesAreLoaded()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", false);
			var job = TestObjectCreator.CreateJob(shipment, createWithMutex: false);
			Factory.Save();

			TestObjectCreator.CreateCharge(job);
			var testJob = Factory.Load<TestJobClass>(job.PK);
			Assert("preCond: validation is not suspended", !Factory.IsValidationSuspended);

			Factory.RowsLoaded += Factory_RowsLoaded;
			AssertEquals("Load job charges", 1, testJob.Charges.Count);
			Factory.RowsLoaded -= Factory_RowsLoaded;

			Assert("validation is not suspended anymore", !Factory.IsValidationSuspended);

			void Factory_RowsLoaded(object sender, RowsLoadedEventArgs e)
			{
				if (e.TableOrViewName == JobChargeSchema.Constants.TableName)
				{
					Assert("Validation is suspended when job charges are loaded", Factory.IsValidationSuspended);
				}
			}
		}

		public void TestRefreshCharges()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", false);
			var job = TestObjectCreator.CreateJob(shipment, createWithMutex: false);
			Factory.Save();

			TestObjectCreator.CreateCharge(job);

			var testJob = Factory.Load<TestJobClass>(job.PK);
			AssertEquals("Precondition: job.Charges.Count", 1, testJob.Charges.Count);
			AssertEquals("Precondition: job.Charges.Count", 100m, testJob.JH_TotalCost);
			AssertEquals("Precondition: job.Charges.Count", 100m, testJob.JH_TotalRevenue);

			var newFactory = new BusinessObjectFactory { RefreshEnabled = false };
			var newCharge = newFactory.New<Charge>();
			newCharge.JR_JH = job.PK;
			newCharge.JR_AC = TestObjectCreator.CC1.PK;
			newCharge.JR_OSCostAmt = 50;
			newCharge.JR_OSSellAmt = 60;
			newFactory.Save();

			AssertEquals("Precondition after charge is added: job.Charges.Count", 1, testJob.Charges.Count);
			AssertEquals("Precondition after charge is added: job.Charges.Count", 100m, testJob.JH_TotalCost);
			AssertEquals("Precondition after charge is added: job.Charges.Count", 100m, testJob.JH_TotalRevenue);
			Assert("Precondition: RefreshBindingTotalFieldsCalled", !testJob.RefreshBindingTotalFieldsCalled);
			testJob.RefreshCharges();
			Assert("RefreshBindingTotalFieldsCalled", testJob.RefreshBindingTotalFieldsCalled);
			AssertEquals("job.Charges.Count", 2, testJob.Charges.Count);
			AssertEquals("Precondition: job.Charges.Count", 150m, testJob.JH_TotalCost);
			AssertEquals("Precondition: job.Charges.Count", 160m, testJob.JH_TotalRevenue);
		}

		public void TestSetBranchIfEmptyForChargesAndLinesSetHasChangesOnJobIfSettingHasChangesIsNotSuspendedForJob() => AssertSetBranchIfEmptyForChargesAndLines(false);

		public void TestSetBranchIfEmptyForChargesAndLinesDoNotSetHasChangesOnJobIfSettingHasChangesIsSuspendedForJob() => AssertSetBranchIfEmptyForChargesAndLines(true);

		void AssertSetBranchIfEmptyForChargesAndLines(bool isSettingHasChangesOnJobIsSuspended)
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", true);
			var job = TestObjectCreator.CreateJob(shipment, createWithMutex: false);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 0m, 0m);
			Factory.Save();

			Assert("Precondition : charge sell amount is zero.", charge.JR_OSSellAmt.IsEmpty);
			Assert("Precondition : charge cost amount is zero.", charge.JR_OSCostAmt.IsEmpty);
			Assert("Precondition : job has no changes.", !job.HasChanges);

			using (isSettingHasChangesOnJobIsSuspended ? job.SuspendSettingHasChanges() : null)
			{
				job.JH_GB = TestObjectCreator.NonCurrentBranch.PK;

				AssertEquals(!isSettingHasChangesOnJobIsSuspended, job.HasChanges);
				AssertEquals(TestObjectCreator.NonCurrentBranch.PK, job.JH_GB);
				AssertEquals(TestObjectCreator.NonCurrentBranch.PK, charge.JR_GB);
			}
		}

