		public void TestCheckIfCanDeleteJobInCurrentCompany()
		{
			var creator = new TestObjectCreator(Factory);
			var shipment = creator.CreateShipment("S00001001");
			var job = new Loader(shipment).TryCreateWithoutMutexForTestOnly();

			var portTransport = creator.CreateCartage();
			var portTransportJob = new Loader(portTransport).TryCreateWithoutMutexForTestOnly();
			portTransportJob.JH_JH_ParentJob = job.PK;
			Factory.Save();

			AssertEquals($@"This job cannot be deleted.
Child Invoicing Job(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());

			var accHotCheque = Factory.NewWithValidTestData<AccHotCheque>();
			accHotCheque.AQ_AK = TestObjectCreator.AUDChequeBook.PK;
			accHotCheque.AQ_ChequeNumber = "10006";
			accHotCheque.AQ_JH = job.PK;
			Factory.Save();
			AssertEquals(@"This job cannot be deleted.
Hot Cheque(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());

			var invoice = Factory.NewWithValidTestData<AccTransactionHeader>();
			invoice.AH_JH = job.PK;
			Factory.Save();
			AssertEquals(@"This job cannot be deleted.
Accounting Transaction(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());

			var invoiceLine = Factory.NewWithValidTestData<AccTransactionLines>();
			invoiceLine.AL_JH = job.PK;
			invoiceLine.AL_AG = Factory.NewWithValidTestData<AccGLHeader>().PK;
			Factory.Save();
			AssertEquals(@"This job cannot be deleted.
Accounting Transaction Line(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());

			var charge1 = Factory.NewWithValidTestData<JobCharge>();
			charge1.JR_JH = job.PK;
			Factory.Save();

			bool allAmountsZero = charge1.JR_OSCostAmt == 0m && charge1.JR_LocalCostAmt == 0m && charge1.JR_EstimatedCost == 0m && charge1.JR_AgentDeclaredCostAmt == 0m &&
				charge1.JR_OSSellAmt == 0m && charge1.JR_LocalSellAmt == 0m && charge1.JR_EstimatedRevenue == 0m && charge1.JR_AgentDeclaredSellAmt == 0m;
			Assert("all amounts on the JobCharge should be zero", allAmountsZero);

			AssertEquals("Should not complain about JobCharges because all amounts are zero", @"This job cannot be deleted.
Accounting Transaction Line(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());

			charge1.JR_OSCostAmt = 5m;
			charge1.JR_LocalCostAmt = 5m;
			Factory.Save();
			AssertEquals(@"This job cannot be deleted.
Job Invoicing Charge(s) have been saved against this Invoicing Job Header.", job.CheckIfCanDeleteJobInCurrentCompany());
		}

