		public void TestUpdateFieldsThatShouldNotChangedWhenJobChargeIsSaved()
		{
			ErrorReporter.Clear();
			var consol = TestObjectCreator.CreateConsol(consolNum: "ConsolJob");
			var shipment = TestObjectCreator.CreateShipment("S001909", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S001920");
			Factory.Save();

			using (var job = TestObjectCreator.CreateJob(shipment))
			using (var job2 = TestObjectCreator.CreateJob(shipment2))
			using (new DisposableAction(() => Factory.SetContext(BusinessContext.EnableCheckFieldCannotChangeWhenJobIsAlreadyInDatabase_ForTestOnly),
				() => Factory.RemoveContext(BusinessContext.EnableCheckFieldCannotChangeWhenJobIsAlreadyInDatabase_ForTestOnly)))
			{
				AssertEquals(shipment.PK, job.JH_ParentID);
				AssertEquals(JobShipmentSchema.Constants.Prefix, job.JH_ParentTableCode);
				Assert(!job.JH_JobNum.IsEmpty);

				job.Parent = consol;
				job.JH_ParentID = consol.PK;
				job.JH_ParentTableCode = JobConsolSchema.Constants.Prefix;
				job.JH_JobNum = "ConsolJob";
				AssertEquals("Shouldn't report developer error since the job is not saved", string.Empty, ErrorReporter.LastMessageReported);
				Factory.Save();

				job.JH_ParentID = shipment.PK;
				AssertEquals($@"The jobHeader JH_ParentID should not be changed after the job is already in the database. The JH_ParentID value was changed from '{consol.PK}' to '{shipment.PK}'.
Job Details: Job Number = ConsolJob, Parent Table Code = JK, Parent ID = {consol.PK}, Parent Type = {consol.GetType()}, Job Type = SHP, Job Status = WRK, Parent Job = ()", ErrorReporter.LastMessageReported);
				ErrorReporter.Clear();

				job.Parent = shipment;
				job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
				AssertEquals($@"The jobHeader JH_ParentTableCode should not be changed after the job is already in the database. The JH_ParentTableCode value was changed from 'JK' to 'JS'.
Job Details: Job Number = ConsolJob, Parent Table Code = JK, Parent ID = {shipment.PK}, Parent Type = {shipment.GetType()}, Job Type = SHP, Job Status = WRK, Parent Job = ()", ErrorReporter.LastMessageReported);
				ErrorReporter.Clear();

				job.JH_JH_ParentJob = job2.PK;
				job.JH_JobNum = "S001910";
				AssertEquals($@"The jobHeader JH_JobNum should not be changed after the job is already in the database. The JH_JobNum value was changed from 'ConsolJob' to 'S001910'.
Job Details: Job Number = ConsolJob, Parent Table Code = JS, Parent ID = {shipment.PK}, Parent Type = {shipment.GetType()}, Job Type = SHP, Job Status = WRK, Parent Job = (Job Details: Job Number = S001920, Parent Table Code = JS, Parent ID = {shipment2.PK}, Parent Type = {shipment2.GetType()}, Job Type = SHP, Job Status = WRK, Parent Job = ())", ErrorReporter.LastMessageReported);
				ErrorReporter.Clear();
			}
		}

