		public void TestErrorReportedEvenWhenChangingParentFromDtbBooking()
		{
			ErrorReporter.Clear();
			var transportBookingConsolidation = (BusinessObject)Factory.New<IDtbBookingConsolidation>();
			transportBookingConsolidation[DtbBookingConsolidationSchema.KB_JobType] = "BKG";
			transportBookingConsolidation.FillWithValidTestData();
			var transportBooking = (BusinessObject)Factory.New<IDtbBooking>();
			transportBooking[DtbBookingSchema.KM_JobType] = "BKG";
			transportBooking[DtbBookingSchema.KM_KB_Booking] = transportBookingConsolidation.PK;
			transportBooking[DtbBookingSchema.KM_JobID] = "TBX0001";
			transportBooking[DtbBookingSchema.KM_IsAgentBooking] = true;
			transportBooking.FillWithValidTestData();

			Factory.Save();

			var trnJob = TestObjectCreator.CreateJob((IJobInvoicingPlugIn)transportBooking, TestObjectCreator.LocalClient, 1.0M, TestObjectCreator.Agent, 1.0M);
			Factory.Save();

			using (new DisposableAction(() => Factory.SetContext(BusinessContext.EnableCheckFieldCannotChangeWhenJobIsAlreadyInDatabase_ForTestOnly),
				() => Factory.RemoveContext(BusinessContext.EnableCheckFieldCannotChangeWhenJobIsAlreadyInDatabase_ForTestOnly)))
			{
				AssertEquals("Precondition: Job Header ParentID points at transport booking", transportBooking.PK, trnJob.JH_ParentID);
				AssertEquals("Precondition: Job Header ParentTableCode is 'KM'", DtbBookingSchema.Constants.Prefix, trnJob.JH_ParentTableCode);
				AssertEquals("Precondition: Job Header JobID matches transport booking JobID", transportBooking[DtbBookingSchema.KM_JobID], trnJob.JH_JobNum);

				Factory.Save();

				Assert("Precondition: Error Reporter is still clear of messages", !ErrorReporter.LastExceptionsReported().Any());

				var oldTrnJobParent = trnJob.JH_ParentID;
				trnJob.JH_ParentID = ZGuid.Empty;
				AssertMultilineASCIIEquals(
					"Setting Job Header ParentID to empty should send error report with old value of JH_ParentTableCode is 'KM'",
					FormattableString.Invariant($@"The jobHeader JH_ParentID should not be changed after the job is already in the database. The JH_ParentID value was changed from '{oldTrnJobParent}' to '{ZGuid.Empty}'.
Job Details: Job Number = {transportBooking[DtbBookingSchema.KM_JobID]}, Parent Table Code = KM, Parent ID = {oldTrnJobParent}, Parent Type = Enterprise.TransportBookings.Business.DtbBooking, Job Type = ATB, Job Status = WRK, Parent Job = ()"),
					ErrorReporter.LastMessageReported);
				ErrorReporter.Clear();
			}
		}

