		public void TestExchangeRateConfigurationRateConsumer()
		{
			var consol = TestObjectCreator.CreateConsol();
			consol.Transports.MostInterestingTransport.JW_ATA = new ZDateTime(2018, 03, 01);
			consol.Transports.MostInterestingTransport.JW_ATD = new ZDateTime(2018, 03, 05);

			var shipment = TestObjectCreator.CreateShipment("S001909", consol);
			shipment.JS_E_ARV = new ZDateTime(2018, 02, 19);
			shipment.JS_E_DEP = new ZDateTime(2018, 02, 25);
			using (var job = TestObjectCreator.CreateJob(shipment))
			{
				job.LocalChargesPK = TestObjectCreator.LocalClient.PK;
				var rateConsumer = job.ExchangeRateConfigurationRateConsumer;

				AssertEquals(JobInvoicingConsumerTypes.Shipment.Code, rateConsumer.JobType);
				AssertEquals(Constants.FreightShipmentDirection.Code.Export, rateConsumer.Direction);
				AssertEquals(Core.Constants.TransportModes.Air, rateConsumer.TransportMode);
				AssertEquals(TestObjectCreator.LocalClient.PK, rateConsumer.LocalClientPK);
				AssertEquals(GlbCompany.CurrentCompany.PK, rateConsumer.Company.PK);
				AssertEquals(ZDateTime.Invalid, rateConsumer.ConsolExchangeRateDate);
				AssertEquals(new ZDateTime(2018, 03, 01), rateConsumer.HistoricalRateFromActualArrivalDate);
				AssertEquals(new ZDateTime(2018, 03, 05), rateConsumer.HistoricalRateFromActualDepartureDate);
				AssertEquals(new ZDateTime(2018, 02, 19), rateConsumer.HistoricalRateFromEstimatedArrivalDate);
				AssertEquals(new ZDateTime(2018, 02, 25), rateConsumer.HistoricalRateFromEstimatedDepartureDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.HistoricalRateFromEstimatedArrivalAtLoadPortDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.HistoricalRateFromActualArrivalAtLoadPortDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.PickupDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.DeliveryDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.RequiredDate);
				AssertEquals(ZDateTime.Empty, rateConsumer.FinalizedDate);
				AssertEquals(ZDecimal.Zero, rateConsumer.GetExchangeRateForConsolExchangeRatePreference(TestObjectCreator.USD));
			}
		}

