		public void TestDefaultingSalesRepFromControllingCustomer()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", "AUSYD", "NZAKL");
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			Assert(shipment.IsExport());
			Assert(shipment.IsAir);
			var job = TestObjectCreator.CreateJob(shipment);
			TestObjectCreator.LocalClient.StaffAssignments.ExportAirRep = "EA1";
			job.LocalChargesPK = TestObjectCreator.LocalClient.PK;
			job.JH_GS_NKRepSales = ZString.Empty;
			Factory.Save();

			Assert("As job is in database, sales rep field will be defaulted only if it is empty.", job.JH_GS_NKRepSales.IsEmpty);
			AssertNull("Shipment has no controlling customer.", shipment.InvoicingSupporter.ControllingCustomer);

			AssertDefaultingSalesRepFromControllingCustomer_AddControllingCustomer(shipment.PK, job.PK);

			var controllingCustomerOrg = Factory.NewWithValidTestData<OrgHeader>();
			controllingCustomerOrg.StaffAssignments.ExportAirRep = "EA2";
			shipment.ControllingCustomerAddress.E2_OA_Address = controllingCustomerOrg.MainAddress.PK;
			Factory.Save();

			AssertNotNull("Shipment has a controlling customer.", shipment.InvoicingSupporter.ControllingCustomer);

			AssertDefaultingSalesRepFromControllingCustomer_ChangeControllingCustomer_ControllingCustomerSalesRepIsNotEmpty(shipment.PK, job.PK);

			AssertDefaultingSalesRepFromControllingCustomer_ChangeControllingCustomer_ControllingCustomerSalesRepIsEmpty(shipment.PK, job.PK);

			AssertDefaultingSalesRepFromControllingCustomer_RemoveControllingCustomer(shipment.PK, job.PK);
		}

