		void AssertDefaultingSalesRepFromControllingCustomerWithJobLoadingSequence(ZGuid shipmentPK, ZGuid jobPK, ZString expectedSalesRep, Action<ForwardingShipment> makeChangesToShipment, bool shouldLoadJobFirst)
		{
			var testFactory1 = new BusinessObjectFactory();
			testFactory1.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);
			Job jobInTestFactory1 = null;
			if (shouldLoadJobFirst)
			{
				jobInTestFactory1 = testFactory1.Load<Job>(jobPK);
				jobInTestFactory1.InitializeParentFromGenericJobWithSettingDefaults();
			}
			var shipmentInTestFactory1 = testFactory1.Load<ForwardingShipment>(shipmentPK);
			makeChangesToShipment(shipmentInTestFactory1);
			if (!shouldLoadJobFirst)
			{
				jobInTestFactory1 = testFactory1.Load<Job>(jobPK);
				jobInTestFactory1.InitializeParentFromGenericJobWithSettingDefaults();
