		void AssertOnControllingCustomerChangedEventSubscription(bool isSettingDefaults, ZGuid shipmentPK, ZGuid jobPK)
		{
			var currentSalesRep = "ABC";
			var newSalesRep = "XYZ";

			var newFactory = new BusinessObjectFactory();
			newFactory.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);
			var shipmentInNewFactory = newFactory.Load<ForwardingShipment>(shipmentPK);
			var jobInNewFactory = newFactory.Load<Job>(jobPK);
			if (isSettingDefaults)
			{
				jobInNewFactory.InitializeParentFromGenericJobWithSettingDefaults();
			}
			else
			{
				jobInNewFactory.InitializeParentFromGenericJobWithoutSettingDefaults();
			}
			jobInNewFactory.JH_GS_NKRepSales = currentSalesRep;

			var anotherControllingCustomerOrg = new TestObjectCreator(newFactory).CreateOrgHeader(TestObjectCreator.GetRandomString(6), false, false);
			anotherControllingCustomerOrg.StaffAssignments.ExportAirRep = newSalesRep;
			shipmentInNewFactory.DocAddresses.FindByDocAddressType(DocAddressType.ControllingCustomer).E2_OA_Address = anotherControllingCustomerOrg.MainAddress.PK;

			var expectedSalesRep = isSettingDefaults ? newSalesRep : currentSalesRep;
			AssertEquals(expectedSalesRep, jobInNewFactory.JH_GS_NKRepSales);
		}

		public void TestSalesRepDefaultingWhenSystemDefaultsControllingCustomer()
		{
