			var controllingCustomerOrg = TestObjectCreator.CreateOrgHeader("ABCORG", false, false);
			controllingCustomerOrg.StaffAssignments.ExportAirRep = controllingCustomerExportAirRep;

			var consignor = TestObjectCreator.CreateOrgHeader("NORORG", true, true);
			consignor.StaffAssignments.ExportAirRep = consignorExportAirRep;

			var consignee = TestObjectCreator.CreateOrgHeader("NEEORG", true, true);
			consignee.StaffAssignments.ExportAirRep = consigneeExportAirRep;

			var consigneeRelatedParty = consignee.AllRelatedParties.AddNew();
			consigneeRelatedParty.PR_PartyType = RelatedPartyTypeList.Codes.ControllingCustomer;
			consigneeRelatedParty.PR_OH_RelatedParty = controllingCustomerOrg.PK;
			consigneeRelatedParty.PR_GC = GlbCompany.CurrentCompany.PK;
			consigneeRelatedParty.PR_FreightDirection = RelatedPartyDirectionList.Codes.Delivery;

			Factory.Save();

			AssertSalesRepDefaultingWhenSystemDefaultsControllingCustomer(true, consignor, consignee, controllingCustomerOrg.PK, consignorExportAirRep, controllingCustomerExportAirRep);
			AssertSalesRepDefaultingWhenSystemDefaultsControllingCustomer(false, consignor, consignee, controllingCustomerOrg.PK, consignorExportAirRep, consignorExportAirRep);
