		void AssertSalesRepDefaultingWhenSystemDefaultsControllingCustomer(bool controllingCustomerUseSalesRepRegistryIsOn, OrgHeader consignor, OrgHeader consignee, ZGuid controllingCustomerOrgPK, ZString expectedSalesRepBeforeDefaultingControllingCustomer, ZString expectedSalesRepAfterDefaultingControllingCustomer)
		{
			using (FreightDataRegistry.Instance.DefaultShipmentControllingCustomer.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			using (FreightDataRegistry.Instance.ControllingCustomerUseSalesRep.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, controllingCustomerUseSalesRepRegistryIsOn))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001", "AUSYD", "NZAKL");
				shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
				Assert(shipment.IsExport());
				Assert(shipment.IsAir);

				shipment.ConsignorDocumentaryAddress.E2_OA_Address = consignor.MainAddress.PK;
				shipment.ConsigneeDocumentaryAddress.E2_OA_Address = consignee.MainAddress.PK;

				TestObjectCreator.Factory.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);
				using (var job = TestObjectCreator.CreateJob(shipment))
				{
					AssertEquals(consignor.PK, job.LocalCharges.PK);
					AssertEquals(expectedSalesRepBeforeDefaultingControllingCustomer, job.JH_GS_NKRepSales);
					AssertNull(shipment.InvoicingSupporter.ControllingCustomer);

					shipment.RunPreSaveValidation();

					AssertNotNull(shipment.InvoicingSupporter.ControllingCustomer);
					AssertEquals(controllingCustomerOrgPK, shipment.InvoicingSupporter.ControllingCustomer.PK);
					AssertEquals(expectedSalesRepAfterDefaultingControllingCustomer, job.JH_GS_NKRepSales);
				}
			}
		}

