		void AssertEventSubscriptionWithInvoicingPluginGUIExcludingConsolContext(bool hasInvoicingPluginGUIExcludingConsolContext)
		{
			var newFactory = new BusinessObjectFactory();
			if (hasInvoicingPluginGUIExcludingConsolContext)
			{
				newFactory.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);
			}
			var objectCreator = new TestObjectCreator(newFactory);

			var shipment = objectCreator.CreateShipment("S00001", "AUSYD", "NZAKL");
			shipment.JS_TransportMode = Constants.TransportModes.Air;
			Assert(shipment.IsExport());
			Assert(shipment.IsAir);
			var job = objectCreator.CreateJob(shipment, false);
			job.InitializeParentFromGenericJobWithSettingDefaults();

			AssertEquals(hasInvoicingPluginGUIExcludingConsolContext, job.HasContext(BusinessContext.InvoicingPluginGUIExcludingConsol));
			AssertEquals(ZString.Empty, job.JH_GS_NKRepSales);

			var newSalesRep = "XYZ";
			var controllingCustomerOrg = objectCreator.CreateOrgHeader(TestObjectCreator.GetRandomString(6), false, false);
			controllingCustomerOrg.StaffAssignments.ExportAirRep = newSalesRep;
			shipment.ControllingCustomerAddress.E2_OA_Address = controllingCustomerOrg.MainAddress.PK;

			var expectedSalesRep = hasInvoicingPluginGUIExcludingConsolContext ? newSalesRep : string.Empty;
			AssertEquals(expectedSalesRep, job.JH_GS_NKRepSales);

			if (!hasInvoicingPluginGUIExcludingConsolContext)
			{
				newFactory.Save();
				var reloadFactory = new BusinessObjectFactory();
				var reloadedJob = reloadFactory.Load<Job>(job.PK);
				reloadedJob.InitializeParentFromGenericJobWithSettingDefaults();
				AssertEquals(newSalesRep, reloadedJob.JH_GS_NKRepSales);
			}
		}

		[ExpectNoExceptions]
		public void TestOnControllingCustomerChangedEventUnsubscriptionWhenJobIsDeleted()
		{
			using (FreightDataRegistry.Instance.ControllingCustomerUseSalesRep.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001", "AUSYD", "NZAKL");
				shipment.JS_TransportMode = Constants.TransportModes.Air;
				Assert(shipment.IsExport());
				Assert(shipment.IsAir);
				TestObjectCreator.Factory.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);
				var job = TestObjectCreator.CreateJob(shipment, false);
				job.InitializeParentFromGenericJobWithSettingDefaults();

				var saleRepForControllingCustomerOrg1 = "XYZ";
				var controllingCustomerOrg1 = TestObjectCreator.CreateOrgHeader("XYZORG", false, false);
				controllingCustomerOrg1.StaffAssignments.ExportAirRep = saleRepForControllingCustomerOrg1;

				AssertEquals(ZString.Empty, job.JH_GS_NKRepSales);
				shipment.ControllingCustomerAddress.E2_OA_Address = controllingCustomerOrg1.MainAddress.PK;
				AssertEquals("Subscription is working - sales rep is defaulted.", saleRepForControllingCustomerOrg1, job.JH_GS_NKRepSales);

				var saleRepForControllingCustomerOrg2 = "PQR";
				var controllingCustomerOrg2 = TestObjectCreator.CreateOrgHeader("PQRORG", false, false);
				controllingCustomerOrg2.StaffAssignments.ExportAirRep = saleRepForControllingCustomerOrg2;

				job.Delete();
				var newJob = TestObjectCreator.CreateJob(shipment, false);
				newJob.InitializeParentFromGenericJobWithSettingDefaults();

				Assert(job.IsDeleted);
				AssertEquals(saleRepForControllingCustomerOrg1, newJob.JH_GS_NKRepSales);

				shipment.ControllingCustomerAddress.E2_OA_Address = controllingCustomerOrg2.MainAddress.PK;

				AssertEquals(saleRepForControllingCustomerOrg2, newJob.JH_GS_NKRepSales);
			}
		}

