		public void TestNotifyControllingCustomerChangedWhenJobIsFromAnotherCompanyAndIsDeactived()
		{
			FreightDataRegistry.Instance.ControllingCustomerUseSalesRep.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			Factory.SetContext(BusinessContext.InvoicingPluginGUIExcludingConsol);

			var shipment = TestObjectCreator.CreateShipment("S001", true);

			Job jobInAnotherCompany = null;
			using (Env.SetTemporaryUserContext(Env.CurrentUserPK, TestObjectCreator.NonCurrentCompanyBranch.PK.ToGuid(), Env.CurrentDepartmentPK))
			{
				var newFactory = Factory.CreateNewFactory();
				newFactory.RefreshEnabled = false;
				jobInAnotherCompany = new Loader(newFactory, shipment).TryCreateWithoutMutexForTestOnly();
				jobInAnotherCompany.PlugInData = shipment;
				newFactory.Save();
			}

			var jobInAnotherCompanyReload = Factory.Load<Job>(jobInAnotherCompany.PK);
			int eventTriggerCount = 0;
			(shipment.InvoicingSupporter as ISalesRepDefaultingFromControllingCustomer).NotifyControllingCustomerChanged((sender, e) => eventTriggerCount++);

			AssertEquals("Pre-condition", 0, eventTriggerCount);
			AssertNotEquals(ZGuid.Invalid, shipment.ControllingCustomerAddress.E2_OA_Address);

			jobInAnotherCompanyReload.SetContext(BusinessContext.InterCompanyJobOperation);
			jobInAnotherCompanyReload.MarkAsInactive();
			shipment.ControllingCustomerAddress.E2_OA_Address = ZGuid.Invalid;

			AssertEquals("Event binding should not be cleared", 1, eventTriggerCount);
		}

