		public void TestTaxOverrideForBooking()
		{
			var group1 = TestObjectCreator.CreateTaxOverride(TestObjectCreator.CC1, TestObjectCreator.GST1.PK, ZGuid.Empty, "ALL", "ALL", "ALL", "ALL", "ALL", "ALL");
