			quote1.Booking.CustomsEntryNumberType = "TF";
			var job1 = new Loader(quote1).TryLoadOrCreateWithoutMutexForTestOnly();
			var job2 = new Loader(quote2).TryLoadOrCreateWithoutMutexForTestOnly();
			var charge1 = TestObjectCreator.CreateCharge(job1, TestObjectCreator.CC1, "Test1", TestObjectCreator.USD, 100m, TestObjectCreator.AALSHI, TestObjectCreator.USD, 100m, TestObjectCreator.TestOrganisation);
