			AssertEquals("Sell Tax Message", TestObjectCreator.TaxMsg1.PK, charge1.JR_A9_SellVATClass);
			AssertEquals("Cost Tax ID", TestObjectCreator.GSTFREE1.PK, charge1.JR_AT_CostGSTRate);
			AssertEquals("Cost Tax Message", TestObjectCreator.TaxMsg1.PK, charge1.JR_A9_CostVATClass);

			AssertEquals("Sell Tax ID", TestObjectCreator.GST1.PK, charge2.JR_AT_SellGSTRate);
