			AssertEquals("Cost Tax Message", ZGuid.Empty, charge2.JR_A9_CostVATClass);
		}

		public void TestAddRateIntoExchangeRatesCollectionWhileIterating()
		{
			var shipment = TestObjectCreator.CreateShipment("S001");
			var job = TestObjectCreator.CreateJob(shipment);
			Factory.Save();

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Test1", TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS, TestObjectCreator.USD, 100m, TestObjectCreator.Debtor);
			charge1.JR_InvoiceType = InvoiceTypesList.Codes.FinalInvoice;
