		public void TestNonZeroBalanceDisbursementsDefaultOption()
		{
			SetEnforceZeroBalanceDisbursementsOptionInRegistry(AccountingConstants.EnforceZeroBalanceDisbursementsOption.Default.Code);
			var creator = new TestObjectCreator(Factory);
			var job = creator.Job1;
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;

			var charge1 = creator.CreateDSBCharge(job, creator.AUD, creator.AUD, 100m);
			new ChargePoster(Factory).Post(charge1);
			var charge2 = creator.CreateDSBCharge(job, creator.USD, creator.USD, 25m);
			new ChargePoster(Factory).Post(charge2);

			Assert("Cost is not posted", !charge1.JR_IsCostPosted);
			Assert("Revenue is posted", charge1.JR_IsRevenuePosted);
			charge1.JR_OSCostAmt = 200m;
			job.RunPreSaveValidationCore_ForTestOnly();
			Assert("Cost and Sell amounts are not equal", charge1.JR_OSCostAmt != charge1.JR_OSSellAmt);
			AssertNoRowWarningContaining(charge1, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertNoRowErrorContaining(charge1, dsbChargesCostAndSellAmountsMustBeSameMessage);

			Assert("Cost is not posted", !charge2.JR_IsCostPosted);
			Assert("Revenue is posted", charge2.JR_IsRevenuePosted);
			charge2.JR_OSCostAmt = 50m;
			job.RunPreSaveValidationCore_ForTestOnly();
			Assert("Cost and Sell amounts are not equal", charge2.JR_OSCostAmt != charge2.JR_OSSellAmt);
			AssertNoRowWarningContaining(charge2, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertNoRowErrorContaining(charge2, dsbChargesCostAndSellAmountsMustBeSameMessage);
		}

		public void TestNonZeroBalanceDisbursementsOSAmountOption()
		{
			SetEnforceZeroBalanceDisbursementsOptionInRegistry(AccountingConstants.EnforceZeroBalanceDisbursementsOption.OSAmount.Code);
			var creator = new TestObjectCreator(Factory);
			creator.LocalClient.CompanyData.OB_RX_NKARDDefltCurrency = creator.AUD.Code;
			creator.LocalClient.CompanyData.OB_RX_NKAPDefltCurrency = creator.AUD.Code;
			var job = creator.Job1;
			job.PlugInData = creator.CreateShipment("S0001", "AUSYD", "USLAX");
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;

			creator.SetExchangeRate(job, creator.USD, 2m, creator.Debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			creator.SetExchangeRate(job, creator.GBP, 3m, creator.Debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			creator.SetExchangeRate(job, creator.CNY, 4m, creator.Debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			creator.SetExchangeRate(job, creator.USD, 2m, creator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);
			creator.SetExchangeRate(job, creator.GBP, 3m, creator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);
			creator.SetExchangeRate(job, creator.CNY, 4m, creator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);

			var charge = creator.CreateMarginCharge(job, creator.AUD, creator.AUD, 140m);
			var charge1 = creator.CreateDSBCharge(job, creator.AUD, creator.USD, 100m);
			var charge2 = creator.CreateDSBCharge(job, creator.USD, creator.GBP, 80m);
			var charge3 = creator.CreateDSBCharge(job, creator.CNY, creator.GBP, 150m);
			var charge4 = creator.CreateDSBCharge(job, creator.USD, creator.GBP, 120m);

			var allowSaveNonZeroBalanceDisbursements = Env.Security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.SaveNonZeroBalanceDisbursements);
			allowSaveNonZeroBalanceDisbursements.IsAllowed = false;
