			AssertNoRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });
			AssertNoRowErrorContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertHasRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2, charge3, charge4 });

			allowSaveNonZeroBalanceDisbursements.IsAllowed = true;
			job.RunPreSaveValidationCore_ForTestOnly();

			AssertNoRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });
			AssertNoRowWarningContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertHasRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2, charge3, charge4 });

			charge3.JR_RX_NKCostCurrency = creator.AUD.Code;

			charge2.JR_OSCostAmt = 100m;
			charge4.JR_OSCostAmt = 200m;

			charge2.JR_RX_NKSellCurrency = creator.USD.Code;
			charge3.JR_RX_NKSellCurrency = creator.AUD.Code;
			charge4.JR_RX_NKSellCurrency = creator.AUD.Code;

			charge3.JR_OSCostAmt = 150;

			job.RunPreSaveValidationCore_ForTestOnly();

			AssertNoRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });
			AssertNoRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });

			charge4.JR_OSCostAmt = 100;
			allowSaveNonZeroBalanceDisbursements.IsAllowed = false;
			job.RunPreSaveValidationCore_ForTestOnly();

			AssertNoRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });
			AssertNoRowErrorContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertHasRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2, charge3, charge4 });

			allowSaveNonZeroBalanceDisbursements.IsAllowed = true;
			job.RunPreSaveValidationCore_ForTestOnly();

			AssertNoRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2, charge3, charge4 });
			AssertNoRowWarningContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertHasRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2, charge3, charge4 });
