			allowSaveNonZeroBalanceDisbursements.IsAllowed = true;
			job.RunPreSaveValidationCore_ForTestOnly();

			AssertNoRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2 });
			AssertNoRowWarningContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertHasRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2 });
		}

