		public void TestNonZeroBalanceDisbursements_ShouldShowErrorWhenUserWithoutSecurityRightsMakesChangesToDisbursementCharges()
		{
			var creator = new TestObjectCreator(Factory);
			creator.LocalClient.CompanyData.OB_RX_NKARDDefltCurrency = creator.AUD.Code;
			creator.LocalClient.CompanyData.OB_RX_NKAPDefltCurrency = creator.AUD.Code;
			SetEnforceZeroBalanceDisbursementsOptionInRegistry(AccountingConstants.EnforceZeroBalanceDisbursementsOption.Both.Code);
			var job = creator.Job1;
			job.PlugInData = creator.CreateShipment("S0001", "AUSYD", "USLAX");
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;

			creator.SetExchangeRate(job, creator.USD, 2m, creator.Debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			creator.SetExchangeRate(job, creator.USD, 3m, creator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);

			var charge1 = creator.CreateDSBCharge(job, creator.AUD, creator.USD, 100m);
			var charge2 = creator.CreateDSBCharge(job, creator.USD, creator.USD, 0m);
			charge2.JR_OSCostAmt = 100m;

			Factory.Save();

			var allowSaveNonZeroBalanceDisbursements = Env.Security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.SaveNonZeroBalanceDisbursements);
			allowSaveNonZeroBalanceDisbursements.IsAllowed = false;
			var charge = creator.CreateDSBCharge(job, creator.AUD, creator.AUD, 150m);
			charge.JR_GE = creator.FESDepartment.PK;

			job.RunPreSaveValidationCore_ForTestOnly();

			Assert("Charge present on job", job.Charges.Contains(charge1));
			Assert("Charge present on job", job.Charges.Contains(charge2));
			Assert("Charge present on job", job.Charges.Contains(charge));
			Assert("No changes to charge", !charge1.HasChanges);
			Assert("No changes to charge", !charge2.HasChanges);
			Assert("Changes to charge", charge.HasChanges);
			AssertHasRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2 });
			AssertNoRowErrorContaining(charge, dsbChargesCostAndSellAmountsMustBeSameMessage);
			AssertNoRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge, charge1, charge2 });

			job.Charges.Remove(charge);
			job.JH_GS_NKRepSales = "ABC";
			job.RunPreSaveValidationCore_ForTestOnly();

			Assert("Charge present on job", job.Charges.Contains(charge1));
			Assert("Charge present on job", job.Charges.Contains(charge2));
			Assert("Charge not present on job", !job.Charges.Contains(charge));
			Assert("No changes to charge", !charge1.HasChanges);
			Assert("No changes to charge", !charge2.HasChanges);
			AssertNoRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2 });
			AssertHasRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, new BusinessObject[] { charge1, charge2 });
		}

		public void TestNonZeroBalanceDisbursements_ShouldValidateOtherDisbursementsChargesWhenUserWithoutSecurityRightsDeletesDisbursementCharges()
		{
			var creator = new TestObjectCreator(Factory);
			creator.LocalClient.CompanyData.OB_RX_NKARDDefltCurrency = creator.AUD.Code;
			creator.LocalClient.CompanyData.OB_RX_NKAPDefltCurrency = creator.AUD.Code;
			SetEnforceZeroBalanceDisbursementsOptionInRegistry(AccountingConstants.EnforceZeroBalanceDisbursementsOption.Both.Code);
			var job = creator.Job1;
			job.PlugInData = creator.CreateShipment("S0001", "AUSYD", "USLAX");
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;

			creator.SetExchangeRate(job, creator.USD, 2m, creator.Debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			creator.SetExchangeRate(job, creator.USD, 3m, creator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);

			var charge1 = creator.CreateDSBCharge(job, creator.AUD, creator.USD, 100m);
			var charge2 = creator.CreateDSBCharge(job, creator.USD, creator.USD, 250m);
			var charge3 = creator.CreateDSBCharge(job, creator.AUD, creator.AUD, 50m);
			var charge4 = creator.CreateMarginCharge(job, creator.AUD, creator.AUD, 140m);

			Factory.Save();

			charge3.Delete();
			Assert("Flag has not been set due to security rights", !job.ShouldRaiseErrorForNonZeroBalanceDisbursementChargesEvenIfNoChanges);

			var allowSaveNonZeroBalanceDisbursements = Env.Security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.SaveNonZeroBalanceDisbursements);
			allowSaveNonZeroBalanceDisbursements.IsAllowed = false;

			charge4.Delete();
			Assert("Flag has not been set due to non-disbursement charge deletion", !job.ShouldRaiseErrorForNonZeroBalanceDisbursementChargesEvenIfNoChanges);

			charge2.Delete();
			Assert("Flag has been set due to disbursement charge deletion", job.ShouldRaiseErrorForNonZeroBalanceDisbursementChargesEvenIfNoChanges);

			job.RunPreSaveValidationCore_ForTestOnly();
			Assert("Charge present on job", job.Charges.Contains(charge1));
			Assert("Charge not present on job", !job.Charges.Contains(charge2));
			Assert("No changes to charge", !charge1.HasChanges);
			AssertHasRowErrorContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, charge1);
			AssertNoRowWarningContaining(dsbChargesCostAndSellAmountsMustBeSameMessage, charge1);

			Factory.Save();
			Assert("Flag has been reset due to factory save", !job.ShouldRaiseErrorForNonZeroBalanceDisbursementChargesEvenIfNoChanges);
		}

