					nameof(job.JH_TotalRevenue),
					nameof(job.JH_TotalRevenuePosted),
					nameof(job.JH_TotalWIP),
					nameof(job.JH_ProfitLoss),
					nameof(job.JH_ProfitLossPosted),
					nameof(job.JH_TotalCost),
					nameof(job.JH_TotalCostPosted),
				};

