		public void TestChargeLoadingSuspender()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 10, 10);

			var shipment2 = TestObjectCreator.CreateShipmentWithCoLoadMaster("S0002", "AUSYD", "USLAX", shipment);
			var job2 = TestObjectCreator.CreateJob(shipment2, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			var charge2 = TestObjectCreator.CreateCharge(job2, TestObjectCreator.CC1, 20, 20);

			Factory.Save();
			AssertEquals("saved charge JR_DisplaySequence", (ZShort)1, charge.JR_DisplaySequence);

			ReleaseFactory();

			var chargeTableHits = Factory.GetTableHitCount(JobCharge.Schema.TableName);
			AssertEquals("chargeTableHits", 0, chargeTableHits);

			var shipmentInNewFactory = Factory.Load(shipment.GetType(), shipment.PK);
			var jobInNewFactory = new Loader((IJobHeaderParent)shipmentInNewFactory).Load(true);
			AssertNotNull("Precondition: PlugInData is initialized and so SetJobDefaults is called", jobInNewFactory.PlugInData);
			Charge newCharge1;
			Charge newCharge2;
			using (jobInNewFactory.ChargesLoadSuspender.GetSuspender())
			{
				AssertEquals("collection loading suspended and job initialization shouldn't load charges if no default values changed", 0, jobInNewFactory.Charges.Count);

				newCharge1 = jobInNewFactory.Charges.AddNew();
				newCharge2 = jobInNewFactory.Charges.AddNew();
				AssertEquals("Only new charge should be in collection as loading suspended", 2, jobInNewFactory.Charges.Count);
				AssertEquals("new charge1 JR_DisplaySequence", (ZShort)2, newCharge1.JR_DisplaySequence);
				AssertEquals("new charge2 JR_DisplaySequence", (ZShort)3, newCharge2.JR_DisplaySequence);
				newCharge2.JR_DisplaySequence = 2;
				AssertHasRowWarning(newCharge2, "Charges with duplicated sequence values will be displayed in the order that they were entered.");
				newCharge2.JR_DisplaySequence = 3;
				AssertNoRowErrors(newCharge2);
			}

			chargeTableHits = Factory.GetTableHitCount(JobCharge.Schema.TableName);
			AssertEquals("chargeTableHits", 0, chargeTableHits);

			var charges = jobInNewFactory.Charges;
			AssertEquals("all charges should be in collection", 4, charges.Count);
			Assert("existed charge1 in collection after load", charges.Contains(charge.PK));
			Assert("existed charge2 in collection after load", charges.Contains(charge2.PK));
			Assert("new charge1 in collection after load", charges.Contains(newCharge1.PK));
			Assert("new charge2 in collection after load", charges.Contains(newCharge2.PK));
			AssertEquals("charge1 JR_DisplaySequence", (ZShort)1, charges[0].JR_DisplaySequence);
			AssertEquals("charge2 JR_DisplaySequence", (ZShort)2, charges[1].JR_DisplaySequence);
			AssertEquals("charge3 JR_DisplaySequence", (ZShort)3, charges[2].JR_DisplaySequence);
			AssertEquals("charge4 JR_DisplaySequence", (ZShort)4, charges[3].JR_DisplaySequence);

			chargeTableHits = Factory.GetTableHitCount(JobCharge.Schema.TableName);
			AssertEquals("chargeTableHits", 1, chargeTableHits);
		}

		public void TestChargeIsDeletedFromCollectionWhenAddedUnderLoadingSuspender()
		{
			var job = TestObjectCreator.Job1;
			Factory.Save();
			ReleaseFactory();
			var jobInNewFactory = new BusinessObjectFactory().Load<Job>(job.PK);
			Charge charge = null;
			using (jobInNewFactory.ChargesLoadSuspender.GetSuspender())
			{
				Assert("Precondition: collection is not loaded", !jobInNewFactory.Charges.IsLoaded);
				charge = jobInNewFactory.Charges.AddNew();
				AssertCollectionContains(charge, jobInNewFactory.Charges);
			}

			charge.Delete();
			AssertCollectionNotContains("Collection must not be loaded in the middle of delete process.", charge, jobInNewFactory.Charges);
			Assert("Postcondition: collection is now loaded", jobInNewFactory.Charges.IsLoaded);
		}

		public void TestSuspendSettingHasChangesOnAllChildren()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 10, 10);
			var exRate = job.ExchangeRates.AddNew();
			exRate.JF_RX_NKRateCurrency = "RUB";
			exRate.JF_BaseRate = 100;

			var shipment2 = TestObjectCreator.CreateShipmentWithCoLoadMaster("S0002", "AUSYD", "USLAX", shipment);
			var job2 = TestObjectCreator.CreateJob(shipment2, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			var charge2 = TestObjectCreator.CreateCharge(job2, TestObjectCreator.CC1, 20, 20);

			Factory.Save();
			AssertEquals("saved charge JR_DisplaySequence", (ZShort)1, charge.JR_DisplaySequence);

			ReleaseFactory();

			var shipmentInNewFactory = Factory.Load(shipment.GetType(), shipment.PK);
			var jobInNewFactory = new Loader((IJobHeaderParent)shipmentInNewFactory).Load(true);
			AssertNotNull("Precondition: PlugInData is initialized and so SetJobDefaults is called", jobInNewFactory.PlugInData);
			var shipment2InNewFactory = Factory.Load(shipment.GetType(), shipment2.PK);
			var job2InNewFactory = new Loader((IJobHeaderParent)shipment2InNewFactory).Load(true);
			AssertNotNull("Precondition: PlugInData is initialized and so SetJobDefaults is called", job2InNewFactory.PlugInData);

			var newCharge1 = jobInNewFactory.Charges.AddNew();
			var newCharge2 = jobInNewFactory.Charges.AddNew();

			// SuspendSettingHasChangesOnAllChildrenIfInPlugInGUI not in InvoicingPlugIn GUI
			AssertEquals("Precondition: No Context set on the factory", false, jobInNewFactory.Factory.HasContext(BusinessContext.InvoicingPlugInGUI));
			using (jobInNewFactory.SuspendSettingHasChangesOnAllChildren())
			{
				AssertIsSettingHasChangesSuspended(jobInNewFactory, job2InNewFactory, true);
			}

			// SuspendSettingHasChangesOnAllChildrenIfInPlugInGUI in InvoicingPlugIn GUI
			jobInNewFactory.Factory.SetContext(BusinessContext.InvoicingPlugInGUI);
			AssertEquals("Precondition: Context set on the factory", true, jobInNewFactory.Factory.HasContext(BusinessContext.InvoicingPlugInGUI));
			using (jobInNewFactory.SuspendSettingHasChangesOnAllChildren())
			{
				AssertIsSettingHasChangesSuspended(jobInNewFactory, job2InNewFactory, true);
			}

			AssertIsSettingHasChangesSuspended(jobInNewFactory, job2InNewFactory, false);
		}

		public void TestHasChangesAfterLoadForAutoPopulate()
		{
			var shipment = TestObjectCreator.CreateShipment("S0003", "AUSYD", "USLAX");
			var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, "desc", TestObjectCreator.AUD, 2000m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 2000m, TestObjectCreator.ABIGAS);

			Factory.Save();

			Assert("Precondition: ", !charge.HasChanges);
			job.Creditor = charge.JR_OH_CostAccount;
			job.LoadForAutoPopulate();
			Assert("Postcondition1: ", job.ChargesForAutoPopulate.Contains(charge));
			Assert("Value must not be changed", !charge.HasChanges);

			charge.JR_Desc = "Test1";
			Assert("Precondition: ", charge.HasChanges);
			job.LoadForAutoPopulate();
			Assert("Postcondition2: ", job.ChargesForAutoPopulate.Contains(charge));
			Assert("Value must not be changed", charge.HasChanges);
		}

		void AssertIsSettingHasChangesSuspended(Job jobInNewFactory, Job job2InNewFactory, bool isSuspended)
		{
			AssertEquals("Job.IsSettingHasChangesSuspended", isSuspended, jobInNewFactory.IsSettingHasChangesSuspended);

			var charges = jobInNewFactory.Charges;
			AssertEquals("all charges should be in collection", 4, charges.Count);

			var exRates = jobInNewFactory.ExchangeRates;
			Assert("Should be some ExchangeRates", exRates.Count > 0);
			foreach (var rate in exRates)
			{
				AssertEquals("ExchangeRate.IsSettingHasChangesSuspended", isSuspended, rate.IsSettingHasChangesSuspended);
			}

			AssertEquals("Job2.IsSettingHasChangesSuspended should be always false", false, job2InNewFactory.IsSettingHasChangesSuspended);
		}

