			var wip1 = TestObjectCreator.CreateWIP(job1);
			var acr1 = TestObjectCreator.CreateAccrual(job1);
			Factory.Save();

			Assert(!job1.HasOrphanWIPsorAccruals);

			var shipment2 = TestObjectCreator.CreateShipment("S001002");
			var job2 = TestObjectCreator.CreateJob(shipment2, false, false);

			var wip2 = TestObjectCreator.CreateWIP(job2);
			var wip2Charge = wip2.LoadRelatedJobCharge();
			wip2.RelatedJobCharge.ReverseWIP(ZDateTime.Now);
			wip2.AL_ReverseDate = ZDateTime.Empty;
			Factory.Save();

			Assert(job2.HasOrphanWIPsorAccruals);

			wip2Charge.JR_AL_ARLine = wip2.PK;
			Factory.Save();

			Assert(!job1.HasOrphanWIPsorAccruals);

			var acr2 = TestObjectCreator.CreateAccrual(job2);
			acr2.RelatedJobCharge.ReverseAccrual(ZDateTime.Now);
			acr2.AL_ReverseDate = ZDateTime.Empty;
			Factory.Save();

			Assert(job2.HasOrphanWIPsorAccruals);
		}

