		public void TestAddressContactCallRefreshBindingForCharges()
		{
			var localClient = TestObjectCreator.LocalClient;
			var localClientAddress = TestObjectCreator.CreateAddress(localClient);
			var localClientContact = TestObjectCreator.CreateContact(localClient);
			var agent = TestObjectCreator.Agent;
			var agentAddress = TestObjectCreator.CreateAddress(agent);
			var someOtherDebtor = TestObjectCreator.Debtor;

			var job = TestJob;
			job.LocalChargesPK = localClient.PK;
			job.AgentCollectPK = agent.PK;

			var chargeLocalClient = job.Charges.AddNew();
			chargeLocalClient.JR_OH_SellAccount = localClient.PK;
			bool chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
			bool chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
			chargeLocalClient.JR_OA_SellInvoiceAddressInfo.ValueChanged += (sender, e) => chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged = true;
			chargeLocalClient.JR_OC_SellInvoiceContactInfo.ValueChanged += (sender, e) => chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged = true;

			bool chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
			bool chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
			var chargeAgent = job.Charges.AddNew();
			chargeAgent.JR_OH_SellAccount = agent.PK;
			chargeAgent.JR_OA_SellInvoiceAddressInfo.ValueChanged += (sender, e) => chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged = true;
			chargeAgent.JR_OC_SellInvoiceContactInfo.ValueChanged += (sender, e) => chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged = true;

			bool chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
			bool chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
			var chargeSomeOtherDebtor = job.Charges.AddNew();
			chargeSomeOtherDebtor.JR_OH_SellAccount = someOtherDebtor.PK;
			chargeSomeOtherDebtor.JR_OA_SellInvoiceAddressInfo.ValueChanged += (sender, e) => chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged = true;
			chargeSomeOtherDebtor.JR_OC_SellInvoiceContactInfo.ValueChanged += (sender, e) => chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged = true;

			Action resetValueChangedFlags = () =>
			{
				chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
				chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
				chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
				chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
				chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged = false;
				chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged = false;
			};

			resetValueChangedFlags();
			job.JH_OA_LocalChargesAddr = localClientAddress.PK;
			var messagePrefix = "setting local client address: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", true, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);

			resetValueChangedFlags();
			job.JH_OA_LocalChargesAddr = job.JH_OA_LocalChargesAddr;
			messagePrefix = "setting the same local client address: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);

			resetValueChangedFlags();
			job.JH_OC_LocalBillingContact = localClientContact.PK;
			messagePrefix = "setting local client contact: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", true, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);

			resetValueChangedFlags();
			job.JH_OC_LocalBillingContact = job.JH_OC_LocalBillingContact;
			messagePrefix = "setting the same local client contact: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);

			resetValueChangedFlags();
			job.JH_OA_AgentCollectAddr = agentAddress.PK;
			messagePrefix = "setting agent address: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", true, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);

			resetValueChangedFlags();
			job.JH_OA_AgentCollectAddr = job.JH_OA_AgentCollectAddr;
			messagePrefix = "setting the same agent address: ";
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeLocalClient_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeLocalClient_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeAgent_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeAgent_JR_OC_SellInvoiceContactInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OA_SellInvoiceAddressInfo_ValueChanged);
			AssertEquals(messagePrefix + "chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged", false, chargeSomeOtherDebtor_JR_OC_SellInvoiceContactInfo_ValueChanged);
		}

		[TestDate(2017, 03, 10)]
		public void TestChangingLocalClientOrOverseasAgentResetsChargeDebtor()
		{
			var helper = new TestHelper(Factory);

			var validLocalClient = helper.NewOrgHeader();
			validLocalClient.OH_IsDebtor = true;
			var invalidLocalClient = helper.NewOrgHeader();
			invalidLocalClient.OH_IsDebtor = false;

			var validOverseasAgent = helper.NewOrgHeader();
			validOverseasAgent.OH_IsDebtor = true;
			var invalidOverseasAgent = helper.NewOrgHeader();
			invalidOverseasAgent.OH_IsDebtor = false;

			var consignee = helper.NewOrgHeader();
			var consignor = helper.NewOrgHeader();

			var cnrInvalidDebtorAFT = helper.NewOrgHeader();
			cnrInvalidDebtorAFT.OH_Code = "CNRIFT";
			cnrInvalidDebtorAFT.OH_IsDebtor = false;
			consignor.SetRelatedParty(cnrInvalidDebtorAFT, RelatedPartyTypeList.Codes.InvoiceFreightJobsTo, RelatedPartyDirectionList.Codes.Pickup);

			Factory.SetContext(BusinessContext.InvoicingPlugInGUI);

			var fRT_ChargeCode = helper.ChargeCodes.New("FRT1", "FRT", FlatCalculator.Code, ChargeCodeGroupList.Codes.Freight);
			var oDOC_ChargeCode = helper.ChargeCodes.New("ODC1", "ODOC", FlatCalculator.Code, ChargeCodeGroupList.Codes.Origin);

			var importShipment = TestObjectCreator.CreateShipment("IMPORT_SHP");
			importShipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			importShipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			importShipment.JS_RL_NKOrigin = "USLAX";
			importShipment.JS_RL_NKDestination = "AUSYD";
			importShipment.JS_INCO = Constants.IncoTerms.FreeOnBoard;

			using (var testJob = Job.CreateWithMutex(Factory, importShipment))
			{
				testJob.PlugInData = importShipment;
				testJob.LocalChargesPK = ZGuid.Empty;

				var frtCharge = testJob.Charges.AddNew();
				frtCharge.JR_AC = fRT_ChargeCode.PK;
				frtCharge.JR_OH_SellAccount = ZGuid.Empty;

				var odocCharge = testJob.Charges.AddNew();
				odocCharge.JR_AC = oDOC_ChargeCode.PK;
				odocCharge.JR_OH_SellAccount = ZGuid.Empty;

				var postedCharge = testJob.Charges.AddNew();
				postedCharge.JR_AL_ARLine = Factory.New<ARInvoiceLine>().PK;

				AssertEquals("Prerequisite: IsRevenuePosted", true, postedCharge.IsRevenuePosted);
				AssertEquals("Prerequisite: sell account not set", ZGuid.Empty, frtCharge.JR_OH_SellAccount);
				AssertEquals("Prerequisite: sell account not set", ZGuid.Empty, odocCharge.JR_OH_SellAccount);

				testJob.LocalChargesPK = validLocalClient.PK;

				AssertEquals("Should default to local client", validLocalClient.PK, frtCharge.JR_OH_SellAccount);
				AssertEquals("Should be empty", ZGuid.Empty, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);

				testJob.AgentCollectPK = validOverseasAgent.PK;

				AssertEquals("Should remain local client", validLocalClient.PK, frtCharge.JR_OH_SellAccount);
				AssertEquals("Should default to overseas agent", validOverseasAgent.PK, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);

				testJob.LocalChargesPK = invalidLocalClient.PK;

				AssertEquals("Sell account should be empty", ZGuid.Empty, frtCharge.JR_OH_SellAccount);
				AssertEquals("Should remain overseas agent", validOverseasAgent.PK, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);

				testJob.AgentCollectPK = invalidOverseasAgent.PK;

				AssertEquals("Sell account should be blank", ZGuid.Empty, frtCharge.JR_OH_SellAccount);
				AssertEquals("Sell account should be blank", ZGuid.Empty, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);

				var validLocalClient2 = helper.NewOrgHeader();
				validLocalClient2.OH_IsDebtor = true;
				var validOverseasAgent2 = helper.NewOrgHeader();
				validOverseasAgent2.OH_IsDebtor = true;

				testJob.LocalChargesPK = validLocalClient2.PK;
				AssertEquals("Sell account should be new client", validLocalClient2.PK, frtCharge.JR_OH_SellAccount);
				AssertEquals("Sell account should be blank", ZGuid.Empty, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);

				testJob.AgentCollectPK = validOverseasAgent2.PK;
				AssertEquals("Sell account should be new client", validLocalClient2.PK, frtCharge.JR_OH_SellAccount);
				AssertEquals("Sell account should be changed", validOverseasAgent2.PK, odocCharge.JR_OH_SellAccount);
				AssertEquals("Should remain empty", ZGuid.Empty, postedCharge.JR_OH_SellAccount);
			}
		}

		public void TestLoadForAutoPopulateExcludesApportionedCharges()
		{
			var consol = TestObjectCreator.CreateConsol("KRSEL", "AUSYD", "C1");
			var shipment1 = TestObjectCreator.CreateShipment("S1", consol);
			var shipment2 = TestObjectCreator.CreateShipment("S2", consol);
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.AALSHI, 1000m, false);
			Factory.Save();

			Job job = Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, shipment2.PK));
			AssertEquals("Should be one charge", 1, job.Charges.Count);
			AssertEquals("the charge should be apportioned", 1, job.Charges.Where(x => x.JR_IsApportioned).Count());

			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, "desc", TestObjectCreator.AUD, 2000m, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 2000m, TestObjectCreator.ABIGAS);
			AssertEquals("Should be two charge", 2, job.Charges.Count);
			AssertEquals("the charges should have one apportionment charge", 1, job.Charges.Where(x => x.JR_IsApportioned).Count());
			AssertEquals("the charges should have one non-apportionment charge", 1, job.Charges.Where(x => !x.JR_IsApportioned).Count());

			job.Creditor = charge.JR_OH_CostAccount;
			job.LoadForAutoPopulate();
			AssertEquals("Should be one charge for auto populate", 1, job.ChargesForAutoPopulate.Count);
			AssertEquals("The charge should be non apportioned", 1, job.ChargesForAutoPopulate.Where(x => !x.JR_IsApportioned).Count());
		}

