		[TestDate(2020, 01, 01)]
		public void TestIsPastAllowedRestrictionDate()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", "CNSHA", "AUSYD", transportMode: TransportModes.Sea);
			using (Job job = Job.CreateWithMutex(Factory, shipment))
			{
				job.JH_A_JOP = new ZDateTime(2019, 12, 20);

				var header = new JobClosureConfigurationHeader();
				var configLine = header.ConfigurationCollection.AddNew();
				configLine.JobType = "SHP";
				configLine.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
				configLine.Mode = TransportModes.Sea;
				configLine.JobClosureDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
				configLine.Offset = 5;
				configLine.ReopenRestrictionOffset = 7;
				AccountingConfigurationRegistry.Instance.JobClosureConfigurationSetup.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, header);

				Assert(job.IsPastAllowedRestrictionDate());

				job.JobClosureConfiguration_ForTestOnly = null;
				configLine.ReopenRestrictionOffset = 0;
				AccountingConfigurationRegistry.Instance.JobClosureConfigurationSetup.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, header);

				Assert(!job.IsPastAllowedRestrictionDate());
			}
		}

		[TestDate(2020, 01, 01)]
		public void TestTryToGetReOpenRestirctionDate()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", "CNSHA", "AUSYD", transportMode: TransportModes.Sea);
			var shipment1 = TestObjectCreator.CreateShipment("S00002", "CNSHA", "AUSYD", transportMode: TransportModes.Air);
			using (Job job = Job.CreateWithMutex(Factory, shipment))
			using (Job job1 = Job.CreateWithMutex(Factory, shipment1))
			{
				var reopenRestrictionDate = job.TryToGetReOpenRestirctionDate_ForTestOnly();
				AssertEquals(ZDateTime.Empty, reopenRestrictionDate);

				var header = new JobClosureConfigurationHeader();
				var configLine = header.ConfigurationCollection.AddNew();
				configLine.JobType = "SHP";
				configLine.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
				configLine.Mode = TransportModes.Air;
				configLine.JobClosureDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
				configLine.Offset = 5;
				configLine.ReopenRestrictionOffset = 7;

				AccountingConfigurationRegistry.Instance.JobClosureConfigurationSetup.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, header);

				reopenRestrictionDate = job.TryToGetReOpenRestirctionDate_ForTestOnly();
				AssertEquals(ZDateTime.Empty, reopenRestrictionDate);

				shipment.JS_TransportMode = TransportModes.Air;
				reopenRestrictionDate = job.TryToGetReOpenRestirctionDate_ForTestOnly();
				AssertEquals(ZDateTime.Today.AddDays(configLine.ReopenRestrictionOffset), reopenRestrictionDate);

				configLine.ReopenRestrictionOffset = 0;
				AccountingConfigurationRegistry.Instance.JobClosureConfigurationSetup.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, header);

				reopenRestrictionDate = job1.TryToGetReOpenRestirctionDate_ForTestOnly();
				AssertEquals(ZDateTime.Empty, reopenRestrictionDate);
			}
		}

