			AssertEquals("Precondition: Is Gateway billing Job", true, gatewayConsolJob.IsGatewayBillingJob());
			AssertEquals("Collect Agent should be null as there is no Receiving Forwarder", null, gatewayConsolJob.AgentCollect);
