				charge.JR_AC = org.PK;
				AssertEquals(sendingAgent.PK, charge.JR_OH_SellAccount);

				charge = job.Charges.AddNew();
				charge.JR_AC = frt.PK;
				AssertEquals(receivingAgent.PK, charge.JR_OH_SellAccount);
