		public void TestJobDescription()
		{
			var jobInvoiceDescriptionConfig = AccountingConfigurationRegistry.Instance.JobInvoiceDescriptionConfiguration.Value;
			var item = jobInvoiceDescriptionConfig.AddNew();
			item.JobType = "GCN";
			item.Mode = "AIR";
			item.DirectionCode = "ALL";
			item.InvoiceDescription = "Consol: <ConsolNumber>";
			AccountingConfigurationRegistry.Instance.JobInvoiceDescriptionConfiguration.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, jobInvoiceDescriptionConfig);

			var consol1 = TestObjectCreator.CreateGatewayConsol("USCHI", "AUSYD", "C001001", receivingGatewayCompany: GlbCompany.CurrentCompany);
			var consolJob1 = new JobHeader.Loader(consol1).TryLoadOrCreateWithoutMutexForTestOnly() as Job;
			AssertNotNull(consolJob1);
			AssertEquals("JH_Description", ZString.Empty, consolJob1.JH_Description);
			AssertEquals("JobDescription is not overriden", false, consolJob1.IsJobDescriptionOverriden);
			AssertEquals("IsJobDescriptionOverridenInfo.ReadOnly", false, consolJob1.IsJobDescriptionOverridenInfo.ReadOnly);
			AssertEquals("JobDescription", "Consol: C001001", consolJob1.JobDescription);
			AssertEquals("JobDescriptionInfo.ReadOnly", true, consolJob1.JobDescriptionInfo.ReadOnly);

			consolJob1.JH_Description = "My Job Description";
			AssertEquals("JobDescription is overriden", true, consolJob1.IsJobDescriptionOverriden);
			AssertEquals("IsJobDescriptionOverridenInfo.ReadOnly", false, consolJob1.IsJobDescriptionOverridenInfo.ReadOnly);
			AssertEquals("JobDescription", "My Job Description", consolJob1.JobDescription);
			AssertEquals("JobDescriptionInfo.ReadOnly", false, consolJob1.JobDescriptionInfo.ReadOnly);

			Env.Security.ModifyJobDescription.IsAllowed = false;
			AssertEquals("IsJobDescriptionOverridenInfo.ReadOnly without permissions", true, consolJob1.IsJobDescriptionOverridenInfo.ReadOnly);
			AssertEquals("JobDescriptionInfo.ReadOnly without permissions", true, consolJob1.JobDescriptionInfo.ReadOnly);

			Env.Security.ModifyJobDescription.IsAllowed = true;
			AssertEquals("IsJobDescriptionOverridenInfo.ReadOnly", false, consolJob1.IsJobDescriptionOverridenInfo.ReadOnly);
			AssertEquals("JobDescriptionInfo.ReadOnly", false, consolJob1.JobDescriptionInfo.ReadOnly);

			consolJob1.IsJobDescriptionOverriden = false;
			AssertEquals("JobDescription reset to default", "Consol: C001001", consolJob1.JobDescription);

			var consol2 = TestObjectCreator.CreateGatewayConsol("USCHI", "AUSYD", "C0123456789012345678", receivingGatewayCompany: GlbCompany.CurrentCompany);
			var consolJob2 = new JobHeader.Loader(consol2).TryLoadOrCreateWithoutMutexForTestOnly() as Job;
			AssertNotNull(consolJob2);
			AssertEquals("JH_Description", ZString.Empty, consolJob2.JH_Description);
			AssertEquals("JobDescription is not overriden", false, consolJob2.IsJobDescriptionOverriden);

			item.InvoiceDescription = "Consol:<ConsolNumber>-<ConsolNumber>-<ConsolNumber>-<ConsolNumber>-<ConsolNumber>-<ConsolNumber>"; // Should exceed JH_Description max length (100) when parsed
			AccountingConfigurationRegistry.Instance.JobInvoiceDescriptionConfiguration.SetValue(Env.CurrentCompany.PK, Guid.Empty, Guid.Empty, jobInvoiceDescriptionConfig);

			Assert("JobDescription", consolJob2.JobDescription.StartsWith("Consol:C0123456789012345678-"));
			AssertEquals("JobDescription Length", consolJob2.JH_DescriptionInfo.MaxLength, consolJob2.JobDescription.Length);
		}

