		public void TestTimeJobWasLoaded()
		{
			AssertNotEquals("Precondition: ZDateTime.UTCNow.ToDateTime() should not be the same as ZDateTime.Now.ToDateTime()", ZDateTime.Now.ToDateTime(), ZDateTime.UtcNow.ToDateTime());

			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment);
			ZDateTime departureDate = ZDateTime.Now;
			shipment.JS_E_DEP = departureDate;

			AssertEquals("Empty for an unsaved job", ZDateTime.Empty, job.UtcTimeJobWasLoaded);
			Factory.Save();
			AssertDateTimeWithinOneSecond("Should be set when job is saved for the first time", ZDateTime.UtcNow.ToDateTime(), job.UtcTimeJobWasLoaded.ToDateTime());

			BusinessObjectFactory newFactoryForLoading = new BusinessObjectFactory();
			Job loadedJob = newFactoryForLoading.Load<Job>(job.PK);
			AssertDateTimeWithinOneSecond("Job.TimeJobWasLoaded after loading the job", ZDateTime.UtcNow.ToDateTime(), loadedJob.UtcTimeJobWasLoaded.ToDateTime());

			DateTime anotherDate = ZDateTime.UtcNow.AddSeconds(30).ToDateTime();
			loadedJob.UtcTimeJobWasLoaded = anotherDate;
			AssertEquals("Job.TimeJobWasLoaded after setting the value manually", anotherDate, loadedJob.UtcTimeJobWasLoaded.ToDateTime());
		}

		public void TestHasBeenAutoRatedByAnotherUserAfterBeingLoaded()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment);
			var chargeCode = TestObjectCreator.CC1;
			var organisation = TestObjectCreator.ABIGAS;
			var currency = TestObjectCreator.AUD;
			var testUser = Factory.NewWithValidTestData<GlbStaff>();
			testUser.GS_Code = "MAR";
			testUser.GS_LoginName = "MrAutoRating";
			testUser.GS_FullName = "Mr AutoRating";

			TestObjectCreator.NonCurrentBranch.GB_RL_NKHomePort = "NZAKL";
			Factory.Save();

			var newFactoryForLoading = new BusinessObjectFactory();
			shipment = newFactoryForLoading.Load<ForwardingShipment>(shipment.PK);
			job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			job.LocalChargesPK = organisation.PK;

			var log = new TestInteractor();
			var starter = new AutoRatingStarter(shipment, log);
			starter.ExecuteAutorating(AutoRateOptions.AutorateCosts);

			var expectedMessage = "Mr AutoRating (MAR) has run autorating on this job.";

			AssertEquals("Message (after job was loaded)", false, log.Information.Any(i => i.Contains(expectedMessage)));

			using (TestObjectCreator.NonCurrentBranch.SetAsTemporaryContext())
			{
				var factoryToSimulateSecondUser = new BusinessObjectFactory();
				factoryToSimulateSecondUser.RefreshEnabled = false;

				var shipmentLoadedBySecondUser = factoryToSimulateSecondUser.Load<ForwardingShipment>(shipment.PK);
				var jobLoadedBySecondUser = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();

				var autoratingLog = shipmentLoadedBySecondUser.Logs.AddNew(Events.ChargesHaveBeenAutoRated);
				using (autoratingLog.LockForUpdatingKeyFieldsForTesting())
				{
					autoratingLog.SL_GS_NKUser = "MAR";
					autoratingLog.SL_Reference = "Company: " + Env.CurrentCompany.Code;
					var charge = TestObjectCreator.CreateCharge(jobLoadedBySecondUser, chargeCode, "DESC", currency, 100M, organisation, currency, 100M, organisation);
					jobLoadedBySecondUser.LocalChargesPK = organisation.PK;
				}

				factoryToSimulateSecondUser.Save();
			}

			log = new TestInteractor();
			starter = new AutoRatingStarter(shipment, log);
			starter.ExecuteAutorating(AutoRateOptions.AutorateCosts);

			AssertEquals("Message (after another user has autorated)", true, log.Information.Any(i => i.Contains(expectedMessage)));

			System.Threading.Thread.Sleep(2000);
			job.UtcTimeJobWasLoaded = ZDateTime.UtcNow;
			starter.ExecuteAutorating(AutoRateOptions.AutorateCostsRevenue);

			log = new TestInteractor();
			starter = new AutoRatingStarter(shipment, log);
			starter.ExecuteAutorating(AutoRateOptions.AutorateCosts);

			AssertEquals("Message (after resetting the load time)", false, log.Information.Any(i => i.Contains(expectedMessage)));
		}

		[DisableZeroExchangeRateOverriding]
		public void TestGetBuyExchangeRate()
		{
			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment);

			var jobPluginWIN = TestObjectCreator.CreateJobPlugIn(JobInvoicingConsumerTypes.WarehouseInwards);
			var jobWIN = TestObjectCreator.CreateJob(jobPluginWIN, false);
			BusinessObject bizoWIN = ((BusinessObject)jobPluginWIN);
			var finalisedDate = new ZDateTime(2016, 2, 9);
			bizoWIN[WhsDocketSchema.Constants.WD_DocketStatus] = "FIN";
			bizoWIN[WhsDocketSchema.Constants.WD_FinalisedDate] = finalisedDate;

			var jobPluginWOU = TestObjectCreator.CreateJobPlugIn(JobInvoicingConsumerTypes.WarehouseOutwards);
			var jobWOU = TestObjectCreator.CreateJob(jobPluginWOU, false);
			BusinessObject bizoWOU = ((BusinessObject)jobPluginWOU);
			var requireDate = new ZDateTime(2016, 2, 11);
			bizoWOU[WhsDocketSchema.Constants.WD_RequiredDate] = requireDate;

			var jobPluginTRN = TestObjectCreator.CreateJobPlugIn(JobInvoicingConsumerTypes.LocalCartage);
			var jobTRN = TestObjectCreator.CreateJob(jobPluginTRN, false);
			BusinessObject bizoTRN = ((BusinessObject)jobPluginTRN);
			var deliveryDate = new ZDateTime(2016, 2, 17);
			bizoTRN[JobCartageSchema.Constants.JJ_EstimatedDelivery] = deliveryDate;

			ZDateTime departureDate = ZDateTime.Now;
			shipment.JS_E_DEP = departureDate;

			Factory.Save();

			Enterprise.ZArchitecture.Core.ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals("Null pluginData", ZDecimal.Zero, AccExchangeRateConfigurationRateFinder.GetExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));

			job.PlugInData = shipment;
			Factory.Save();

			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate("SHP", "IMP", "ALL", preference: "HAR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate("SHP", "EXP", "ALL", preference: "HDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate("TRN", "IMP", "SEA", preference: "ESD");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate("WIN", "ALL", "ALL", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate("WOU", "ALL", "ALL", preference: "TDR");
			GlbCompany.CurrentCompany.Factory.Save();

			AccountingConfigurationRegistry.Instance.FallBackToPreviousExchangeRate.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);

			RefExchangeRate rate = TestObjectCreator.AUD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Today;
			rate.RE_ExpiryDate = ZDateTime.Today;
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 0.131506272M;

			rate = TestObjectCreator.AUD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Today.AddDays(1);
			rate.RE_ExpiryDate = ZDateTime.Today.AddDays(10);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 3.0m;

			rate = TestObjectCreator.AUD.ExchangeRates.AddNew();
			rate.RE_StartDate = finalisedDate;
			rate.RE_ExpiryDate = finalisedDate;
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 0.54m;

			rate = TestObjectCreator.USD.ExchangeRates.AddNew();
			rate.RE_StartDate = requireDate;
			rate.RE_ExpiryDate = requireDate;
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 3.599m;

			rate = TestObjectCreator.EUR.ExchangeRates.AddNew();
			rate.RE_StartDate = deliveryDate;
			rate.RE_ExpiryDate = deliveryDate;
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 2.9m;

			Factory.Save();

			var reloadFactory = new BusinessObjectFactory();
			var reloadedJob = reloadFactory.Load<Job>(job.PK);
			reloadedJob.InitializeParentFromGenericJobWithoutSettingDefaults();
			var reloadedJobWIN = reloadFactory.Load<Job>(jobWIN.PK);
			reloadedJobWIN.InitializeParentFromGenericJobWithoutSettingDefaults();
			var reloadedJobWOU = reloadFactory.Load<Job>(jobWOU.PK);
			reloadedJobWOU.InitializeParentFromGenericJobWithoutSettingDefaults();
			var reloadedJobTRN = reloadFactory.Load<Job>(jobTRN.PK);
			reloadedJobTRN.InitializeParentFromGenericJobWithoutSettingDefaults();

			Enterprise.ZArchitecture.Core.ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals(0.131506m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(reloadedJob.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));
			AssertEquals(0.131506m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(reloadedJobWIN.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));
			AssertEquals(0m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(reloadedJobWOU.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, null, ExchangeRateValidLedgerEnum.AR));
			AssertEquals(2.9m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(reloadedJobTRN.ExchangeRateConfigurationRateConsumer, TestObjectCreator.EUR, null, ExchangeRateValidLedgerEnum.AR));
		}

