		#region Exchange Rate Configuration Tests for Pickup and Delivery Date When Job Is Shipment

		Job GetShipmentJob(bool withActualDate, bool withEstimatedDate)
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "USLAX", "C001");
			var shipment = TestObjectCreator.CreateShipment("S001", "AUSYD", "USLAX");
			consol.Shipments.Add(shipment);
			consol.Transports.MostInterestingTransport.JW_ETD = ZDateTime.Today;
			if (withActualDate)
			{
				shipment.DocsAndCartage.JP_PickupCartageCompleted = ExpectedExchangeRateDate;
				shipment.DocsAndCartage.JP_DeliveryCartageCompleted = ExpectedExchangeRateDate;
			}
			if (withEstimatedDate)
			{
				shipment.DocsAndCartage.JP_EstimatedPickup = ExpectedExchangeRateDate;
				shipment.DocsAndCartage.JP_EstimatedDelivery = ExpectedExchangeRateDate;
			}
			AssertNotEquals(ExpectedExchangeRateDate, consol.Transports.MostInterestingTransport.JW_ETD);
			return new Loader(shipment).TryLoadOrCreate();
		}

		public void TestGetExchangeRateDate_WhenJobIsShipment_AndWhenJobBillingExchangeRatePreferenceIsPickupDate_ThenDefaultExchangeRateAccordingToActualPickupDate()
		{
			Job shipmentJob = GetShipmentJob(true, false);
			AssertGetExchangeRate(shipmentJob, JobInvoicingConsumerTypes.Shipment.Code, Constants.JobBillingExchangeRatePreference.Code.ShipmentOrBrokeragePickupDate);
		}

