		RefExchangeRate SetExRate_AUD(short year, byte month, decimal rate)
		{
			var newRate = TestObjectCreator.AUD.ExchangeRates.AddNew();
			newRate.RE_StartDate = new DateTime(year, month, 01);
			newRate.RE_ExpiryDate = new DateTime(year, month, 01).AddMonths(1).AddDays(-1);
			newRate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			newRate.RE_SellRate = rate;
			return newRate;
		}

		[DisableZeroExchangeRateOverriding]
		[TestDate(2020, 07, 01)]
		public void TestExchangeRateHBD()
		{
			SetExRate_AUD(2020, 07, 2007m);
			SetExRate_AUD(2020, 06, 2006m);
			var rateHouseBillIssueDate = SetExRate_AUD(2020, 05, 2005m);
			SetExRate_AUD(2020, 04, 2004m);
			SetExRate_AUD(2020, 03, 2003m);
			SetExRate_AUD(2020, 02, 2002m);
			SetExRate_AUD(2020, 01, 2001m);

			var consol = TestObjectCreator.CreateConsol("AUSYD", "USLAX", "C001");
			consol.Transports.MostInterestingTransport.JW_ETD = new ZDateTime(2020, 07, 01);
			consol.Transports.MostInterestingTransport.JW_ETA = new ZDateTime(2020, 06, 01);

			var shipment = TestObjectCreator.CreateShipment("S001", "AUSYD", "USLAX");
			shipment.Consols.Add(consol);
			shipment.JS_E_DEP = new ZDateTime(2020, 04, 01);
			shipment.JS_E_ARV = new ZDateTime(2020, 03, 01);

			var job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			job.Company.AccExchangeRateConfigurations.DeleteAll();
			job.Company.AccExchangeRateConfigurations.SetExRate(
				JobInvoicingConsumerTypes.Shipment.Code,
				"ALL",
				"ALL",
				 preference: Constants.JobBillingExchangeRatePreference.Code.HouseBillIssueDate
			);
			Factory.Save();

			shipment.JS_HouseBillIssueDate = ZDateTime.Empty;
			ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals(0m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));

			shipment.JS_HouseBillIssueDate = new ZDateTime(2020, 05, 01);
			ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals(2005m, rateHouseBillIssueDate.RE_SellRate);
			AssertEquals(2005m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));

			rateHouseBillIssueDate.Delete();
			Factory.Save();

			AccountingConfigurationRegistry.Instance.FallBackToPreviousExchangeRate.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals(0m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));

			AccountingConfigurationRegistry.Instance.FallBackToPreviousExchangeRate.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			ExchangeRateReader.GetReaderInstance().ClearCache();
			AssertEquals(2004m, AccExchangeRateConfigurationRateFinder.GetExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.AUD, null, ExchangeRateValidLedgerEnum.AR));
		}

