				AssertNull("Should return null for same currency code as current company local currency", exRateProvider.GetExchangeRate(Env.CurrentCompany.LocalCurrency.Code.ToLower(), TestObjectCreator.LocalClient.PK, allLedgers.First(), forceExchangeRateCreation: true)); //, emptyExRateOverride: 1.1m));
