		[DisableZeroExchangeRateOverriding]
		public void TestNoExceptionisThrownWhenMissingExchangeRateIsAddedToTheJob()
		{
			var shipment = TestObjectCreator.CreateShipment("S008", "AUSYD", "USLAX");
			var job = TestObjectCreator.CreateJob(shipment, localClientOrg: TestObjectCreator.LocalClient, agentOrg: TestObjectCreator.Agent);
			var rate1 = job.ExchangeRates.AddRate(TestObjectCreator.USD, 1.5m, TestObjectCreator.Creditor1.PK, ExchangeRateOrgTypeEnum.Creditor);
			rate1.JF_JH = job.PK;
			var rate2 = job.ExchangeRates.AddRate(TestObjectCreator.USD, 1.5m, TestObjectCreator.Debtor1.PK, ExchangeRateOrgTypeEnum.Debtor);
			rate2.JF_JH = job.PK;
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.USD, 250M, TestObjectCreator.Creditor1, TestObjectCreator.USD, 250M, TestObjectCreator.Debtor1);
			rate2.Delete();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var jobInNewFactory = newFactory.Load<Job>(job.PK);
			AssertEquals(1, jobInNewFactory.Charges.Count);
			var newRate = jobInNewFactory.ExchangeRates.AddNew();
			newRate.JF_RX_NKRateCurrency = "USD";
			AssertEquals(0M, newRate.JF_BaseRate);
			AssertEquals("USD", newRate.JF_RX_NKRateCurrency);
		}

