				Assert("Should not fall into infinite recursion", true);
			}
		}

		[DisableZeroExchangeRateOverriding]
		public void TestIExchangeRateProvider_GetExchangeRate()
		{
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "ALL", "ALL", preference: Constants.JobBillingExchangeRatePreference.Code.TodaysRate);

			var rate = TestObjectCreator.USD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Today.AddDays(-2);
			rate.RE_ExpiryDate = ZDateTime.Today.AddDays(2);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 1.56m;

			Factory.Save();
			ExchangeRateReader.GetReaderInstance().ClearCache();

			var shipment = TestObjectCreator.CreateShipment("S001", "AUSYD", "USLAX");
			using (var job = TestObjectCreator.CreateJob(shipment, localClientOrg: TestObjectCreator.LocalClient, agentOrg: TestObjectCreator.Agent))
			{
				var exRateProvider = job as IExchangeRateProvider;
				AssertNotNull(exRateProvider);

				var allLedgers = (ExchangeRateValidLedgerEnum[])Enum.GetValues(typeof(ExchangeRateValidLedgerEnum));
				var allOrgTypes = (ExchangeRateOrgTypeEnum[])Enum.GetValues(typeof(ExchangeRateOrgTypeEnum));
				var allOrgPKs = new ZGuid[] { TestObjectCreator.LocalClient.PK, TestObjectCreator.Agent.PK, TestObjectCreator.Debtor.PK, TestObjectCreator.Creditor1.PK, ZGuid.Empty };

				// Null returned
				foreach (ExchangeRateValidLedgerEnum ledger in allLedgers)
				{
					foreach (var orgPK in allOrgPKs)
					{
						AssertNull("Empty currency", exRateProvider.GetExchangeRate(ZString.Empty, orgPK, ledger, forceExchangeRateCreation: true));
						AssertNull("Local currency", exRateProvider.GetExchangeRate(Env.CurrentCompany.LocalCurrency.Code, orgPK, ledger, forceExchangeRateCreation: true));
					}
				}

				// New Rate created with no system ex rate
				IExchangeRateJobBilling exRate = null;
				IExchangeRateJobBilling crdRate = null;
				foreach (var orgPK in allOrgPKs)
				{
					crdRate = null;
					foreach (var ledger in allLedgers)
					{
						exRate = exRateProvider.GetExchangeRate(TestObjectCreator.EUR.RX_Code, orgPK, ledger, forceExchangeRateCreation: true);
						AssertNotNull($"EUR Exchange Rate for Ledger {ledger} and Org PK {orgPK}", exRate);
						AssertEquals("CurrencyCode", TestObjectCreator.EUR.RX_Code, exRate.CurrencyCode);
						AssertEquals("Rate", 0m, exRate.Rate);
						AssertEquals("OrgPk", orgPK, exRate.OrgPk);
						AssertEquals("OrgType", job.GetJobInvoicingOrgType(ledger), exRate.OrgType);

						if (ledger == ExchangeRateValidLedgerEnum.AP)
						{
							crdRate = exRate;
						}
						if (ledger == ExchangeRateValidLedgerEnum.UA)
						{
							AssertEquals("UA should share the same Exchange Rate as AP", crdRate.ExchangeRatePk, exRate.ExchangeRatePk);
						}
					}
				}
				AssertEquals("Exchange Rates Count", (allLedgers.Length - 1) * allOrgPKs.Length, job.ExchangeRates.Count);
				Assert("All EUR Exchange Rates Count", job.ExchangeRates.Cast<ExchangeRate>().All(x => x.JF_RX_NKRateCurrency == TestObjectCreator.EUR.RX_Code));

				// New Rate created with system ex rate
				foreach (var orgPK in allOrgPKs)
				{
					crdRate = null;
					foreach (ExchangeRateValidLedgerEnum ledger in allLedgers)
					{
						exRate = exRateProvider.GetExchangeRate(TestObjectCreator.USD.RX_Code, orgPK, ledger, forceExchangeRateCreation: true);
						AssertNotNull($"USD Exchange Rate for Ledger {ledger} and Org PK {orgPK}", exRate);
						AssertEquals("CurrencyCode", TestObjectCreator.USD.RX_Code, exRate.CurrencyCode);
						AssertEquals("Rate", 1.56m, exRate.Rate);
						AssertEquals("OrgPk", orgPK, exRate.OrgPk);
						AssertEquals("OrgType", job.GetJobInvoicingOrgType(ledger), exRate.OrgType);

						if (ledger == ExchangeRateValidLedgerEnum.AP)
						{
							crdRate = exRate;
						}
						if (ledger == ExchangeRateValidLedgerEnum.UA)
						{
							AssertEquals("UA should share the same Exchange Rate as AP", crdRate.ExchangeRatePk, exRate.ExchangeRatePk);
						}
					}
				}
				AssertEquals("Exchange Rates Count", 2 * (allLedgers.Length - 1) * allOrgPKs.Length, job.ExchangeRates.Count);

				var eurExRates = job.ExchangeRates.Cast<ExchangeRate>().Where(x => x.JF_RX_NKRateCurrency == TestObjectCreator.EUR.RX_Code).ToArray();
				var usdExRates = job.ExchangeRates.Cast<ExchangeRate>().Where(x => x.JF_RX_NKRateCurrency == TestObjectCreator.USD.RX_Code).ToArray();

				AssertEquals("EUR Exchange Rates Count", (allLedgers.Length - 1) * allOrgPKs.Length, eurExRates.Length);
				AssertEquals("USD Exchange Rates Count", (allLedgers.Length - 1) * allOrgPKs.Length, usdExRates.Length);

				foreach (var orgPK in allOrgPKs)
				{
					foreach (var orgType in allOrgTypes)
					{
						AssertEquals($"EUR Exchange Rate for Org Type {orgType} and Org PK {orgPK}", 1, eurExRates.Count(x => x.JF_OH_Org == orgPK && x.OrgType == orgType));
						AssertEquals($"USD Exchange Rate for Org Type {orgType} and Org PK {orgPK}", 1, usdExRates.Count(x => x.JF_OH_Org == orgPK && x.OrgType == orgType));
					}
				}

				// Existing Rate returned
				foreach (var orgPK in allOrgPKs)
				{
					crdRate = null;
					foreach (var ledger in allLedgers)
					{
						exRate = exRateProvider.GetExchangeRate(TestObjectCreator.USD.RX_Code, orgPK, ledger);
						AssertNotNull($"USD Exchange Rate for Ledger {ledger} and Org PK {orgPK}", exRate);
						AssertNotNull($"USD Exchange Rate for Ledger {ledger} and Org PK {orgPK} should be an existing one", usdExRates.FirstOrDefault(x => x.PK == exRate.ExchangeRatePk));
						AssertEquals("CurrencyCode", TestObjectCreator.USD.RX_Code, exRate.CurrencyCode);
						AssertEquals("Rate", 1.56m, exRate.Rate);
						AssertEquals("OrgPk", orgPK, exRate.OrgPk);
						AssertEquals("OrgType", job.GetJobInvoicingOrgType(ledger), exRate.OrgType);
					}
				}
			}
		}

		#endregion

		public void TestGetExchangeRate()
		{
			var allOrgPKs = new ZGuid[] { TestObjectCreator.LocalClient.PK, TestObjectCreator.Agent.PK, TestObjectCreator.Debtor.PK, ZGuid.Empty };
			var allOrgTypes = (ExchangeRateOrgTypeEnum[])Enum.GetValues(typeof(ExchangeRateOrgTypeEnum));
			var allExRateTypes = (ExchangeRateType[])Enum.GetValues(typeof(ExchangeRateType));

			var cfx = 10m;
			foreach (var orgPK in allOrgPKs)
			{
				if (orgPK.IsValid)
				{
					var org = Factory.Load<OrgHeader>(orgPK);
					org.CompanyData.AccCFXConfigurations.SetUplifts("ALL", OrgConstants.ServiceDirection.Code.Export, OrgConstants.ModesForGroupOrSubTotal.Codes.All, cfx);
					cfx += 10m;
				}
			}
			Factory.Save();

			var shipment = TestObjectCreator.CreateShipment("S001", "AUSYD", "USLAX");
			using (var job = TestObjectCreator.CreateJob(shipment, localClientOrg: TestObjectCreator.LocalClient, agentOrg: TestObjectCreator.Agent))
			{
				// Zero returned
				foreach (var rateType in allExRateTypes)
				{
					foreach (var orgPK in allOrgPKs)
					{
						foreach (var orgType in allOrgTypes)
						{
							foreach (var invoiceCurrencyType in new[] { InvoiceCurrencyType.Foreign, InvoiceCurrencyType.Local, InvoiceCurrencyType.NotApplicable })
							{
								AssertEquals("Empty currency", decimal.Zero, job.GetExchangeRate(ZString.Empty, orgPK, orgType, rateType, invoiceCurrencyType));
								AssertEquals("Local currency", decimal.Zero, job.GetExchangeRate(Env.CurrentCompany.LocalCurrency.Code, orgPK, orgType, rateType, invoiceCurrencyType));
							}
						}
					}
				}

				// Only Buy and Sell have exchange rate
				foreach (var rateType in allExRateTypes)
				{
					cfx = 10m;
					var rate = 0.5m;
					foreach (var orgPK in allOrgPKs)
					{
						var org = Factory.Load<OrgHeader>(orgPK);

						foreach (var orgType in allOrgTypes)
						{
							var exRate = job.ExchangeRates.AddRate(TestObjectCreator.USD, rate, orgPK, orgType);
							AssertEquals(rate, exRate.JF_BaseRate);

							var expectedRate = decimal.Zero;
							if (rateType == ExchangeRateType.Sell && orgType == ExchangeRateOrgTypeEnum.Debtor && org != null && org.CompanyData.OB_IsDebtor)
							{
								expectedRate = rate * (100m - cfx) / 100m;  // Sell Rate with CFX
							}
							else if (rateType == ExchangeRateType.Buy || rateType == ExchangeRateType.Sell)
							{
								expectedRate = rate;
							}
							AssertEquals($"USD Exchange Rate of {rateType} for Org Type {orgType} and Org PK {orgPK}", expectedRate, job.GetExchangeRate(TestObjectCreator.USD.RX_Code, orgPK, orgType, rateType));

							rate += 0.01m;
						}

						cfx += 10m;
					}
					AssertEquals("Exchange Rates added ", allOrgPKs.Length * allOrgTypes.Length, job.ExchangeRates.Count);
				}
			}
		}

		public void TestConsolAndShipmentNumbersDontLoadThem()
		{
			var consol1 = TestObjectCreator.CreateConsol("AUSYD", "AUBNE", "C001");
			var consol2 = TestObjectCreator.CreateConsol("AUBNE", "NZAKL", "C002");
			var consol3 = TestObjectCreator.CreateConsol("NZAKL", "USLAX", "C003");
			var shipment = TestObjectCreator.CreateShipment("S001", "AUSYD", "USLAX");
			shipment.JS_HouseBill = "HBNUM123";
			consol1.Shipments.Add(shipment);
			consol2.Shipments.Add(shipment);
			consol3.Shipments.Add(shipment);
			consol1.JK_MasterBillNum = "MBNUM1";
			consol2.JK_MasterBillNum = "MBNUM2";
			consol3.JK_MasterBillNum = "MBNUM3";
			var job = TestObjectCreator.CreateJob(shipment);
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var jobInNewFactory = newFactory.Load<Job>(job.PK);
			ZQuery cacheOnlyFilter = new ZQuery();
			cacheOnlyFilter.FetchOnlyFromLocalCache = true;
			AssertEquals("Precondition: shipments are not loaded.", 0, newFactory.Load<ForwardingShipment>(cacheOnlyFilter).Length);
			AssertEquals("Precondition: consols are not loaded.", 0, newFactory.Load<ForwardingConsol>(cacheOnlyFilter).Length);

			AssertEquals("JobType", JobInvoicingConsumerTypes.Shipment, jobInNewFactory.JobType);

			AssertContainsExactElementsInAnyOrder("JH_ConsolNo",
				new string[] { "C001", "C002", "C003" },
				jobInNewFactory.JH_ConsolNo.ToString().Split(new string[] { ", " }, StringSplitOptions.None));
			AssertContainsExactElementsInAnyOrder("JH_MasterBillNo",
				new string[] { "MBNUM1", "MBNUM2", "MBNUM3" },
				jobInNewFactory.JH_MasterBillNo.ToString().Split(new string[] { ", " }, StringSplitOptions.None));
			AssertEquals("JH_HouseBillNo", "HBNUM123", jobInNewFactory.JH_HouseBillNo);

			AssertEquals("Shipments should not be loaded.", 0, newFactory.Load<ForwardingShipment>(cacheOnlyFilter).Length);
			AssertEquals("Consols should not be loaded.", 0, newFactory.Load<ForwardingConsol>(cacheOnlyFilter).Length);
		}

