		public void TestSubShipmentChargesDoGetLoadedWhenParentIsSetAndDefaultIsNotSetWhenJobLoaded()
		{
			var consol = TestObjectCreator.CreateConsol("AUMEL", "NZAKL", "C001001");
			consol.JK_ConsolMode = "BCN";
			Factory.Save();

			var shipment1 = TestObjectCreator.CreateMasterShipment("S001001", consol);
			Job masterShipmentJob = TestObjectCreator.CreateJob(shipment1, false, true);
			masterShipmentJob.JH_OA_LocalChargesAddr = TestObjectCreator.ABIGAS.Addresses.MainAddress.PK;
			TestObjectCreator.CreateCharge(masterShipmentJob, TestObjectCreator.CC1, 0M, 50M);

			AssertEquals(1, masterShipmentJob.Charges.Count);

			var shipment2 = TestObjectCreator.CreateShipmentWithCoLoadMaster("S001002", consol, shipment1);
			Job subShipmentJob = TestObjectCreator.CreateJob(shipment2, false, true);
			subShipmentJob.JH_OA_LocalChargesAddr = TestObjectCreator.ABIGAS.Addresses.MainAddress.PK;
			TestObjectCreator.CreateCharge(subShipmentJob, TestObjectCreator.CC1, 0M, 100M);

			AssertEquals("We want to load charges only once", 1, masterShipmentJob.Charges.Count);

			masterShipmentJob.SetDefaultsForJob();

			AssertEquals("After calling SetDefaultsForJob we want to again reload the charges.", 2, masterShipmentJob.Charges.Count);

			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			Loader loader = new Loader(newFactory, shipment1);

			Job job = loader.Load(true, false); //While loading job parent should be set but job should not be defaulted

			AssertEquals(@"In case of shipment with sub shipment, if job loaded with parent set but job not defaulted then charges from subshipment are not loaded in the master shipment
					, this eventually causes error while posting.", 2, job.Charges.Count);
		}

		public void TestChargeTypeOverrideCachedForPerformance()
		{
			AccChargeCode testChargeCode = Factory.New<AccChargeCode>();
			testChargeCode.AC_Code = "TESTJ";
			testChargeCode.AC_ChargeType = Core.Constants.ChargeType.Margin;
			testChargeCode.AC_MarginPercentage = 10.5m;

			ForwardingShipment importShipment = Factory.New<ForwardingShipment>();
			importShipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			importShipment.JS_RL_NKOrigin = "USLAX";

			ForwardingShipment exportShipment = Factory.New<ForwardingShipment>();
			exportShipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			exportShipment.JS_RL_NKDestination = "USLAX";

			BaseJobDeclaration declaration = Factory.New<BaseJobDeclaration>();
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;

			Job invoicingJob = Factory.NewJobForTesting<Job>();
			invoicingJob.PlugInData = importShipment;
			AssertEquals("Movement Direction should be import", Directions.Import, invoicingJob.MovementDirection);

			var chargeTypeOverrideInformation1 = invoicingJob.GetChargeTypeOverrideInformation_ForTestOnly(testChargeCode);
			AssertEquals(1, invoicingJob.ChargeTypeCache_ForTestOnly.Count);

			invoicingJob.PlugInData = exportShipment;
			AssertEquals("Movement Direction should be export", Directions.Export, invoicingJob.MovementDirection);
			var chargeTypeOverrideInformation2 = invoicingJob.GetChargeTypeOverrideInformation_ForTestOnly(testChargeCode);
			AssertEquals(2, invoicingJob.ChargeTypeCache_ForTestOnly.Count);
			AssertEquals(chargeTypeOverrideInformation1.PK, chargeTypeOverrideInformation2.PK);

			testChargeCode.AC_ChargeType = Core.Constants.ChargeType.Revenue;
			var chargeTypeOverrideInformation3 = invoicingJob.GetChargeTypeOverrideInformation_ForTestOnly(testChargeCode);
			AssertEquals(3, invoicingJob.ChargeTypeCache_ForTestOnly.Count);
			AssertEquals(chargeTypeOverrideInformation2.PK, chargeTypeOverrideInformation3.PK);

			invoicingJob.ChargeTypeCache_ForTestOnly.Clear();
			AssertEquals(chargeTypeOverrideInformation3.PK, invoicingJob.GetChargeTypeOverrideInformation_ForTestOnly(testChargeCode).PK);
		}

		public void TestQuoteNumberAssignment()
		{
			// there are database hits due to looking for child jobs to attach to job in OnJobCreating for both ForwardingConsol and ForwardingShipment now
			const int expectedHitsOnRefreshingUpdatedConsolJobParent = 2;
			const int expectedHitsOnRefreshingUpdatedShipmentJobParent = 2;

			int initialHitCount;
			ForwardingConsol consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_MasterBillNum = "TEST12345";

			Job consolJob = Factory.NewJobWithValidTestDataForTesting<Job>();

			using (consolJob.GetValidationSuspender())
			using (consolJob.GetSetJobDefaultsSuspender())
			{
				initialHitCount = Factory.DatabaseLoadCount;
				consolJob.Parent = consol;
			}

			AssertEquals("We only have quoted bookings for Shipments. Shouldn't even try to find quote number for consol.", initialHitCount + expectedHitsOnRefreshingUpdatedConsolJobParent, Factory.DatabaseLoadCount);

			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "TEST12345";

			Job shipmentJob = Factory.NewJobWithValidTestDataForTesting<Job>();

			using (shipmentJob.GetValidationSuspender())
			using (shipmentJob.GetSetJobDefaultsSuspender())
			{
				initialHitCount = Factory.DatabaseLoadCount;
				shipmentJob.Parent = shipment;
			}

			AssertNotEquals("We only have quoted bookings for Shipments. Should try to find quote number for this shipment.", initialHitCount + expectedHitsOnRefreshingUpdatedShipmentJobParent, Factory.DatabaseLoadCount);

			using (shipmentJob.GetValidationSuspender())
			using (shipmentJob.GetSetJobDefaultsSuspender())
			{
				initialHitCount = Factory.DatabaseLoadCount;
				shipmentJob.Parent = shipment;
			}

			AssertEquals("Should not try to find quote number second time.", initialHitCount, Factory.DatabaseLoadCount);
		}

