		public void TestSetDefaultValuesForTaxBranchWhenRegistryIsTurnedOn()
		{
			AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			var jobPlugin = TestObjectCreator.CreateShipment("S00001000");
			var job = Factory.NewJobForTesting<Job>();
			job.JH_ParentID = jobPlugin.PK;
			job.PlugInData = jobPlugin;

			var defaultBranch = ZGuid.NewZGuid();

			var companyMock = new Mock<ICompany>();
			var branchMock = new Mock<IBranch>();
			var departmentMock = new Mock<IDepartment>();
			var taxBranchDefaultingManagerMock = new Mock<IJobBillingTaxBranchDefaultingManager>();
			taxBranchDefaultingManagerMock.Setup(x => x.SetDefaultValue(jobPlugin, Env.CurrentCompany, Env.CurrentBranch, Env.CurrentDepartment));
			taxBranchDefaultingManagerMock.Setup(x => x.DefaultValue).Returns(defaultBranch);

			ObjectFactory.Substitute(taxBranchDefaultingManagerMock.Object);

			AccountingConfigurationRegistry.Instance.CustomJobTaxBranchDefaultingRulesEngineConfiguration.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);

			job.JH_GB_TaxBranch = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Falls back to Login Branch.", GlbBranch.CurrentBranch.PK.ToGuid(), job.JH_GB_TaxBranch);

			taxBranchDefaultingManagerMock.Verify(x => x.SetDefaultValue(jobPlugin, Env.CurrentCompany, Env.CurrentBranch, Env.CurrentDepartment), Times.Never);
			taxBranchDefaultingManagerMock.Verify(x => x.DefaultValue, Times.Never);

			AccountingConfigurationRegistry.Instance.CustomJobTaxBranchDefaultingRulesEngineConfiguration.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			job.JH_GB_TaxBranch = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Picks up the value from rules engine", defaultBranch, job.JH_GB_TaxBranch);
		}

