		public void TestReasonNotToAllowPostCost()
		{
			OrgHeader org = Factory.NewWithValidTestData<OrgHeader>();

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			AssertNoExceptionThrown(() => job.ReasonNotToAllowPostCost.ToCharArray());

			AccChargeCode chargeCode1 = Factory.NewWithValidTestData<AccChargeCode>();
			AccChargeCode chargeCode2 = Factory.NewWithValidTestData<AccChargeCode>();

			DummyJobInvoicingPlugIn dummyParent = new DummyJobInvoicingPlugIn(Factory);
			((DummyJobInvoicingPlugInJobInvoicingSupporter)dummyParent.InvoicingSupporter).ReasonNotToAllowPostCost = "I am the boss";
			((DummyJobInvoicingPlugInJobInvoicingSupporter)dummyParent.InvoicingSupporter).ChargeCodePKToStopPostingCost = chargeCode2.PK;
			job.Parent = dummyParent;

			AssertNull("PreCondition", ((IJobInvoicingPlugIn)dummyParent).InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode1.PK));
			AssertEquals("PreCondition", "I am the boss", ((IJobInvoicingPlugIn)dummyParent).InvoicingSupporter.GetReasonNotToAllowChangeOnCostDetails(chargeCode2.PK));

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_AC = chargeCode1.PK;
			charge1.JR_APInvoiceNum = "Inv 123456";
			charge1.JR_OH_SellAccount = org.PK;
			charge1.JR_LocalCostAmt = 100m;
			charge1.JR_LocalSellAmt = 100m;
			charge1.JR_APInvoiceDate = ZDateTime.Now;
			AssertEquals("charge1 is mapped to chargeCode1 for which cost posting is not prohibited", "", job.ReasonNotToAllowPostCost);

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_AC = chargeCode2.PK;
			charge2.JR_APInvoiceNum = "Inv 123456";
			charge2.JR_OH_CostAccount = org.PK;
			charge2.JR_APInvoiceDate = ZDateTime.Now;

			AssertEquals("charge2 is mapped to chargeCode2 however it does not have valid data", "", job.ReasonNotToAllowPostCost);

			charge2.JR_LocalCostAmt = 100m;
			charge2.JR_LocalSellAmt = 100m;

			AssertEquals("PreCondition", true, charge2.HasValidDataForCostPosting);
			AssertEquals("I am the boss", job.ReasonNotToAllowPostCost);
		}

