				AssertEquals(job.InvoiceDate, job.DocumentReceivedDate);
			}
		}

		public void TestCalculateDueDateWithDocumentReceivedDate()
		{
			var currentDate = ZDateTime.Now;
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			var charge = job.ChargesForAutoPopulate.AddNew();
			charge.IsSelectedForAutoPopulation = true;
			charge.JR_OH_CostAccount = Factory.New<OrgHeader>().PK;
			charge.CostAccount.CompanyData.OB_APPaymentTerms = "INV";
			charge.CostAccount.CompanyData.OB_APPaymentTermDays = 0;
			job.Charges.Add(charge);

			AssertEquals(ZDateTime.Empty, job.InvoiceDueDate);

			job.InvoiceDate = currentDate.Date.AddDays(-1);
			job.DocumentReceivedDate = currentDate.AddDays(2);
			AssertEquals("Due Date should be yestday based on Invoice Date", currentDate.Date.AddDays(-1), job.InvoiceDueDate.Date);

			job.InvoiceDueDate = ZDateTime.Empty;
			using (AccountingMasterFilesRegistry.Instance.APInvoiceDueDateCalculationRule.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				job.DocumentReceivedDate = currentDate.AddDays(1);
				AssertEquals("Due Date should be tomorrow based on Document Received Date", currentDate.Date.AddDays(1), job.InvoiceDueDate.Date);
			}
		}

