		public void TestLoadForAutoPopulate()
		{
			AccChargeCode chargeCode1 = Factory.NewWithValidTestData<AccChargeCode>();
			chargeCode1.AC_Code = "ABC";
			OrgHeader provider = Factory.New<OrgHeader>();
			provider.OH_Code = "PROV1";
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Creditor = provider.PK;

			Charge ch = job.Charges.AddNew();
			ch.JR_AC = chargeCode1.PK;
			ch.JR_OH_CostAccount = provider.PK;
			ch.JR_RX_NKCostCurrency = TestObjectCreator.GBP.RX_Code;
			ch.CostExchangeRate.SetBuyRate_ForTestOnly(1m);
			ch.JR_APInvoiceNum = "1111";

			ch = job.Charges.AddNew();
			ch.JR_AC = chargeCode1.PK;
			ch.JR_OH_CostAccount = provider.PK;
			ch.JR_RX_NKCostCurrency = TestObjectCreator.USD.RX_Code;
			ch.CostExchangeRate.SetBuyRate_ForTestOnly(1m);

			ch = job.Charges.AddNew();
			ch.JR_AC = chargeCode1.PK;
			ch.JR_OH_CostAccount = provider.PK;
			ch.JR_RX_NKCostCurrency = TestObjectCreator.AUD.RX_Code;
			Factory.Save();

			job.LoadForAutoPopulate();
			AssertEquals(3, job.ChargesForAutoPopulate.Count);
			foreach (Charge charge in job.ChargesForAutoPopulate)
			{
				if (charge.JR_APInvoiceNum.IsEmpty)
				{
					Assert(charge.IsSelectedForAutoPopulation);
				}
				else
				{
					AssertEquals(false, charge.IsSelectedForAutoPopulation);
				}
			}
		}

		public void TestPostAutoPopulation()
		{
			AccChargeCode chargeCode1 = Factory.NewWithValidTestData<AccChargeCode>();
			chargeCode1.AC_Code = "ABC";
			OrgHeader provider = Factory.New<OrgHeader>();
			provider.OH_Code = "PROV1";
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Creditor = provider.PK;
			job.InvoiceNum = "12345";
			job.InvoiceDate = ZDateTime.Today;
			job.InvoiceDueDate = ZDateTime.Today;
			job.DocumentReceivedDate = ZDateTime.Today;
			job.SupplierCostReference = "ABC";

			Charge ch1 = job.Charges.AddNew();
			ch1.JR_AC = chargeCode1.PK;
			ch1.JR_OH_CostAccount = provider.PK;
			ch1.JR_RX_NKSellCurrency = TestObjectCreator.GBP.RX_Code;
			ch1.RevenueExchangeRate?.SetBuyRate_ForTestOnly(1m);
			ch1.JR_APInvoiceNum = "54321";
			ch1.JR_APInvoiceDate = ZDateTime.Today.AddDays(1);
			ch1.JR_APDocumentReceivedDate = ZDateTime.Today.AddDays(1);
			ch1.JR_PaymentDate = ZDateTime.Today.AddDays(1);
			ch1.JR_CostReference = "XYZ";

			Charge ch2 = job.Charges.AddNew();
			ch2.JR_AC = chargeCode1.PK;
			ch2.JR_OH_CostAccount = provider.PK;
			ch2.JR_RX_NKSellCurrency = TestObjectCreator.GBP.RX_Code;
			ch2.RevenueExchangeRate?.SetBuyRate_ForTestOnly(1m);

			Factory.Save();
			job.LoadForAutoPopulate();
			job.InvoiceNum = "12345";
			job.InvoiceDate = ZDateTime.Today;
			job.InvoiceDueDate = ZDateTime.Today;
			job.DocumentReceivedDate = ZDateTime.Today;
			job.SupplierCostReference = "ABC";
			job.PostAutoPopulation();

			AssertNotEquals("12345", ch1.JR_APInvoiceNum);
			AssertNotEquals(ZDateTime.Today, ch1.JR_APInvoiceDate);
			AssertNotEquals(ZDateTime.Today, ch1.JR_PaymentDate);
			AssertNotEquals(ZDateTime.Today, ch1.JR_APDocumentReceivedDate);
			AssertNotEquals("ABC", ch1.JR_CostReference);
		}

		public void TestAddVoyageExchangeRates()
		{
			JobVoyage voyage = Factory.New<JobVoyage>();

			VoyageExRate rate1 = voyage.ExRates.AddNew();
			rate1.E8_RX_NKExCurrency = "USD";
			rate1.E8_VoyageExchangeRate = 1.34m;

			VoyageExRate rate2 = voyage.ExRates.AddNew();
			rate2.E8_RX_NKExCurrency = "JPY";
			rate2.E8_VoyageExchangeRate = 0.66m;

			Job job = Factory.NewJobForTesting<Job>();
			AssertEquals("precondition:", 0, job.ExchangeRates.Count);

			job.AddGenericExchangeRatesFromSource_ForTestOnly(voyage);
			AssertEquals("should now have 2 exchange rates", 2, job.ExchangeRates.Count);
			AssertGenericRateForVoyageRate(job, rate1);
			AssertGenericRateForVoyageRate(job, rate2);

			job.ExchangeRates.FindByRefCurrency(rate1.ExCurrency).JF_BaseRate = 1.37m;
			job.ExchangeRates.FindByRefCurrency(rate2.ExCurrency).Delete();
			AssertEquals("should be down to 1 exchange rate", 1, job.ExchangeRates.Count);

			job.AddGenericExchangeRatesFromSource_ForTestOnly(voyage);
			AssertEquals("should be back up to 2 exchange rates", 2, job.ExchangeRates.Count);
			AssertEquals("rate 1 should not be overridden", 1.37m, job.ExchangeRates.FindByRefCurrency(rate1.ExCurrency).JF_BaseRate);
			AssertGenericRateForVoyageRate(job, rate2);
		}

