		void AssertDefaultExchangeRatesFromVoyage(CommonShipment shipment)
		{
			var voyage = Factory.New<JobVoyage>();
			voyage.Origins.AddNew().JA_RL_NKPortOfLoading = "AUBNE";
			voyage.Destinations.AddNew().JB_RL_NKPortOfDischarge = "SGSIN";
			voyage.GenerateSailings();

			var rate1 = voyage.ExRates.AddNew();
			rate1.E8_RX_NKExCurrency = "USD";
			rate1.E8_VoyageExchangeRate = 1.34m;

			var rate2 = voyage.ExRates.AddNew();
			rate2.E8_RX_NKExCurrency = "JPY";
			rate2.E8_VoyageExchangeRate = 0.66m;

			using (Job job = Factory.NewJobForTesting<Job>())
			{
				job.JH_ParentID = shipment.PK;
				job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
				job.PlugInData = shipment;
				job.SetDefaultsForJob();
				AssertEquals("no voyage to get the rates from", 0, job.ExchangeRates.Count);

				shipment.JS_JX = voyage.Sailings[0].PK;
				job.SetDefaultsForJob();
				AssertEquals("Should have added the voyage exchange rates.", 2, job.ExchangeRates.Count);
				AssertGenericRateForVoyageRate(job, rate1);
				AssertGenericRateForVoyageRate(job, rate2);
			}

			var account = (BusinessObject)Factory.New<Agency.IVoyageAccount>();
			IJobInvoicingPlugIn plugin = (IJobInvoicingPlugIn)Factory.Load<Agency.IVoyageAccount>(account.PK);

			using (Job job = Factory.NewJobForTesting<Job>())
			{
				job.JH_ParentID = account.PK;
				job.JH_ParentTableCode = JobVoyAccountSchema.Constants.Prefix;
				job.PlugInData = plugin;
				job.SetDefaultsForJob();
				job.Charges.AddNew();
				AssertEquals("no voyage to get the rates from", 0, job.ExchangeRates.Count);

				account[JobVoyAccountSchema.NA_JV] = voyage.PK;
				job.SetDefaultsForJob();
				AssertEquals("Should have added the voyage exchange rates.", 2, job.ExchangeRates.Count);
				AssertGenericRateForVoyageRate(job, rate1);
				AssertGenericRateForVoyageRate(job, rate2);
			}
		}

		void AssertGenericRateForVoyageRate(Job job, VoyageExRate voyageRate)
		{
			var jobRate = job.ExchangeRates.FindByRefCurrency(voyageRate.ExCurrency);
			AssertNotNull("Generic Job Exchange Rate should be found", jobRate);
			AssertEquals("JF_BaseRate", voyageRate.E8_VoyageExchangeRate, jobRate.JF_BaseRate);
			Assert("No OrgType", jobRate.JF_OrgType.IsEmpty);
			Assert("No Org", jobRate.JF_OH_Org.IsEmpty);
			Assert("JF_IsTransformed", jobRate.JF_IsTransformed);
		}

