			job2.JH_ParentID = ship.PK;
			job2.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			Charge charge2 = job2.Charges.AddNew();
			charge2.JR_AC = Env.Registry.FreightChargeCode;
			charge2.JR_LocalSellAmt = 100m;

			Factory.Save();

			AssertEquals(1, job1.Charges.Count);

			job1.Charges.IncludeChargesFromJobs(job2.PK);
			job1.Charges.Load();
			AssertEquals(2, job1.Charges.Count);
		}

		public void TestClearAllUnpostedChargesDoesNotAffectChargesFromRelatedJobs()
		{
			ForwardingShipment ship = Factory.NewWithValidTestData<ForwardingShipment>();
			Factory.Save();

			Job job1 = Factory.NewJobWithValidTestDataForTesting<Job>();
			Charge charge1 = job1.Charges.AddNew();
			charge1.JR_AC = Env.Registry.FreightChargeCode;
			charge1.JR_LocalSellAmt = 100m;

			Job job2 = Factory.NewJobWithValidTestDataForTesting<Job>();
			job2.JH_ParentID = ship.PK;
			job2.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			Charge charge2 = job2.Charges.AddNew();
			charge2.JR_AC = Env.Registry.FreightChargeCode;
			charge2.JR_LocalSellAmt = 100m;

			Factory.Save();

			AssertEquals(1, job1.Charges.Count);

			job1.Charges.IncludeChargesFromJobs(job2.PK);
			job1.Charges.Load();

			AssertEquals(2, job1.Charges.Count);
			AssertNotEquals("Should have WIP Linked", ZGuid.Empty, job1.Charges[0].JR_AL_APLine);
			AssertNotEquals("Should have ACR Linked", ZGuid.Empty, job1.Charges[0].JR_AL_ARLine);
			AssertNotEquals("Should have WIP Linked", ZGuid.Empty, job1.Charges[1].JR_AL_APLine);
			AssertNotEquals("Should have ACR Linked", ZGuid.Empty, job1.Charges[1].JR_AL_ARLine);

			job1.ClearAllUnpostedCharges_ForTestOnly();

			AssertNotEquals("Related Job's Charge should still have WIP Linked", ZGuid.Empty, job2.Charges[0].JR_AL_APLine);
			AssertNotEquals("Related Job's Charge should still have ACR Linked", ZGuid.Empty, job2.Charges[0].JR_AL_ARLine);
		}

