		public void TestSettingPlugInDataDoesNotAffectHasChanges()
		{
			ForwardingConsol exportConsol = Factory.New<ForwardingConsol>();

			exportConsol.JK_TransportMode = "AIR";
			Transport exportTransport = exportConsol.Transports[0];
			exportTransport.JW_RL_NKDiscPort = "USLAX";

			ForwardingShipment shipment = exportConsol.Shipments.AddNew();

			RefExchangeRate currentUSDRate = TestObjectCreator.USD.ExchangeRates.AddNew();
			currentUSDRate.RE_StartDate = ZDateTime.Now.AddDays(-5);
			currentUSDRate.RE_ExpiryDate = ZDateTime.Now.AddDays(5);
			currentUSDRate.RE_ExRateType = nameof(ZArchitecture.Core.ExchangeRateType.Buy);
			currentUSDRate.RE_SellRate = 0.7m;

			Factory.Save();

			Enterprise.ZArchitecture.Core.ExchangeRateReader.GetReaderInstance().ClearCache();
			Job job = new Loader(Factory, shipment).TryLoadOrCreateWithMutex();
			job.JH_GE = Factory.LoadTop1<GlbDepartment>(new ZQuery(GlbDepartmentSchema.PK, SQLComparisonOperator.NotEqual, GlbDepartment.CurrentDepartment.PK)).PK;
			Assert(job.HasChanges);

			ApportionmentListing apps = new ApportionmentListing(Factory, exportConsol);
			JobConsolCost cost = apps.CostsCollection.TryAddNew();
			cost.E6_AC_ChargeCode = Env.Registry.FreightChargeCode;
			cost.E6_RX_NKCurrency = USD.RX_Code;
			cost.E6_ExchangeRate = 0.63m;
			cost.E6_OSCostAmount = 100m;
			cost.E6_ApportionmentMethod = "SHP";

			job.PlugInData = shipment;
			AssertEquals("Setting PlugInData should not clear HasChanges", true, job.HasChanges);

			Factory.Save();
			AssertEquals("HasChanges", false, job.HasChanges);

			shipment = exportConsol.Shipments.AddNew();
			Factory.Save();
			job.PlugInData = shipment;
			AssertEquals("Setting PlugInData should not set HasChanges", false, job.HasChanges);

			Charge charge = job.Charges.AddNew();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			Factory.Save();
			charge.JR_OSCostAmt = 100m;
			Assert(charge.HasChanges);
			job.PlugInData = shipment;
			Assert(charge.HasChanges);
		}

		public void TestSettingSameParentDoesNotValidateLocalClientAndAgent()
		{
			var localClient = TestObjectCreator.LocalClient;
			localClient.MiscServ.OM_ARCreditLimit = 100;
			var agent = TestObjectCreator.Agent;
			agent.MiscServ.OM_ARCreditLimit = 200;

			var shipment = TestObjectCreator.CreateShipment("S00001001");
			Factory.Save();

			AccountingConfigurationRegistry.Instance.IncludeUnpostedRevenueInCreditLimitCalculation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, Constants.CreditLimitChecking.PostedRecognizedAndUnrecognized);

			var job = TestObjectCreator.CreateJob(shipment, localClient, 0, agent, 0);
			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100, null, "", TestObjectCreator.AUD, 200m, localClient);
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100, null, "", TestObjectCreator.AUD, 300, agent);

			Factory.Save();

			string expectedWarning = @"The Credit Limit for {2} is set to {1:0.00} AUD. Credit approved.
The Total Outstanding Balance is {0:0.00} AUD, which is over the credit limit.

The Total Outstanding Balance is calculated by summing the following:
  *  the Posted Outstanding Balance, 0.00 AUD
  *  the Unposted Recognized Revenue, {0:0.00} AUD
  *  the Unposted Unrecognized Revenue, 0.00 AUD";

			AssertNoWarning("Job Local client should be validated yet", job.JH_OA_LocalChargesAddrInfo, string.Format(expectedWarning, 200m, 100M, localClient.OH_Code));
			AssertNoWarning("Job Agent should be validated yet", job.JH_OA_AgentCollectAddrInfo, string.Format(expectedWarning, 300m, 200m, agent.OH_Code));

			localClient.CreditChecker.ClearCreditLimitAndOutstandingBalanceCache();
			agent.CreditChecker.ClearCreditLimitAndOutstandingBalanceCache();
			job.JH_ParentID = ZGuid.Empty;
			job.Parent = shipment;

			AssertHasWarning("Job Local client should be validated on setting different Parent", job.JH_OA_LocalChargesAddrInfo, string.Format(expectedWarning, 200m, 100M, localClient.OH_Code));
			AssertHasWarning("Job Agent should be validated on setting different Parent", job.JH_OA_AgentCollectAddrInfo, string.Format(expectedWarning, 300m, 200m, agent.OH_Code));

			var newFactory = new BusinessObjectFactory();
			var jobInNewFactory = newFactory.Load<Job>(job.PK);
			var shipmentInNewFactory = newFactory.Load<ForwardingShipment>(shipment.PK);

			AssertEquals("JH_ParentID should be Shipment PK", shipmentInNewFactory.PK, jobInNewFactory.JH_ParentID);
			jobInNewFactory.Parent = shipmentInNewFactory;

			AssertNoWarning("Job Local client should not be validated on setting same Parent", jobInNewFactory.JH_OA_LocalChargesAddrInfo, string.Format(expectedWarning, 200m, 100M, localClient.OH_Code));
			AssertNoWarning("Job Agent should  should not be validated on setting same Parent", jobInNewFactory.JH_OA_AgentCollectAddrInfo, string.Format(expectedWarning, 300m, 200m, agent.OH_Code));
		}

