		void TestCaseIfPosted(string transactionLineType)
		{
			var shipment = TestObjectCreator.CreateShipment("S001001");
			var job = TestObjectCreator.CreateJob(shipment, false, false);

			Type invoiceType = null;
			if (transactionLineType == TransactionLineTypes.Cost)
			{
				invoiceType = typeof(APInvoice);
			}
			else
			{
				invoiceType = typeof(ARInvoice);
			}

			var invoice = TestObjectCreator.CreateInvoice(invoiceType, "INV1", TestObjectCreator.AUD, 1M);
			var invoiceLine1 = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 120M, GlbBranch.CurrentBranch.PK, false);
			var invoiceLine2 = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 120M, GlbBranch.CurrentBranch.PK, false);

			if (invoiceType == typeof(APInvoice))
			{
				invoiceLine1.AL_OH = TestObjectCreator.AALSHI.PK;
				invoiceLine2.AL_OH = TestObjectCreator.AALSHI.PK;
			}
			else
			{
				invoiceLine1.AL_OH = TestObjectCreator.ABIGAS.PK;
				invoiceLine2.AL_OH = TestObjectCreator.ABIGAS.PK;
			}

			JobCharge jobCharge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.FRT, "test charge1", TestObjectCreator.AUD, 120M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 120M, TestObjectCreator.ABIGAS);
			JobCharge jobCharge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.FRT, "test charge2", TestObjectCreator.AUD, 120M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 120M, TestObjectCreator.ABIGAS);

			Factory.Save();

			job.Charges.Load();

			AssertEquals("There are two charges in the job", 2, job.Charges.Count);
			if (invoiceType == typeof(APInvoice))
			{
				Assert(!job.Charges[0].IsCostPosted);
				Assert(!job.Charges[1].IsCostPosted);
			}
			else
			{
				Assert(!job.Charges[0].IsRevenuePosted);
				Assert(!job.Charges[1].IsRevenuePosted);
			}

			Assert(!job.IsAnyCostOrRevenuePosted());

			if (invoiceType == typeof(APInvoice))
			{
				var linkedInvoiceLine1 = Factory.Load<AccTransactionLines>(jobCharge1.JR_AL_APLine);
				(jobCharge1 as BaseCharge).ReverseAccrual(DateTime.Now);
				invoiceLine1.AL_JH = job.PK;
				jobCharge1.JR_AL_APLine = invoiceLine1.PK;
			}
			else
			{
				var linkedInvoiceLine1 = Factory.Load<AccTransactionLines>(jobCharge1.JR_AL_ARLine);
				(jobCharge1 as BaseCharge).ReverseWIP(DateTime.Now);
				invoiceLine1.AL_JH = job.PK;
				jobCharge1.JR_AL_ARLine = invoiceLine1.PK;
			}

			Factory.Save();

			if (invoiceType == typeof(APInvoice))
			{
				Assert(job.Charges[0].IsCostPosted);
				Assert(!job.Charges[1].IsCostPosted);
			}
			else
			{
				Assert(job.Charges[0].IsRevenuePosted);
				Assert(!job.Charges[1].IsRevenuePosted);
			}

			Assert(job.IsAnyCostOrRevenuePosted());
			AssertEquals(1, job.GetPostedARAPLines().Count());

			if (invoiceType == typeof(APInvoice))
			{
				Assert(job.IsAnyCostOrRevenuePosted(TestObjectCreator.AALSHI.PK));
				AssertEquals(1, job.GetPostedARAPLines(TestObjectCreator.AALSHI.PK).Count());

				Assert(!job.IsAnyCostOrRevenuePosted(TestObjectCreator.ABIGAS.PK));
			}
			else
			{
				Assert(!job.IsAnyCostOrRevenuePosted(TestObjectCreator.AALSHI.PK));

				Assert(job.IsAnyCostOrRevenuePosted(TestObjectCreator.ABIGAS.PK));
				AssertEquals(1, job.GetPostedARAPLines(TestObjectCreator.ABIGAS.PK).Count());
			}

			var shipment2 = TestObjectCreator.CreateShipment("S001002");
			var job2 = TestObjectCreator.CreateJob(shipment2, false, false);

			jobCharge1 = TestObjectCreator.CreateCharge(job2, TestObjectCreator.FRT, "test charge1", TestObjectCreator.AUD, 120M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 120M, TestObjectCreator.ABIGAS);
			jobCharge2 = TestObjectCreator.CreateCharge(job2, TestObjectCreator.FRT, "test charge2", TestObjectCreator.AUD, 120M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 120M, TestObjectCreator.ABIGAS);

			Factory.Save();

			job2.Charges.Load();

			AssertEquals("There are two charges in the job", 2, job2.Charges.Count);

			if (invoiceType == typeof(APInvoice))
			{
				Assert(!job2.Charges[0].IsCostPosted);
				Assert(!job2.Charges[1].IsCostPosted);
			}
			else
			{
				Assert(!job2.Charges[0].IsRevenuePosted);
				Assert(!job2.Charges[1].IsRevenuePosted);
			}

			Assert(!job2.IsAnyCostOrRevenuePosted());

			invoice = TestObjectCreator.CreateInvoice(invoiceType, "INV2", TestObjectCreator.AUD, 1M);
			invoiceLine1 = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 120M, GlbBranch.CurrentBranch.PK, false);
			invoiceLine2 = TestObjectCreator.CreateInvoiceLine(invoice, TestObjectCreator.AUD, 1M, 120M, GlbBranch.CurrentBranch.PK, false);

			if (invoiceType == typeof(APInvoice))
			{
				var linkedInvoiceLine1 = Factory.Load<AccTransactionLines>(jobCharge1.JR_AL_APLine);
				(jobCharge1 as BaseCharge).ReverseAccrual(DateTime.Now);
				invoiceLine1.AL_JH = job2.PK;
				jobCharge1.JR_AL_APLine = invoiceLine1.PK;
				jobCharge1.JR_AT_CostGSTRate = Guid.Empty;

				var linkedInvoiceLine2 = Factory.Load<AccTransactionLines>(jobCharge2.JR_AL_APLine);
				(jobCharge2 as BaseCharge).ReverseAccrual(DateTime.Now);
				invoiceLine1.AL_JH = job2.PK;
				jobCharge2.JR_AL_APLine = invoiceLine2.PK;
				jobCharge2.JR_AT_CostGSTRate = Guid.Empty;
			}
			else
			{
				var linkedInvoiceLine1 = Factory.Load<AccTransactionLines>(jobCharge1.JR_AL_ARLine);
				(jobCharge1 as BaseCharge).ReverseWIP(DateTime.Now);
				linkedInvoiceLine1.AL_JH = job2.PK;
				jobCharge1.JR_AL_ARLine = invoiceLine1.PK;

				var linkedInvoiceLine2 = Factory.Load<AccTransactionLines>(jobCharge2.JR_AL_ARLine);
				(jobCharge2 as BaseCharge).ReverseWIP(DateTime.Now);
				invoiceLine1.AL_JH = job2.PK;
				jobCharge2.JR_AL_ARLine = invoiceLine2.PK;
			}

			Factory.Save();

			if (invoiceType == typeof(APInvoice))
			{
				Assert(job2.Charges[0].IsCostPosted);
				Assert(job2.Charges[1].IsCostPosted);
			}
			else
			{
				Assert(job2.Charges[0].IsRevenuePosted);
				Assert(job2.Charges[1].IsRevenuePosted);
			}

			Assert(job.IsAnyCostOrRevenuePosted());
			AssertEquals(1, job.GetPostedARAPLines().Count());

			if (invoiceType == typeof(APInvoice))
			{
				Assert(job.IsAnyCostOrRevenuePosted(TestObjectCreator.AALSHI.PK));
				AssertEquals(1, job.GetPostedARAPLines(TestObjectCreator.AALSHI.PK).Count());

				Assert(!job.IsAnyCostOrRevenuePosted(TestObjectCreator.ABIGAS.PK));
			}
			else
			{
				Assert(!job.IsAnyCostOrRevenuePosted(TestObjectCreator.AALSHI.PK));

				Assert(job.IsAnyCostOrRevenuePosted(TestObjectCreator.ABIGAS.PK));
				AssertEquals(1, job.GetPostedARAPLines(TestObjectCreator.ABIGAS.PK).Count());
			}
		}

		public void TestFixedPlaceOfSupply()
		{
			var ausyd = Factory.LoadFromUniqueKey<RefUNLOCO>(RefUNLOCOSchema.RL_Code, new ZString("AUSYD"));

			var mockSupporter = new Mock<IJobInvoicingSupporter>();
			mockSupporter.Setup(m => m.IsImport).Returns(true);
			mockSupporter.Setup(m => m.IsExport).Returns(false);
			mockSupporter.Setup(m => m.IsDomestic).Returns(false);
			mockSupporter.Setup(m => m.Consignee).Returns((OrgHeader)null);
			mockSupporter.Setup(m => m.TransportMode).Returns(Core.Constants.TransportModes.Sea);
			mockSupporter.Setup(m => m.OperationsBranch).Returns((GlbBranch)null);
			mockSupporter.Setup(m => m.OverriddenDepartmentPK).Returns(ZGuid.Empty);
			mockSupporter.Setup(m => m.ConsumerType).Returns(JobInvoicingConsumerTypes.LocalCartage);
			mockSupporter.Setup(m => m.FixedPlaceOfSupply).Returns(ausyd);
			mockSupporter.Setup(m => m.ValidateOnInvoicingSupporter_JH_OA_LocalChargesAddr(It.IsAny<ZGuid>())).Returns(ZString.Empty);
			mockSupporter.Setup(m => m.ValidateOnInvoicingSupporter_JH_OA_AgentCollectAddr(It.IsAny<ZGuid>())).Returns(ZString.Empty);
			mockSupporter.Setup(m => m.CanCreateInvoicingJob).Returns(true);

			var invoicingMock = new Mock<IJobInvoicingPlugIn>();
			invoicingMock.Setup(m => m.InvoicingSupporter).Returns(mockSupporter.Object);
			invoicingMock.Setup(m => m.Factory).Returns(Factory);
			invoicingMock.Setup(m => m.PK).Returns(ZGuid.NewZGuid());
			invoicingMock.Setup(m => m.IsInDatabase).Returns(true);

			using (var job = new Loader(invoicingMock.Object).TryCreateWithoutMutexForTestOnly())
			{
				AssertNotNull("JobHeader.FixedPlaceOfSupply when registry is YES", job.FixedPlaceOfSupply);
				AssertEquals("JobHeader.FixedPlaceOfSupply when registry is YES", ausyd.Code, job.FixedPlaceOfSupply.Code);

				using (AccountingMasterFilesRegistry.Instance.UseCusClearPortAsHomeCntryForTaxOvrds.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
				{
					AssertNull("JobHeader.FixedPlaceOfSupply when registry is NO", job.FixedPlaceOfSupply);
				}
			}
		}

		public void TestServiceDirection()
		{
			var mockSupporterWithoutIServiceDirection = new Mock<IJobInvoicingSupporter>();
			mockSupporterWithoutIServiceDirection.Setup(m => m.IsImport).Returns(true);
			mockSupporterWithoutIServiceDirection.Setup(m => m.IsExport).Returns(false);
			mockSupporterWithoutIServiceDirection.Setup(m => m.IsDomestic).Returns(false);

			var invoicingMock = new Mock<IJobInvoicingPlugIn>();
			invoicingMock.Setup(m => m.InvoicingSupporter).Returns(mockSupporterWithoutIServiceDirection.Object);

			Job testJob = Factory.NewJobWithValidTestDataForTesting<Job>();
			testJob.Parent = invoicingMock.Object;
			AssertEquals("Expect ServiceDirection Unknown for InvoicingSupporter which doesn't support IServiceDirection", OrgConstants.ServiceDirection.Code.Unknown, testJob.ServiceDirection);

			var mockSupporterWithIServiceDirection = new Mock<IJobInvoicingSupporterWithIServiceDirection>();
			mockSupporterWithIServiceDirection.Setup(m => m.IsImport).Returns(true);
			mockSupporterWithIServiceDirection.Setup(m => m.IsExport).Returns(false);
