			AssertEquals("Expect ServiceDirectin NOT Unknown for InvoicingSupporter which supports IServiceDirection", OrgConstants.ServiceDirection.Code.Export, testJob2.ServiceDirection);
		}

		public interface IJobInvoicingSupporterWithIServiceDirection : IJobInvoicingSupporter, IServiceDirection
		{ }

		public void TestDirection()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "USLAX";

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.Export, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Export, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Export, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(!testJob.IsDomestic);

				shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = "AUSYD";
			}

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.Import, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Import, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Import, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(!testJob.IsExport);
				Assert(testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(!testJob.IsDomestic);

				shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = "USLAX";
			}

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.Domestic, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Domestic, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Domestic, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(!testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(testJob.IsDomestic);

				shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "INBOM";
				shipment.JS_RL_NKDestination = "USLAX";
			}

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.CrossTrade, testJob.MovementDirection);
				AssertEquals(ServiceDirection.CrossTrade, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Other, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(!testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(testJob.IsCrossTrade);
				Assert(!testJob.IsDomestic);

				shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "AUMEL";
				shipment.JS_RL_NKDestination = "AUSYD";
			}

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.Domestic, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Domestic, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Domestic, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(!testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(testJob.IsDomestic);

				shipment = Factory.New<ForwardingShipment>();
				shipment.JS_RL_NKOrigin = "";
				shipment.JS_RL_NKDestination = "";
			}

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;

				AssertEquals(Directions.Export, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Unknown, testJob.ServiceDirection);
				AssertEquals(Constants.FreightShipmentDirection.Code.Other, testJob.Direction);
				AssertEquals(Job.GetDirection(shipment), testJob.Direction);
				Assert(testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(!testJob.IsDomestic);
			}

			using (Job testJob = Factory.NewJobForTesting<Job>())
			{
				AssertEquals("Null plugindata", Directions.Unknown, testJob.MovementDirection);
				AssertEquals(ServiceDirection.Unknown, testJob.ServiceDirection);
				AssertEquals("", testJob.Direction);
				AssertEquals(Job.GetDirection(null), testJob.Direction);
				Assert(!testJob.IsExport);
				Assert(!testJob.IsImport);
				Assert(!testJob.IsCrossTrade);
				Assert(!testJob.IsDomestic);
			}
		}

