		void AssertClearSellFields_ZeroAmount(AccChargeCode chargeCode, bool expectedSellRated, string message)
		{
			var shipment = Factory.New<ForwardingShipment>();
			Factory.Save();

			TestObjectCreator.Job1.PlugInData = shipment;

			var info = new AutoRateInfo(Factory);
			info.ChargeCode = chargeCode;
			TestObjectCreator.Job1.Charges.RemoveAndDeleteAll();
			var newCharge = TestObjectCreator.Job1.Charges.AddNew();
			newCharge.JR_AC = info.ChargeCode.PK;

			info.AddFlatPaymentBasis(0, ZString.Empty, "AUD");
			info.CalculationDescription = "Sell Amount was specified as 0";
			TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);

			CombineAssertions(message, () =>
			{
				Assert(info.HasExplicitZeroAmount);
				AssertEquals("JR_LocalSellAmt should be 0", 0m, newCharge.JR_LocalSellAmt);
				AssertEquals("JR_OSSellAmt should be 0", 0m, newCharge.JR_OSSellAmt);
				AssertEquals("SellRated", expectedSellRated, newCharge.JR_SellRated);
			});
		}

