		public void TestAutoRateMarginChargeCostZero()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			Factory.Save();

			TestJob.LocalChargesPK = TestObjectCreator.Debtor.PK;

			TestObjectCreator.Job1.PlugInData = shipment;

			var invsup = TestObjectCreator.Job1.GetInvoicingSupporter();

			AutoRateInfo info = new AutoRateInfo(Factory);
			info.ChargeCode = TestObjectCreator.MRG100;

			TestObjectCreator.Job1.Charges.RemoveAndDeleteAll();

			var newCharge = TestObjectCreator.Job1.Charges.AddNew();
			newCharge.JR_AC = info.ChargeCode.PK;

			info.Currency = "AUD";
			info.AddFlatPaymentBasis(100m, shipment.RatingAdapter.OperationalJobCode);

			TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Cost);

			info.Bases.Clear();
			info.AddFlatPaymentBasis(0, shipment.RatingAdapter.OperationalJobCode);
			info.CalculationDescription = "Sell Amount was specified as 0";

			TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);

			AssertEquals("Sell should be 1 charge", 1, TestObjectCreator.Job1.Charges.Count);
			AssertEquals("Cost should be 100", 100m, TestObjectCreator.Job1.Charges[0].JR_LocalCostAmt);
			AssertEquals("Sell should be 0", 0m, TestObjectCreator.Job1.Charges[0].JR_LocalSellAmt);
			AssertNotEquals("Debtor should still be set", ZGuid.Empty, TestObjectCreator.Job1.Charges[0].JR_OH_SellAccount);
		}

		public void TestAutoRateMarginChargeCostZeroButDebtorOverrideGetsSet()
		{
			#region Setup

			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader debtor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader overrideDebtor = Factory.NewWithValidTestData<OrgHeader>();

			Factory.Save();

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			TestJob.LocalChargesPK = debtor.PK;

			TestObjectCreator.Job1.PlugInData = shipment;

			#endregion

			AutoRateInfo info = new AutoRateInfo(Factory);
			info.ChargeCode = TestObjectCreator.MRG100;
			info.Currency = "AUD";
			info.DebtorOverridePK = overrideDebtor.PK;

			TestObjectCreator.Job1.Charges.RemoveAndDeleteAll();

			var newCharge = TestObjectCreator.Job1.Charges.AddNew();
			newCharge.JR_AC = info.ChargeCode.PK;

			TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Cost);
			TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);

			AssertEquals("Sell should be 1 charge", 1, TestObjectCreator.Job1.Charges.Count);
			AssertEquals("Cost should be 0", 0m, TestObjectCreator.Job1.Charges[0].JR_LocalCostAmt);
			AssertEquals("Sell should be 0", 0m, TestObjectCreator.Job1.Charges[0].JR_LocalSellAmt);
			AssertEquals("Debtor should be set", overrideDebtor.PK, TestObjectCreator.Job1.Charges[0].JR_OH_SellAccount);
		}

		[System.Diagnostics.CodeAnalysis.SuppressMessage("CargoWiseOne", "CW1115:DoNotUseSetUserContext", Justification = "Testing")]
		public void TestChangingCFXDoesntRecalculateLocalCostAmounts()
		{
			TestObjectCreator.SetCurrentCompanyReciprocal(true);
			Factory.Save();
			Env.SetUserContext(new UserContext(Env.CurrentUser.LoginName, GlbBranch.CurrentBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid()));

			TestObjectCreator.SetCurrentCompanyReciprocal(true);
			try
			{
				TestObjectCreator.Job1.AddCurrency(TestObjectCreator.GBP, 9.3m, ExchangeRateValidLedgerEnum.AP);
				TestObjectCreator.Job1.LocalChargesPK = TestObjectCreator.Agent.PK;
				TestObjectCreator.Job1.JH_LocalChargesCFX = 0m;
				Charge testCharge = TestObjectCreator.Job1.Charges.AddNew();
				testCharge.JR_AC = TestObjectCreator.CC2.PK;
				testCharge.JR_RX_NKCostCurrency = TestObjectCreator.GBP.RX_Code;
				testCharge.JR_LocalCostAmt = 4450m;
				AssertEquals("Should have set os cost to 500", 478.49m, testCharge.JR_OSCostAmt);
				TestObjectCreator.Job1.JH_LocalChargesCFX = 5m;
				AssertEquals("Should not have changed local cost amount", 4450m, testCharge.JR_LocalCostAmt);
			}
			finally
			{
				TestObjectCreator.SetCurrentCompanyReciprocal(false);
				Factory.Save();
				Env.SetUserContext(new UserContext(Env.CurrentUser.LoginName, GlbBranch.CurrentBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid()));
			}
		}

