		public void TestGetPropertiesReadOnlyState()
		{
			bool isAllowed = Env.Security.ModifyChargesOfCompleteJobs.IsAllowed;
			try
			{
				TestJob.AddCurrency(RefCurrency.LoadFromCurrencyCode(Factory, "USD"), 2.0m, ExchangeRateValidLedgerEnum.AR);
				TestJob.Charges.AddNew();
				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = false;
				TestJob.JH_Status = JobHeaderStatus.Complete.Code;

				foreach (ZPropertyInfo info in TestJob.ZPropertyInfoHash)
				{
					AssertEquals("Property should be readonly", true, info.ReadOnly);
				}
				Assert(TestJob.Charges.ReadOnly);
				Assert(TestJob.Charges[0].ReadOnly);
				Assert(TestJob.ExchangeRates.ReadOnly);
				Assert(TestJob.ExchangeRates[0].ReadOnly);

				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = true;
				TestJob.JH_Status = JobHeaderStatus.Complete.Code;

				Assert(!TestJob.ReadOnly);
				Assert(!TestJob.Charges.ReadOnly);
				Assert(!TestJob.Charges[0].ReadOnly);
				Assert(!TestJob.ExchangeRates.ReadOnly);
				Assert(!TestJob.ExchangeRates[0].ReadOnly);
			}
			finally
			{
				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = isAllowed;
			}
		}

		public void TestJH_StatusCompleteJob()
		{
			bool isAllowed = Env.Security.ChangeStatusOfCompleteJobs.IsAllowed;
			bool isAllowedChangeStatusOfReadyToPostJobs = Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed;
			try
			{
				Env.Security.ChangeStatusOfCompleteJobs.IsAllowed = false;
				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = true;

				TestJob.JH_Status = JobHeaderStatus.Complete.Code;

				string errMsg = null;
				TestJob.OnCannotChangeStatusUserMessage += (object sender, UserMessageEventArgs e) => { errMsg = e.Message; };

				Factory.Save();
				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);

				errMsg = null;
				TestJob.JH_Status = JobHeaderStatus.Complete.Code;
				AssertNull("No error message displayed", errMsg);

				var fromJobStatus = JobHeaderStatus.Complete.Code;
				var jobStatusUpdateRestrictionRuleCollection = AccountingConfigurationRegistry.Instance.JobStatusUpdateRestrictionRule.DefaultValue;
				var jobStatusUpdateRestrictionRule = jobStatusUpdateRestrictionRuleCollection.Cast<JobStatusUpdateRestrictionRule>().FirstOrDefault(x => x.JobStatus == fromJobStatus);
				jobStatusUpdateRestrictionRule.Working = "YES";

				using (AccountingConfigurationRegistry.Instance.JobStatusUpdateRestrictionRule.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, jobStatusUpdateRestrictionRuleCollection))
				{
					TestJob.JH_Status = JobHeaderStatus.Working.Code;
					TestJob.Validation.ValidateJH_Status();
					AssertHasError("Changing Status of Complete Job if no security access should cause error.", TestJob.JH_StatusInfo, Env.Security.ChangeStatusOfCompleteJobs.ErrorMessageForNotAllowed + JobValidation.CompleteJobSecurityErrorMessage);
				}

				TestJob.JH_Status = JobHeaderStatus.Complete.Code;

				Env.Security.ChangeStatusOfCompleteJobs.IsAllowed = true;

				errMsg = null;
				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);
			}
			finally
			{
				Env.Security.ChangeStatusOfCompleteJobs.IsAllowed = isAllowed;
				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = isAllowedChangeStatusOfReadyToPostJobs;
			}
		}

