			finally
			{
				Env.Security.ReopenJob.IsAllowed = isAllowed;
			}
		}

		public void TestReopenJobWhenImporting()
		{
			var isAllowed = Env.Security.ReopenJob.IsAllowed;
			try
			{
				TestJob.JH_Status = JobHeaderStatus.Closed.Code;
				Factory.Save();

				Env.Security.ReopenJob.IsAllowed = false;
				var testOrg = Factory.New<OrgHeader>();
				testOrg.OH_Code = "GJESHICPH1";
				var testInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
				testInvoice.AH_OH = testOrg.PK;

				Assert("Job should NOT be reopenable", !TestJob.CanReOpenClosedJobSecurity(JobHeaderStatus.Working.Code));

				testInvoice.Factory.SetContext(BusinessContext.AllowReopenJobWhenImporting);

				testInvoice.AH_Ledger = "AP";
				testInvoice.AH_TransactionType = "INV";
				testInvoice.AH_TransactionNum = "Tran001";

				Assert("Job should be reopenable", TestJob.CanReOpenClosedJobSecurity(JobHeaderStatus.Working.Code));
				TestJob.ReOpenByImport(string.Format(CultureInfo.InvariantCulture, " - {0} {1} {2} ({3})", testInvoice.AH_Ledger, testInvoice.AH_TransactionType, testInvoice.AH_TransactionNum, testOrg.OH_Code));
				AssertEquals("AllowReopenJobWhenImporting has been set. Should Reopen even ReopenJob.IsAllowed = false", JobHeaderStatus.Working.Code, TestJob.JH_Status);
			}
			finally
			{
				Env.Security.ReopenJob.IsAllowed = isAllowed;
			}
		}

