				errMsg = null;

				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = true;

				TestJob.JH_Status = JobHeaderStatus.JobReadyForCostPosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = true, Should change to Ready for other ledger posting", JobHeaderStatus.JobReadyForCostPosting.Code, TestJob.JH_Status);

				TestJob.JH_Status = JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = false, Should change to Ready for both ledger posting", JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code, TestJob.JH_Status);

				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = true, Should Reopen", JobHeaderStatus.Working.Code, TestJob.JH_Status);
			}
			finally
			{
				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = isAllowed;
			}
		}

		public void TestJH_StatusReadyToPostCost()
		{
			bool isAllowed = Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed;

			try
			{
				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = false;

				string errMsg = null;
				TestJob.OnCannotChangeStatusUserMessage += (object sender, UserMessageEventArgs e) => { errMsg = e.Message; };

				TestJob.JH_Status = JobHeaderStatus.JobReadyForCostPosting.Code;
				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("IsInDatabase = false, Should set to WRK", JobHeaderStatus.Working.Code, TestJob.JH_Status);

				TestJob.JH_Status = JobHeaderStatus.JobReadyForCostPosting.Code;
				Factory.Save();

				TestJob.JH_Status = JobHeaderStatus.JobReadyForRevenuePosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = false, Should still be set to new value", JobHeaderStatus.JobReadyForRevenuePosting.Code, TestJob.JH_Status);
				errMsg = null;

				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = false, Should still be set to new value", JobHeaderStatus.Working.Code, TestJob.JH_Status);
				errMsg = null;

				TestJob.JH_Status = JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = false, Should change to Ready for both ledger posting", JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code, TestJob.JH_Status);
				errMsg = null;

				Env.Security.ChangeStatusOfReadyToPostJobs.IsAllowed = true;

				TestJob.JH_Status = JobHeaderStatus.JobReadyForRevenuePosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = true, Should change to Ready for other ledger posting", JobHeaderStatus.JobReadyForRevenuePosting.Code, TestJob.JH_Status);

				TestJob.JH_Status = JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = false, Should change to Ready for both ledger posting", JobHeaderStatus.JobReadyForRevenueAndCostPosting.Code, TestJob.JH_Status);

				TestJob.JH_Status = JobHeaderStatus.Working.Code;
				AssertNull("No error message displayed", errMsg);
				AssertEquals("JobReadyForRevenueAndCostPosting.IsAllowed = true, Should Reopen", JobHeaderStatus.Working.Code, TestJob.JH_Status);
			}
			finally
			{
				Env.Security.ReopenJob.IsAllowed = isAllowed;
			}
		}

