		public void TestJobReopenAndCloseAgainNotificationEmail()
		{
			var testStaff = Factory.NewWithValidTestData<GlbStaff>();
			testStaff.GS_EmailAddress = "test@test.com";

			var testGroup = Factory.NewWithValidTestData<GlbGroup>();
			testGroup.Staff.Add(testStaff);

			TestJob.JH_JobNum = "JOB1";
			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			Factory.Save();

			var branchPk = TestJob.Branch.PK;

			Env.Security.ReopenJob.IsAllowed = true;
			AccountingConfigurationRegistry.Instance.JobReopenNotifyGroup.SetValue(Guid.Empty, branchPk.ToGuid(), Guid.Empty, testGroup.PK.ToGuid());

			TestJob.JH_Status = JobHeaderStatus.Working.Code;
			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			TestJob.JH_A_JCLInfo.Value = TestJob.JH_A_JCLInfo.OriginalValue; //this is not real situation as I know just to test that email is sending from OnSaved instead of OnFactorySaved. So only if Job need to be saved.
			var changesFields = from property in TestJob.ZPropertyInfoHash.Cast<ZPropertyInfo>()
								where property.IsPersistent && property.HasChanges
								select property.Name;
			Assert("Precodndition: JH_Status shouldn't have changes", !TestJob.JH_StatusInfo.HasChanges);
			AssertContainsExactElementsInAnyOrder("Precondition: job properties should not be changed.", Array.Empty<string>(), changesFields);
			Factory.Save();
			AssertEquals("No Emails should be created as job had no change and was not acctually saved in db", 0, Env.OutgoingMailManager.EmailsCreated.Count);

			TestJob.JH_Status = JobHeaderStatus.Working.Code;
			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			Assert("Precodndition: JH_Status shouldn't have changes", !TestJob.JH_StatusInfo.HasChanges);
			Assert("Precondition: some other job properties should be changed to make job saved.", changesFields.Any());
			Factory.Save();
			AssertEquals("1 Email should be created", 1, Env.OutgoingMailManager.EmailsCreated.Count);
			EmailDef email = Env.OutgoingMailManager.EmailsCreated[0];
			AssertEquals("Job number JOB1 was reopened by CWSupport (CargoWise Support)", email.Subject);
			AssertEquals(string.Format(
@"The following job was reopened by CWSupport (CargoWise Support) : 
Number: 'JOB1', Company: '{0}'. However this was closed again after some changes.
",
				TestJob.Company.GC_Code), email.Body);
		}

