		void AssertReopenedUserAndLog(string initialStatus, bool userIsStored)
		{
			TestJob.JH_Status = initialStatus;
			Factory.Save();

			SecurityCore userSecurityWithAccess = CreateTestSecurity(true);
			TestJob.SecurityOverrideProvider = new NonInteractiveSecurityOverrideProvider();
			(TestJob.SecurityOverrideProvider as NonInteractiveSecurityOverrideProvider).OverrideLogin = User.SupportUserName;
			(TestJob.SecurityOverrideProvider as NonInteractiveSecurityOverrideProvider).OverridePassword = CWSupportLoginToken.TokenForTest;
			TestJob.SecurityOverrideProvider.PromptForTemporaryAccess(userSecurityWithAccess.ReopenJob);

			TestJob.ReOpen();
			AssertNotNull(TestJob.SecurityOverrideProvider.UserSecurityOverride);
			if (userIsStored)
			{
				GlbStaff overrideStaff = Factory.LoadTop1<GlbStaff>(new ZQuery(GlbStaffSchema.GS_LoginName, User.SupportUserName));
				AssertEquals(TestJob.SecurityOverrideProvider.UserSecurityOverride.UserPK, TestJob.ReopenedUserPK_ForTestOnly);
				StmALog lastLog = TestJob.Logs.GetAllLogs()[TestJob.Logs.GetAllLogs().Count - 1];
				AssertEquals("added log should be ATH", Events.Authorised.Code, lastLog.SL_SE_NKEvent);
				AssertEquals("added log should contain proper reference", "Job reopening authorized by " + overrideStaff.GS_LoginName + " (" + overrideStaff.GS_FullName + ")", lastLog.SL_Reference);
			}
			else
			{
				AssertEquals(ZGuid.Empty, TestJob.ReopenedUserPK_ForTestOnly);
				AssertNotEquals("added log should be ATH", Events.Authorised, TestJob.Logs.AddedLog.SL_SE_NKEvent);
			}
		}

		SecurityCore CreateTestSecurity(bool isAllowed)
		{
			SecurityForTest testSecurity = new SecurityForTest(null, Env.CurrentUser.PK, Env.CurrentBranch.PK, Env.CurrentDepartment.PK, Env.CurrentCompany.PK);
			testSecurity.CachingEnabled = false;
			testSecurity.ReopenJob.IsAllowed = isAllowed;

			return testSecurity;
		}

