		public void TestJH_StatusChangeWithNoSecurityChangeStatusOfCompleteJobs()
		{
			Env.Security.ChangeStatusOfCompleteJobs.IsAllowed = false;

			string statusChangeMessage = null;
			var testJob = Factory.NewJobForTesting<TestJobClass>();
			testJob.JH_JobNum = "job01";
