		public void TestResetUnpostedLinesInvoiceType()
		{
			AccChargeCode disbursementChargeCode = Factory.New<AccChargeCode>();
			disbursementChargeCode.AC_ChargeType = Core.Constants.ChargeType.Disbursement;

			BusinessObjectFactory orgFactory = new BusinessObjectFactory();
			OrgHeader org = orgFactory.NewWithValidTestData<OrgHeader>();
			org.CompanyData.InvoiceRollupOrGroups.RemoveAndDeleteAll();
			OrgInvoiceRollupOrGroup group = org.CompanyData.InvoiceRollupOrGroups.AddNew();
			group.PG_JobType = OrgInvoiceRollupOrGroupLookups.JobType_List.All.Code;
			group.PG_ServiceDirection = OrgConstants.ServiceDirection.Code.All;
			group.PG_TransportMode = OrgConstants.ModesForGroupOrSubTotal.Codes.All;
			group.PG_InvoicePostingStyle = InvoicePostingOptionsList.Codes.DisbursementAndFinal;
			orgFactory.Save();

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			job.LocalChargesPK = org.PK;

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_AC = Env.Registry.FreightChargeCode;

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_AC = disbursementChargeCode.PK;

			AssertEquals("Final Invoice", InvoiceTypesList.Codes.FinalInvoice, charge1.JR_InvoiceType);
			AssertEquals("Disbursement Invoice", InvoiceTypesList.Codes.DisbursementInvoice, charge2.JR_InvoiceType);

			charge1.JR_InvoiceType = InvoiceTypesList.Codes.ForeignCurrencyInvoice;
			charge2.JR_InvoiceType = InvoiceTypesList.Codes.ForeignCurrencyInvoice;
			AssertEquals("ForeignCurrencyInvoice Invoice", InvoiceTypesList.Codes.ForeignCurrencyInvoice, charge1.JR_InvoiceType);
			AssertEquals("ForeignCurrencyInvoice Invoice", InvoiceTypesList.Codes.ForeignCurrencyInvoice, charge2.JR_InvoiceType);

			ChargePoster poster = new ChargePoster(Factory);
			poster.Post(charge2);

			job.ResetUnpostedLinesInvoiceType();
			AssertEquals("Final Invoice", InvoiceTypesList.Codes.FinalInvoice, charge1.JR_InvoiceType);
			AssertEquals("Still ForeignCurrencyInvoice as it was posted", InvoiceTypesList.Codes.ForeignCurrencyInvoice, charge2.JR_InvoiceType);
		}

		public void TestResetDefaultDebtorOnUnpostedLines()
		{
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.JH_ParentTableCode = JobShipmentSchema.Constants.Prefix;
			job.LocalChargesPK = TestObjectCreator.AALSHI.PK;

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_AC = Env.Registry.FreightChargeCode;

			Charge charge2 = job.Charges.AddNew();
			charge2.JR_AC = Env.Registry.FreightChargeCode;

			AssertEquals("charge1's Debtor", TestObjectCreator.AALSHI.PK, charge1.JR_OH_SellAccount);
			AssertEquals("charge2's Debtor", TestObjectCreator.AALSHI.PK, charge2.JR_OH_SellAccount);

			charge1.JR_OH_SellAccount = TestObjectCreator.ABIGAS.PK;
			charge2.JR_OH_SellAccount = TestObjectCreator.ABIGAS.PK;
			AssertEquals("charge1's Debtor", TestObjectCreator.ABIGAS.PK, charge1.JR_OH_SellAccount);
			AssertEquals("charge2's Debtor", TestObjectCreator.ABIGAS.PK, charge2.JR_OH_SellAccount);

			new ChargePoster(Factory).Post(charge2);
			job.ResetDefaultDebtorOnUnpostedLines();
			AssertEquals("Debtor should be reset to its default value of AAALSHI", TestObjectCreator.AALSHI.PK, charge1.JR_OH_SellAccount);
			AssertEquals("Debtor should remain ABIGAS", TestObjectCreator.ABIGAS.PK, charge2.JR_OH_SellAccount);
		}

		public void TestDefaultExchangeRate()
		{
			RefUNLOCO uSLAX = Factory.LoadFromNaturalKey<RefUNLOCO>(RefUNLOCOSchema.RL_Code, "USLAX");
			ForwardingConsol exportConsol = Factory.New<ForwardingConsol>();

			exportConsol.JK_TransportMode = "AIR";
			Transport exportTransport = exportConsol.Transports[0];
			exportTransport.JW_RL_NKDiscPort = uSLAX.RL_Code;

			ApportionmentListing apps = new ApportionmentListing(Factory, exportConsol);

			try
			{
				apps.IsActivated = true;
				JobConsolCost freightCost = apps.CostsCollection.TryAddNew();
				freightCost.E6_AC_ChargeCode = Env.Registry.FreightChargeCode;
				freightCost.E6_RX_NKCurrency = TestObjectCreator.USD.RX_Code;
				freightCost.E6_ExchangeRate = 0.6713m;
				freightCost.E6_OSCostAmount = 0m;

				RefExchangeRate currentUSDRate = TestObjectCreator.USD.ExchangeRates.AddNew();
				currentUSDRate.RE_StartDate = ZDateTime.Now.AddDays(-5);
				currentUSDRate.RE_ExpiryDate = ZDateTime.Now.AddDays(5);
				currentUSDRate.RE_ExRateType = nameof(ZArchitecture.Core.ExchangeRateType.Buy);
				currentUSDRate.RE_SellRate = 0.7m;
				Enterprise.ZArchitecture.Core.ExchangeRateReader.GetReaderInstance().ClearCache();

				ForwardingShipment shipment = exportConsol.Shipments.AddNew();
				freightCost.E6_ApportionmentMethod = "SHP";

				Factory.Save();

				Job job = Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, shipment.PK));
				AssertNotNull(job);
			}
			finally
			{
				apps.ReleaseMutexes();
			}
		}

