		void SetupUpliftConfiguration(AccCFXUpliftConfigurationCollection airConfiguration, AccCFXUpliftConfigurationCollection seaConfiguration, AccCFXUpliftConfigurationCollection railConfiguration, AccCFXUpliftConfigurationCollection allConfiguration)
		{
			TestObjectCreator.CreateCFXUplift(allConfiguration, serviceDirection: ServiceDirection.Import, percentage: 21m, minimum: 30m);
			TestObjectCreator.CreateCFXUplift(allConfiguration, serviceDirection: ServiceDirection.Export, percentage: 41m, minimum: 50m);

			TestObjectCreator.CreateCFXUplift(seaConfiguration, serviceDirection: ServiceDirection.Import, transportMode: TransportMode.Sea, percentage: 20m, minimum: 25m);
			TestObjectCreator.CreateCFXUplift(seaConfiguration, serviceDirection: ServiceDirection.Export, transportMode: TransportMode.Sea, percentage: 40m, minimum: 45m);

			TestObjectCreator.CreateCFXUplift(airConfiguration, serviceDirection: ServiceDirection.Import, transportMode: TransportMode.Air, percentage: 10m, minimum: 15m);
			TestObjectCreator.CreateCFXUplift(airConfiguration, serviceDirection: ServiceDirection.Export, transportMode: TransportMode.Air, percentage: 30m, minimum: 35m);
			TestObjectCreator.CreateCFXUplift(airConfiguration, serviceDirection: ServiceDirection.Export, transportMode: TransportMode.Air, currencyCode: "USD", percentage: 36m, minimum: 37m);
			TestObjectCreator.CreateCFXUplift(airConfiguration, serviceDirection: ServiceDirection.Export, transportMode: TransportMode.Air, currencyCode: "USD", percentage: 38m, minimum: 39m,
				startDate: new ZDate(2025, 1, 4), expiryDate: new ZDate(2025, 1, 7));

			TestObjectCreator.CreateCFXUplift(railConfiguration, jobType: "SHP", origin: "NZ", destination: "", transportMode: TransportMode.Rail, percentage: 60m, minimum: 61m);
			TestObjectCreator.CreateCFXUplift(railConfiguration, jobType: "SHP", origin: "", destination: "CA", transportMode: TransportMode.Rail, percentage: 62m, minimum: 63m);
			TestObjectCreator.CreateCFXUplift(railConfiguration, jobType: "SHP", origin: "NZ", destination: "CA", transportMode: TransportMode.Rail, percentage: 64m, minimum: 65m);
			TestObjectCreator.CreateCFXUplift(railConfiguration, jobType: "SHP", origin: "NZ", destination: "CA", transportMode: TransportMode.Rail, currencyCode: "NZD", percentage: 66m, minimum: 67m);
		}

		void AssertCFXPercentAndMinimum(OrgHeader debtor)
		{
			var date = new ZDate(2025, 1, 6);
			var shipment = CommonShipment.New(Factory);
			using (var job = Job.CreateWithMutex(Factory, shipment))
			{
				var charge = job.Charges.AddNew();
				job.PlugInData = shipment;

				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_TransportMode = TransportModes.Air;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out var cfxPercent, out var cfxMinimum);
				AssertEquals("Import, Air - Percent", 10m, cfxPercent);
				AssertEquals("Import, Air - Minimum", 15m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_TransportMode = TransportModes.Sea;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Import, Sea - Percent", 20m, cfxPercent);
				AssertEquals("Import, Sea - Minimum", 25m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "USLAX";
				shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_TransportMode = TransportModes.Road;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Import, Road - falls back to All - Percent", 21m, cfxPercent);
				AssertEquals("Import, Road - falls back to All - Minimum", 30m, cfxMinimum);

				shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_RL_NKDestination = "USLAX";
				shipment.JS_TransportMode = TransportModes.Air;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Air - Percent", 30m, cfxPercent);
				AssertEquals("Export, Air - Minimum", 35m, cfxMinimum);

				shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_RL_NKDestination = "USLAX";
				shipment.JS_TransportMode = TransportModes.Air;
				job.GetCFXPairFromOrganization(debtor, "USD", new ZDate(2025, 1, 1), out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Air - Percent", 36m, cfxPercent);
				AssertEquals("Export, Air - Minimum", 37m, cfxMinimum);

				job.GetCFXPairFromOrganization(debtor, "USD", date, out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Air - Percent", 38m, cfxPercent);
				AssertEquals("Export, Air - Minimum", 39m, cfxMinimum);

				shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_RL_NKDestination = "USLAX";
				shipment.JS_TransportMode = TransportModes.Sea;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Sea - Percent", 40m, cfxPercent);
				AssertEquals("Export, Sea - Minimum", 45m, cfxMinimum);

				shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
				shipment.JS_RL_NKDestination = "USLAX";
				shipment.JS_TransportMode = TransportModes.Road;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Road - falls back to All - Percent", 41m, cfxPercent);
				AssertEquals("Export, Road - falls back to All - Minimum", 50m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "NZABY";
				shipment.JS_RL_NKDestination = "AUSYD";
				shipment.JS_TransportMode = TransportModes.Rail;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("NZ->All, Rail - Percent", 60m, cfxPercent);
				AssertEquals("NZ->All, Rail - Minimum", 61m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "AUSYD";
				shipment.JS_RL_NKDestination = "CATOR";
				shipment.JS_TransportMode = TransportModes.Rail;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("All->CA, Rail - Percent", 62m, cfxPercent);
				AssertEquals("All->CA, Rail - Minimum", 63m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "NZABY";
				shipment.JS_RL_NKDestination = "CATOR";
				shipment.JS_TransportMode = TransportModes.Rail;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("NZ->CA, Rail - Percent", 64m, cfxPercent);
				AssertEquals("NZ->CA, Rail - Minimum", 65m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "NZABY";
				shipment.JS_RL_NKDestination = "CATOR";
				shipment.JS_TransportMode = TransportModes.Rail;
				job.GetCFXPairFromOrganization(debtor, "NZD", date, out cfxPercent, out cfxMinimum);
				AssertEquals("NZ->CA (NZD), Rail - Percent", 66m, cfxPercent);
				AssertEquals("NZ->CA (NZD), Rail - Minimum", 67m, cfxMinimum);

				shipment.JS_RL_NKOrigin = "";
				shipment.JS_RL_NKDestination = "";
				shipment.JS_TransportMode = TransportModes.Rail;
				job.GetCFXPairFromOrganization(debtor, charge.JR_RX_NKSellCurrency, date, out cfxPercent, out cfxMinimum);
				AssertEquals("Export, Rail - falls back to All - Percent", 41m, cfxPercent);
				AssertEquals("Export, Rail - falls back to All - Minimum", 50m, cfxMinimum);
			}
		}

