		public void TestAllowedToViewAdditionalCharge()
		{
			var testUser = Factory.NewWithValidTestData<GlbStaff>();
			testUser.GS_IsController = false;
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var warehouseHelper = ObjectFactory.New<IWhsTransactionTestHelper>(Factory);
			var warehouse = warehouseHelper.CreateWarehouse("WHS", "A");
			var client = warehouseHelper.CreateClient("SAM");
			var product = warehouseHelper.CreateProduct(client, "BOWLHAT");
			var stock = warehouseHelper.CreateStock(warehouse.PK, client, product.PK, 20m);
			var warehouseOrder = warehouseHelper.CreateWhsOrder(client, warehouse.PK, "ORD1", null);
			var warehouseOrderBO = Factory.Load<IWhsOrder>(warehouseOrder);
			var jobHeader = new Loader((IJobHeaderParent)warehouseOrderBO).TryCreateWithoutMutexForTestOnly();

			var testCharge1 = TestObjectCreator.CreateCharge(jobHeader, TestObjectCreator.CC1, 100m, 100m);
			var testCharge2 = TestObjectCreator.CreateCharge(jobHeader, TestObjectCreator.CC2, 100m, 100m);
			testCharge1.JR_GB = Env.CurrentBranch.PK;
			testCharge1.JR_GE = Env.CurrentDepartment.PK;
			Factory.Save();

			var newJobLoaded = newFactory.Load<Job>(jobHeader.PK);
			Assert(!newJobLoaded.JH_ParentID.IsEmpty);
			Assert(!newJobLoaded.JH_ParentTableCode.IsEmpty);
			AssertNull(newJobLoaded.Parent);

			var newJobCharge2 = newFactory.Load<JobCharge>(testCharge2.PK);
			AssertNotNullOrEmpty(newJobCharge2.JR_GB.ToString());
			AssertNotNullOrEmpty(newJobCharge2.JR_GE.ToString());
			var testWarehouseBranch = Factory.Load<GlbBranch>(newJobCharge2.JR_GB);
			var testWarehouseDepartment = Factory.Load<GlbDepartment>(newJobCharge2.JR_GE);
			AssertNotEquals(Env.CurrentDepartment.PK, testWarehouseDepartment.PK);
			AssertNotEquals(Env.CurrentBranch.PK, testWarehouseBranch.PK);

			using (Env.SetTemporaryUserContext(testUser.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
			{
				var securityFactory = new BusinessObjectFactory();
				var security1 = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK);
				var security2 = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, testWarehouseBranch.PK.ToGuid(), testWarehouseDepartment.PK.ToGuid());

				var loginSecurity1 = securityFactory.New<GlbSecurity>();
				loginSecurity1.GU_GB = Env.CurrentBranch.PK;
				loginSecurity1.GU_GE = Env.CurrentDepartment.PK;
				loginSecurity1.GU_GS = Env.CurrentUser.PK;
				loginSecurity1.GU_SecurityRight = security1.Login.Code;

				var loginSecurity2 = securityFactory.New<GlbSecurity>();
				loginSecurity2.GU_GB = testWarehouseBranch.PK;
				loginSecurity2.GU_GE = testWarehouseDepartment.PK;
				loginSecurity2.GU_GS = Env.CurrentUser.PK;
				loginSecurity2.GU_SecurityRight = security2.Login.Code;

				loginSecurity1.GU_SecurityItemIsAllowed = true;
				loginSecurity2.GU_SecurityItemIsAllowed = false;

				securityFactory.Save();

				AssertEquals("Precondtion", false, security1.GetInvoicingSecurityCheckPoint(Env.Security.WhsOrderJobInvoicing, SecurityCore.AllowViewCharges).IsAllowed);
				AssertEquals(false, security2.GetInvoicingSecurityCheckPoint(Env.Security.WhsOrderJobInvoicing, SecurityCore.AllowViewCharges).IsAllowed);

				jobHeader.ChargesFilteredByChargeViewingPermission.Rebuild();

				AssertEquals("Should only show testcharge1. Should not show testcharge2 because the security setting does not allow to view charge outside permitted branch and department.", 1, jobHeader.ChargesFilteredByChargeViewingPermission.Count);
				AssertEquals(2, jobHeader.Charges.Count);
				AssertEquals(testCharge1.PK, jobHeader.ChargesFilteredByChargeViewingPermission[0].PK);
			}

			using (Env.SetTemporaryUserContext(testUser.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
			{
				var securityFactory = new BusinessObjectFactory();
				var security = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, testWarehouseBranch.PK.ToGuid(), testWarehouseDepartment.PK.ToGuid());

				var invoicingSecurity = securityFactory.New<GlbSecurity>();
				invoicingSecurity.GU_GB = testWarehouseBranch.PK;
				invoicingSecurity.GU_GE = testWarehouseDepartment.PK;
				invoicingSecurity.GU_GS = Env.CurrentUser.PK;
				invoicingSecurity.GU_SecurityRight = security.GetInvoicingSecurityCheckPoint(Env.Security.WhsOrderJobInvoicing, SecurityCore.AllowViewCharges).Code;
				invoicingSecurity.GU_SecurityItemIsAllowed = true;
				security.GetInvoicingSecurityCheckPoint(Env.Security.WhsOrderJobInvoicing, SecurityCore.AllowViewCharges).IsAllowed = true;

				securityFactory.Save();

				jobHeader.ChargesFilteredByChargeViewingPermission.Rebuild();

				AssertEquals("Charge collection should have both TestCharge1 and TestCharge2. The security setting allows to view charge outside branch and department.",
							 2, jobHeader.ChargesFilteredByChargeViewingPermission.Count);
				AssertEquals(2, jobHeader.Charges.Count);

				var targetCharge = jobHeader.ChargesFilteredByChargeViewingPermission.First(x => x.PK == testCharge2.PK) as Charge;
				AssertEquals("TestCharge2 should have parent loaded and has correct security right.", true, targetCharge.IsAllowedToViewThisCharge);
				AssertNotNull(targetCharge.Job.Parent);
			}
		}

