		public void TestFilteredCharges()
		{
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			AssertEquals("Inner Charges Collection does not container any charges.", 0, job.FilteredCharges.Count);

			job = Factory.NewJobWithValidTestDataForTesting<Job>();
			var chargeNone = job.Charges.AddNew();
			var chargeABC = job.Charges.AddNew();
			var chargeDEF = job.Charges.AddNew();
			chargeABC.JR_CostReference = "ABC";
			chargeDEF.JR_CostReference = "DEF";
			AssertContainsExactElementsInAnyOrder("Should not be filtering, should contain the 3 new charges.", new[] { chargeNone, chargeABC, chargeDEF }, job.FilteredCharges);

			var jobHeaderParent = Factory.New<DummyJobHeaderParent>();
			var jobHeaderInvoiceSupporter = (DummyJobHeaderParentJobInvoicingSupporter)jobHeaderParent.InvoicingSupporter;
			jobHeaderInvoiceSupporter.OperationalJobRef = "ABC";
			jobHeaderInvoiceSupporter.ShowOperationalJobRefFilter = true;
			job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Parent = jobHeaderParent;
			chargeNone = job.Charges.AddNew();
			chargeABC = job.Charges.AddNew();
			chargeDEF = job.Charges.AddNew();
			chargeNone.JR_CostReference = "";
			chargeABC.JR_CostReference = "ABC";
			chargeDEF.JR_CostReference = "DEF";
			AssertContainsExactElementsInAnyOrder("Filtering on ABC, so should contain the ABC charge only.", new[] { chargeABC }, job.FilteredCharges);
		}

		public void TestParentDefaultChargeCostReferenceChanged()
		{
			var jobHeaderParent = Factory.New<DummyJobHeaderParent>();
			var jobHeaderInvoiceSupporter = (DummyJobHeaderParentJobInvoicingSupporter)jobHeaderParent.InvoicingSupporter;
			jobHeaderInvoiceSupporter.OperationalJobRef = "ABC";
			jobHeaderInvoiceSupporter.ShowOperationalJobRefFilter = true;
			var job = new Loader(jobHeaderParent).TryCreateWithoutMutexForTestOnly();
			var chargeNone = job.Charges.AddNew();
			var chargeABC = job.Charges.AddNew();
			var chargeDEF = job.Charges.AddNew();
			chargeNone.JR_CostReference = "";
			chargeABC.JR_CostReference = "ABC";
			chargeDEF.JR_CostReference = "DEF";
			AssertContainsExactElementsInAnyOrder("Should contain the ABC charge only.", new[] { chargeABC }, job.FilteredCharges);

			jobHeaderInvoiceSupporter.OperationalJobRef = "HIJ";
			job.ParentOperationalJobRefChanged("ABC", "HIJ", false);
			AssertEquals("chargeABC should have been updated to HIJ.", "HIJ", chargeABC.JR_CostReference);
			AssertContainsExactElementsInAnyOrder("Filtering on HIJ, should contain the ABC(now HIJ) charge only.", new[] { chargeABC }, job.FilteredCharges);

			jobHeaderInvoiceSupporter.OperationalJobRef = "DEF";
			job.ParentOperationalJobRefChanged("XXX", "DEF", false);
			AssertContainsExactElementsInAnyOrder("Should contain the DEF charge only.", new[] { chargeDEF }, job.FilteredCharges);

			jobHeaderInvoiceSupporter.OperationalJobRef = "";
			job.ParentOperationalJobRefChanged("XXX", "", false);
			AssertContainsExactElementsInAnyOrder("Should be filtering on chargeNone.", new[] { chargeNone }, job.FilteredCharges);
		}

		public void TestParentDefaultChargeCostReferenceChangedLeavesConsolCostCharges()
		{
			var consol = TestObjectCreator.CreateConsol("AUSYD", "AUMEL", "0001");
			ForwardingShipment shipment1 = consol.Shipments.AddNew();
			var consolCost = TestObjectCreator.CreateConsolCost(consol, TestObjectCreator.CC1, TestObjectCreator.AALSHI);
			consolCost.E6_RX_NKCurrency = TestObjectCreator.AUD.RX_Code;
			consolCost.E6_OSCostAmount = 100M;
			consolCost.E6_ApportionmentMethod = AllocationMethod.ChargeableUnits;
			consolCost.E6_CostReference = "";
			Factory.Save();

			var charge = consolCost.ApportionmentCharges[0];
			var jobHeaderParent = Factory.New<DummyJobHeaderParent>();
			var jobHeaderInvoiceSupporter = (DummyJobHeaderParentJobInvoicingSupporter)jobHeaderParent.InvoicingSupporter;

			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Parent = jobHeaderParent;
			charge.JR_JH = job.PK;
			Factory.Save();

			jobHeaderInvoiceSupporter.OperationalJobRef = "ABC";
			job = new BusinessObjectFactory().Load<Job>(job.PK);

			AssertEquals("There is a charge on the job", 1, job.Charges.Count);

			job.ParentOperationalJobRefChanged("", "ABC", true);
			AssertEquals("Charge not updated because it has a consol cost.", "", job.Charges[0].JR_CostReference);
			job.ParentOperationalJobRefChanged("", "ABC", false);
			AssertEquals("Charge not updated because it has a consol cost.", "", job.Charges[0].JR_CostReference);
		}

		public void TestParentDefaultChargeCostReferenceChanged_OnFirstSaved()
		{
			var jobHeaderParent = Factory.New<DummyJobHeaderParent>();
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Parent = jobHeaderParent;

			var jobHeaderInvoiceSupporter = (DummyJobHeaderParentJobInvoicingSupporter)jobHeaderParent.InvoicingSupporter;
			jobHeaderInvoiceSupporter.OperationalJobRef = "";
			jobHeaderInvoiceSupporter.ShowOperationalJobRefFilter = true;

			var shipmentCharge = Factory.NewWithValidTestData<Charge>();
			job.Charges.Add(shipmentCharge);

			Factory.Save();

			var tbCharge = Factory.NewWithValidTestData<Charge>();
			job.Charges.Add(tbCharge);

			job.ParentOperationalJobRefChanged("", "ABC", false);
			AssertEquals("Belongs to the shipment (has already been saved)", "", shipmentCharge.JR_CostReference);
			AssertEquals("Belongs to the TB (is a new charge)", "ABC", tbCharge.JR_CostReference);

			job.ParentOperationalJobRefChanged("", "ABC", true);
			AssertEquals("Update any charge", "ABC", shipmentCharge.JR_CostReference);
			AssertEquals("Already updated", "ABC", tbCharge.JR_CostReference);
		}

		public void TestJH_FilterByCostReference()
		{
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			var chargeABC = job.Charges.AddNew();
			chargeABC.JR_CostReference = "ABC";
			AssertEquals("Should not be filtering.", false, job.JH_IsChargeCostReferenceFilterEnabled);
			AssertContainsExactElementsInAnyOrder("Should contain all charges.", new[] { chargeABC }, job.FilteredCharges);

			var jobHeaderParent = Factory.New<DummyJobHeaderParent>();
			var jobHeaderInvoiceSupporter = (DummyJobHeaderParentJobInvoicingSupporter)jobHeaderParent.InvoicingSupporter;
			jobHeaderInvoiceSupporter.OperationalJobRef = "ABC";
			jobHeaderInvoiceSupporter.ShowOperationalJobRefFilter = true;
			job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Parent = jobHeaderParent;
			var chargeNone = job.Charges.AddNew();
			chargeNone.JR_CostReference = "";
			chargeABC = job.Charges.AddNew();
			var chargeDEF = job.Charges.AddNew();
			chargeABC.JR_CostReference = "ABC";
			chargeDEF.JR_CostReference = "DEF";
			AssertEquals("Should be filtering because the parent supplied a cost reference, ABC.", true, job.JH_IsChargeCostReferenceFilterEnabled);
			AssertContainsExactElementsInAnyOrder("Filtering on ABC, so should contain the ABC charge only.", new[] { chargeABC }, job.FilteredCharges);

			job.JH_IsChargeCostReferenceFilterEnabled = false;
			AssertEquals("Filtering turned off.", false, job.JH_IsChargeCostReferenceFilterEnabled);
			AssertContainsExactElementsInAnyOrder("Should not be filtering.", new[] { chargeNone, chargeABC, chargeDEF }, job.FilteredCharges);
		}

