		public void TestJH_TotalTaxExpenseRevenueAndCost()
		{
			GlbStaff testUser = Factory.NewWithValidTestData<GlbStaff>();
			testUser.GS_IsController = false;

			var testBranch = TestObjectCreator.CreateBranch("TBR", "Test Branch", GlbCompany.CurrentCompany);
			Factory.Save();

			var taxProcessorMock = new Mock<ITaxProcessor>();
			ObjectFactory.Substitute(taxProcessorMock.Object);

			using (Env.SetTemporaryUserContext(testUser.GS_LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK))
			{
				var shipment = TestObjectCreator.CreateShipment("S00001234");
				var job = TestObjectCreator.CreateJob(shipment);
				var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 20m, 130m);
				var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.DSBChargeCode, 150m, 170m);
				var chargeNotPosted = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 110m, 230m);

				Factory.Save();

				SetupSecurity(testBranch);

				CombineAssertions(() =>
				{
					AssertEquals("Precondition: job contains 3 charges", 3, job.Charges.Count);
					AssertEquals("Precondition: should show all charges", 3, job.ChargesFilteredByChargeViewingPermission.Count);

					AssertEquals(0m, job.JH_TotalTaxExpenseRevenue);
					AssertEquals(0m, job.JH_TotalTaxExpenseCost);
					AssertEquals(0m, job.JH_TotalTaxExpense_ForTestOnly);
					AssertEquals(0m, job.JH_TotalTaxExpensePosted_ForTestOnly);
					AssertEquals(0m, job.JH_TotalTaxExpensePostedExcludingDSB_ForTestOnly);
					AssertEquals(0m, job.JH_TotalTaxExpenseExcludingDSB_ForTestOnly);

					AssertEquals(230m, job.JH_ProfitLoss);
					AssertEquals(0m, job.JH_ProfitLossPosted);
					AssertEquals(0m, job.JH_ProfitLossPostedExcludingDSB);
					AssertEquals(230m, job.JH_ProfitLossExcludingDSB_ForTestOnly);
					AssertEquals(230m, job.GetTotalProfitAndLossLocal(c => true).Amount);
				});

				SetupTaxExpenseAmountsForCharge(charge1, 7.63m, 12.55m);
				SetupTaxExpenseAmountsForCharge(charge2, 1.02m, 2.02m);

				CombineAssertions(() =>
				{
					AssertEquals(8.65m, job.JH_TotalTaxExpenseRevenue);
					AssertEquals(14.57m, job.JH_TotalTaxExpenseCost);
					AssertEquals(23.22m, job.JH_TotalTaxExpense_ForTestOnly);
					AssertEquals(23.22m, job.JH_TotalTaxExpensePosted_ForTestOnly);
					AssertEquals(20.18m, job.JH_TotalTaxExpensePostedExcludingDSB_ForTestOnly);
					AssertEquals(20.18m, job.JH_TotalTaxExpenseExcludingDSB_ForTestOnly);

					AssertEquals(253.22m, job.JH_ProfitLoss);
					AssertEquals(133.22m, job.JH_ProfitLossPosted);
					AssertEquals(130.18m, job.JH_ProfitLossPostedExcludingDSB);
					AssertEquals(250.18m, job.JH_ProfitLossExcludingDSB_ForTestOnly);
					AssertEquals(253.22m, job.GetTotalProfitAndLossLocal(c => true).Amount);
				});

				charge1.JR_GB = testBranch.PK;
				Factory.ClearCachedValue<bool>(("Login BRN:" + testBranch.GB_Code + " DEP:" + GlbDepartment.CurrentDepartment.GE_Code));

				CombineAssertions(() =>
				{
					AssertEquals("Precondition: job contains 3 charges", 3, job.Charges.Count);
					AssertEquals(2, job.ChargesFilteredByChargeViewingPermission.Count);
					AssertCollectionContains("Precondition : should show charge2", charge2, job.ChargesFilteredByChargeViewingPermission);
					AssertCollectionContains("Precondition : should show chargeNotPosted", chargeNotPosted, job.ChargesFilteredByChargeViewingPermission);

					AssertEquals(1.02m, job.JH_TotalTaxExpenseRevenue);
					AssertEquals(2.02m, job.JH_TotalTaxExpenseCost);
					AssertEquals(3.04m, job.JH_TotalTaxExpense_ForTestOnly);
					AssertEquals(23.22m, job.JH_TotalTaxExpensePosted_ForTestOnly);
					AssertEquals(20.18m, job.JH_TotalTaxExpensePostedExcludingDSB_ForTestOnly);
					AssertEquals(0m, job.JH_TotalTaxExpenseExcludingDSB_ForTestOnly);

					AssertEquals(123.04m, job.JH_ProfitLoss);
					AssertEquals(133.22m, job.JH_ProfitLossPosted);
					AssertEquals(130.18m, job.JH_ProfitLossPostedExcludingDSB);
					AssertEquals(120m, job.JH_ProfitLossExcludingDSB_ForTestOnly);
					AssertEquals(123.04m, job.GetTotalProfitAndLossLocal(c => true).Amount);
				});

				void SetupTaxExpenseAmountsForCharge(Charge charge, ZDecimal totalTaxExpenseRevenue, ZDecimal totalTaxExpenseCost)
				{
					var arInvoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), TestObjectCreator.AUD);
					var arInvLine = TestObjectCreator.CreateRevenueLine(charge, arInvoice.PK);
					taxProcessorMock.Setup(t => t.GetTaxExpenses(Factory, arInvLine.PK)).Returns(new (ZDate TaxExpenseDate, ZDecimal TaxExpenseAmount)[] { (ZDate.Today, totalTaxExpenseRevenue) });

					var apInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice), TestObjectCreator.AUD);
					var apInvLine = TestObjectCreator.CreateCostLine(charge, apInvoice.PK);
					taxProcessorMock.Setup(t => t.GetTaxExpenses(Factory, apInvLine.PK)).Returns(new (ZDate TaxExpenseDate, ZDecimal TaxExpenseAmount)[] { (ZDate.Today, totalTaxExpenseCost) });

					Factory.Save();

					AssertEquals(totalTaxExpenseRevenue, charge.JR_TotalTaxExpenseRevenue);
					AssertEquals(totalTaxExpenseCost, charge.JR_TotalTaxExpenseCost);
				}

				void SetupSecurity(GlbBranch branch)
				{
					BusinessObjectFactory securityFactory = new BusinessObjectFactory();

					SecurityCore security1 = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK);
					SecurityCore security2 = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, branch.PK.ToGuid(), Env.CurrentDepartment.PK);

					GlbSecurity loginSecurity1 = securityFactory.New<GlbSecurity>();
					loginSecurity1.GU_GB = Env.CurrentBranch.PK;
					loginSecurity1.GU_GE = Env.CurrentDepartment.PK;
					loginSecurity1.GU_GS = Env.CurrentUser.PK;
					loginSecurity1.GU_SecurityRight = security1.Login.Code;
					GlbSecurity loginSecurity2 = securityFactory.New<GlbSecurity>();
					loginSecurity2.GU_GB = branch.PK;
					loginSecurity2.GU_GE = Env.CurrentDepartment.PK;
					loginSecurity2.GU_GS = Env.CurrentUser.PK;
					loginSecurity2.GU_SecurityRight = security2.Login.Code;

					GlbSecurity invoicingSecurity = securityFactory.New<GlbSecurity>();
					invoicingSecurity.GU_GB = Env.CurrentBranch.PK;
					invoicingSecurity.GU_GE = Env.CurrentDepartment.PK;
					invoicingSecurity.GU_GS = Env.CurrentUser.PK;
					invoicingSecurity.GU_SecurityRight = security1.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.AllowViewCharges).Code;

					loginSecurity1.GU_SecurityItemIsAllowed = true;
					security1.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.AllowViewCharges).IsAllowed = false;
					invoicingSecurity.GU_SecurityItemIsAllowed = false;
					securityFactory.Save();
				}
			}
		}

		public void TestJH_ProfitLoss()
		{
			Charge testCharge1 = GetTestCharge();
			AccTransactionLines cfxLine1 = Factory.NewWithValidTestData<AccTransactionLines>();
			cfxLine1.AL_LineType = TransactionLineTypes.Revenue;
			cfxLine1.AL_LineAmount = 10;
