			testCharge1.JR_LocalCostAmt = 10;
			testCharge1.JR_LocalSellAmt = 20;
			TestJob.Charges.Add(testCharge1);

			Charge testCharge2 = GetTestCharge();
			AccTransactionLines cfxLine2 = Factory.NewWithValidTestData<AccTransactionLines>();
			cfxLine2.AL_LineType = TransactionLineTypes.Revenue;
			cfxLine2.AL_LineAmount = 70;
			testCharge2.JR_AL_CFXLine = cfxLine2.PK;
			testCharge2.JR_LocalCostAmt = 30;
