		public void TestScenarioWhenJobIsCanceledFromJobManagmentModule()
		{
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			var relaodedJob = newFactory.Load<Job>(job.PK);
			var mockSupporter = TestObjectCreator.GetIJobInvoicingSupporterMock();
			var mockPlugin = TestObjectCreator.GetTestShipmentPlugInMock("S0000001", mockSupporter);
			mockPlugin.CallBase = true;
			mockPlugin.Setup(m => m.OnJobDeleting(It.IsAny<JobHeader>()));
			mockPlugin.Setup(m => m.OnJobDeleted(It.IsAny<JobHeader>()));
			relaodedJob.Parent = mockPlugin.Object;

			relaodedJob.MarkAsInactive();
			Factory.Save();

			AssertEquals($"Found Type: {mockPlugin.Object.GetType()} which did not equal the expected Castle.Proxies.IJobInvoicingPlugInProxy", "Castle.Proxies.IJobInvoicingPlugInProxy", mockPlugin.Object.GetType().ToString());
			AssertNoExceptionThrown(() =>
			{
				mockPlugin.Verify(m => m.OnJobDeleting(It.IsAny<JobHeader>()));
				mockPlugin.Verify(m => m.OnJobDeleted(It.IsAny<JobHeader>()));
			});
		}

