		public void TestSetDefaultValuesForNullObject()
		{
			// JH_Status and JH_GS_NKRepOps are visible from the shipment search grid and the columns are bound like this: Job+JH_Status.
			// When there is no Job for the shipment, a null object will be created by ZArchitecture so the binding can still work.
			// If the Job has been created for this purpose, then it won't be saved.
			// When this null object is shown in the grid, we should be showing an empty string for both fields, not the current user and working status.

			var job = Factory.NewJobForTesting<Job>();
			AssertEquals(JobHeaderStatus.Working.Code, TestJob.JH_Status);
			AssertEquals(GlbStaff.CurrentUser.GS_Code, TestJob.JH_GS_NKRepOps);

			var nullJob = Factory.GetNull<Job>();
			AssertEquals("", nullJob.JH_Status);
			AssertEquals("", nullJob.JH_GS_NKRepOps);
		}

		public override void TestSetDefaultValues()
		{
			AssertEquals(JobHeaderStatus.Working.Code, TestJob.JH_Status);
			AssertEquals(GlbStaff.CurrentUser.GS_Code, TestJob.JH_GS_NKRepOps);

			string origin = "XXXXX"; // foreign country
			string destination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;

			JobSailing sailing = Factory.New<JobSailing>();
			JobVoyage voyage = Factory.New<JobVoyage>();

			VoyageOrigin voyageOrigin = voyage.Origins.AddNew();
			voyageOrigin.JA_RL_NKPortOfLoading = origin;
			VoyageDestination voyageDestination = voyage.Destinations.AddNew();
			voyageDestination.JB_RL_NKPortOfDischarge = destination;
			sailing.JX_JA = voyageOrigin.PK;
			sailing.JX_JB = voyageDestination.PK;

			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = Enterprise.Core.Constants.TransportModes.Sea;

			Transport transport = consol.Transports[0];
			transport.JW_JX = sailing.PK;
			transport.JW_RL_NKLoadPort = origin;
			transport.JW_RL_NKDiscPort = destination;

			consol.SetDefaultSendingForwarderAddress(TestObjectCreator.AALSHI);
			consol.SetDefaultReceivingForwarderAddress(TestObjectCreator.ABIGAS);

			GlbDepartment department = Factory.New<GlbDepartment>();
			department.GE_Code = "FEA";
			TestJob.JH_GE = ZGuid.Empty;
			TestJob.JH_GE = department.PK;

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.Consols.Add(consol);
			shipment.JS_RL_NKOrigin = origin;
			shipment.JS_RL_NKDestination = destination;

			TestJob.PlugInData = shipment;
			TestJob.JH_GE = department.PK;

			AssertEquals("For jobs on import consols, default OS agent should be sending agent.", ((IJobInvoicingPlugIn)shipment).InvoicingSupporter.SendingAgent.PK, TestJob.AgentCollectPK);
		}

		public void TestSetDefaultValues_SalesRep()
		{
			InvoicingParam plugInData = new InvoicingParam();

			OrgHeader org1 = Factory.NewWithValidTestData<OrgHeader>();
			org1.OH_Code = "OH1";
			OrgHeader org2 = Factory.NewWithValidTestData<OrgHeader>();
			org2.OH_Code = "OH2";
			Factory.Save();

			GlbStaff newAirStaff = Factory.NewWithValidTestData<GlbStaff>();
			newAirStaff.GS_Code = "AAA";
			GlbStaff newSeaStaff = Factory.NewWithValidTestData<GlbStaff>();
			newSeaStaff.GS_Code = "BBB";
			GlbStaff newWhsStaff = Factory.NewWithValidTestData<GlbStaff>();
			newWhsStaff.GS_Code = "CCC";
			GlbStaff newAllStaff = Factory.NewWithValidTestData<GlbStaff>();
			newAllStaff.GS_Code = "DDD";
			GlbStaff newSalesRep = Factory.NewWithValidTestData<GlbStaff>();
			newSalesRep.GS_Code = "MXU";

			GlbBranch branch = Factory.NewWithValidTestData<GlbBranch>();

			org1.StaffAssignments.ImportAirRep = newAirStaff.GS_Code;
			org1.StaffAssignments.ImportSeaRep = newSeaStaff.GS_Code;
			org1.StaffAssignments.WarehousingRep = newWhsStaff.GS_Code;
			org1.StaffAssignments.OverallSalesRep = newAllStaff.GS_Code;
			org1.CompanyData.OB_GB_ControllingBranch = branch.PK;

			plugInData.JobNumber = TestObjectCreator.GetRandomString(8);
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			plugInData.IsImport = true;
			plugInData.ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Constants.TransportModes.Air;
			TestJob.PlugInData = plugInData;
			TestJob.LocalChargesPK = org1.PK;
			Factory.Save();
			AssertEquals("Sales Rep must be Import Air Sales Rep from Local Charges Organization", org1.StaffAssignments.ImportAirRep, TestJob.JH_GS_NKRepSales);

			TestJob.LocalChargesPK = org2.PK;
			AssertEquals("Sales rep should be empty when Local Client Organization doesn't have sales rep", ZString.Empty, TestJob.JH_GS_NKRepSales);

			var shipmentAllowOverrideSalesRepCheckPoint = Env.Security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainShipmentJobInvoicing, SecurityCore.AllowOverrideSalesRep);
			shipmentAllowOverrideSalesRepCheckPoint.IsAllowed = false;
			TestJob.LocalChargesPK = org1.PK;
			TestJob.JH_GS_NKRepSales = newSalesRep.GS_Code;
			AssertHasError(TestJob.JH_GS_NKRepSalesInfo, "You do not have sufficient security rights to modify this field. You must reset the value to its previous value AAA");

			org2.StaffAssignments.ImportAirRep = newSalesRep.GS_Code;
			TestJob.LocalChargesPK = org2.PK;
			AssertNoErrors(TestJob.JH_GS_NKRepSalesInfo);
			AssertEquals("Sales rep should be updated when local client has changed.", newSalesRep.GS_Code, TestJob.JH_GS_NKRepSales);

			shipmentAllowOverrideSalesRepCheckPoint.IsAllowed = true;
			TestJob.JH_GS_NKRepSales = ZString.Empty;
			shipmentAllowOverrideSalesRepCheckPoint.IsAllowed = false;
			TestJob.SetDefaultsForJob();
			AssertNoErrors(TestJob.JH_GS_NKRepSalesInfo);
			AssertEquals("Sales rep should be updated when orignal sales rep is empty.", newSalesRep.GS_Code, TestJob.JH_GS_NKRepSales);
		}

