		public void TestJH_StatusCloseJobWithUnapprovedTransactions()
		{
			TestJob.JH_Status = JobHeaderStatus.Working.Code;
			AssertNoErrors("Valid job status", TestJob.JH_StatusInfo);

			UAInvoice uaInvoice = Factory.NewWithValidTestData<UAInvoice>();
			UAInvoiceLine line = (UAInvoiceLine)uaInvoice.Lines.AddNew();

			Charge charge = TestJob.Charges.AddNew();
			charge.JR_AL_APLine = line.PK;

			TestJob.OnCloseJobError += new ErrorMessageHandler(Job_OnCloseJobError);
			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			AssertEquals("Status should not be changed", JobHeaderStatus.Working.Code, TestJob.JH_Status);
			Assert("Error handler should be called", OnCloseJobErrorCalled);

			TestJob.OnCloseJobError -= new ErrorMessageHandler(Job_OnCloseJobError);
			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			AssertEquals("Status should be changed", JobHeaderStatus.Working.Code, TestJob.JH_Status);
			Assert("Error handler should be called", OnCloseJobErrorCalled);
		}

