		public void TestFARRecognizedWhenPostDisbursementCharge()
		{
			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);

			var revenueRecognitionCollection = new RevenueRecognitionCollection();
			var revenueRecognitionFAR = revenueRecognitionCollection.AddNew();
			revenueRecognitionFAR.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			revenueRecognitionFAR.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, revenueRecognitionCollection);

			var revenueRecognitionByChargeGroupCollection = AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.Value;
			foreach (RevenueRecognitionByChargeGroup revenueRecognitionByChargeGroup in revenueRecognitionByChargeGroupCollection)
			{
				if (revenueRecognitionByChargeGroup.ChargeGroup == ChargeCodeGroupList.Codes.CustomsDuty)
				{
					RevenueRecognition revenueRecognitionIMM = revenueRecognitionByChargeGroup.ChargeGroupSettings.AddNew();
					revenueRecognitionIMM.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
					revenueRecognitionIMM.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
				}
			}
			AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, revenueRecognitionByChargeGroupCollection);

			var changeStatusCollection = new CodeDescriptionBoolDisallowNewCollection();
			var changeStatus = changeStatusCollection.AddNew();
			changeStatus.Code = JobHeaderStatus.Working.Code;
			changeStatus.Bool = true;

			AccountingConfigurationRegistry.Instance.SetJobStatusToInvoicedWhenFirstARInvoicePosted.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, changeStatusCollection);

			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			TestJob.Parent = shipment;
			TestJob.JH_Status = JobHeaderStatus.Working.Code;

			TestObjectCreator.DSBChargeCode.AC_ChargeGroup = ChargeCodeGroupList.Codes.CustomsDuty;
			var frt = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.FRT, debtor: TestObjectCreator.Debtor);
			var dsb = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.DSBChargeCode, debtor: TestObjectCreator.Debtor);
			dsb.JR_InvoiceType = InvoiceTypesList.Codes.DisbursementInvoice;

			Factory.Save();

			AssertEquals("Precondition: Cost recognition of DSB charge should be 'IMM'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, dsb.CostRecognition);
			AssertEquals("Precondition: Sell recognition of DSB charge should be 'IMM'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, dsb.SellRecognition);
			AssertEquals("Precondition: Cost recognition of FRT charge should be 'FAR'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, frt.CostRecognition);
			AssertEquals("Precondition: Sell recognition of FRT charge should be 'FAR'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, frt.SellRecognition);

			var postManager = new InvoicingPostManager(TestJob);
			postManager.CreateTransactions(JobInvoicingPostingOption.Disbursement);

			Factory.Save();

			AssertEquals("Job Status should still be working", JobHeaderStatus.Working.Code, TestJob.JH_Status);

			var query = new ZQuery();
			query.AddToFilter(AccTransactionLinesSchema.AL_AC, TestObjectCreator.DSBChargeCode.PK);
			var lines = Factory.Load<AccTransactionLines>(query);

			AssertEquals(3, lines.Length);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.WIP).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.Accrual).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.Revenue).AL_RevRecognitionType);

			query = new ZQuery();
			query.AddToFilter(AccTransactionLinesSchema.AL_AC, TestObjectCreator.FRT.PK);
			lines = Factory.Load<AccTransactionLines>(query);

			AssertEquals(2, lines.Length);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, lines.First(x => x.AL_LineType == TransactionLineTypes.WIP).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, lines.First(x => x.AL_LineType == TransactionLineTypes.Accrual).AL_RevRecognitionType);
		}

		public void TestRevenueRecognizedAsFARWhenEitherCostAndSellRecognitonIsFAR()
		{
			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);

			var changeStatusCollection = new CodeDescriptionBoolDisallowNewCollection();
			var changeStatus = changeStatusCollection.AddNew();
			changeStatus.Code = JobHeaderStatus.Working.Code;
			changeStatus.Bool = true;

			AccountingConfigurationRegistry.Instance.SetJobStatusToInvoicedWhenFirstARInvoicePosted.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, changeStatusCollection);

			var revenueRecognitionByChargeGroupCollection = AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.Value;
			foreach (RevenueRecognitionByChargeGroup revenueRecognitionByChargeGroup in revenueRecognitionByChargeGroupCollection)
			{
				if (revenueRecognitionByChargeGroup.ChargeGroup == ChargeCodeGroupList.Codes.CustomsDuty)
				{
					RevenueRecognition revenueRecognitionIMM = revenueRecognitionByChargeGroup.ChargeGroupSettings.AddNew();
					revenueRecognitionIMM.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
					revenueRecognitionIMM.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
				}
			}
			AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, revenueRecognitionByChargeGroupCollection);

			AccountingConfigurationRegistry.Instance.CreateWIPOrAccrualWhenNoInvoicesPosted.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			AccountingConfigurationRegistry.Instance.WIPMustHaveDebtorCode.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			shipment.JS_E_DEP = ZDateTime.Today;
			TestJob.Parent = shipment;
			TestJob.JH_Status = JobHeaderStatus.Working.Code;

			var frt = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.FRT, "desc", TestObjectCreator.AUD, 100m, TestObjectCreator.Creditor2);
			frt.JR_APInvoiceDate = ZDateTime.Today;
			frt.JR_APInvoiceNum = "INV_001";

			TestObjectCreator.DSBChargeCode.AC_ChargeGroup = ChargeCodeGroupList.Codes.CustomsDuty;
			var dsb = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.DSBChargeCode, "desc", TestObjectCreator.AUD, 200m, TestObjectCreator.Creditor2);
			dsb.JR_APInvoiceDate = ZDateTime.Today;
			dsb.JR_APInvoiceNum = "INV_001";
			Factory.Save();

			var postManager = new InvoicingPostManager(TestJob);
			postManager.CreateTransactions(JobInvoicingPostingOption.Costs);
			Factory.Save();

			var revenueRecognitionCollection = new RevenueRecognitionCollection();
			var revenueRecognition = revenueRecognitionCollection.AddNew();
			revenueRecognition.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			revenueRecognition.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, revenueRecognitionCollection);
			Factory.Save();

			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			AssertEquals("Precondition: Cost recognition of FRT charge should be 'IMM'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, frt.CostRecognition);
			AssertEquals("Precondition: Sell recognition of FRT charge should be 'FAR'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, frt.SellRecognition);
			AssertEquals("Precondition: Cost recognition of DSB charge should be 'IMM'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, dsb.CostRecognition);
			AssertEquals("Precondition: Sell recognition of DSB charge should be 'IMM'.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, dsb.SellRecognition);

			frt.JR_OH_SellAccount = TestObjectCreator.Debtor.PK;
			dsb.JR_OH_SellAccount = TestObjectCreator.Debtor.PK;
			dsb.JR_InvoiceType = InvoiceTypesList.Codes.DisbursementInvoice;
			Factory.Save();

			postManager.CreateTransactions(JobInvoicingPostingOption.Disbursement);
			Factory.Save();

			AssertEquals("Job Status should still be working", JobHeaderStatus.Working.Code, TestJob.JH_Status);

			var query = new ZQuery();
			query.AddToFilter(AccTransactionLinesSchema.AL_AC, TestObjectCreator.DSBChargeCode.PK);
			var lines = Factory.Load<AccTransactionLines>(query);

			AssertEquals(3, lines.Length);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.WIP).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.Cost).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.Revenue).AL_RevRecognitionType);

			query = new ZQuery();
			query.AddToFilter(AccTransactionLinesSchema.AL_AC, TestObjectCreator.FRT.PK);
			lines = Factory.Load<AccTransactionLines>(query);

			AssertEquals(2, lines.Length);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, lines.First(x => x.AL_LineType == TransactionLineTypes.Cost).AL_RevRecognitionType);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, lines.First(x => x.AL_LineType == TransactionLineTypes.WIP).AL_RevRecognitionType);
		}

		public void TestJobContainsFARChargeCache()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			TestJob.Parent = shipment;
			TestJob.JH_Status = JobHeaderStatus.Working.Code;

			var invoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
			invoice.AH_JH = TestJob.PK;

			var line = invoice.Lines.AddNew() as InvoicingLineBase;
			line.AL_LineType = TransactionLineTypes.Revenue;
			line.AL_JH = TestJob.PK;
			line.AL_AC = TestObjectCreator.CC1.PK;
			line.AL_PostDate = ZDateTime.Today;

			var charge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, debtor: TestObjectCreator.Debtor);

			var anotherShipment = TestObjectCreator.CreateShipment("S0002", "AUSYD", "USALX");
			var anotherJob = TestObjectCreator.CreateJob(anotherShipment, TestObjectCreator.Creditor2, 0, null, 0);
			anotherJob.JH_Status = JobHeaderStatus.Working.Code;

			var anotherInvoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice));
			anotherInvoice.AH_JH = anotherJob.PK;

			var anotherLine = anotherInvoice.Lines.AddNew() as InvoicingLineBase;
			anotherLine.AL_LineType = TransactionLineTypes.Revenue;
			anotherLine.AL_JH = anotherJob.PK;
			anotherLine.AL_AC = TestObjectCreator.CC1.PK;
			anotherLine.AL_PostDate = ZDateTime.Today;

			var anotherCharge = TestObjectCreator.CreateCharge(anotherJob, TestObjectCreator.CC1, debtor: TestObjectCreator.Debtor);

			TestJob.ApplyRevenueRecognitionDate(line);

			var chargeRevRecOverride = TestObjectCreator.CC2.RevenueRecOverrides.AddNew();
			chargeRevRecOverride.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			chargeRevRecOverride.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			var charge1 = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC2, debtor: TestObjectCreator.Debtor);
			var line1 = invoice.Lines.AddNew() as InvoicingLineBase;
			line1.AL_LineType = TransactionLineTypes.Revenue;
			line1.AL_JH = TestJob.PK;
			line1.AL_AC = TestObjectCreator.CC2.PK;
			line1.AL_PostDate = ZDateTime.Today;

			var anotherCharge1 = TestObjectCreator.CreateCharge(anotherJob, TestObjectCreator.CC2, debtor: TestObjectCreator.Debtor);
			var anotherLine1 = anotherInvoice.Lines.AddNew() as InvoicingLineBase;
			anotherLine1.AL_LineType = TransactionLineTypes.Revenue;
			anotherLine1.AL_JH = anotherJob.PK;
			anotherLine1.AL_AC = TestObjectCreator.CC2.PK;
			anotherLine1.AL_PostDate = ZDateTime.Today;

			TestJob.ApplyRevenueRecognitionDate(line);
			anotherJob.ApplyRevenueRecognitionDate(anotherLine);

			var query = new ZQuery(JobChargeRevRecognitionSchema.D3_JH, TestJob.PK);
			query.AddToFilter(JobChargeRevRecognitionSchema.D3_RecognitionType, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
			var revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(query);
			AssertNull("Should not create FAR revenue recognition for job as has false cache", revRecognition);

			var anotherQuery = new ZQuery(JobChargeRevRecognitionSchema.D3_JH, anotherJob.PK);
			anotherQuery.AddToFilter(JobChargeRevRecognitionSchema.D3_RecognitionType, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
			revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(anotherQuery);
			AssertNotNull("Should create FAR revenue recognition for job as no cache", revRecognition);

			TestJob.ClearCacheOfContainsFARCharge_ForTestsOnly(TestJob.PK);
			TestJob.ApplyRevenueRecognitionDate(line);

			revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(query);
			AssertNotNull("Should create FAR revenue recognition for job as false cache cleared", revRecognition);
		}

