		void AssertRevenueRecognitionTypeForLTCJobType(string recognitionDateOptionCode, ZDateTime expectedRecognitionDate)
		{
			TestObjectCreator.CreateTestPeriods(new ZDateTime(2014, 06, 01));

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = "LTC";
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = recognitionDateOptionCode;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			Factory.Save();

			var plugin = this.TestObjectCreator.CreateJobPlugIn(JobInvoicingConsumerTypes.TransportConsignment);
			var job = this.TestObjectCreator.CreateJob(plugin);
			(plugin as BusinessObject).GetLogs().AddNew(new EventValue(Events.PickedUp, eventTime: new ZDateTimeOffset(2014, 10, 15)));
			(plugin as BusinessObject).GetLogs().AddNew(new EventValue(Events.Delivered, eventTime: new ZDateTimeOffset(2014, 10, 25)));
			Factory.Save();

			job = Factory.Load<Job>(job.PK);
			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 100m, 100m);
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 100m, 100m);
			charge1.JR_OH_SellAccount = charge2.JR_OH_SellAccount = TestObjectCreator.AALSHI.PK;

			job.ApplyRevenueRecognitionDateForWholeJob(out _);

			Factory.Save();

			var query = new ZQuery(JobChargeRevRecognitionSchema.D3_JH, job.PK);
			query.AddToFilter(JobChargeRevRecognitionSchema.D3_RecognitionType, recognitionDateOptionCode);
			var revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(query);
			AssertNotNull("Job Revenue Recognition information shouldn't be null", revRecognition);
			AssertEquals("Revenue Recognition Type", recognitionDateOptionCode, revRecognition.D3_RecognitionType);
			AssertEquals("Revenue Recognition Date", expectedRecognitionDate, revRecognition.D3_RecognitionDate);
		}

