		public void TestClosingJob()
		{
			OrgHeader creditor1 = Factory.New<OrgHeader>();
			creditor1.OH_Code = "CRED1";
			OrgHeader creditor2 = Factory.New<OrgHeader>();
			creditor2.OH_Code = "CRED2";
			Factory.Save();

			TestJob.JH_JobNum = TestObjectCreator.GetRandomString(8);
			TestJob.LocalChargesPK = creditor1.PK;
			Factory.Save();
			TestJob.Reload();

			AccTransactionHeader aRTransaction = Factory.NewWithValidTestData<ARInvoice>();
			AccTransactionLines aRTransactionLine = Factory.NewWithValidTestData<ARInvoiceLine>();
			aRTransactionLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			aRTransactionLine.AL_AH = aRTransaction.PK;
			aRTransactionLine.AL_AG = TestObjectCreator.GLHeader1.PK;

			AccTransactionHeader aPTransaction = Factory.NewWithValidTestData<APInvoice>();
			AccTransactionLines aPTransactionLine = Factory.NewWithValidTestData<APInvoiceLine>();
			aPTransactionLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Cost;
			aPTransactionLine.AL_AH = aPTransaction.PK;
			aPTransactionLine.AL_AG = TestObjectCreator.GLHeader1.PK;

			WIP wIP1 = Factory.New<WIP>();
			wIP1.AL_JH = TestJob.PK;
			wIP1.AL_AG = TestObjectCreator.GLHeader1.PK;

			Accrual aCR = Factory.New<Accrual>();
			aCR.AL_JH = TestJob.PK;
			aCR.AL_AG = TestObjectCreator.GLHeader1.PK;

			Accrual aCR2 = Factory.New<Accrual>();
			aCR2.AL_JH = TestJob.PK;
			aCR2.AL_AG = TestObjectCreator.GLHeader1.PK;

			Charge testCharge1 = TestJob.Charges.AddNew();
			testCharge1.JR_OH_SellAccount = creditor2.PK;
			testCharge1.JR_OSCostAmt = 10;
			testCharge1.JR_OSSellAmt = 20;
			testCharge1.JR_AL_ARLine = aRTransactionLine.PK;
			testCharge1.ARLine.AL_OSAmount = testCharge1.ARLine.AL_LineAmount = testCharge1.JR_OSSellAmt;
			testCharge1.JR_AL_APLine = aPTransactionLine.PK;
			testCharge1.APLine.AL_OSAmount = testCharge1.APLine.AL_LineAmount = -testCharge1.JR_OSCostAmt;
			testCharge1.JR_AC = TestObjectCreator.CC1.PK;

			Charge testCharge2 = TestJob.Charges.AddNew();
			testCharge2.JR_OH_SellAccount = creditor1.PK;
			testCharge2.JR_OSCostAmt = 100;
			testCharge2.JR_OSSellAmt = 200;
			testCharge2.JR_AL_APLine = aCR.PK;
			testCharge2.JR_AC = TestObjectCreator.CC2.PK;
			testCharge2.APLine.AL_OSAmount = testCharge2.APLine.AL_LineAmount = -testCharge2.JR_OSCostAmt;

			Charge testCharge3 = TestJob.Charges.AddNew();
			testCharge3.JR_OSCostAmt = 1000;
			testCharge3.JR_OSSellAmt = 2000;
			testCharge3.JR_AL_ARLine = wIP1.PK;
			testCharge3.ARLine.AL_OSAmount = testCharge3.ARLine.AL_LineAmount = testCharge3.JR_OSSellAmt;
			testCharge3.JR_AL_APLine = aCR2.PK;
			testCharge3.APLine.AL_OSAmount = testCharge3.APLine.AL_LineAmount = -testCharge3.JR_OSCostAmt;
			testCharge3.JR_AC = TestObjectCreator.CC3.PK;

			TestJob.Close(null, null);
			Factory.Save();

			AssertEquals(JobHeaderStatus.Closed.Code, TestJob.JH_Status);
			AssertEquals("Revenue Recognition Date should be equal Immediate Date", AccountingConstants.RevenueRecognitionDateConstants.Immediate, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			AssertEquals(10m, testCharge1.JR_OSCostAmt);
			AssertEquals(20m, testCharge1.JR_OSSellAmt);
			AssertEquals(aRTransactionLine.PK, testCharge1.JR_AL_ARLine);
			AssertEquals(aPTransactionLine.PK, testCharge1.JR_AL_APLine);

			AssertEquals(0m, testCharge2.JR_OSCostAmt);
			AssertEquals(0m, testCharge2.JR_OSSellAmt);
			AssertEquals(ZGuid.Empty, testCharge2.JR_AL_ARLine);
			AssertEquals(ZGuid.Empty, testCharge2.JR_AL_APLine);

			AssertEquals(0m, testCharge3.JR_OSCostAmt);
			AssertEquals(0m, testCharge3.JR_OSSellAmt);
			AssertEquals(ZGuid.Empty, testCharge3.JR_AL_ARLine);
			AssertEquals(ZGuid.Empty, testCharge3.JR_AL_APLine);

			Assert(wIP1.IsReversed);
			Assert(aCR.IsReversed);
			Assert(aCR2.IsReversed);
		}

		#region TestDeleteUnpostedLines

		public void TestDeleteUnpostedLines()
		{
			AssertEquals(0, TestJob.Charges.Count);
			var testCharge1 = TestJob.Charges.AddNew();
			var testCharge2 = TestJob.Charges.AddNew();
			var testCharge3 = TestJob.Charges.AddNew();
			var testCharge4 = TestJob.Charges.AddNew();
			var testCharge5 = TestJob.Charges.AddNew();
			AssertEquals(5, TestJob.Charges.Count);

			AccTransactionLines transactionLine1 = Factory.New<AccTransactionLines>();
			transactionLine1.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Cost;
			testCharge1.JR_AL_APLine = transactionLine1.PK;

			AccTransactionLines transactionLine2 = Factory.New<AccTransactionLines>();
			transactionLine2.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			testCharge2.JR_AL_ARLine = transactionLine2.PK;

			AccTransactionLines transactionLine4 = Factory.New<AccTransactionLines>();
			transactionLine4.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			testCharge4.JR_AL_ARLine = transactionLine4.PK;

			int jobChargesListChangedHitCount = 0;
			var listChangedHandler = new ListChangedEventHandler(
				(sender, e) =>
				{ jobChargesListChangedHitCount++; }
			);
			((IBindingList)TestJob.Charges).ListChanged += listChangedHandler;

			TestJob.DeleteUnpostedLines();

			AssertEquals("ListChanged on TestJob.Charges should be called once", 1, jobChargesListChangedHitCount);
			AssertEquals(3, TestJob.Charges.Count);
			Assert(TestJob.Charges.Contains(testCharge1));
			Assert(TestJob.Charges.Contains(testCharge2));
			Assert(TestJob.Charges.Contains(testCharge4));
		}

