		[DisableZeroExchangeRateOverriding]
		public void TestAddCurrency()
		{
			TestObjectCreator.ABIGAS.CompanyData.AccARExchangeRateConfigurations.SetExRate(LedgerTypes.AccountsReceivable, JobInvoicingConsumerTypes.Shipment.Code, OrgConstants.ServiceDirection.Code.Export, OrgConstants.ModesForGroupOrSubTotal.Codes.Sea,
				Constants.ExchangeRateTypes.Code.SellRate, preference: Constants.JobBillingExchangeRatePreference.Code.TodaysRate);

			var rate = TestObjectCreator.EUR.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Today.AddDays(-2);
			rate.RE_ExpiryDate = ZDateTime.Today.AddDays(2);
			rate.RE_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;
			rate.RE_SellRate = 1.56m;

			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			TestJob.Parent = shipment;

			Factory.Save();
			ExchangeRateReader.GetReaderInstance().ClearCache();

			AssertEquals("Initially no exchange rates", 0, TestJob.ExchangeRates.Count);
			var exRateAR = TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AR);
			AssertEquals("Should contain USD rate now", 1, TestJob.ExchangeRates.Count);
			AssertExchangeRate(exRateAR, USD.RX_Code, ExchangeRateOrgTypeEnum.Debtor, ZGuid.Empty, 0m);

			AssertNull(this.TestJob.AddCurrency(null, ExchangeRateValidLedgerEnum.AR));
			AssertEquals("Should still only have 1 row", 1, TestJob.ExchangeRates.Count);

			var exRate2 = TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AR);
			AssertNotNull(exRate2);
			AssertEquals("Should be the same ExchangeRate", exRateAR.PK, exRate2.PK);

			var exRateAP = TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AP);
			AssertEquals("Should contain USD rates now", 2, TestJob.ExchangeRates.Count);
			AssertExchangeRate(exRateAP, USD.RX_Code, ExchangeRateOrgTypeEnum.Creditor, ZGuid.Empty, 0m);

			// Picking up existing System Exchange Rate based on the configuration
			exRateAR = TestJob.AddCurrency(TestObjectCreator.EUR, TestObjectCreator.ABIGAS.PK, ExchangeRateValidLedgerEnum.AR);
			AssertEquals("Should contain EUR rate now", 3, TestJob.ExchangeRates.Count);
			AssertExchangeRate(exRateAR, TestObjectCreator.EUR.RX_Code, ExchangeRateOrgTypeEnum.Debtor, TestObjectCreator.ABIGAS.PK, 1.56m);

			// Passing exchange rate as a parameter
			exRate2 = TestJob.AddCurrency(TestObjectCreator.EUR, 1.6m, ExchangeRateValidLedgerEnum.AR);
			AssertEquals("Should contain EUR rates now", 4, TestJob.ExchangeRates.Count);
			AssertNotEquals("Should be new ExchangeRate", exRateAR.PK, exRate2.PK);
			AssertExchangeRate(exRate2, TestObjectCreator.EUR.RX_Code, ExchangeRateOrgTypeEnum.Debtor, ZGuid.Empty, 1.6m);

			// Existing ExchangeRate is not updated when we try to add matching one with different ex rate
			exRate2 = TestJob.AddCurrency(TestObjectCreator.EUR, 1.61m, TestObjectCreator.ABIGAS.PK, ExchangeRateValidLedgerEnum.AR);
			AssertEquals("Should contain same EUR rate", 4, TestJob.ExchangeRates.Count);
			AssertEquals("Should be the same ExchangeRate", exRateAR.PK, exRate2.PK);
			AssertExchangeRate(exRateAR, TestObjectCreator.EUR.RX_Code, ExchangeRateOrgTypeEnum.Debtor, TestObjectCreator.ABIGAS.PK, 1.56m);

			// Adding Currency with specific exchange rate for an Org and Ledger
			exRate2 = TestJob.AddCurrency(USD, 1.5m, TestObjectCreator.ABIGAS.PK, ExchangeRateValidLedgerEnum.AP);
			AssertEquals("Should contain more USD rates now", 5, TestJob.ExchangeRates.Count);
			AssertNotEquals("Should be new ExchangeRate", exRateAP.PK, exRate2.PK);
			AssertExchangeRate(exRate2, USD.RX_Code, ExchangeRateOrgTypeEnum.Creditor, TestObjectCreator.ABIGAS.PK, 1.5m);
		}

		void AssertExchangeRate(ExchangeRate exRate, string currencyCode, ExchangeRateOrgTypeEnum orgType, ZGuid orgPK, decimal baseRate, decimal cfx = 0m, decimal cfxMin = 0m, bool isTransformed = false)
		{
			AssertEquals("JF_RX_NKRateCurrency", currencyCode, exRate.JF_RX_NKRateCurrency);
			AssertEquals("JF_OrgType", orgType.ToCode(), exRate.JF_OrgType);
			AssertEquals("JF_OH_Org", orgPK, exRate.JF_OH_Org);
			AssertEquals("JF_BaseRate", baseRate, exRate.JF_BaseRate);
			AssertEquals("JF_CFXPercent", cfx, exRate.JF_CFXPercent);
			AssertEquals("JF_CFXMinimum", cfxMin, exRate.JF_CFXMinimum);
			AssertEquals("JF_SellRate for AU company", cfx == decimal.Zero ? baseRate : (baseRate * (100m - cfx) / 100m), exRate.JF_SellRate);
			AssertEquals("JF_IsTransformed", isTransformed, exRate.JF_IsTransformed);
		}

		[TestDate(2023, 01, 16)]
		public void TestUpdateBaseExchangeRate_InvoiceCurrencyType()
		{
			using (AccountingMasterFilesRegistry.Instance.EnableInvoiceCurrencyType.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				CreateRefExRate(TestObjectCreator.EUR.RX_Code, new ZDateTime(2023, 1, 1), new ZDateTime(2023, 1, 7), 1.5m);
				CreateRefExRate(TestObjectCreator.EUR.RX_Code, new ZDateTime(2023, 1, 8), new ZDateTime(2023, 1, 15), 2m);
				CreateRefExRate(TestObjectCreator.EUR.RX_Code, new ZDateTime(2023, 1, 16), new ZDateTime(2023, 1, 16), 2.5m);

				CreateAccExchangeRateConfiguration(Core.Constants.InvoicePostingExchangeRateCurrencyType.Code.Local, -10);
				var foreignConfig = CreateAccExchangeRateConfiguration(Core.Constants.InvoicePostingExchangeRateCurrencyType.Code.Foreign, -2);

				Factory.Save();

				var jobExRate1 = TestJob.ExchangeRates.AddNew();
				jobExRate1.JF_RX_NKRateCurrency = TestObjectCreator.EUR.RX_Code;
				jobExRate1.JF_OrgType = ExchangeRateOrgTypeEnum.Debtor.ToCode();
				jobExRate1.JF_BaseRate = 1.5m;

				var jobExRate2 = TestJob.ExchangeRates.AddNew();
				jobExRate2.JF_RX_NKRateCurrency = TestObjectCreator.EUR.RX_Code;
				jobExRate2.JF_OrgType = ExchangeRateOrgTypeEnum.Debtor.ToCode();
				jobExRate2.JF_InvoiceCurrencyType = InvoicePostingExchangeRateCurrencyType.Code.Foreign;
				jobExRate2.JF_BaseRate = 2m;

				var jobExRate3 = TestJob.ExchangeRates.AddNew();
				jobExRate3.JF_RX_NKRateCurrency = TestObjectCreator.EUR.RX_Code;
				jobExRate3.JF_OrgType = ExchangeRateOrgTypeEnum.Debtor.ToCode();
				jobExRate3.JF_InvoiceCurrencyType = InvoicePostingExchangeRateCurrencyType.Code.Local;
				jobExRate3.JF_BaseRate = 2.5m;

				AssertJobExRatesBaseRate(1.5m, 2m, 2.5m);

				TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 3m, invoiceCurrencyType: InvoiceCurrencyType.NotApplicable);
				AssertJobExRatesBaseRate(3m, 2m, 2.5m);

				TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 4m, invoiceCurrencyType: InvoiceCurrencyType.Foreign);
				AssertJobExRatesBaseRate(3m, 4m, 2.5m);

				TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 5m, invoiceCurrencyType: InvoiceCurrencyType.Local);
				AssertJobExRatesBaseRate(3m, 4m, 5m);

				foreignConfig.Delete();
				Factory.Save();

				TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 6m, invoiceCurrencyType: InvoiceCurrencyType.Foreign);
				AssertJobExRatesBaseRate(3m, 6m, 5m);

				void AssertJobExRatesBaseRate(ZDecimal notApplicableJobExRateBaseRate, ZDecimal foreignJobExRateBaseRate, ZDecimal localJobExRateBaseRate)
				{
					AssertEquals("ExchangeRates Count", 3, TestJob.ExchangeRates.Count);
					AssertEquals(notApplicableJobExRateBaseRate, jobExRate1.JF_BaseRate);
					AssertEquals(foreignJobExRateBaseRate, jobExRate2.JF_BaseRate);
					AssertEquals(localJobExRateBaseRate, jobExRate3.JF_BaseRate);
				}

				AccExchangeRateConfiguration CreateAccExchangeRateConfiguration(string invoiceCurrencyType, int offSet)
				{
					var exRateConfig = Factory.NewWithValidTestData<AccExchangeRateConfiguration>();
					exRateConfig.JCE_Ledger = LedgerTypes.AccountsReceivable;
					exRateConfig.JCE_JobType = JobConfigurationSelectorLookups.JobTypeAdditionalCodes.All;
					exRateConfig.JCE_InvoiceCurrencyType = invoiceCurrencyType;
					exRateConfig.JCE_Offset = offSet;

					AssertEquals(Core.Constants.JobBillingExchangeRatePreference.Code.TodaysRate, exRateConfig.JCE_Preference);
					return exRateConfig;
				}

				void CreateRefExRate(string currency, ZDateTime startDate, ZDateTime expiryDate, ZDecimal exRate)
				{
					var newExRate = Factory.NewWithValidTestData<RefExchangeRate>();
					newExRate.RE_GC = GlbCompany.CurrentCompany.PK;
					newExRate.RE_RX_NKExCurrency = currency;
					newExRate.RE_ExRateType = Core.Constants.ExchangeRateTypes.Code.BuyRate;
					newExRate.RE_StartDate = startDate;
					newExRate.RE_ExpiryDate = expiryDate;
					newExRate.RE_SellRate = exRate;
				}
			}
		}

		[DisableZeroExchangeRateOverriding]
		public void TestUpdateBaseExchangeRate()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			TestJob.Parent = shipment;

			Factory.Save();

			var genericUSD = TestJob.AddCurrency(TestObjectCreator.USD, ExchangeRateValidLedgerEnum.None);
			AssertEquals("ExchangeRates Count", 1, TestJob.ExchangeRates.Count);
			Assert("Org Type", genericUSD.JF_OrgType.IsEmpty);
			Assert("Org Type", genericUSD.JF_OH_Org.IsEmpty);
			AssertEquals("Currency", TestObjectCreator.USD.RX_Code, genericUSD.JF_RX_NKRateCurrency);

			var charge1 = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Test1", TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS, TestObjectCreator.USD, 100m, TestObjectCreator.Debtor);
			charge1.JR_InvoiceType = InvoiceTypesList.Codes.FinalInvoice;
			charge1.JR_RX_NKSellInvoiceCurrency = TestObjectCreator.EUR.RX_Code;
			Assert(charge1.BillInInvoiceCurrency);

			AssertEquals("ExchangeRates Count", 4, TestJob.ExchangeRates.Count);
			AssertEquals("USD ExchangeRates Count", 3, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_RX_NKRateCurrency == TestObjectCreator.USD.RX_Code));
			AssertEquals("EUR ExchangeRates Count", 1, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_RX_NKRateCurrency == TestObjectCreator.EUR.RX_Code));
			Assert("Exchange rates were not set", TestJob.ExchangeRates.Cast<ExchangeRate>().All(x => x.JF_BaseRate.IsEmpty));
			Assert("Cost rate not set", charge1.JR_OSCostExRate.IsEmpty);
			Assert("Sell rate not set", charge1.JR_OSSellExRate.IsEmpty);
			Assert("Sell Invoice rate not set", charge1.JR_OSSellInvoiceExRate.IsEmpty);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AP, 0.76m, new Charge[] { charge1 });
			AssertEquals("Cost rate set", 0.76m, charge1.JR_OSCostExRate);
			Assert("Sell rate not set", charge1.JR_OSSellExRate.IsEmpty);
			Assert("Sell Invoice rate not set", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			Assert("Exchange rates were not set", TestJob.ExchangeRates.Cast<ExchangeRate>().All(x => x.JF_BaseRate.IsEmpty));

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AR, 0.78m, new Charge[] { charge1 });
			AssertEquals("Cost rate set", 0.76m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate was set", 0.78m, charge1.JR_OSSellExRate);
			Assert("Sell Invoice rate not set", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			Assert("Exchange rates were not set", TestJob.ExchangeRates.Cast<ExchangeRate>().All(x => x.JF_BaseRate.IsEmpty));

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 0.8m, new Charge[] { charge1 });
			AssertEquals("Cost rate set", 0.76m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate was set", 0.78m, charge1.JR_OSSellExRate);
			Assert("Sell Invoice rate was set but Job Exchange Rate takes priority", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			Assert("Exchange rates were not set", TestJob.ExchangeRates.Cast<ExchangeRate>().All(x => x.JF_BaseRate.IsEmpty));

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AR, 0.77m);
			AssertEquals("Cost rate set", 0.76m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate from Job Exchange Rate", 0.77m, charge1.JR_OSSellExRate);
			Assert("Sell Invoice rate was set but Job Exchange Rate takes priority", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			AssertEquals("ExchangeRates Count for updated rate", 2, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_BaseRate == 0.77m));
			var debtorUSD = TestJob.ExchangeRates.Cast<ExchangeRate>().First(x => x.JF_BaseRate == 0.77m && x.PK != genericUSD.PK);
			AssertEquals("Org Type", ExchangeRateOrgTypeEnum.Debtor.ToCode(), debtorUSD.JF_OrgType);
			AssertEquals("Currency", TestObjectCreator.USD.RX_Code, debtorUSD.JF_RX_NKRateCurrency);
			AssertEquals("Generic ExchangeRate was updated", 0.77m, genericUSD.JF_BaseRate);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AP, 0.79m);
			AssertEquals("Cost rate set", 0.79m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate from Job Exchange Rate", 0.77m, charge1.JR_OSSellExRate);
			Assert("Sell Invoice rate was set but Job Exchange Rate takes priority", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			AssertEquals("ExchangeRates Count for updated rate", 2, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_BaseRate == 0.79m));
			var creditorUSD = TestJob.ExchangeRates.Cast<ExchangeRate>().First(x => x.JF_BaseRate == 0.79m && x.PK != genericUSD.PK);
			AssertEquals("Org Type", ExchangeRateOrgTypeEnum.Creditor.ToCode(), creditorUSD.JF_OrgType);
			AssertEquals("Currency", TestObjectCreator.USD.RX_Code, creditorUSD.JF_RX_NKRateCurrency);
			AssertEquals("Generic ExchangeRate was updated", 0.79m, genericUSD.JF_BaseRate);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.UA, 0.75m);
			AssertEquals("Cost rate previously set", 0.79m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate from Job Exchange Rate", 0.77m, charge1.JR_OSSellExRate);
			Assert("Sell Invoice rate was set but Job Exchange Rate takes priority", charge1.JR_OSSellInvoiceExRate.IsEmpty);
			AssertEquals("ExchangeRates Count for updated rate", 1, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_BaseRate == 0.75m));
			AssertEquals("Generic ExchangeRate was updated", 0.75m, genericUSD.JF_BaseRate);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.EUR.RX_Code, ExchangeRateValidLedgerEnum.AR, 0.81m);
			AssertEquals("Cost rate previously set", 0.79m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate from Job Exchange Rate", 0.77m, charge1.JR_OSSellExRate);
			AssertEquals("Sell Invoice rate from Job Exchange Rate", 0.81m, charge1.JR_OSSellInvoiceExRate);
			AssertEquals("ExchangeRates Count for updated rate", 1, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_BaseRate == 0.81m));
			var debtorEUR = TestJob.ExchangeRates.Cast<ExchangeRate>().First(x => x.JF_BaseRate == 0.81m);
			AssertEquals("Org Type", ExchangeRateOrgTypeEnum.Debtor.ToCode(), debtorEUR.JF_OrgType);
			AssertEquals("Currency", TestObjectCreator.EUR.RX_Code, debtorEUR.JF_RX_NKRateCurrency);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.None, 1.1m);
			AssertEquals("Cost rate previously set", 0.79m, charge1.JR_OSCostExRate);
			AssertEquals("Sell rate from Job Exchange Rate", 0.77m, charge1.JR_OSSellExRate);
			AssertEquals("Sell Invoice rate from Job Exchange Rate", 0.81m, charge1.JR_OSSellInvoiceExRate);
			AssertEquals("ExchangeRates Count for updated rate", 1, TestJob.ExchangeRates.Cast<ExchangeRate>().Count(x => x.JF_BaseRate == 1.1m));
			AssertEquals("Generic ExchangeRate was updated", 1.1m, genericUSD.JF_BaseRate);
			Assert("Org Type", genericUSD.JF_OrgType.IsEmpty);
			Assert("Org Type", genericUSD.JF_OH_Org.IsEmpty);
			AssertEquals("Currency", TestObjectCreator.USD.RX_Code, genericUSD.JF_RX_NKRateCurrency);
		}

		[DisableZeroExchangeRateOverriding]
		public void TestUpdateBaseExchangeRateWithOrg()
		{
			var shipment = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			TestJob.Parent = shipment;
			Factory.Save();

			var genericUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, ExchangeRateValidLedgerEnum.None);
			var aalshiNoneUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, TestObjectCreator.AALSHI.PK, ExchangeRateValidLedgerEnum.None);
			var aalshiARUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, TestObjectCreator.AALSHI.PK, ExchangeRateValidLedgerEnum.AR);
			var aalshiAPUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, TestObjectCreator.AALSHI.PK, ExchangeRateValidLedgerEnum.AP);
			var abigasARUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, TestObjectCreator.ABIGAS.PK, ExchangeRateValidLedgerEnum.AR);
			var abigasAPUSD = TestJob.AddCurrency(TestObjectCreator.USD, 1, TestObjectCreator.ABIGAS.PK, ExchangeRateValidLedgerEnum.AP);
			AssertEquals("ExchangeRates Count", 6, TestJob.ExchangeRates.Count);

			var apAalshiArAbigasCharge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Test1", TestObjectCreator.USD, 100m, TestObjectCreator.AALSHI, TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS);
			apAalshiArAbigasCharge.JR_InvoiceType = InvoiceTypesList.Codes.FinalInvoice;
			apAalshiArAbigasCharge.JR_RX_NKSellInvoiceCurrency = TestObjectCreator.USD.RX_Code;

			var apAbigasArAalshiCharge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Test1", TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS, TestObjectCreator.USD, 100m, TestObjectCreator.AALSHI);
			apAbigasArAalshiCharge.JR_InvoiceType = InvoiceTypesList.Codes.FinalInvoice;
			apAbigasArAalshiCharge.JR_RX_NKSellInvoiceCurrency = TestObjectCreator.USD.RX_Code;
			AssertEquals("ExchangeRates Count", 6, TestJob.ExchangeRates.Count);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.None, 1.1m);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.1m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1m, abigasARUSD.JF_BaseRate);
			AssertEquals(1m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting generic rate should not change charges", apAalshiArAbigasCharge, 1, 1, 1);
			AssertChargeExRates("Setting generic rate should not change charges", apAbigasArAalshiCharge, 1, 1, 1);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.None, 1.2m, TestObjectCreator.AALSHI.PK);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.2m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1m, abigasARUSD.JF_BaseRate);
			AssertEquals(1m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting generic rate should not change charges", apAalshiArAbigasCharge, 1, 1, 1);
			AssertChargeExRates("Setting generic rate should not change charges", apAbigasArAalshiCharge, 1, 1, 1);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AP, 1.3m, TestObjectCreator.ABIGAS.PK);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.2m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1m, abigasARUSD.JF_BaseRate);
			AssertEquals(1.3m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting AP ABIGAS should only change cost on charge with ABIGAS creditor", apAalshiArAbigasCharge, 1, 1, 1);
			AssertChargeExRates("Setting AP ABIGAS should only change cost on charge with ABIGAS creditor", apAbigasArAalshiCharge, 1.3, 1, 1);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AP, 1.4m, TestObjectCreator.AALSHI.PK);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.4m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1.4m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1m, abigasARUSD.JF_BaseRate);
			AssertEquals(1.3m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting AP AALSHI should only change cost on charge with AALSHI creditor", apAalshiArAbigasCharge, 1.4, 1, 1);
			AssertChargeExRates("Setting AP AALSHI should only change cost on charge with AALSHI creditor", apAbigasArAalshiCharge, 1.3, 1, 1);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AR, 1.5m, TestObjectCreator.ABIGAS.PK);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.4m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1.4m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1.5m, abigasARUSD.JF_BaseRate);
			AssertEquals(1.3m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting AR ABIGAS should only change cost on charge with ABIGAS debtor", apAalshiArAbigasCharge, 1.4, 1.5, 1.5);
			AssertChargeExRates("Setting AR ABIGAS should only change cost on charge with ABIGAS debtor", apAbigasArAalshiCharge, 1.3, 1, 1);

			TestJob.UpdateBaseExchangeRate(TestObjectCreator.USD.RX_Code, ExchangeRateValidLedgerEnum.AR, 1.6m, TestObjectCreator.AALSHI.PK);
			AssertEquals(1.1m, genericUSD.JF_BaseRate);
			AssertEquals(1.6m, aalshiNoneUSD.JF_BaseRate);
			AssertEquals(1.6m, aalshiARUSD.JF_BaseRate);
			AssertEquals(1.4m, aalshiAPUSD.JF_BaseRate);
			AssertEquals(1.5m, abigasARUSD.JF_BaseRate);
			AssertEquals(1.3m, abigasAPUSD.JF_BaseRate);
			AssertChargeExRates("Setting AR AALSHI should only change cost on charge with AALSHI debtor", apAalshiArAbigasCharge, 1.4, 1.5, 1.5);
			AssertChargeExRates("Setting AR AALSHI should only change cost on charge with AALSHI debtor", apAbigasArAalshiCharge, 1.3, 1.6, 1.6);

			void AssertChargeExRates(ZString message, Charge charge, ZDecimal osCostExRate, ZDecimal osSellExRate, ZDecimal osSellInvoiceExRate)
			{
				AssertEquals(message, osCostExRate, charge.JR_OSCostExRate);
				AssertEquals(message, osSellExRate, charge.JR_OSSellExRate);
				AssertEquals(message, osSellInvoiceExRate, charge.JR_OSSellInvoiceExRate);
			}
		}

