		public void TestAddCurrencyExchangeRates()
		{
			ZDateTime day_1 = ZDateTime.Now;
			ZDateTime day_2 = day_1.AddDays(-1);
			ZDateTime day_3 = day_1.AddDays(-2);
			ZDateTime day_4 = day_1.AddDays(-3);
			ZDateTime day_5 = day_1.AddDays(-4);
			ZDateTime day_6 = day_1.AddDays(-5);
			ZDateTime day_7 = day_1.AddDays(-6);

			var vessel = RefVessel.LookupVesselByName("APL IVORY", Factory).First();

			var voyage = Factory.New<JobVoyage>();
			voyage.JV_AirSeaRoad = Constants.TransportModes.Sea;
			voyage.JV_VoyageFlight = "12";
			voyage.JV_RV_NKVessel = vessel.RV_FK;
			var origin = voyage.Origins.AddNew();
			origin.JA_RL_NKPortOfLoading = "AUMEL";
			origin.JA_A_DEP = day_2;
			origin.JA_A_ARV = day_6;
			voyage.Destinations.AddNew().JB_RL_NKPortOfDischarge = "AUSYD";
			voyage.Destinations.AddNew().JB_RL_NKPortOfDischarge = "USLAX";
			var sailing_MEL_SYD = voyage.Sailings.GetSailingFromLoadAndDischarge("AUMEL", "AUSYD");
			var sailing_MEL_LAX = voyage.Sailings.GetSailingFromLoadAndDischarge("AUMEL", "USLAX");

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_AgentType = Constants.AgentType.Agent;
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_TransportMode = Constants.TransportModes.Air;
			consol.Transports.ArrivalTransport.JW_ATA = day_4;
			consol.Transports.DepartureTransport.JW_ATD = day_2;

			var departureTransport = consol.Transports.DepartureTransport;
			var shipment = consol.Shipments.AddNew();

			var charge = Factory.NewWithValidTestData<ApportionSplitCharge>();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			charge.JR_OSCostAmt = 100m;
			charge.JR_OSCostExRate = 1m;
			charge.JR_JH = TestJob.PK;

			TestJob.Parent = shipment;

			#region Set Up Exchange Rates

			USD.ExchangeRates.DeleteAll();
			AddCurrencyRate(USD, day_1, Constants.ExchangeRateTypes.Code.BuyRate, 01.5m); // TDR 0
			AddCurrencyRate(USD, day_2, Constants.ExchangeRateTypes.Code.BuyRate, 02.5m);
