		void ResetUSDCurrencyOnJob()
		{
			TestJob.ExchangeRates.RemoveAll();
			TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AR);
		}

		void AddCurrencyRate(RefCurrency currency, ZDateTime startDate, ZString rateType, ZDecimal rateValue)
		{
			RefExchangeRate rate = currency.ExchangeRates.AddNew();
			rate.RE_StartDate = startDate;
			rate.RE_ExpiryDate = startDate;
			rate.RE_ExRateType = rateType;
			rate.RE_SellRate = rateValue;
		}

		public void TestAddCurrencyExchangeRatesUsesExistingRates()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = "AIR";
			consol.Transports.ArrivalTransport.JW_ATA = ZDateTime.Now.AddDays(-10);
			consol.Transports.DepartureTransport.JW_ATD = ZDateTime.Now.AddDays(-20);

			ForwardingShipment shipment = consol.Shipments.AddNew();
			TestJob.Parent = shipment;

			RefExchangeRate rate = USD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-22).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(-21);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 3.5m;

			Factory.Save();

			ExchangeRateReader.GetReaderInstance().ClearCache();

			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "IMP", "AIR", preference: "HAR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "EXP", "AIR", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "DOM", "AIR", preference: "CER");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "OTH", "AIR", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "IMP", "SEA", preference: "HAR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "EXP", "SEA", preference: "HDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "DOM", "SEA", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "OTH", "SEA", preference: "TDR");

			AccountingConfigurationRegistry.Instance.FallBackToPreviousExchangeRate.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AR);
			shipment.JS_TransportMode = "AIR";
			shipment.JS_RL_NKOrigin = consol.JK_RL_NKLoadPort = "NZAKL";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "USLAX";
			AssertExchangeRate("OTH, AIR -> TDR", TestJob.ExchangeRates, USD, 3.5m);

			consol.JK_RL_NKLoadPort = "USLAX";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "AUMEL";
			ResetUSDCurrencyOnJob();
			AssertExchangeRate("IMP, AIR -> HAR", TestJob.ExchangeRates, USD, 3.5m);

			shipment.JS_TransportMode = "SEA";
			shipment.JS_RL_NKOrigin = consol.JK_RL_NKLoadPort = "AUMEL";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "USLAX";
			ResetUSDCurrencyOnJob();
			AssertExchangeRate("EXP, SEA -> HDR", TestJob.ExchangeRates, USD, 3.5m);
		}

		public void TestUpdateExchangeRates()
		{
			ForwardingConsol consol = Factory.New<ForwardingConsol>();
			consol.JK_TransportMode = "AIR";
			consol.Transports.ArrivalTransport.JW_ATA = ZDateTime.Now.AddDays(-10);
			consol.Transports.DepartureTransport.JW_ATD = ZDateTime.Now.AddDays(-20);

			ForwardingShipment shipment = consol.Shipments.AddNew();
			TestJob.Parent = shipment;

			RefExchangeRate rate = USD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-21).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(-19);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 3.5m;

			rate = USD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-11).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(-9);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 4.5m;

			rate = USD.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-1).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(1);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 5.5m;

			rate = GBP.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-21).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(-19);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 13.5m;

			rate = GBP.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-11).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(-9);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 14.5m;

			rate = GBP.ExchangeRates.AddNew();
			rate.RE_StartDate = ZDateTime.Now.AddDays(-1).Date;
			rate.RE_ExpiryDate = ZDateTime.Now.AddDays(1);
			rate.RE_ExRateType = nameof(ExchangeRateType.Buy);
			rate.RE_SellRate = 15.5m;

			Factory.Save();

			ExchangeRateReader.GetReaderInstance().ClearCache();

			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "IMP", "AIR", preference: "HAR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "EXP", "AIR", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "DOM", "AIR", preference: "CER");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "OTH", "AIR", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "IMP", "SEA", preference: "HAR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "EXP", "SEA", preference: "HDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "DOM", "SEA", preference: "TDR");
			GlbCompany.CurrentCompany.AccExchangeRateConfigurations.SetExRate(JobInvoicingConsumerTypes.Shipment.Code, "OTH", "SEA", preference: "TDR");
			GlbCompany.CurrentCompany.Factory.Save();

			shipment.JS_TransportMode = "AIR";
			shipment.JS_RL_NKOrigin = consol.JK_RL_NKLoadPort = "NZAKL";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "USLAX";
			Factory.Save();
			TestJob.AddCurrency(USD, ExchangeRateValidLedgerEnum.AR);
			TestJob.AddCurrency(GBP, ExchangeRateValidLedgerEnum.AR);
			AssertEquals("OTH, AIR -> TDR", TestJob.ExchangeRates.FindByRefCurrency(USD).JF_SellRate, 5.5m);
			AssertEquals("OTH, AIR -> TDR", TestJob.ExchangeRates.FindByRefCurrency(GBP).JF_SellRate, 15.5m);

			consol.JK_RL_NKLoadPort = "USLAX";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "AUMEL";
			TestJob.UpdateExchangeRates(false);
			AssertEquals("IMP, AIR -> HAR", TestJob.ExchangeRates.FindByRefCurrency(USD).JF_SellRate, 4.5m);
			AssertEquals("IMP, AIR -> HAR", TestJob.ExchangeRates.FindByRefCurrency(GBP).JF_SellRate, 14.5m);

			shipment.JS_TransportMode = "SEA";
			shipment.JS_RL_NKOrigin = consol.JK_RL_NKLoadPort = "AUMEL";
			shipment.JS_RL_NKDestination = consol.JK_RL_NKDischargePort = "USLAX";
			TestJob.UpdateExchangeRates(false);
			AssertEquals("EXP, SEA -> HDR", TestJob.ExchangeRates.FindByRefCurrency(USD).JF_SellRate, 3.5m);
			AssertEquals("EXP, SEA -> HDR", TestJob.ExchangeRates.FindByRefCurrency(GBP).JF_SellRate, 13.5m);
		}

