		void AssertChargesAreNotDuplicatedWhileCopyingQuoteCharges(ZGuid localChargesPK)
		{
			var department = Factory.NewWithValidTestData<GlbDepartment>();
			department.GE_Code = "ABC";
			AddNewDepartmentCharge(department, TestObjectCreator.CC1);
			AddNewDepartmentCharge(department, TestObjectCreator.CC2);
			Factory.Save();

			var quote = Factory.NewWithValidTestData<Quote>();
			quote.TH_QuoteNumber = TestObjectCreator.GetRandomString(4);
			quote.TH_OneTimeQuote = true;

			var quoteJob = new Loader(quote).TryLoadOrCreateWithoutMutexForTestOnly();
			quoteJob.LocalChargesPK = localChargesPK;
			quoteJob.JH_GE = department.PK;
			Factory.Save();

			AssertEquals("Precondition: quoteJob department should be set to 'ABC' department", "ABC", quoteJob.Department.GE_Code);
			AssertEquals("Precondition: quoteJob should have 2 charge copied from the department charges", 2, quoteJob.Charges.Count);
			AssertContainsExactElementsInAnyOrder("Precondition: depatment charge codes should match with the quoteJob charge codes", quoteJob.Charges.Select(x => x.ChargeCode), department.DeptCharges.Select(x => x.ChargeCode));

			var shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_RL_NKOrigin = "USLAX";
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;
			shipment.JS_PackingMode = "LSE";
			shipment.JS_ShipmentType = "STD";

			TestJob.JH_ParentTableCode = ObjectFactory.Get<IApplicationSchemaResolver>().GetColumnNamePrefix(CommonShipment.Schema.TableName);
			TestJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
			TestJob.JH_ParentID = shipment.PK;

			if (!TestJob.LocalChargesPK.IsEmpty)
			{
				TestJob.LocalCharges.CompanyData.OB_IsDebtor = true;
			}

			Factory.Save();

			AssertNotEquals("Precondition: TestJob department is not same as 'ABC' department", "ABC", TestJob.Department.GE_Code);
			AssertEquals("Precondition: TestJob is not having any charges", 0, TestJob.Charges.Count);

			var departmentCollection = new JobInvoicingDefaultDepartmentsCollection { new JobInvoicingDefaultDepartments(true) { ConsolType = "ALL", Department = department.PK } };
			AccountingConfigurationRegistry.Instance.JobInvoicingDefaultDepartmentForwardingImportAirOther.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, departmentCollection);

			TestJob.JH_GE = ZGuid.Empty; // TestJob department is cleared so that assigning quote number will assign the "ABC" department to the TestJob
			TestJob.JH_TH_NKQuoteNumber = quote.TH_QuoteNumber;
			AssertEquals("Precondition: TestJob department should be set to 'ABC' department", "ABC", TestJob.Department.GE_Code);
			AssertEquals("Should have 2 charges. Department charges should not be included to avoid duplicate", 2, TestJob.Charges.Count);
		}

		public void TestDepartmentChargesAreSavedCorrectlyIfThereIsNoInitialBranch()
		{
			TestJob.LocalCharges.CompanyData.OB_IsDebtor = true;
			TestJob.LocalCharges.CompanyData.InvoiceRollupOrGroups.RemoveAndDeleteAll();
			OrgInvoiceRollupOrGroup group = TestJob.LocalCharges.CompanyData.InvoiceRollupOrGroups.AddNew();
			group.PG_JobType = OrgInvoiceRollupOrGroupLookups.JobType_List.All.Code;
			group.PG_ServiceDirection = OrgConstants.ServiceDirection.Code.All;
			group.PG_TransportMode = OrgConstants.ModesForGroupOrSubTotal.Codes.All;
			group.PG_InvoicePostingStyle = InvoicePostingOptionsList.Codes.FinalInvoiceOnly;
			Factory.Save();

			GlbDepartment newDepartment = Factory.NewWithValidTestData<GlbDepartment>();
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC1);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC2);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC3);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC5);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC6);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC7);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC8);
			AddNewDepartmentCharge(newDepartment, TestObjectCreator.CC9);

			TestJob.JH_GB = ZGuid.Empty; // Simulate when we cant default a branch
			TestJob.JH_GE = newDepartment.PK;
			TestJob.DeleteUnpostedLines();
			AssertEquals("Should be no charges", 0, TestJob.Charges.Count);
			AssertEquals("TestJob.Charges should have no errors", false, TestJob.Charges.HasErrors());

			int jobChargesListChangedHitCount = 0;
			var listChangedHandler = new ListChangedEventHandler(
				(sender, e) =>
				{ jobChargesListChangedHitCount++; }
			);
			((IBindingList)TestJob.Charges).ListChanged += listChangedHandler;

			TestJob.AddDepartmentCharges();

			AssertEquals("ListChanged on TestJob.Charges should be called once", 1, jobChargesListChangedHitCount);
			AssertEquals("Should be 8 charges", 8, TestJob.Charges.Count);

			foreach (Charge charge in TestJob.Charges)
			{
				charge.Debtors.Add(charge.SellAccount); // to avoid a full, expensive, load
				charge.Validation.ValidateJR_OH_SellAccount();
			}

			if (TestJob.Charges.HasErrors())
			{
				Fail("Job has errors " + TestJob.NotificationsIncludingChildren.GetErrors().ToUniqueMessageListString());
			}
			AssertEquals("TestJob.Charges should have no errors", false, TestJob.Charges.HasErrors());

			foreach (Charge currentCharge in TestJob.Charges)
			{
				AssertEquals("Charge should have correct JR_JH link", TestJob.PK, currentCharge.JR_JH);
				AssertNotNull("Charge should have correct JR_AC link", currentCharge.ChargeCode);
				AssertEquals("Charge should have an empty Branch", ZGuid.Empty, currentCharge.JR_GB);
				AssertNotNull("Charge should have correct JR_AC link", currentCharge.ChargeCode);
			}

			TestJob.JH_GB = GlbBranch.CurrentBranch.PK;

			foreach (Charge currentCharge in TestJob.Charges)
			{
				AssertEquals("Charge should have correct JR_JH link", TestJob.PK, currentCharge.JR_JH);
				AssertNotNull("Charge should have correct JR_AC link", currentCharge.ChargeCode);
				AssertEquals("Charge should have a Branch", TestJob.JH_GB, currentCharge.JR_GB);
				AssertNotNull("Charge should have correct JR_AC link", currentCharge.ChargeCode);
			}
		}

		void AddNewDepartmentCharge(GlbDepartment department, AccChargeCode chargeCode)
		{
			GlbDeptCharges newDeptCharge = Factory.New<GlbDeptCharges>();
			newDeptCharge.GD_AC = chargeCode.PK;
			newDeptCharge.GD_GC = GlbCompany.CurrentCompany.PK;
			newDeptCharge.GD_GE = department.PK;
			department.DeptCharges.Add(newDeptCharge);
		}

