		public void TestDefaultsForDomesticShipment()
		{
			SetUpDepartmentTests();

			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.Prepaid, ExportFreightBillTo.PK);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.Collect, ImportFreightBillTo.PK);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.CollectThirdParty, ZGuid.Empty);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.CollectCOD, ImportFreightBillTo.PK);

			Consignor.AllRelatedParties.RemoveRelatedParty(RelatedPartyTypeList.Codes.InvoiceFreightJobsTo, RelatedPartyDirectionList.Codes.Pickup);
			Consignee.AllRelatedParties.RemoveRelatedParty(RelatedPartyTypeList.Codes.InvoiceFreightJobsTo, RelatedPartyDirectionList.Codes.Delivery);

			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.Prepaid, Consignor.PK);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.Collect, Consignee.PK);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.CollectThirdParty, ZGuid.Empty);
			AssertDomesticShipmentBillToCorrect(Core.Constants.DomesticPaymentTerms.CollectCOD, Consignee.PK);
		}

		void AssertDomesticShipmentBillToCorrect(ZString domesticIncoTerm, ZGuid expectedBillToPK)
		{
			Shipment.JS_RL_NKDestination = "AUSYD";
			Shipment.JS_RL_NKOrigin = "AUBNE";
			Shipment.IsDomesticFreight = true;
			Shipment.JS_TransportMode = "AIR";
			Shipment.JS_INCO = domesticIncoTerm;

			TestJob.PlugInData = Shipment;
			TestJob.LocalChargesPK = ZGuid.Empty;
			TestJob.AgentCollectPK = ZGuid.Empty;

			AssertEquals("Precondition: BillTo", ZGuid.Empty, TestJob.LocalChargesPK);
			AssertEquals("Precondition: Agent", ZGuid.Empty, TestJob.AgentCollectPK);

			TestJob.SetDefaultsForJob();
			AssertEquals("BillTo", expectedBillToPK, TestJob.LocalChargesPK);
			AssertEquals("Agent", ZGuid.Empty, TestJob.AgentCollectPK);
		}

