		public void TestDefaultOverseasAgentAndLocalClientWhenTheyAreTheSame()
		{
			Consol = Factory.New<ForwardingConsol>();
			Consol.JK_AgentType = Core.Constants.AgentType.Direct;
			ForwardingShipment shipment = Consol.Shipments.AddNew();
			shipment.ConsignorDocumentaryAddress.OrganisationPK = TestObjectCreator.ABIGAS.PK;
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = TestObjectCreator.ABIGAS.PK;
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "NZAKL";

			using (Job testJob = Job.CreateWithMutex(Factory, shipment))
			{
				testJob.PlugInData = shipment;
				AssertNull(testJob.AgentCollect);
				AssertNotNull(testJob.LocalCharges);
				AssertEquals(testJob.LocalChargesPK, TestObjectCreator.ABIGAS.PK);

				testJob.SetDefaultsForJob();
				AssertNull(testJob.AgentCollect);
				AssertNotNull(testJob.LocalCharges);
				AssertEquals(testJob.LocalChargesPK, TestObjectCreator.ABIGAS.PK);

				testJob.AgentCollectPK = testJob.LocalChargesPK;
				testJob.LocalChargesPK = ZGuid.Empty;

				testJob.SetDefaultsForJob();
				AssertNotNull(testJob.AgentCollect);
				AssertEquals(testJob.AgentCollectPK, TestObjectCreator.ABIGAS.PK);
				AssertNull(testJob.LocalCharges);
			}
		}

