		public void TestJobHeaderFieldsAreDefaultedIfEmpty()
		{
			ForwardingShipment shipment = TestObjectCreator.CreateShipment("S00001234", "AUSYD", "USLAX");

			OrgHeader localClient = Factory.NewWithValidTestData<OrgHeader>();
			localClient.CompanyData.OB_IsDebtor = true;

			OrgHeader overseasAgent = Factory.NewWithValidTestData<OrgHeader>();
			overseasAgent.CompanyData.OB_IsDebtor = true;

			shipment.ConsignorDocumentaryAddress.OrganisationPK = localClient.PK;
			localClient.StaffAssignments.ExportAirRep = GlbStaff.CurrentUser.GS_Code;
			shipment.JS_OH_DeliveryAgent = overseasAgent.PK;

			AssertNotNull("Precondition: Consignor should not be null", shipment.Consignor);
			AssertNotNull("Precondition: Delivery Agent should not be null", shipment.DeliveryAgent);

			shipment.JS_TransportMode = "AIR";

			Job job = Factory.NewJobForTesting<Job>();

			AssertEquals("Local Client", ZGuid.Empty, job.LocalChargesPK);
			AssertEquals("Overseas Agent", ZGuid.Empty, job.AgentCollectPK);
			AssertEquals("Job Status", JobHeaderStatus.Working.Code, job.JH_Status);
			AssertEquals("Branch", ZGuid.Empty, job.JH_GB);
			AssertEquals("Department", ZGuid.Empty, job.JH_GE);
			AssertEquals("Sales Rep", ZString.Empty, job.JH_GS_NKRepSales);
			AssertEquals("Operator", GlbStaff.CurrentUser.GS_Code, job.JH_GS_NKRepOps);

			job.PlugInData = shipment;

			AssertNotNull("Local Charges should not be null", job.LocalCharges);
			AssertEquals("Local Client should not be empty", shipment.Consignor.OH_Code, job.LocalCharges.OH_Code);
			AssertNotNull("Overseas Agent should not be null", job.AgentCollect);
			AssertEquals("Overseas Agent should not be empty", shipment.DeliveryAgent.OH_Code, job.AgentCollect.OH_Code);
			AssertEquals("Job Status should not be empty", JobHeaderStatus.Working.Code, job.JH_Status);
			Assert("Branch should not be empty", !job.JH_GB.IsEmpty);
			Assert("Department should not be empty", !job.JH_GE.IsEmpty);
			Assert("Sales Rep should not be empty", !job.JH_GS_NKRepSales.IsEmpty);
			AssertEquals("Operator", GlbStaff.CurrentUser.GS_Code, job.JH_GS_NKRepOps);

			Factory.Save();

			job = Factory.NewJobForTesting<Job>();
			job.LocalChargesPK = ZGuid.Empty;
			job.AgentCollectPK = ZGuid.Empty;
			job.JH_Status = ZString.Empty;
			job.JH_GB = ZGuid.Empty;
			job.JH_GE = ZGuid.Empty;
			job.JH_GS_NKRepSales = ZString.Empty;
			job.JH_GS_NKRepOps = ZString.Empty;

			job.PlugInData = shipment;

			AssertNotNull("Local Charges should not be null", job.LocalCharges);
			AssertEquals("Local Client should not be empty", shipment.Consignor.OH_Code, job.LocalCharges.OH_Code);
			AssertNotNull("Overseas Agent should not be null", job.AgentCollect);
			AssertEquals("Overseas Agent should not be empty", shipment.DeliveryAgent.OH_Code, job.AgentCollect.OH_Code);
			AssertEquals("Job Status should not be empty", JobHeaderStatus.Working.Code, job.JH_Status);
			Assert("Branch should not be empty", !job.JH_GB.IsEmpty);
			Assert("Department should not be empty", !job.JH_GE.IsEmpty);
			Assert("Sales Rep should not be empty", !job.JH_GS_NKRepSales.IsEmpty);
			AssertEquals("Operator", GlbStaff.CurrentUser.GS_Code, job.JH_GS_NKRepOps);
		}

