		public void TestAdditionalReference_ForCommonShipment()
		{
			var shipment = Factory.New<CommonShipment>();
			Factory.Save();

			var jobForShipment = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();

			var cusNumber1 = shipment.Numbers.AddNew();
			cusNumber1.CE_EntryType = CustomsReferenceNumberType.CustomsAdditionalReferenceNumbersCodes.AMS;
			cusNumber1.CE_EntryNum = "XXXABILL1";
			cusNumber1.CE_RN_NKCountryCode = "AU";
			AssertEquals(1, jobForShipment.AdditionalReferences.Count);
			var reference = jobForShipment.AdditionalReferences[0];
			AssertEquals("AMS", reference.CE_EntryType);
			AssertEquals("XXXABILL1", reference.CE_EntryNum);
			AssertEquals("AU", reference.CE_RN_NKCountryCode);

			var cusNumber2 = shipment.Numbers.AddNew();
			cusNumber2.CE_EntryType = CustomsReferenceNumberType.CustomsAdditionalReferenceNumbersCodes.BKG;
			cusNumber2.CE_EntryNum = "CV00001";
			cusNumber2.CE_RN_NKCountryCode = "CN";

			AssertEquals(2, jobForShipment.AdditionalReferences.Count);
			reference = jobForShipment.AdditionalReferences[1];
			AssertEquals("BKG", reference.CE_EntryType);
			AssertEquals("CV00001", reference.CE_EntryNum);
			AssertEquals("CN", reference.CE_RN_NKCountryCode);

			var quoteBooking = QuotedBooking.New(QuoteBookingType.QuickBooking, Factory);
			var cusNumber3 = quoteBooking.Booking.Numbers.AddNew();
			cusNumber3.CE_EntryType = CustomsReferenceNumberType.CustomsAdditionalReferenceNumbersCodes.AMS;
			cusNumber3.CE_RN_NKCountryCode = "";
			cusNumber3.CE_EntryNum = "XXXABILL1";
			cusNumber3.CE_RN_NKCountryCode = "AU";

			var job = new Loader(quoteBooking).TryLoadOrCreateWithoutMutexForTestOnly();
			AssertEquals(1, job.AdditionalReferences.Count);
