		public void TestJH_TH_NKQuoteNumber()
		{
			var newFactory = new BusinessObjectFactory();

			var debtor1 = newFactory.New<OrgHeader>();
			debtor1.OH_Code = "TEST1";
			debtor1.OH_IsDebtor = true;

			var debtor2 = newFactory.New<OrgHeader>();
			debtor2.OH_Code = "TEST2";
			debtor2.OH_IsDebtor = true;

			var newQuote = Factory.New<Quote>();
			newQuote.TH_QuoteNumber = TestObjectCreator.GetRandomString(4);
			newQuote.TH_OneTimeQuote = true;
			newQuote.TH_OH = debtor2.PK;
			newQuote.CurrentOneOffQuote.TT_OH_Carrier = TestOrganisation.PK;
			newFactory.Save();

			var job = new Loader(newQuote).TryLoadOrCreateWithoutMutexForTestOnly();
			job.JH_OA_LocalChargesAddr = debtor1.MainAddress.PK;

			var charge = job.Charges.AddNew();

			charge.JR_OH_SellAccount = debtor1.PK;
			charge.JR_OH_CostAccount = TestOrganisation.PK;
			charge.SellAccount.CompanyData.SetARTaxApplicable(true);

			charge.JR_AC = Margin100Code.PK;
			charge.JR_OSSellAmt = 100m;
			charge.JR_AT_SellGSTRate = FREEGST.PK;
			charge.JR_OSCostAmt = 100m;
			charge.JR_AT_CostGSTRate = FREEGST.PK;

			newFactory.Save();

			newQuote.CurrentOneOffQuote.TT_QuoteApprovedByManager = true;

			TestJob.LocalChargesPK = ZGuid.Empty;
			TestJob.JH_TH_NKQuoteNumber = newQuote.TH_QuoteNumber;

			AssertEquals(debtor1.PK, TestJob.LocalChargesPK);
			AssertEquals(20, TestJob.JH_TH_NKQuoteNumberInfo.MaxLength);
			AssertEquals(1, TestJob.Charges.Count);

			var testJobCharge = TestJob.Charges[0];
			AssertEquals("Correct Sell GST rate code. Should be re-defaulted, not copied from quote", GST.PK, testJobCharge.JR_AT_SellGSTRate);
			AssertEquals("The Sell GSTAmt Should be 0 on charge.", 0m, charge.JR_OSSellGSTAmt_Calc);
			AssertEquals("The Sell GSTAmt Should be reset to 10 on TestJob charge.", 10m, testJobCharge.JR_OSSellGSTAmt_Calc);
			AssertEquals("Correct Cost GST rate code. Should be re-defaulted, not copied from quote", GST.PK, testJobCharge.JR_AT_CostGSTRate);
			AssertEquals("The Cost GSTAmt Should be 0 on charge.", 0m, charge.JR_OSCostGSTAmt_Calc);
			AssertEquals("The Cost GSTAmt Should be reset to 10 on TestJob charge.", 10m, testJobCharge.JR_OSCostGSTAmt_Calc);
		}

