		public void TestJH_OH_AgentCollectWithWarning_WithInvoicingPluginContext()
		{
			var expectedMessageForJH_OA_AgentCollectAddr = "You must save this form to have this organization recorded as the Overseas Agent on this job.  Currently this Overseas Agent is NOT saved against this job.";
			var expectedMessageForJH_GS_NKRepSales = "You must save this form to have this staff member recorded as the Sales Rep on this job. Currently this Sales Rep is NOT saved against this job.";

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code);
			job.AgentCollectPK = ZGuid.Empty;
			job.JH_GS_NKRepSales = ZString.Empty;
			Factory.SetContext(BusinessContext.InvoicingPlugInGUI);
			Factory.Save();

			AssertNoWarning(job.JH_OA_AgentCollectAddrInfo, expectedMessageForJH_OA_AgentCollectAddr);
			AssertNoWarning(job.JH_GS_NKRepSalesInfo, expectedMessageForJH_GS_NKRepSales);

			job.AgentCollectPK = TestOrganisation.PK;
			AssertHasWarning(job.JH_OA_AgentCollectAddrInfo, expectedMessageForJH_OA_AgentCollectAddr);

			job.JH_GS_NKRepSales = GlbStaff.CurrentUser.GS_Code;
			AssertHasWarning(job.JH_GS_NKRepSalesInfo, expectedMessageForJH_GS_NKRepSales);

			Factory.Save();
			AssertNoWarning(job.JH_OA_AgentCollectAddrInfo, expectedMessageForJH_OA_AgentCollectAddr);
			AssertNoWarning(job.JH_GS_NKRepSalesInfo, expectedMessageForJH_GS_NKRepSales);
		}

		public void TestJH_OH_AgentCollectWithWarning_WithoutInvoicingPluginContext()
		{
			var expectedMessageForJH_OA_AgentCollectAddr = "You must save this form to have this organization recorded as the Overseas Agent on this job.  Currently this Overseas Agent is NOT saved against this job.";
			var expectedMessageForJH_GS_NKRepSales = "You must save this form to have this staff member recorded as the Sales Rep on this job. Currently this Sales Rep is NOT saved against this job.";

			var job = TestObjectCreator.CreateAndSaveTestShipmentJob(JobHeaderStatus.Working.Code);
			job.AgentCollectPK = ZGuid.Empty;
			job.JH_GS_NKRepSales = ZString.Empty;
			Factory.Save();

			AssertNoWarning(job.JH_OA_AgentCollectAddrInfo, expectedMessageForJH_OA_AgentCollectAddr);
			AssertNoWarning(job.JH_GS_NKRepSalesInfo, expectedMessageForJH_GS_NKRepSales);

			job.AgentCollectPK = TestOrganisation.PK;
			AssertHasWarning(job.JH_OA_AgentCollectAddrInfo, expectedMessageForJH_OA_AgentCollectAddr);

			job.JH_GS_NKRepSales = GlbStaff.CurrentUser.GS_Code;
