		public void TestContainsUnpostedApportionmentForSpecificChargeCode()
		{
			Assert("Should not contain any unposted apportionments yet for either charge code", TestJob.UnpostedApportionmentForSpecificChargeCode(Margin100Code.PK) == null);
			Assert("Should not contain any unposted apportionments yet for either charge code", TestJob.UnpostedApportionmentForSpecificChargeCode(DisbursementChargeCode.PK) == null);

			AccTransactionLines postedApportionChargeAPLine = Factory.New<AccTransactionLines>();
			postedApportionChargeAPLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Cost;

			Charge postedApportionCharge = TestJob.Charges.AddNew();
			postedApportionCharge.JR_AL_APLine = postedApportionChargeAPLine.PK;
			postedApportionCharge.JR_AC = Margin100Code.PK;

			AccTransactionLines postedApportionChargeARLine = Factory.New<AccTransactionLines>();
			postedApportionChargeARLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;

			Charge unpostedApportionment = TestJob.Charges.AddNew(); // As yet this charge is not an apportionment,
																	 //becomes one when the cost split group is set, i.e. Line 3078

			unpostedApportionment.JR_AC = Margin100Code.PK;

			postedApportionCharge.JR_AL_ARLine = postedApportionChargeARLine.PK;
			postedApportionCharge.JR_E6 = ZGuid.NewZGuid();

			Charge unpostedStandardCharge = TestJob.Charges.AddNew();
			unpostedStandardCharge.JR_AC = DisbursementChargeCode.PK;

			Assert("margin charge code used for charge that is not yet an apportionment", TestJob.UnpostedApportionmentForSpecificChargeCode(Margin100Code.PK) == null);
			Assert("DSB charge not used for unposted apportionment charges for DSB", TestJob.UnpostedApportionmentForSpecificChargeCode(DisbursementChargeCode.PK) == null);

			unpostedApportionment.JR_E6 = ZGuid.NewZGuid(); // Make the charge an apportionment
			Assert("margin charge code used for charge that is now an apportionment", TestJob.UnpostedApportionmentForSpecificChargeCode(Margin100Code.PK) != null);
			Assert("DSB charge not used for unposted apportionment charges for DSB", TestJob.UnpostedApportionmentForSpecificChargeCode(DisbursementChargeCode.PK) == null);
		}

		public void TestClearARLinks()
		{
			InvoicingBaseCollection collection = new InvoicingBaseCollection(Factory);
			ARInvoice inv1 = Factory.New<ARInvoice>();
			DependentTransactionLine inv1Line = inv1.Lines.AddNew();
			inv1Line.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			collection.Add(inv1);

			ARInvoice inv2 = Factory.New<ARInvoice>();
			DependentTransactionLine inv2Line = inv2.Lines.AddNew();
			inv2Line.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			collection.Add(inv2);

			ARCreditNote crd = Factory.New<ARCreditNote>();
			DependentTransactionLine crdLine = crd.Lines.AddNew();
			crdLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			collection.Add(crd);

			Charge charge1 = TestJob.Charges.AddNew();
			Charge charge2 = TestJob.Charges.AddNew();
			Charge charge3 = TestJob.Charges.AddNew();
			Charge charge4 = TestJob.Charges.AddNew();

			charge1.JR_OSSellAmt = 100;
			charge1.JR_AL_ARLine = inv1Line.PK;

			charge2.JR_OSSellAmt = 200;
			charge2.JR_AL_ARLine = inv2Line.PK;

			charge3.JR_OSSellAmt = 300;
			charge3.JR_AL_ARLine = crdLine.PK;

			charge4.JR_OSSellAmt = 400;

			AssertEquals(100m, charge1.JR_OSSellAmt);
			AssertEquals(100m, charge1.JR_LocalSellAmt);
			AssertEquals(inv1Line.PK, charge1.JR_AL_ARLine);

			AssertEquals(200m, charge2.JR_OSSellAmt);
			AssertEquals(200m, charge2.JR_LocalSellAmt);
			AssertEquals(inv2Line.PK, charge2.JR_AL_ARLine);

			AssertEquals(300m, charge3.JR_OSSellAmt);
			AssertEquals(300m, charge3.JR_LocalSellAmt);
			AssertEquals(crdLine.PK, charge3.JR_AL_ARLine);

			AssertEquals(400m, charge4.JR_OSSellAmt);
			AssertEquals(400m, charge4.JR_LocalSellAmt);
			AssertEquals(ZGuid.Empty, charge4.JR_AL_ARLine);

			TestJob.ClearARLinks(collection.ToArray<InvoicingBase>());

			AssertEquals(0m, charge1.JR_OSSellAmt);
			AssertEquals(0m, charge1.JR_LocalSellAmt);
			AssertEquals(ZGuid.Empty, charge1.JR_AL_ARLine);

			AssertEquals(0m, charge2.JR_OSSellAmt);
			AssertEquals(0m, charge2.JR_LocalSellAmt);
			AssertEquals(ZGuid.Empty, charge2.JR_AL_ARLine);

			AssertEquals(0m, charge3.JR_OSSellAmt);
			AssertEquals(0m, charge3.JR_LocalSellAmt);
			AssertEquals(ZGuid.Empty, charge3.JR_AL_ARLine);

			AssertEquals(400m, charge4.JR_OSSellAmt);
			AssertEquals(400m, charge4.JR_LocalSellAmt);
			AssertEquals(ZGuid.Empty, charge4.JR_AL_ARLine);
		}

