			AssertEquals(0m, charge1.JR_LocalSellAmt);
			AssertEquals(0m, charge1.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge1.JR_AgentDeclaredSellAmtLocal);

			AssertEquals(0m, charge2.JR_OSCostAmt);
			AssertEquals(0m, charge2.JR_LocalCostAmt);
			AssertEquals(0m, charge2.JR_AgentDeclaredCostAmt);
			AssertEquals(0m, charge2.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(220m, charge2.JR_OSSellAmt);
			AssertEquals(220m, charge2.JR_LocalSellAmt);
			AssertEquals(220m, charge2.JR_AgentDeclaredSellAmt);
			AssertEquals(220m, charge2.JR_AgentDeclaredSellAmtLocal);

			AssertEquals(0m, charge3.JR_OSCostAmt);
			AssertEquals(0m, charge3.JR_LocalCostAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredCostAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(0m, charge3.JR_OSSellAmt);
			AssertEquals(0m, charge3.JR_LocalSellAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredSellAmtLocal);

			AssertEquals(400m, charge4.JR_OSCostAmt);
			AssertEquals(400m, charge4.JR_LocalCostAmt);
			AssertEquals(400m, charge4.JR_AgentDeclaredCostAmt);
			AssertEquals(400m, charge4.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(0m, charge4.JR_OSSellAmt);
			AssertEquals(0m, charge4.JR_LocalSellAmt);
			AssertEquals(0m, charge4.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge4.JR_AgentDeclaredSellAmtLocal);

			AssertEquals(500m, charge5.JR_OSCostAmt);
			AssertEquals(500m, charge5.JR_LocalCostAmt);
			AssertEquals(500m, charge5.JR_AgentDeclaredCostAmt);
			AssertEquals(500m, charge5.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(0m, charge5.JR_OSSellAmt);
			AssertEquals(0m, charge5.JR_LocalSellAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredSellAmtLocal);

			AssertEquals(false, charge3.JR_CostRatingOverride);
			AssertEquals(ZString.Empty, charge3.JR_CostRatingOverrideComment);
			AssertEquals(false, charge3.JR_SellRatingOverride);
			AssertEquals(ZString.Empty, charge3.JR_SellRatingOverrideComment);
			AssertEquals(false, charge3.JR_SellRated);
			AssertEquals(false, charge3.JR_CostRated);
		}

		public void TestClearUnpostedChargesAmountsWhenLinkedToCashAdvance()
		{
			TestObjectCreator objectCreator = new TestObjectCreator(Factory);
			var shipment = objectCreator.CreateShipment("S000091");
			var job = objectCreator.CreateJob(shipment, objectCreator.LocalClient, 1.0M, objectCreator.Agent, 1.0M);

			Factory.Save();

			var charge1 = objectCreator.CreateCharge(job, objectCreator.CC1, "line 001", objectCreator.AUD, 100M, objectCreator.Creditor1, objectCreator.AUD, 120M, objectCreator.Debtor);
			charge1.JR_AgentDeclaredCostAmt = 100;
			charge1.JR_OSSellAmt = charge1.JR_AgentDeclaredSellAmt = 120;

			var charge2 = objectCreator.CreateCharge(job, objectCreator.CC2, "line 002", objectCreator.AUD, 200M, objectCreator.Creditor1, objectCreator.AUD, 220M, objectCreator.Debtor);
			charge2.JR_AgentDeclaredCostAmt = 200;
			charge2.JR_OSSellAmt = charge2.JR_AgentDeclaredSellAmt = 220;

			var charge3 = objectCreator.CreateCharge(job, objectCreator.CC3, "line 003", objectCreator.AUD, 300M, objectCreator.Creditor1, objectCreator.AUD, 320M, objectCreator.Debtor);
			charge3.JR_AgentDeclaredCostAmt = 300;
			charge3.JR_OSSellAmt = charge3.JR_AgentDeclaredSellAmt = 320;

			var charge4 = objectCreator.CreateCharge(job, objectCreator.CC4, "line 004", objectCreator.AUD, 400M, objectCreator.Creditor1, objectCreator.AUD, 420M, objectCreator.Debtor);

			var charge5 = objectCreator.CreateCharge(job, objectCreator.CC5, "line 005", objectCreator.AUD, 500M, objectCreator.Creditor1, objectCreator.AUD, 520M, objectCreator.Debtor);
			Factory.Save();

			var arCah = objectCreator.CreateCashAdvanceRequestHeader(job, objectCreator.Debtor, LedgerTypes.AccountsReceivable, 340M, 340M, TestObjectCreator.AUD.RX_Code, "ARCAH01");
			var arCal1 = objectCreator.CreateCashAdvanceRequestLine(arCah, 120M, 120M, "REQ", charge1);
			var arCal2 = objectCreator.CreateCashAdvanceRequestLine(arCah, 220M, 220M, "REQ", charge2);

			var apCah = objectCreator.CreateCashAdvanceRequestHeader(job, objectCreator.Debtor, LedgerTypes.AccountsPayable, 700M, 700M, TestObjectCreator.AUD.RX_Code, "APCAH01");
			var apCal1 = objectCreator.CreateCashAdvanceRequestLine(apCah, 300M, 300M, "REQ", charge3);
			var apCal2 = objectCreator.CreateCashAdvanceRequestLine(apCah, 400M, 400M, "REQ", charge4);
			Factory.Save();

			job.ClearUnpostedChargesAmounts();

			AssertEquals(0m, charge1.JR_OSCostAmt);
			AssertEquals(0m, charge1.JR_LocalCostAmt);
			AssertEquals(0m, charge1.JR_AgentDeclaredCostAmt);
			AssertEquals(0m, charge1.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(false, charge1.JR_IsAPCashAdvance);
			AssertEquals(120m, charge1.JR_OSSellAmt);
			AssertEquals(120m, charge1.JR_LocalSellAmt);
			AssertEquals(120m, charge1.JR_AgentDeclaredSellAmt);
			AssertEquals(120m, charge1.JR_AgentDeclaredSellAmtLocal);
			AssertEquals(true, charge1.JR_IsARCashAdvance);

			Assert(charge2.IsDisbursementCharge);
			AssertEquals(0m, charge2.JR_OSCostAmt);
			AssertEquals(0m, charge2.JR_LocalCostAmt);
			AssertEquals(0m, charge2.JR_AgentDeclaredCostAmt);
			AssertEquals(0m, charge2.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(false, charge2.JR_IsAPCashAdvance);
			AssertEquals(220m, charge2.JR_OSSellAmt);
			AssertEquals(220m, charge2.JR_LocalSellAmt);
			AssertEquals(220m, charge2.JR_AgentDeclaredSellAmt);
			AssertEquals(220m, charge2.JR_AgentDeclaredSellAmtLocal);
			AssertEquals(true, charge2.JR_IsARCashAdvance);

			AssertEquals(300m, charge3.JR_OSCostAmt);
			AssertEquals(300m, charge3.JR_LocalCostAmt);
			AssertEquals(300m, charge3.JR_AgentDeclaredCostAmt);
			AssertEquals(300m, charge3.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(true, charge3.JR_IsAPCashAdvance);
			AssertEquals(0m, charge3.JR_OSSellAmt);
			AssertEquals(0m, charge3.JR_LocalSellAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge3.JR_AgentDeclaredSellAmtLocal);
			AssertEquals(false, charge3.JR_IsARCashAdvance);

			AssertEquals(400m, charge4.JR_OSCostAmt);
			AssertEquals(400m, charge4.JR_LocalCostAmt);
			AssertEquals(400m, charge4.JR_AgentDeclaredCostAmt);
			AssertEquals(400m, charge4.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(true, charge4.JR_IsAPCashAdvance);
			AssertEquals(0m, charge4.JR_OSSellAmt);
			AssertEquals(0m, charge4.JR_LocalSellAmt);
			AssertEquals(0m, charge4.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge4.JR_AgentDeclaredSellAmtLocal);
			AssertEquals(false, charge4.JR_IsARCashAdvance);

			AssertEquals(0m, charge5.JR_OSCostAmt);
			AssertEquals(0m, charge5.JR_LocalCostAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredCostAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredCostAmtLocal);
			AssertEquals(false, charge5.JR_IsAPCashAdvance);
			AssertEquals(0m, charge5.JR_OSSellAmt);
			AssertEquals(0m, charge5.JR_LocalSellAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredSellAmt);
			AssertEquals(0m, charge5.JR_AgentDeclaredSellAmtLocal);
			AssertEquals(false, charge5.JR_IsARCashAdvance);
		}

		public void TestCreateWIPsForPostedCost()
		{
			TestObjectCreator.AALSHI.CompanyData.OB_RX_NKARDDefltCurrency = ZString.Empty;
			TestObjectCreator.AALSHI.CompanyData.OB_RX_NKAPDefltCurrency = ZString.Empty;
			var job = TestObjectCreator.CreateJob(TestObjectCreator.AALSHI, 0, null, 0);

			APInvoice invoice = Factory.NewWithValidTestData<APInvoice>();
			APInvoiceLine line1 = (APInvoiceLine)invoice.Lines.AddNew();
			line1.AL_AG = TestObjectCreator.GLHeader1.PK;
			line1.FillWithValidTestData();
			line1.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Cost;

			APInvoiceLine line2 = (APInvoiceLine)invoice.Lines.AddNew();
			line2.AL_AG = TestObjectCreator.GLHeader1.PK;
			line2.FillWithValidTestData();
			line2.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Cost;

			ExchangeRate rate = job.ExchangeRates.AddNew();
			rate.JF_RX_NKRateCurrency = USD.RX_Code;
			rate.JF_BaseRate = 0.6m;

			rate = job.ExchangeRates.AddNew();
			rate.JF_RX_NKRateCurrency = GBP.RX_Code;
			rate.JF_BaseRate = 1.5m;

			AccChargeCode mrg100 = Factory.New<AccChargeCode>();
			mrg100.AC_ChargeType = Core.Constants.ChargeType.Margin;
			mrg100.AC_MarginPercentage = 100;
			mrg100.AC_Code = "Mrg100";
			mrg100.FillWithValidTestData();

			AccChargeCode mrg80 = Factory.New<AccChargeCode>();
			mrg80.AC_ChargeType = Core.Constants.ChargeType.Margin;
			mrg80.AC_MarginPercentage = 80;
			mrg80.AC_Code = "Mrg80";
			mrg80.FillWithValidTestData();

			Charge charge1 = job.Charges.AddNew();
			charge1.JR_AC = mrg100.PK;
			charge1.JR_LocalCostAmt = 100;
