			Charge charge2 = job.Charges.AddNew();
			charge2.JR_AC = mrg80.PK;
			charge2.JR_RX_NKCostCurrency = USD.RX_Code;
			charge2.JR_LocalCostAmt = 200;
			charge2.JR_LocalSellAmt = 600;
			charge2.JR_AL_APLine = line2.PK;
			line2.AL_RX_NKTransactionCurrency = USD.RX_Code;
			line2.AL_ExchangeRate = 0.6m;
			line2.AL_OSAmount = -charge2.JR_OSCostAmt;
			line2.AL_LineAmount = -charge2.JR_LocalCostAmt;
			charge2.JR_LocalSellAmt = 0;

			Charge charge3 = job.Charges.AddNew();
			charge3.JR_AC = mrg100.PK;
			charge3.JR_RX_NKCostCurrency = USD.RX_Code;
			charge3.JR_LocalCostAmt = 300;
			charge3.JR_LocalSellAmt = 300;
			charge3.JR_LocalSellAmt = 0;

			var consolCost = Factory.NewWithValidTestData<JobConsolCost>();
			Charge charge4 = job.Charges.AddNew();
			charge4.JR_AC = mrg80.PK;
			charge4.JR_RX_NKCostCurrency = GBP.RX_Code;
			charge4.JR_LocalCostAmt = 20;
