			AssertEquals(0m, charge3.JR_LocalSellAmt);
			AssertEquals(USD.RX_Code, charge3.JR_RX_NKSellCurrency);
			AssertNull(charge3.WIP);

			AssertEquals(37.5m, charge4.JR_OSSellAmt);
			AssertEquals(25m, charge4.JR_LocalSellAmt);
			AssertEquals(GBP.RX_Code, charge4.JR_RX_NKSellCurrency);
			AssertNotNull(charge4.WIP);

			AssertEquals(3750m, charge5.JR_OSSellAmt);
			AssertEquals(2500m, charge5.JR_LocalSellAmt);
			AssertEquals(GBP.RX_Code, charge5.JR_RX_NKSellCurrency);
			AssertNotNull(charge5.WIP);
		}

