		public void TestOneOffQuoteChargesCopyShouldTriggerValidationWhenWipMustHaveDebtorIsSet()
		{
			OrgHeader debtor = Factory.New<OrgHeader>();
			debtor.OH_Code = "TEST1";
			debtor.OH_IsDebtor = false;

			Quote testQuote = Factory.New<Quote>();
			testQuote.TH_OneTimeQuote = true;
			testQuote.TH_QuoteNumber = "123456";
			testQuote.TH_OH = debtor.PK;

			var job = (Job)new JobHeader.Loader(testQuote).TryLoadOrCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			JobCharge charge = job.Charges.AddNew();
			charge.JR_AC = TestObjectCreator.CC1.PK;
			charge.JR_RX_NKSellCurrency = "AUD";
			charge.JR_OSSellAmt = 100m;

			Factory.Save();

			AccountingConfigurationRegistry.Instance.WIPMustHaveDebtorCode.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var shipment = TestObjectCreator.CreateShipment("S001001");
			var shipmentJob = TestObjectCreator.CreateJob(shipment, false);
			shipmentJob.JH_GE = TestObjectCreator.NonCurrentDepartment.PK;

			AssertEquals(0, shipmentJob.Charges.Count);
			AssertEquals(0, shipmentJob.ExchangeRates.Count);

			using (shipmentJob.GetValidationSuspender())
			{
				shipmentJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;
			}

			AssertEquals(1, shipmentJob.Charges.Count);
			AssertEquals(shipmentJob.PK, shipmentJob.Charges[0].JR_JH);
			AssertEquals(TestObjectCreator.CC1.PK, shipmentJob.Charges[0].JR_AC);

			shipmentJob.RunPreSaveValidation();

			string expectedErrorMessage = @"You must enter a debtor. Your system has been configured so that the 'debtor' is mandatory when entering an unposted sell of non zero value.

The registry setting that governs this rule is Accounting > Job Costing > WIP Must Have Debtor Code";
			Assert(shipmentJob.HasErrors());
			AssertHasErrors(expectedErrorMessage, shipmentJob.Charges[0].JR_OH_SellAccountInfo);
		}

		public void TestOneOffQuoteBranchDepartmentCopied()
		{
			var testQuote = Factory.New<Quote>();
			testQuote.TH_OneTimeQuote = true;
			testQuote.TH_QuoteNumber = "123456";
			Factory.Save();

			AssertEquals("Pre-condition", true, testQuote.CurrentOneOffQuote.TT_QuoteApprovedByManager);

			var quoteJob = (Job)new JobHeader.Loader(testQuote).TryLoadOrCreateWithoutMutexForTestOnly();
			quoteJob.JH_GE = TestObjectCreator.NonCurrentDepartment.PK.ToGuid();
			quoteJob.JH_GB = TestObjectCreator.NonCurrentBranch.PK.ToGuid();

			var shipment = TestObjectCreator.CreateShipment("S2333");
