		public void TestShipment_WhenLinkOneOffQuoteAndApplyTheCharges_ThenCompanyTariffOverrideLevelIsCopiedFromOOQ()
		{
			Factory.New<GlobalTariff>();
			Factory.New<GlobalTariff>();
			Factory.Save();
			var testQuote = Factory.New<Quote>();
			testQuote.TH_OneTimeQuote = true;
			testQuote.TH_QuoteNumber = "123456";
			testQuote.CurrentOneOffQuote.TT_CompanyTariffLevelOverride = 2;
			var job = (Job)new JobHeader.Loader(testQuote).TryLoadOrCreate();
			job.JH_OA_LocalChargesAddr = Creditor1.MainAddress.PK;
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			JobCharge charge1 = job.Charges.AddNew();
			charge1.JR_AC = Env.Registry.FreightChargeCode;
			charge1.JR_RX_NKSellCurrency = "USD";
			charge1.JR_OSSellAmt = 97m;
			Factory.Save();
			AssertEquals(1, job.Charges.Count);
			ShouldCancelSpotQuoteCharges = false;
			var shipment = TestObjectCreator.CreateShipment("S2333");
			AssertEquals("Preconditions: The default value of CompanyTariffLevelOverride in Shipment is 0", (ZByte)0, shipment.JS_CompanyTariffLevelOverride);
			var shipmentJob = TestObjectCreator.CreateJob(shipment, false, true);
			shipmentJob.SpotQuoteChargesExist += new CancelEventHandler(TestJob_SpotQuoteChargesExist);
			shipmentJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;
			AssertEquals("Given OneOffQuote's CompanyTariffLevelOverride is 2, When we link it to shipment and apply the charges, Then the shipment's CompanyTariffLevelOverride will be copied from OOQ", (ZByte)2, shipment.JS_CompanyTariffLevelOverride);
		}

