		public void TestOneOffQuoteChargesCopied()
		{
			// System Exchange Rate: BUY - USD - 0.97
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, 0.97m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			Quote testQuote = Factory.New<Quote>();
			testQuote.TH_OneTimeQuote = true;
			testQuote.TH_QuoteNumber = "123456";

			var job = (Job)new JobHeader.Loader(testQuote).TryLoadOrCreateWithoutMutexForTestOnly();
			job.JH_OA_LocalChargesAddr = Creditor1.MainAddress.PK;
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			JobCharge charge1 = job.Charges.AddNew();
			charge1.JR_AC = Env.Registry.FreightChargeCode;
			charge1.JR_RX_NKSellCurrency = "USD";
			charge1.JR_OSSellAmt = 97m;

			void AssertBillingExchangeRates(ExchangeRate[] exchangeRates)
			{
				AssertEquals("There should be exchange rates for CRD and DEB types", 2, exchangeRates.Length);
				var exRateDEB = exchangeRates.Single(x => x.JF_OrgType == "DEB");
				var exRateCRD = exchangeRates.Single(x => x.JF_OrgType == "CRD");
				AssertEquals("USD", exRateDEB.JF_RX_NKRateCurrency);
				AssertEquals(0.97m, exRateDEB.JF_SellRate);
				AssertEquals(0.97m, exRateDEB.JF_BaseRate);
				AssertEquals(Creditor1.PK, exRateDEB.JF_OH_Org);
				AssertEquals("USD", exRateCRD.JF_RX_NKRateCurrency);
				AssertEquals(0.97m, exRateCRD.JF_SellRate);
				AssertEquals(0.97m, exRateCRD.JF_BaseRate);
				AssertEquals(ZGuid.Empty, exRateCRD.JF_OH_Org);
			}

			// Billing Exchange Rates are automatically created when charge is entered.
			AssertBillingExchangeRates(job.ExchangeRates.ToArray<ExchangeRate>());
			Factory.Save();

			AssertEquals(0, TestJob.Charges.Count);
			AssertEquals(0, TestJob.ExchangeRates.Count);

			TestJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;
			AssertEquals(1, TestJob.Charges.Count);
			AssertEquals(TestJob.PK, TestJob.Charges[0].JR_JH);
			AssertEquals(Env.Registry.FreightChargeCode, TestJob.Charges[0].JR_AC);
			AssertEquals(97m, TestJob.Charges[0].JR_OSSellAmt);
			AssertEquals(100m, TestJob.Charges[0].JR_LocalSellAmt);
			// Billing Exchange Rates are automatically created when charge is created by copying.
			AssertBillingExchangeRates(TestJob.ExchangeRates.ToArray<ExchangeRate>());
			Factory.Save();

			TestJob.Charges.RemoveAndDeleteAll();
			TestJob.ExchangeRates.RemoveAndDeleteAll();
			TestJob.SpotQuoteChargesExist += new CancelEventHandler(TestJob_SpotQuoteChargesExist);

			TestJob.JH_TH_NKQuoteNumber = "";
			ShouldCancelSpotQuoteCharges = true;
			TestJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;
			AssertEquals(0, TestJob.Charges.Count);
			AssertEquals(0, TestJob.ExchangeRates.Count);

			TestJob.JH_TH_NKQuoteNumber = "";
			ShouldCancelSpotQuoteCharges = false;
			TestJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;
			AssertEquals(1, TestJob.Charges.Count);
			AssertBillingExchangeRates(TestJob.ExchangeRates.ToArray<ExchangeRate>());
		}

		public void TestOneOffQuoteChargesCopied_CFX_ShouldComeFromOrganizationNotOriginalQuote()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			var currencyUSD = Factory.LoadFromNaturalKey<RefCurrency>(RefCurrencySchema.RX_Code, "USD");
			creator.CreateExchangeRate(currencyUSD, ExchangeRateTypes.Code.BuyRate, 100m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			creator.CreateExchangeRate(currencyUSD, ExchangeRateTypes.Code.SellRate, 101m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			var clientOrg = Factory.New<OrgHeader>();
			clientOrg.OH_Code = "NTC1";
			clientOrg.OH_FullName = "New Test Client";
			clientOrg.MainAddress.OA_Address1 = "123 Fake Street";
			clientOrg.MainAddress.OA_City = "Sydney";
			clientOrg.MainAddress.OA_State = "NSW";
			clientOrg.MainAddress.OA_PostCode = "2000";
			clientOrg.OH_RL_NKClosestPort = "AUSYD";
			clientOrg.OH_IsDebtor = true;
			clientOrg.OH_IsConsignor = true;
			clientOrg.OH_IsConsignee = true;
			clientOrg.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", percentage: 8m, minimum: 5m);

			var providerOrg = Factory.New<OrgHeader>();
			providerOrg.OH_Code = "TRASPROV1";
			providerOrg.OH_FullName = "Transport Provider 1";
			providerOrg.MainAddress.OA_Address1 = "123 Fake Street";
			providerOrg.MainAddress.OA_City = "Sydney";
			providerOrg.MainAddress.OA_State = "NSW";
			providerOrg.MainAddress.OA_PostCode = "2000";
			providerOrg.OH_RL_NKClosestPort = "AUSYD";
			providerOrg.OH_IsShippingProvider = true;
			var shippingLine = Factory.NewWithValidTestData<RefShippingLine>();
			shippingLine.RSL_StandardCarrierAlphaCode = "SCAC";
			providerOrg.OH_RSL_ShippingLine = shippingLine.PK;

			Factory.Save();

			var originalQuote = Factory.New<Quote>();
			originalQuote.QuotationClientAddress.OrganisationPK = clientOrg.PK;
			originalQuote.TH_QuoteNumber = "54321";
			originalQuote.TH_OneTimeQuote = true;
			originalQuote.CurrentOneOffQuote.TT_TransportMode = Constants.TransportModes.Air;
			originalQuote.CurrentOneOffQuote.TT_ContainerMode = Constants.RateMode.LSE;
			originalQuote.CurrentOneOffQuote.TT_OH_Carrier = providerOrg.PK;
			originalQuote.AddRateEntry("AIR", "LSE", "AUSYD", "USLAX");

			var originalJob = new Loader(originalQuote).TryCreate();
			var charge = originalJob.Charges.AddNew();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			charge.JR_OH_SellAccount = clientOrg.PK;
			charge.JR_RX_NKSellCurrency = "USD";
			charge.JR_OSSellAmt = 10000;
			charge.JR_OH_CostAccount = providerOrg.PK;
			charge.JR_RX_NKCostCurrency = "USD";
			charge.JR_OSCostAmt = 5000;

			var originalBillingExchangeRates = originalJob.ExchangeRates.OfType<ExchangeRate>();
			var actualExchangeRates = originalBillingExchangeRates.Select(e => new
			{
				e.JF_OrgType,
				e.JF_BaseRate,
				e.JF_CFXPercent,
				e.JF_CFXMinimum,
				e.JF_OH_Org
			});

			var expectedBillingExchangeRates = (new[] {
				new
				{
					JF_OrgType = (ZString)"DEB",
					JF_BaseRate = (ZDecimal)100m,
					JF_CFXPercent = (ZDecimal)8m,
					JF_CFXMinimum = (ZDecimal)5m,
					JF_OH_Org = clientOrg.PK,
				},
				new
				{
					JF_OrgType = (ZString)"CRD",
					JF_BaseRate = (ZDecimal)100m,
					JF_CFXPercent = (ZDecimal)0m, // Creditor exchange rate does not have CFX config
					JF_CFXMinimum = (ZDecimal)0m,
					JF_OH_Org = providerOrg.PK,
				}
			});

			CombineAssertions(() =>
			{
				AssertEquals(expectedBillingExchangeRates.Length, originalBillingExchangeRates.Count());
				AssertContainsExactElementsInAnyOrder(expectedBillingExchangeRates, actualExchangeRates);
			});

			AssertEquals(100m, charge.JR_OSCostExRate);
			AssertEquals("less 8% from 100", 92m, charge.JR_OSSellExRate);

			// Change the exchange rates' values to assert that they are not copied when OOQ is copied
			originalBillingExchangeRates.ForEach(x =>
			{
				x.JF_BaseRate = 1;
				x.JF_CFXPercent = 7;
				x.JF_CFXMinimum = 2;
			});

			// organization configurations for exchange rates and CFX Uplift
			var exRateARConfig = clientOrg.CompanyData.AccARExchangeRateConfigurations.AddNew();
			exRateARConfig.JCE_JobType = "ALL";
			exRateARConfig.JCE_ServiceDirection = "ALL";
			exRateARConfig.JCE_TransportMode = "ALL";
			exRateARConfig.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;

			var exRateAPConfig = providerOrg.CompanyData.AccAPExchangeRateConfigurations.AddNew();
			exRateAPConfig.JCE_JobType = "ALL";
			exRateAPConfig.JCE_ServiceDirection = "ALL";
			exRateAPConfig.JCE_TransportMode = "ALL";
			exRateAPConfig.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;

			clientOrg.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", percentage: 10m, minimum: 4m);
			Factory.Save();

			var newQuote = (Quote)originalQuote.CopyIncludingChildren();
			var newJob = new Loader(newQuote).Load();
			var newJobExpectedRates = new[]
			{
				new
				{
					JF_OrgType = (ZString)"DEB",
					JF_BaseRate = (ZDecimal)101m,  // from SellRate as directed by organization exchange rate config
					JF_CFXPercent = (ZDecimal)10m, // from organization CFX config
					JF_CFXMinimum = (ZDecimal)4m,
					JF_OH_Org = clientOrg.PK
				},
				new
				{
					JF_OrgType = (ZString)"CRD",
					JF_BaseRate = (ZDecimal)101m,
					JF_CFXPercent = (ZDecimal)0m,
					JF_CFXMinimum = (ZDecimal)0m,
					JF_OH_Org = providerOrg.PK,
				}
			};
			var newJobActualExchangeRates = newJob.ExchangeRates.Select(e =>
				new
				{
					e.JF_OrgType,
					e.JF_BaseRate,
					e.JF_CFXPercent,
					e.JF_CFXMinimum,
					e.JF_OH_Org
				});

			CombineAssertions(() =>
			{
				AssertEquals(newJobExpectedRates.Length, newJob.ExchangeRates.Count);
				AssertContainsExactElementsInAnyOrder("new billing exchange rate should be created with new values and from organization configurations rather than being copied from source",
					newJobExpectedRates, newJobActualExchangeRates);
			});

			var newCharge = (Charge)newJob.Charges.Single();
			AssertEquals(101m, newCharge.JR_OSCostExRate);
			AssertEquals("less 10% from 101", 90.9m, newCharge.JR_OSSellExRate);
		}

