			originalQuote.AddRateEntry("AIR", "LSE", "CNSHA", "USLAX");

			var originalJob = new Loader(originalQuote).TryCreate();
			var charge = originalJob.Charges.AddNew();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			charge.JR_OH_SellAccount = clientOrg.PK;
			charge.JR_RX_NKSellCurrency = "USD";
			charge.JR_OSSellAmt = 10000;
			charge.JR_OH_CostAccount = providerOrg.PK;
			charge.JR_RX_NKCostCurrency = "USD";
			charge.JR_OSCostAmt = 5000;

			var originalBillingExchangeRates = originalJob.ExchangeRates.OfType<ExchangeRate>();
			var expectedExchangeRates = new[] {
				new
				{
					JF_OrgType = (ZString)"DEB",
					JF_BaseRate = (ZDecimal)100m,
					JF_CFXPercent = (ZDecimal)8m,
					JF_CFXMinimum = (ZDecimal)5m,
					JF_OH_Org = clientOrg.PK,
				},
				new
				{
					JF_OrgType = (ZString)"CRD",
					JF_BaseRate = (ZDecimal)100m,
					JF_CFXPercent = (ZDecimal)0m, // Creditor exchange rate does not have CFX config
					JF_CFXMinimum = (ZDecimal)0m,
					JF_OH_Org = providerOrg.PK,
				}
			};

			var actualExchangeRates = originalBillingExchangeRates.Select(e => new
				{
					e.JF_OrgType,
					e.JF_BaseRate,
					e.JF_CFXPercent,
					e.JF_CFXMinimum,
					e.JF_OH_Org
				});

			CombineAssertions(
				() =>
				{
					AssertEquals(expectedExchangeRates.Length, originalBillingExchangeRates.Count());
					AssertContainsExactElementsInAnyOrder(expectedExchangeRates, actualExchangeRates);
				}
			);

			AssertEquals(100m, charge.JR_OSCostExRate);
			AssertEquals("less 8% from 100", 92m, charge.JR_OSSellExRate);

			// Change the exchange rates' values to assert that they are not copied when OOQ is copied
			originalBillingExchangeRates.ForEach(x =>
			{
				x.JF_BaseRate = 1;
				x.JF_CFXPercent = 7;
				x.JF_CFXMinimum = 2;
			});

			// organization configurations for exchange rates and CFX Uplift
			var exRateARConfig = clientOrg.CompanyData.AccARExchangeRateConfigurations.AddNew();
			exRateARConfig.JCE_JobType = "ALL";
			exRateARConfig.JCE_ServiceDirection = "ALL";
			exRateARConfig.JCE_TransportMode = "ALL";
			exRateARConfig.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;

			var exRateARConfigOTH = clientOrg.CompanyData.AccARExchangeRateConfigurations.AddNew();
			exRateARConfigOTH.JCE_JobType = "ALL";
			exRateARConfigOTH.JCE_ServiceDirection = "OTH";
			exRateARConfigOTH.JCE_TransportMode = "AIR";
			exRateARConfigOTH.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;

			var exRateAPConfig = providerOrg.CompanyData.AccAPExchangeRateConfigurations.AddNew();
			exRateAPConfig.JCE_JobType = "ALL";
			exRateAPConfig.JCE_ServiceDirection = "ALL";
			exRateAPConfig.JCE_TransportMode = "ALL";
			exRateAPConfig.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = Constants.ExchangeRateTypes.Code.SellRate;

			clientOrg.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", percentage: 10m, minimum: 4m);
			clientOrg.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "OTH", "AIR", percentage: 7m, minimum: 3m); // Expected to be chosen

			Factory.Save();

			var newQuote = (Quote)originalQuote.CopyIncludingChildren();
			var newJob = new Loader(newQuote).Load();
			expectedExchangeRates = new[]
			{
				new
				{
					JF_OrgType = (ZString)"DEB",
					JF_BaseRate = (ZDecimal)101m,  // from SellRate as directed by organization exchange rate config
					JF_CFXPercent = (ZDecimal)7m, // from organization CFX config (ALL-OTH-AIR)
					JF_CFXMinimum = (ZDecimal)3m,
					JF_OH_Org = clientOrg.PK
				},
				new
				{
					JF_OrgType = (ZString)"CRD",
					JF_BaseRate = (ZDecimal)101m,
					JF_CFXPercent = (ZDecimal)0m,
					JF_CFXMinimum = (ZDecimal)0m,
					JF_OH_Org = providerOrg.PK,
				}
			};

			var newJobActualExchangeRates = newJob.ExchangeRates.Select(e => new
			{
				e.JF_OrgType,
				e.JF_BaseRate,
				e.JF_CFXPercent,
				e.JF_CFXMinimum,
				e.JF_OH_Org
			});

			CombineAssertions(
			() =>
			{
				AssertEquals(expectedExchangeRates.Length, newJob.ExchangeRates.Count);
				AssertContainsExactElementsInAnyOrder("new billing exchange rate should be created with new values and from organization configurations rather than being copied from source",
					expectedExchangeRates, newJobActualExchangeRates);
			});

			var newCharge = (Charge)newJob.Charges.Single();
			AssertEquals(101m, newCharge.JR_OSCostExRate);
			AssertEquals("less 7% from 101", 93.93m, newCharge.JR_OSSellExRate);
		}

