		[DisableZeroExchangeRateOverriding]
		public void TestOneOffQuoteChargesCopied_ShouldRecalculateChargesCostAndSellExchangeRates_ExchangeRateIsZero()
		{
			var testQuote = Factory.New<Quote>();
			testQuote.TH_OneTimeQuote = true;
			testQuote.TH_QuoteNumber = "123456";

			var job = (Job)new JobHeader.Loader(testQuote).TryLoadOrCreateWithoutMutexForTestOnly();
			job.JH_OA_LocalChargesAddr = Creditor1.MainAddress.PK;
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;

			var charge = job.Charges.AddNew();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			charge.JR_RX_NKSellCurrency = "USD";
			charge.JR_OSSellAmt = 97m;

			AssertExchangeRatesShouldBeZero(job.ExchangeRates.ToArray<ExchangeRate>());
			AssertEquals(97m, charge.JR_OSSellAmt);
			AssertEquals("As there is no exchange rates in system for USD, local sell amount should be zero", 0m, charge.JR_LocalSellAmt);

			charge.JR_OSSellExRate = 1.2m;

			AssertEquals(97m, charge.JR_OSSellAmt);
			AssertEquals("local sell amount = 97/1.2", 80.83m, charge.JR_LocalSellAmt);
			AssertNoErrors(charge.JR_OSSellExRateInfo);

			Factory.Save();

			AssertEquals(0, TestJob.Charges.Count);
			AssertEquals(0, TestJob.ExchangeRates.Count);

			TestJob.JH_TH_NKQuoteNumber = testQuote.TH_QuoteNumber;

			AssertEquals(1, TestJob.Charges.Count);
			AssertEquals(TestJob.PK, TestJob.Charges[0].JR_JH);
			AssertEquals(Env.Registry.FreightChargeCode, TestJob.Charges[0].JR_AC);

			AssertExchangeRatesShouldBeZero(TestJob.ExchangeRates.ToArray<ExchangeRate>());
			AssertEquals(97m, TestJob.Charges[0].JR_OSSellAmt);
			AssertEquals("As there is no exchange rates in system for USD, local sell amount copied from quote", 80.83m, TestJob.Charges[0].JR_LocalSellAmt);
			AssertEquals("As there is no exchange rates in system for USD, exchange rate is copied from quote", 1.2m, TestJob.Charges[0].JR_OSSellExRate);

			void AssertExchangeRatesShouldBeZero(ExchangeRate[] exchangeRates)
			{
				AssertEquals("There should be exchange rates for CRD and DEB types", 2, exchangeRates.Length);
				var exRateDEB = exchangeRates.Single(x => x.JF_OrgType == "DEB");
				var exRateCRD = exchangeRates.Single(x => x.JF_OrgType == "CRD");

				CombineAssertions("Exchange rates should not be present for USD, should be zero.", () =>
				{
					AssertEquals("USD", exRateDEB.JF_RX_NKRateCurrency);
					AssertEquals(0m, exRateDEB.JF_SellRate);
					AssertEquals(0m, exRateDEB.JF_BaseRate);
					AssertEquals(Creditor1.PK, exRateDEB.JF_OH_Org);

					AssertEquals("USD", exRateCRD.JF_RX_NKRateCurrency);
					AssertEquals(0m, exRateCRD.JF_SellRate);
					AssertEquals(0m, exRateCRD.JF_BaseRate);
					AssertEquals(ZGuid.Empty, exRateCRD.JF_OH_Org);
				});
			}
		}

		public void TestSpotQuoteCFXCopied()
		{
			// System Exchange Rate: BUY - CNY - 0.98
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(creator.CNY, Constants.ExchangeRateTypes.Code.BuyRate, 0.98m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			var quotedBooking = QuotedBooking.New(QuoteBookingType.SpotQuote, Factory);
			var quote = quotedBooking.Quote;
			quote.TH_QuoteNumber = "TEST123";
			quote.TH_OneTimeQuote = true;

			var quoteJob = (Job)new JobHeader.Loader(quote).TryLoadOrCreateWithoutMutexForTestOnly();
			quoteJob.JH_OA_LocalChargesAddr = Creditor1.MainAddress.PK;
			quoteJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
			quoteJob.LocalCharges.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 3m);

			var exRate = quoteJob.ExchangeRates.AddNew();
			exRate.JF_RX_NKRateCurrency = "CNY";
			exRate.JF_BaseRate = 0.97m;
			AssertEquals(decimal.Zero, exRate.JF_CFXPercent);

			var charge = quoteJob.Charges.AddNew();
			charge.JR_AC = Env.Registry.FreightChargeCode;
			charge.JR_RX_NKSellCurrency = "CNY";
			charge.JR_RX_NKCostCurrency = "CNY";
			charge.JR_OSSellAmt = 85m;
			charge.JR_OSCostAmt = 98m;

			var shipment = Factory.New<ForwardingShipment>();
			Factory.Save();

			var shipmentJob = (Job)new JobHeader.Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			shipmentJob.JH_OA_LocalChargesAddr = Creditor1.MainAddress.PK;
			shipmentJob.JH_GE = GlbDepartment.CurrentDepartment.PK;

			var shipmentExRate1 = shipmentJob.ExchangeRates.AddNew();
			shipmentExRate1.JF_RX_NKRateCurrency = "AUD";
			shipmentExRate1.JF_BaseRate = 0.95;

			shipmentJob.JH_TH_NKQuoteNumber = quote.TH_QuoteNumber;
			var copiedCharge = shipmentJob.Charges[0];

			AssertEquals(3m, copiedCharge.JR_LineCFX);
			AssertEquals(0.9506m, copiedCharge.JR_OSSellExRate); // 0.98*(1-0.03)
			AssertEquals(89.42m, copiedCharge.JR_LocalSellAmt); // 85/(0.98*(1-0.03))
			AssertEquals(100m, copiedCharge.JR_LocalCostAmt); // 98/0.98
			AssertEquals(3m, copiedCharge.RevenueExchangeRate.CFXPercent);
			AssertEquals(0.98m, copiedCharge.RevenueExchangeRate.Rate);
			AssertEquals(0.9506m, copiedCharge.RevenueExchangeRate.SellRate);
			AssertEquals(0.98m, copiedCharge.CostExchangeRate.Rate);

			quoteJob.LocalCharges.CompanyData.AccCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 4m);
			quoteJob.ForceChargesRefreshExRates_ForTestsOnly();

			shipmentJob.JH_TH_NKQuoteNumber = "";
			shipmentJob.Charges.RemoveAll();
			shipmentJob.ExchangeRates.RemoveAndDeleteAll();

			shipmentJob.JH_TH_NKQuoteNumber = quote.TH_QuoteNumber;
			copiedCharge = shipmentJob.Charges[0];

			AssertEquals(4m, copiedCharge.JR_LineCFX);
			AssertEquals(0.9408m, copiedCharge.JR_OSSellExRate); // 0.98*(1-0.04)
			AssertEquals(90.35m, copiedCharge.JR_LocalSellAmt); // 85/(0.98*(1-0.04))
			AssertEquals(100m, copiedCharge.JR_LocalCostAmt); // 98/0.98
			AssertEquals(4m, copiedCharge.RevenueExchangeRate.CFXPercent);
			AssertEquals(0.98m, copiedCharge.RevenueExchangeRate.Rate);
			AssertEquals(0.9408m, copiedCharge.RevenueExchangeRate.SellRate);
			AssertEquals(0.98m, copiedCharge.CostExchangeRate.Rate);
		}

		public void TestQuoteChargesCopiedWithoutExcludedGuidFields()
		{
			// System Exchange Rate: BUY - USD - 0.98
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(creator.USD, Constants.ExchangeRateTypes.Code.BuyRate, 0.98m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			var quotedBooking = QuotedBooking.New(QuoteBookingType.SpotQuote, Factory);
			var quote = quotedBooking.Quote;
			quote.CurrentOneOffQuote.TT_OH_Creditor = TestObjectCreator.Creditor1.PK;
			quote.InternalApproveQuote();
			Assert("Precondition: quote.IsApproved", quote.IsApproved);

			var jobForQuote = new Loader(quotedBooking).TryLoadOrCreateWithoutMutexForTestOnly();
			jobForQuote.JH_GE = GlbDepartment.CurrentDepartment.PK;
			TestObjectCreator.CreateExchangeRate(jobForQuote, TestObjectCreator.USD, 0.97m);
			TestObjectCreator.CreateCharge(jobForQuote, TestObjectCreator.FRT, "", TestObjectCreator.USD, 98, TestObjectCreator.Creditor1, TestObjectCreator.USD, 98, TestObjectCreator.Debtor);
			Factory.Save();
			AssertEquals("Precondition: exchange rate should be added for Quote", 1, jobForQuote.ExchangeRates.Count);
			AssertEquals("Precondition: charge should be added for Quote", 1, jobForQuote.Charges.Count);
			var chargeForQuote = jobForQuote.Charges[0];
			AssertNull("Precondition: Quote WIP must not be created.", chargeForQuote.WIP);
			AssertNull("Precondition: Quote Accrual must not be created.", chargeForQuote.Accrual);

			quotedBooking.ConvertQuoteToQuotedBooking();
			var jobForBooking = new Loader(quotedBooking).TryLoadOrCreateWithoutMutexForTestOnly();
			Factory.Save();
			AssertEquals("Precondition: Booking job should still have the charge", 1, jobForBooking.Charges.Count);
			var chargeForBooking = jobForBooking.Charges[0];
			AssertNull("Precondition: WIP must not be created, converted booking is treated as a quote.", chargeForBooking.WIP);
			AssertNull("Precondition: Accrual must not be created, converted booking is treated as a quote.", chargeForBooking.Accrual);

			var shipment = (CommonShipment)Factory.Load(quotedBooking.Booking.GetType(), quotedBooking.Booking.PK);
			shipment.JS_IsForwardRegistered = true;

			var jobForShipment = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
			Assert("Postcondition: JH_TH_NKQuoteNumber should be set", !jobForShipment.JH_TH_NKQuoteNumber.IsEmpty);
			AssertEquals("Charge should be copied from quote for shipment", 1, jobForShipment.Charges.Count);

			var chargeForShipment = jobForShipment.Charges[0];

			AssertEquals("JR_JH", jobForShipment.PK, chargeForShipment.JR_JH);
			AssertEquals("JR_AC", Env.Registry.FreightChargeCode, chargeForShipment.JR_AC);
			AssertEquals("JR_OSSellAmt", 98m, chargeForShipment.JR_OSSellAmt);
			AssertEquals("JR_LocalSellAmt", 100m, chargeForShipment.JR_LocalSellAmt);
			AssertEquals("JR_OSCostAmt", 98m, chargeForShipment.JR_OSCostAmt);
			AssertEquals("JR_LocalCostAmt", 100m, chargeForShipment.JR_LocalCostAmt);
			AssertEquals("JR_OH_SellAccount", TestObjectCreator.Debtor.PK, chargeForShipment.JR_OH_SellAccount);
			AssertEquals("JR_OH_CostAccount", TestObjectCreator.Creditor1.PK, chargeForShipment.JR_OH_CostAccount);

			AssertNoExceptionThrown(() => Factory.Save());

			AssertEquals("Postcondition: shipment charge count", 1, jobForShipment.Charges.Count);
			AssertNotNull("Postcondition: shipment WIP must be created.", chargeForShipment.WIP);
			AssertNotNull("Postcondition: shipment Accrual must be created.", chargeForShipment.Accrual);

			AssertEquals("Postcondition: booking charge count", 1, jobForBooking.Charges.Count);
			AssertNull("Precondition: Quoted Booking WIP must be reversed.", chargeForBooking.WIP);
			AssertNull("Precondition: Quoted Booking Accrual must be reversed.", chargeForBooking.Accrual);
		}

		[SuspendToTestReportJobIsChangedByDifferentCompany]/*Accounting objects, such as JobHeader, need to be processed under the correct company context. If you want to process many companies, you need to do that one by one*/
		public void TestQuoteNumberIsNotAssignedWhenQuoteIsInDifferentCompany()
		{
			AssertQuoteAssignment(false, 0);
			AssertQuoteAssignment(true, 1);
		}

		void AssertQuoteAssignment(bool useQuoteInThisCompany, int chargesCount)
		{
			var quote = Factory.New<Quote>();
			quote.TH_OneTimeQuote = true;
			quote.TH_QuoteNumber = "123456";
			quote.TH_GC = useQuoteInThisCompany
							? GlbCompany.CurrentCompany.PK
							: Factory.LoadTop1<GlbCompany>(new ZQuery(GlbCompanySchema.PK, SQLComparisonOperator.NotEqual, GlbCompany.CurrentCompany.PK)).PK;

			var job = (Job)new JobHeader.Loader(quote).TryLoadOrCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GC = quote.TH_GC;

			ExchangeRate exRate = job.ExchangeRates.AddNew();
			exRate.JF_RX_NKRateCurrency = "USD";
			exRate.JF_BaseRate = 0.97m;

			var code = Factory.NewWithValidTestData<AccChargeCode>();
			code.AC_GC = quote.TH_GC;

			JobCharge charge = job.Charges.AddNew();
			charge.JR_AC = code.PK;
			charge.JR_RX_NKSellCurrency = "USD";
			charge.JR_OSSellAmt = 97m;

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = string.Format("S00{0}{1}", useQuoteInThisCompany, chargesCount);
			shipment.JS_TH_OneTimeQuote = quote.PK;
			Factory.Save();

			var shipmentJob = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();

			AssertEquals(!useQuoteInThisCompany, shipmentJob.JH_TH_NKQuoteNumber.IsEmpty);
			AssertEquals(chargesCount, shipmentJob.Charges.Count);
		}

