			var sendingAgent = TestObjectCreator.CreateOrgHeader("SSS", false, true);
			var pickupAgent = TestObjectCreator.CreateOrgHeader("TTT", false, true);

			Consol = TestObjectCreator.CreateConsol();
			Consol.SetDefaultReceivingForwarderAddress(ReceivingAgent);

			Shipment = Factory.New<ForwardingShipment>();
			Shipment.Consols.Add(Consol);

			job.PlugInData = Shipment;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be empty", ZGuid.Empty, job.AgentCollectPK);

			Shipment.ConsigneeDocumentaryAddress.OrganisationPK = Consignee.PK;
			Shipment.ConsignorDocumentaryAddress.OrganisationPK = Consignor.PK;
			Shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			Shipment.JS_RL_NKDestination = "USLAX";
			Shipment.JS_TransportMode = "AIR";
			Shipment.JS_OH_DeliveryAgent = ZGuid.Empty;

			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Receiving agent him/herself", ReceivingAgent.PK, job.AgentCollectPK);

			ReceivingAgent.SetRelatedParty(nettingAgentReceiving, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			job = Factory.NewJobForTesting<Job>();
			job.AgentCollectPK = ZGuid.Empty;
			job.PlugInData = Shipment;
			AssertEquals("The default agent should be the Receiving AR netting agent", nettingAgentReceiving.PK, job.AgentCollectPK);

			Shipment.JS_OH_DeliveryAgent = DeliveryAgent.PK;
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Delivery agent him/herself", DeliveryAgent.PK, job.AgentCollectPK);

			DeliveryAgent.SetRelatedParty(nettingAgentDelivery, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Delivery AR netting agent", nettingAgentDelivery.PK, job.AgentCollectPK);

			// Change to import shipment
			Shipment.JS_RL_NKOrigin = "USLAX";
			Shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			Consol.SetDefaultSendingForwarderAddress(sendingAgent);
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Sending agent him/herself", sendingAgent.PK, job.AgentCollectPK);

			sendingAgent.SetRelatedParty(nettingAgentSending, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Sending AR netting agent", nettingAgentSending.PK, job.AgentCollectPK);

			Shipment.PickupAgentPK = pickupAgent.PK;
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Pickup agent him/herself", pickupAgent.PK, job.AgentCollectPK);

			pickupAgent.SetRelatedParty(nettingAgentPickup, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("The default agent should be the Pickup AR netting agent", nettingAgentPickup.PK, job.AgentCollectPK);
		}

		public void TestGetDefaultAgentUsesCorrectConsol()
		{
			Shipment = TestObjectCreator.CreateShipment("S001", GlbBranch.CurrentBranch.GB_RL_NKHomePort, "SGSIN", transportMode: "AIR");

			var consol1 = TestObjectCreator.CreateConsol(consolNum: "C001");
			var consol1SendingAgent = TestObjectCreator.CreateOrgHeader("C1S", false, true);
			consol1.JK_OA_SendingForwarderAddress = consol1SendingAgent.Addresses.MainAddress.PK;
			var consol1ReceivingAgent = TestObjectCreator.CreateOrgHeader("C1R", false, true);
			consol1.JK_OA_ReceivingForwarderAddress = consol1ReceivingAgent.Addresses.MainAddress.PK;

			var transport1 = (consol1.Transports.FirstOrDefault() ?? consol1.Transports.AddNew()) as Transport;
			transport1.JW_RL_NKLoadPort = "USLAX";
			transport1.JW_RL_NKDiscPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			transport1.JW_ATD = ZDateTime.Now;
			transport1.JW_ATA = ZDateTime.Now.AddDays(1);

			var consol2 = TestObjectCreator.CreateConsol(consolNum: "C002");
			var consol2SendingAgent = TestObjectCreator.CreateOrgHeader("C2S", false, true);
			consol2.JK_OA_SendingForwarderAddress = consol2SendingAgent.Addresses.MainAddress.PK;
			var consol2ReceivingAgent = TestObjectCreator.CreateOrgHeader("C2R", false, true);
			consol2.JK_OA_ReceivingForwarderAddress = consol2ReceivingAgent.Addresses.MainAddress.PK;

			var transport2 = (consol2.Transports.FirstOrDefault() ?? consol2.Transports.AddNew()) as Transport;
			transport2.JW_RL_NKLoadPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			transport2.JW_RL_NKDiscPort = "SGSIN";
			transport2.JW_ATD = ZDateTime.Now.AddDays(2);
			transport2.JW_ATA = ZDateTime.Now.AddDays(3);

			Shipment.Consols.Add(consol1);
			Shipment.Consols.Add(consol2);
			var job = TestObjectCreator.CreateJob(Shipment, false);

			Factory.Save();

			AssertEquals(consol1.PK, Shipment.Consols.GetEarliestConsol().PK);
			AssertEquals(consol2.PK, Shipment.Consols.GetLatestConsol().PK);

			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Export shipment sets OS Agent to Receiving agent from latest consol", consol2ReceivingAgent.PK, job.AgentCollectPK);

			Shipment.JS_RL_NKOrigin = "USLAX";
			Shipment.JS_RL_NKDestination = GlbBranch.CurrentBranch.GB_RL_NKHomePort;

			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Import shipment sets OS Agent to Sending agent from earliest consol", consol1SendingAgent.PK, job.AgentCollectPK);

			transport1.JW_RL_NKLoadPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			transport1.JW_RL_NKDiscPort = "SGSIN";
			transport1.JW_ATD = ZDateTime.Now.AddDays(2);
			transport1.JW_ATA = ZDateTime.Now.AddDays(3);

			transport2.JW_RL_NKLoadPort = "USLAX";
			transport2.JW_RL_NKDiscPort = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			transport2.JW_ATD = ZDateTime.Now;
			transport2.JW_ATA = ZDateTime.Now.AddDays(1);

			AssertEquals(consol2.PK, Shipment.Consols.GetEarliestConsol().PK);
			AssertEquals(consol1.PK, Shipment.Consols.GetLatestConsol().PK);

			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Import shipment sets OS Agent to Sending agent from earliest consol", consol2SendingAgent.PK, job.AgentCollectPK);

			Shipment.JS_RL_NKOrigin = GlbBranch.CurrentBranch.GB_RL_NKHomePort;
			Shipment.JS_RL_NKDestination = "SGSIN";

			job.AgentCollectPK = ZGuid.Empty;
			job.SetDefaultsForJob();
			AssertEquals("Export shipment sets OS Agent to Receiving agent from latest consol", consol1ReceivingAgent.PK, job.AgentCollectPK);
		}

		public void TestDefaultBillToPartyForBrokerage()
		{
			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader iMCustomsBillTo = Factory.New<OrgHeader>();
			iMCustomsBillTo.Addresses.AddNew(OrgAddressType.Office, true);
			iMCustomsBillTo.OH_Code = "IM1";
			BaseJobDeclaration declaration = Factory.NewWithValidTestData<BaseJobDeclaration>();
			Job customsJob = Factory.NewJobWithValidTestDataForTesting<Job>();

			declaration.JE_OH_Importer = consignee.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Import;

			customsJob.LocalChargesPK = ZGuid.Empty;
			customsJob.PlugInData = declaration;
			AssertEquals("Bill To Party should be the Consignee themselves", consignee.PK, customsJob.LocalChargesPK);

			consignee.SetRelatedParty(iMCustomsBillTo, RelatedPartyTypeList.Codes.InvoiceCustomsJobsTo, RelatedPartyDirectionList.Codes.Delivery);
			customsJob = Factory.NewJobWithValidTestDataForTesting<Job>();
			customsJob.JH_ParentID = ZGuid.Empty;
			customsJob.LocalChargesPK = ZGuid.Empty;
			customsJob.PlugInData = declaration;
			AssertEquals("Bill To Party should be the IMCustoms BillTo", iMCustomsBillTo.PK, customsJob.LocalChargesPK);

			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader eXCustomsBillTo = Factory.NewWithValidTestData<OrgHeader>();

			declaration.JE_OH_Supplier = consignor.PK;
			declaration.JE_MessageType = JobMessageTypeList.Codes.Export;

			customsJob = Factory.NewJobWithValidTestDataForTesting<Job>();
			customsJob.JH_ParentID = ZGuid.Empty;
			customsJob.LocalChargesPK = ZGuid.Empty;
			customsJob.PlugInData = declaration;
			AssertEquals("Bill To Party should be the Consignor themselves", consignor.PK, customsJob.LocalChargesPK);

			customsJob = Factory.NewJobWithValidTestDataForTesting<Job>();

			consignor.SetRelatedParty(eXCustomsBillTo, RelatedPartyTypeList.Codes.InvoiceCustomsJobsTo, RelatedPartyDirectionList.Codes.Pickup);
			customsJob.JH_ParentID = ZGuid.Empty;
			customsJob.LocalChargesPK = ZGuid.Empty;
			customsJob.PlugInData = declaration;
			AssertEquals("Bill To Party should be the EXCustoms BillTo", eXCustomsBillTo.PK, customsJob.LocalChargesPK);
		}

		public void TestDefaultBillToParty_Gateway()
		{
			var gatewayAgent = GlbCompany.CurrentCompany.OrgProxy;
			var receivingAgent = Factory.NewWithValidTestData<OrgHeader>();

			var gatewayConsol = TestObjectCreator.CreateConsol("USCHI", "AUMEL", "C00100191");
			gatewayConsol.JK_AgentType = Constants.AgentType.Agent;
			gatewayConsol.JK_OA_SendingForwarderAddress = gatewayAgent.MainAddress.PK;
			gatewayConsol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			gatewayConsol.JK_OA_ReceivingForwarderAddress = receivingAgent.MainAddress.PK;
			gatewayConsol.JK_ReceivingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			gatewayConsol.JK_OA_ShippingLineAddress = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;
			gatewayConsol.JK_OA_CreditorAddress = Factory.NewWithValidTestData<OrgHeader>().MainAddress.PK;

			var port = Factory.NewWithValidTestData<OrgAppointedAgentPorts>();
			port.O5_PortOrCountry = "USCHI";
			port.O5_OA_AgentOfficeAddress = gatewayConsol.JK_OA_SendingForwarderAddress;
			port.O5_AgentDirection = AgentDirectionList.Codes.Both;
			port.O5_AirAgentStatus = AgentStatusList.Codes.GatewayAgent;
			gatewayConsol.SendingForwarder.AppointedGatewayAgentPorts.Add(port);

			port = Factory.NewWithValidTestData<OrgAppointedAgentPorts>();
			port.O5_PortOrCountry = "AUSYD";
			port.O5_OA_AgentOfficeAddress = gatewayConsol.JK_OA_SendingForwarderAddress;
			port.O5_AgentDirection = AgentDirectionList.Codes.Both;
			port.O5_AirAgentStatus = AgentStatusList.Codes.GatewayAgent;
			gatewayConsol.SendingForwarder.AppointedGatewayAgentPorts.Add(port);

			var job = new Loader(gatewayConsol).TryLoadOrCreateWithoutMutexForTestOnly();

			AssertEquals("Pre-condition", true, gatewayConsol.IsGateway());
			AssertEquals(gatewayAgent.PK, job.LocalChargesPK);

			gatewayConsol.JK_RL_NKLoadPort = "AUSYD";
			gatewayConsol.JK_OA_SendingForwarderAddress = gatewayAgent.MainAddress.PK;
			job.LocalChargesPK = ZGuid.Empty;
			job.SetDefaultsForJob();

			AssertEquals(gatewayAgent.PK, job.LocalChargesPK);

			gatewayConsol.JK_RL_NKDischargePort = "CNSHA";
			job.LocalChargesPK = ZGuid.Empty;
			job.SetDefaultsForJob();

			AssertEquals(gatewayAgent.PK, job.LocalChargesPK);
		}

		public void TestSetDefaultBranch()
		{
			SetUpRegistry(0, 1, 0, 0);
			GlbBranch branchFromOtherCompany = TestObjectCreator.NonCurrentCompanyBranch;
			GlbBranch branch = GlbBranch.CurrentBranch;
			OrgHeader localClient = Factory.New<OrgHeader>();
			localClient.CompanyData.OB_GB_ControllingBranch = branch.PK;

			var mockSupporter = new Mock<IJobInvoicingSupporter>();
			mockSupporter.Setup(m => m.OperationsBranch).Returns((GlbBranch)null);
			mockSupporter.Setup(m => m.ConsumerType).Returns(JobInvoicingConsumerTypes.LocalCartage);

			var invoicingMock = new Mock<IJobInvoicingPlugIn>();
			invoicingMock.Setup(m => m.InvoicingSupporter).Returns(mockSupporter.Object);

			Job job1 = Factory.NewJobForTesting<Job>();
			job1.SetDefaultBranch(invoicingMock.Object);
			AssertEquals("Invoicing.Branch", true, job1.JH_GB.IsEmpty);

			mockSupporter.Setup(m => m.OperationsBranch).Returns(branch);
			Job job2 = Factory.NewJobForTesting<Job>();
			job2.SetDefaultBranch(invoicingMock.Object);
			AssertEquals("Invoicing.Branch", branch.PK, job2.JH_GB);

			mockSupporter.Reset();
			mockSupporter.Setup(m => m.OperationsBranch).Returns(branchFromOtherCompany);
			Job job3 = Factory.NewJobForTesting<Job>();
			job3.SetDefaultBranch(invoicingMock.Object);
			AssertEquals("Invoicing.Branch", true, job1.JH_GB.IsEmpty);
		}

