		public void TestSetDefaultSalesRep()
		{
			//why does this still exist what is is testing
			InvoicingParam plugInData = new InvoicingParam();

			GlbStaff newAirStaff = Factory.New<GlbStaff>();
			newAirStaff.GS_Code = "AAA";
			GlbStaff newSeaStaff = Factory.New<GlbStaff>();
			newSeaStaff.GS_Code = "BBB";
			GlbStaff newExportAirStaff = Factory.New<GlbStaff>();
			newExportAirStaff.GS_Code = "CCC";
			GlbStaff newExportSeaStaff = Factory.New<GlbStaff>();
			newExportSeaStaff.GS_Code = "DDD";
			GlbStaff newWhsStaff = Factory.New<GlbStaff>();
			newWhsStaff.GS_Code = "EEE";
			GlbStaff newAllStaff = Factory.New<GlbStaff>();
			newAllStaff.GS_Code = "FFF";

			GlbBranch branch = Factory.New<GlbBranch>();
			OrgHeader consignee = Factory.New<OrgHeader>();
			consignee.OH_Code = "CON";
			consignee.StaffAssignments.ImportAirRep = newAirStaff.GS_Code;
			consignee.StaffAssignments.ImportSeaRep = newSeaStaff.GS_Code;
			consignee.StaffAssignments.WarehousingRep = newWhsStaff.GS_Code;
			consignee.StaffAssignments.OverallSalesRep = newAllStaff.GS_Code;
			consignee.CompanyData.OB_GB_ControllingBranch = branch.PK;

			Job job = Factory.NewJobForTesting<Job>();

			// assert Consignee and IsImport and Transport Mode = Air
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignee = consignee;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fIsImport = true;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			job.PlugInData = plugInData;
			AssertEquals(true, job.IsImport);
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.ImportAirRep, job.JH_GS_NKRepSales);

			// assert Consignee and IsImport and Transport Mode = Sea
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.ImportSeaRep, job.JH_GS_NKRepSales);

			// assert Consignee and IsImport and Transport Mode = Other
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);

			// assert Consignee and IsCrossTrade and Transport Mode = Air
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			RefUNLOCO origin = Factory.LoadTop1(typeof(RefUNLOCO), new ZQuery(RefUNLOCOSchema.RL_Code, "USLAX")) as RefUNLOCO;
			RefUNLOCO destination = Factory.LoadTop1(typeof(RefUNLOCO), new ZQuery(RefUNLOCOSchema.RL_Code, "NZAKL")) as RefUNLOCO;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = origin;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fDestination = destination;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fIsImport = false;
			job.PlugInData = plugInData;
			AssertEquals(true, job.IsCrossTrade);
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);

			// assert Consignee and IsCrossTrade and Transport Mode = Sea
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);

			// assert Consignee and IsCrossTrade and Transport Mode = Other
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);

			// assert Consignor and Warehouse Job Type and WarehousingRep empty
			// consignee is still set to assert consignor override
			job = Factory.NewJobForTesting<Job>();
			OrgHeader consignor = Factory.New<OrgHeader>();
			consignor.OH_Code = "NOR";
			consignor.Addresses.AddNew(OrgAddressType.Office, true);
			consignor.StaffAssignments.ImportAirRep = newAirStaff.GS_Code;
			consignor.StaffAssignments.ImportSeaRep = newSeaStaff.GS_Code;
			consignor.StaffAssignments.ExportAirRep = newExportAirStaff.GS_Code;
			consignor.StaffAssignments.ExportSeaRep = newExportSeaStaff.GS_Code;
			consignor.StaffAssignments.WarehousingRep = newWhsStaff.GS_Code;
			consignor.StaffAssignments.OverallSalesRep = newAllStaff.GS_Code;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignor = consignor;
			job.JH_GS_NKRepSales = ZString.Empty;
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseInwards;
			job.PlugInData = plugInData;
			AssertEquals(newWhsStaff.GS_Code, job.JH_GS_NKRepSales);

			// assert Consignee and Warehouse Job Type and WarehousingRep set
			using (AccountingMasterFilesRegistry.Instance.EnableCrossTradeDebtorDefaultingFunctionality.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
			{
				job = Factory.NewJobForTesting<Job>();
				((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignee = consignee;
				consignee.StaffAssignments.WarehousingRep = ZString.Empty;
				job.JH_GS_NKRepSales = ZString.Empty;
				plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseOutwards;
				job.PlugInData = plugInData;
				AssertEquals(plugInData.InvoicingSupporter.Consignee.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);
			}

			// assert Consignor and Warehouse Job Type and WarehousingRep set
			job = Factory.NewJobForTesting<Job>();
			consignee.StaffAssignments.WarehousingRep = newWhsStaff.GS_Code;
			job.JH_GS_NKRepSales = ZString.Empty;
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseStorage;
			job.PlugInData = plugInData;
			AssertEquals(newWhsStaff.GS_Code, job.JH_GS_NKRepSales);

			// assert Consignor and IsExport and Transport Mode = Air
			job = Factory.NewJobForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			plugInData.IsImport = false;
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			job.PlugInData = plugInData;
			AssertEquals(true, job.IsExport);
			AssertEquals(plugInData.InvoicingSupporter.Consignor.StaffAssignments.ExportAirRep, job.JH_GS_NKRepSales);

			// assert Consignor and IsExport and Transport Mode = Sea
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignor.StaffAssignments.ExportSeaRep, job.JH_GS_NKRepSales);

			// assert Consignor and IsCrossTrade and Transport Mode = Other
			job = Factory.NewJobForTesting<Job>();
			job.JH_GS_NKRepSales = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			job.PlugInData = plugInData;
			AssertEquals(plugInData.InvoicingSupporter.Consignor.StaffAssignments.OverallSalesRep, job.JH_GS_NKRepSales);
		}

		public void TestSetDefaultSalesRepFromLocalCharges()
		{
			InvoicingParam plugInData = new InvoicingParam();

			OrgHeader orgHeader1 = Factory.New<OrgHeader>();
			orgHeader1.OH_Code = "OH1";
			orgHeader1.Addresses.AddNew(OrgAddressType.Office, true);
			orgHeader1.StaffAssignments.ImportAirRep = "AAA";
			orgHeader1.StaffAssignments.ImportSeaRep = "ABB";
			orgHeader1.StaffAssignments.ExportAirRep = "ACC";
			orgHeader1.StaffAssignments.ExportSeaRep = "ADD";
			orgHeader1.StaffAssignments.WarehousingRep = "AEE";
			orgHeader1.StaffAssignments.OverallSalesRep = "AFF";

			OrgHeader orgHeader2 = Factory.New<OrgHeader>();
			orgHeader2.OH_Code = "OH2";
			orgHeader2.Addresses.AddNew(OrgAddressType.Office, true);
			orgHeader2.StaffAssignments.ImportAirRep = "BAA";
			orgHeader2.StaffAssignments.ImportSeaRep = "BBB";
			orgHeader2.StaffAssignments.ExportAirRep = "BCC";
			orgHeader2.StaffAssignments.ExportSeaRep = "BDD";
			orgHeader2.StaffAssignments.WarehousingRep = "BEE";
			orgHeader2.StaffAssignments.OverallSalesRep = "BFF";

			//IsImport and Transport Mode = Air
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignee = orgHeader1;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignor = orgHeader2;
			plugInData.IsImport = true;
			plugInData.ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			AssertSalesRepFromLocalCharges("ImportAirRep", "for Import and Transport Mode = Air", plugInData, orgHeader1, orgHeader2);

			//IsImport and Transport Mode = Sea
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			AssertSalesRepFromLocalCharges("ImportSeaRep", "for Import and Transport Mode = Sea", plugInData, orgHeader1, orgHeader2);

			//IsImport and Transport Mode = Other
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			AssertSalesRepFromLocalCharges("OverallSalesRep", "for Import and Transport Mode = Sea", plugInData, orgHeader1, orgHeader2);

			//IsCrossTrade and Transport Mode = Air
			RefUNLOCO origin = Factory.LoadTop1(typeof(RefUNLOCO), new ZQuery(RefUNLOCOSchema.RL_Code, "USLAX")) as RefUNLOCO;
			RefUNLOCO destination = Factory.LoadTop1(typeof(RefUNLOCO), new ZQuery(RefUNLOCOSchema.RL_Code, "NZAKL")) as RefUNLOCO;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = origin;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fDestination = destination;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			AssertSalesRepFromLocalCharges("ImportAirRep", "for CrossTrade and Transport Mode = Air", plugInData, orgHeader1, orgHeader2);

			//IsCrossTrade and Transport Mode = Sea
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			AssertSalesRepFromLocalCharges("ImportSeaRep", "for CrossTrade and Transport Mode = Sea", plugInData, orgHeader1, orgHeader2);

			//IsCrossTrade and Transport Mode = Other
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			AssertSalesRepFromLocalCharges("OverallSalesRep", "for CrossTrade and Transport Mode = Other", plugInData, orgHeader1, orgHeader2);

			//WarehouseInwards and WarehousingRep set
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.WarehouseInwards;
			AssertSalesRepFromLocalCharges("WarehousingRep", "for WarehouseInwards", plugInData, orgHeader1, orgHeader2);

			//WarehouseOutwards and WarehousingRep set
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.WarehouseOutwards;
			AssertSalesRepFromLocalCharges("WarehousingRep", "for WarehouseOutwards", plugInData, orgHeader1, orgHeader2);

			//WarehouseStorage and WarehousingRep set
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.WarehouseStorage;
			AssertSalesRepFromLocalCharges("WarehousingRep", "for WarehouseStorage", plugInData, orgHeader1, orgHeader2);

			//Warehouse and WarehousingRep is empty
			orgHeader1.StaffAssignments.WarehousingRep = ZString.Empty;
			orgHeader2.StaffAssignments.WarehousingRep = ZString.Empty;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.WarehouseStorage;
			AssertSalesRepFromLocalCharges("OverallSalesRep", "for Warehouse", plugInData, orgHeader1, orgHeader2);

			//IsExport and Transport Mode = Air
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fIsImport = false;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			AssertSalesRepFromLocalCharges("ExportAirRep", "for Export and Transport Mode = Air", plugInData, orgHeader1, orgHeader2);

			//IsExport and Transport Mode = Sea
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Sea;
			AssertSalesRepFromLocalCharges("ExportSeaRep", "for Export and Transport Mode = Sea", plugInData, orgHeader1, orgHeader2);

			//IsExport and Transport Mode = Other
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Other;
			AssertSalesRepFromLocalCharges("OverallSalesRep", "for CrossTrade and Transport Mode = Other", plugInData, orgHeader1, orgHeader2);
		}

		void AssertSalesRepFromLocalCharges(string role, string message, InvoicingParam plugInData, OrgHeader orgHeader1, OrgHeader orgHeader2)
		{
			Job job = Factory.NewJobForTesting<Job>();
			job.PlugInData = plugInData;
			job.LocalChargesPK = orgHeader1.PK;
			ZString staffAssignmentToTest = GetStaffAssignmentToTest(orgHeader1.StaffAssignments, role);
			AssertEquals(role + " is set " + message, staffAssignmentToTest, job.JH_GS_NKRepSales);
			job.LocalChargesPK = orgHeader2.PK;
			staffAssignmentToTest = GetStaffAssignmentToTest(orgHeader2.StaffAssignments, role);
			AssertEquals(role + " is changed " + message, staffAssignmentToTest, job.JH_GS_NKRepSales);
		}

		ZString GetStaffAssignmentToTest(OrgStaffAssignmentsCollection staffAssignments, ZString role)
		{
			ZString result = ZString.Empty;
			switch (role)
			{
				case "WarehousingRep":
					result = staffAssignments.WarehousingRep;
					break;
				case "OverallSalesRep":
					result = staffAssignments.OverallSalesRep;
					break;
				case "ImportSeaRep":
					result = staffAssignments.ImportSeaRep;
					break;
				case "ImportAirRep":
					result = staffAssignments.ImportAirRep;
					break;
				case "ExportSeaRep":
					result = staffAssignments.ExportSeaRep;
					break;
				case "ExportAirRep":
					result = staffAssignments.ExportAirRep;
					break;
				default:
					throw new Exception("You have requested a non existant staff assignement role.  Please review your test");
			}
			return result;
		}

		public void TestSetDefaultExcludeFromAutoRating()
		{
			InvoicingParam plugInData = new InvoicingParam();
			plugInData.JobNumber = "S00001000";

			RatingDataRegistry.Instance.ExcludeInwardsFromPeriodicAutoRating.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			Job job = Factory.NewJobForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseInwards;
			job.PlugInData = plugInData;
			AssertEquals(false, job.JH_ExcludeFromPeriodicRating);

			RatingDataRegistry.Instance.ExcludeInwardsFromPeriodicAutoRating.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			job = Factory.NewJobForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseInwards;
			job.PlugInData = plugInData;
			AssertEquals(true, job.JH_ExcludeFromPeriodicRating);

			RatingDataRegistry.Instance.ExcludeOrdersFromPeriodicAutoRating.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
			job = Factory.NewJobForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseOutwards;
			job.PlugInData = plugInData;
			AssertEquals(false, job.JH_ExcludeFromPeriodicRating);

			RatingDataRegistry.Instance.ExcludeOrdersFromPeriodicAutoRating.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			job = Factory.NewJobForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseOutwards;
			job.PlugInData = plugInData;
			AssertEquals(true, job.JH_ExcludeFromPeriodicRating);

			BusinessObjectFactory factory2 = new BusinessObjectFactory();
			job = factory2.NewJobWithValidTestDataForTesting<Job>();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseStorage;
			job.PlugInData = plugInData;
			AssertEquals(false, job.JH_ExcludeFromPeriodicRating);

			factory2.Save();
			plugInData.ConsumerType = JobInvoicingConsumerTypes.WarehouseOutwards;
			job.SetDefaultsForJob();
			AssertEquals(false, job.JH_ExcludeFromPeriodicRating);
		}

		public void TestSetDefaultDepartmentIfDepartmentPKIsNotEmpty()
		{
			CommonCartage cartage = Factory.New<CommonCartage>();
			ZGuid departmentPK = Factory.New<GlbDepartment>().PK;
			CommonCartageType jobTypeWithDept = Factory.New<CommonCartageType>();
			jobTypeWithDept.E3_JobType = "DEPP";
			jobTypeWithDept.E3_GE = departmentPK;
			cartage.JJ_E3_NKJobType = jobTypeWithDept.E3_JobType;
			Job cartageJobWithDept = Factory.NewJobForTesting<Job>();
			cartageJobWithDept.SetDefaultDepartment(cartage);
			AssertEquals("Job.Department.PK", departmentPK, cartageJobWithDept.Department.PK);

			CommonCartageType jobTypeWithoutDept = Factory.New<CommonCartageType>();
			jobTypeWithoutDept.E3_JobType = "NDPP";
			AssertEquals("LocalCartageJobType.E3_GE", true, jobTypeWithoutDept.E3_GE.IsEmpty);
			cartage.JJ_E3_NKJobType = jobTypeWithoutDept.E3_JobType;
			Job cartageJobWithNoDept = Factory.NewJobForTesting<Job>();
			cartageJobWithNoDept.SetDefaultDepartment(cartage);
			AssertNull("Job.Department", cartageJobWithNoDept.Department);
		}

