		public void TestAutoRatingDoNotChangeDSBChargeIfCostIsPosted()
		{
			var costLine = GetTransactionLine(TransactionLineTypes.Cost);
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			TestJob.LocalChargesPK = TestObjectCreator.LocalClient.PK;
			TestObjectCreator.Job1.PlugInData = shipment;

			Factory.Save();

			var sellRate = 100m;
			var existingChargeAmount = 140m;

			var strategy = new AutoRateInvoicingStrategy(shipment, TestJob);
			var operationalJobCodes = new[] { shipment.RatingAdapter.OperationalJobCode };

			var rates = GetRateInfoCollection(sellRate, DSBCharge);
			SetDSBChargeLineOnJob(costLine, DSBCharge, existingChargeAmount, shipment.RatingAdapter.OperationalJobCode);

			AssertPreCondition(existingChargeAmount);
			Assert("Cost is Posted", TestJob.Charges[0].JR_IsCostPosted);

			strategy.AddAutoRates(new LoggerDecorator(), rates, CostSell.Cost, operationalJobCodes);
			AssertEquals(1, TestJob.Charges.Count);

			var charge = TestJob.Charges[0];
			AssertEquals("Local Sell Amount", 140m, charge.JR_LocalSellAmt);
			AssertEquals("Local Cost Amount", 140m, charge.JR_LocalCostAmt);
			AssertEquals("OS Sell Amount", 140m, charge.JR_OSSellAmt);
			AssertEquals("OS Cost Amount", 140m, charge.JR_OSCostAmt);
			AssertEquals("Description", "Original DSB Charge", charge.JR_Desc);
		}

		public void TestAutoratingRevenueClientRateShouldNotSetDefaultCreditorWithCostPosted()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			TestObjectCreator.Job1.PlugInData = shipment;
			TestObjectCreator.Job1.LocalChargesPK = TestObjectCreator.LocalClient.PK;

			var charge1 = TestObjectCreator.CreateCharge(TestObjectCreator.Job1, TestObjectCreator.CC1, 80, 80);
			charge1.JR_JH_InternalJob = TestObjectCreator.Job2.PK;
			AutoJobRevenueJournalCreator.CreateJournalFromCostCharge(charge1);

			Factory.Save();

			Assert(charge1.IsCostPosted);
			Assert(!charge1.IsRevenuePosted);
			Assert(charge1.JR_OH_CostAccount.IsEmpty);
			Assert(charge1.JR_OH_SellAccount.IsEmpty);

			var rates = new AutoRateInfoCollection(Factory);
			AutoRateInfo rate1 = rates.AddNew(TestObjectCreator.CC1, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency, 100, shipment.RatingAdapter.OperationalJobCode);
			rate1.AdditionalInvoiceLineDescription = "Additional Invoice Line description 1";
			rate1.ProviderPK = TestObjectCreator.Creditor1.PK;
			rate1.DebtorOverridePK = TestObjectCreator.Debtor1.PK;
			AutoRateInfo rate2 = rates.AddNew(TestObjectCreator.CC3, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency, 100, shipment.RatingAdapter.OperationalJobCode);
			rate2.AdditionalInvoiceLineDescription = "Additional Invoice Line description 2";
			rate2.ProviderPK = TestObjectCreator.Creditor1.PK;
			rate2.DebtorOverridePK = TestObjectCreator.Debtor1.PK;
			rates.AddIfNotExist(rate1);
			rates.AddIfNotExist(rate2);

			var strategy = new AutoRateInvoicingStrategy(shipment, TestObjectCreator.Job1);
			var operationalJobCodes = new[] { shipment.RatingAdapter.OperationalJobCode };
			strategy.AddAutoRates(new LoggerDecorator(), rates, CostSell.Revenue, operationalJobCodes);

			AssertEquals(2, TestObjectCreator.Job1.Charges.Count);
			charge1 = TestObjectCreator.Job1.Charges.Where(x => x.PK == charge1.PK).FirstOrDefault();
			var charge2 = TestObjectCreator.Job1.Charges.Where(x => x.PK != charge1.PK).FirstOrDefault();

			Assert("The cost account should not set value as the charge is cost posted", charge1.JR_OH_CostAccount.IsEmpty);
			AssertEquals("The sell account should be DebtorOverridePK of the rateinfo.", charge1.JR_OH_SellAccount, TestObjectCreator.Debtor1.PK);
			AssertEquals("The cost account should be ProviderPK of the rateinfo.", charge2.JR_OH_CostAccount, TestObjectCreator.Creditor1.PK);
			AssertEquals("The sell account should be DebtorOverridePK of the rateinfo.", charge2.JR_OH_SellAccount, TestObjectCreator.Debtor1.PK);
		}

		public void TestAutoratingRevenue_ClientRateRateLineWithInternalNote_MatchesAnApportionedConsolCharge_UpdateRevenueCalculationDescription()
		{
			var consol = Factory.NewWithValidTestData<JobConsolCost>();
			consol.E6_OSCostAmount = 1000;
			consol.E6_LocalCostAmount = 1000;

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			TestObjectCreator.Job1.PlugInData = shipment;
			TestObjectCreator.Job1.LocalChargesPK = TestObjectCreator.LocalClient.PK;

			var charge = TestObjectCreator.CreateCharge(TestObjectCreator.Job1, TestObjectCreator.CC1, 0, 0);
			charge.JR_JH_InternalJob = TestObjectCreator.Job2.PK;
			charge.JR_Calc_CostRatingBehavior = "STP";
			charge.JR_LocalCostAmt = 1000;
			charge.JR_Calc_SellRatingBehavior = "REA";
			charge.JR_LocalSellAmt = 0.0;
			charge.JR_E6 = consol.PK; // to make the charge an apportioned charge
			charge.JR_SellRatingOverride = false;

			Factory.Save();

			var mockHeader = new Mock<IRatingHeader>();
			var mockEntry = new Mock<IRateEntry>();
			mockEntry.Setup(e => e.ParentRatingHeader).Returns(mockHeader.Object);
			var mockLine = new Mock<IRateLine>();
			mockLine.Setup(l => l.ParentRateEntry).Returns(mockEntry.Object);
			mockLine.Setup(l => l.ChargeInternalNoteText).Returns("Here is an internal note");

			var rate = new AutoRateInfo(Factory, mockLine.Object);
			rate.ChargeCode = TestObjectCreator.CC1;
			rate.Currency = GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency;
			rate.AddFlatPaymentBasis(0, shipment.RatingAdapter.OperationalJobCode, rate.Currency);
			rate.IsCost = false;
			rate.HasExplicitZeroAmount = true;
			rate.Description = "This should appear";

			var updatedCharge = TestObjectCreator.Job1.AddAutorateRevenue(rate, charge);
			AssertEquals("This should appear", updatedCharge.RevenueCalculationDescription.ToAscii());
		}

