		public void TestJR_AgentDeclaredSellAmt_ShouldBeRoundedCorrectly()
		{
			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			TestObjectCreator.Job1.PlugInData = shipment;
			TestObjectCreator.Job1.LocalChargesPK = TestObjectCreator.LocalClient.PK;

			var charge = TestObjectCreator.CreateCharge(TestObjectCreator.Job1, TestObjectCreator.CC1, 0, 0);
			charge.JR_RX_NKSellCurrency = AUD.RX_Code;
			Factory.Save();

			var mockHeader = new Mock<IRatingHeader>();
			var mockEntry = new Mock<IRateEntry>();
			mockEntry.Setup(e => e.ParentRatingHeader).Returns(mockHeader.Object);
			var mockLine = new Mock<IRateLine>();
			mockLine.Setup(l => l.ParentRateEntry).Returns(mockEntry.Object);
			mockLine.Setup(l => l.ChargeInformationNoteText).Returns("Here is a public note");

			var rate = new AutoRateInfo(Factory, mockLine.Object);
			rate.ChargeCode = TestObjectCreator.CC1;
			rate.Currency = "AUD";
			rate.AddFlatPaymentBasis(3.667, shipment.RatingAdapter.OperationalJobCode, rate.Currency);
			rate.HasExplicitZeroAmount = true;

			AssertEquals("initial charge JR_AgentDeclaredSellAmt", 0m, charge.JR_AgentDeclaredSellAmt);

			var updatedCharge = TestObjectCreator.Job1.AddAutorateRevenue(rate, charge);
			AssertEquals(2, AUD.Decimals);
			AssertEquals("after quick calculator, calculate JR_AgentDeclaredSellAmt and decimal is 2", 3.67m, charge.JR_AgentDeclaredSellAmt);

			charge.JR_OSSellExRate = 1.5m;
			charge.JR_RX_NKSellCurrency = TWD.RX_Code;
			AssertEquals(0, TWD.Decimals);
			AssertEquals("after changing sell currency, recalculate JR_AgentDeclaredSellAmt(3.67/1.5) and deciaml is 0", 2m, charge.JR_AgentDeclaredSellAmt);
		}

