		public void TestGenerateEventLogsOnSaving_JobInactive()
		{
			Action<string[]> assertEvents = expectedValues =>
			{
				TestJob.Factory.Save();
				TestJob.Factory.Save(); //the second save to test we do not add more events for a job that was not changed between savings
				var logs = TestJob.Logs.GetAllLogs();
				var events = logs.Cast<StmALog>().Select(log => log.SL_SE_NKEvent.ToString()).ToArray();
				AssertContainsExactElementsInAnyOrder(expectedValues, events); //for easy test fixing as this is can show the difference in events even if their amount is not the same.
			};

			TestJob.JH_Status = JobHeaderStatus.Working.Code;
			TestJob.Factory.Save();

			var jobNumber = TestJob.JH_JobNum;

			TestJob.MarkAsInactive();

			var expectedEvents = new[]
			{
					Events.BillingJobEdit.Code,
					Events.SetToInactive.Code,
					Events.BillingJobEdit.Code,
					Events.EditedARecord.Code,
					Events.BillingJobEdit.Code,
					Events.StatusUpdated.Code,
					Events.JobOpen.Code,
					Events.AddedARecordToTheSystem.Code,
				};
			assertEvents(expectedEvents);
			Assert(TestJob.Logs.GetAllLogs().Any(x => ((StmALog)x).SL_SE_NKEvent == Events.BillingJobEdit.Code && ((StmALog)x).SL_Reference == "Job marked as Inactive"));

			TestJob.ActivateJob();
			TestJob.JH_JobNum = jobNumber;

			expectedEvents = new[]
			{
					Events.BillingJobEdit.Code,
					Events.SetToInactive.Code,
					Events.BillingJobEdit.Code,
					Events.EditedARecord.Code,
					Events.BillingJobEdit.Code,
					Events.StatusUpdated.Code,
					Events.JobOpen.Code,
					Events.AddedARecordToTheSystem.Code,
					Events.EditedARecord.Code,
					Events.SetToActive.Code,
					Events.BillingJobEdit.Code,
					Events.BillingJobEdit.Code,
					Events.JobOpen.Code,
				};
			assertEvents(expectedEvents);

			Assert(TestJob.Logs.GetAllLogs().Any(x => ((StmALog)x).SL_SE_NKEvent == Events.BillingJobEdit.Code && ((StmALog)x).SL_Reference == "Job marked as Active"));
		}

		public void TestAutoCreatedLogReferenceWhenJobStatusChanged()
		{
			TestJob.Factory.Save();

			TestJob.JH_Status = JobHeaderStatus.CustomsProcessActive.Code;
			TestJob.Factory.Save();
			AssertEquals("Job status changed from WRK to CUS.", TestJob.Logs.AutoCreatedLog.SL_Reference);

			TestJob.JH_Status = JobHeaderStatus.Closed.Code;
			TestJob.Factory.Save();

			var testOrg = Factory.New<OrgHeader>();
			testOrg.OH_Code = "GJESHICPH1";

			var testInvoice = TestObjectCreator.CreateInvoice(typeof(APInvoice));
			testInvoice.AH_OH = testOrg.PK;

			testInvoice.Factory.SetContext(BusinessContext.AllowReopenJobWhenImporting);

			testInvoice.AH_Ledger = "AP";
			testInvoice.AH_TransactionType = "INV";
			testInvoice.AH_TransactionNum = "Tran001";

			TestJob.ReOpenByImport(string.Format(CultureInfo.InvariantCulture, " - {0} {1} {2} ({3})", "AP", "INV", "Tran001", "GJESHICPH1"));
			TestJob.Factory.Save();
			AssertEquals("Job status changed from CLS to WRK - AP INV Tran001 (GJESHICPH1).", TestJob.Logs.AutoCreatedLog.SL_Reference);

			var job = new BusinessObjectFactory().Load<Job>(TestJob.PK);
			job.JH_ProfitLossReasonCode = "ABC";
			job.Factory.Save();
			AssertEquals("Nothing should be recorded because job status didn't change.", ZString.Empty, job.Logs.AutoCreatedLog.SL_Reference);
		}

		public void TestSettingJH_JobNumOnSaving()
		{
			// Arrange
			using (((IDbConnected)Factory).Connection.BeginTransactionWithManager()) // Fails at number fountain otherwise and OnSaving should be in a transaction during production
			{
				var testJob = Factory.NewJobForTesting<Job>();
				testJob.JH_GE = GlbDepartment.CurrentDepartment.PK;
				testJob.JH_GB = GlbBranch.CurrentBranch.PK;

				// Act
				testJob.OnSaving();

				// Assert
				AssertEquals("IsInDatabase", false, testJob.IsInDatabase);
				AssertNull("Parent", testJob.Parent);
				AssertEquals("JH_JobNum", "", testJob.JH_JobNum);

				var expectedError = $@"Job does not have a job number. Job Info:
	PK = {testJob.PK}
	IsInDatabase = False
	IsDeleted = False
	JH_ParentTableCode = 
	JH_ParentID = 00000000-0000-0000-0000-000000000000
Registry Key JobsNumberSequenceCustomisation:
	ElementName:	Sequence Number
	Order:	1
	Code:	
	Length:	8
	Fountain:	Y
	Description:	
Next Fountain Value for GetLocalJobRefNumberGeneratorFountain is:";

				AssertStartsWith("LastMessageReported", expectedError, ErrorReporter.LastMessageReported);

				ErrorReporter.Clear();

				var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
				shipment.JS_UniqueConsignRef = "S00001000";
				testJob.Delete();
				testJob = CreateWithMutex(Factory, shipment);
				testJob.PlugInData = shipment;
				testJob.JH_GE = GlbDepartment.CurrentDepartment.PK;

				testJob.OnSaving();
				AssertEquals("IsInDatabase", false, testJob.IsInDatabase);
				AssertNotNull("Parent", testJob.Parent);
				AssertEquals("JH_JobNum", "S00001000", testJob.JH_JobNum);
				AssertEquals("LastMessageReported", ZString.Empty, ErrorReporter.LastMessageReported);

				ErrorReporter.Clear();
				testJob.FillWithValidTestData();
				Factory.Save();

				testJob.JH_JobNum = "";
				testJob.OnSaving();
				AssertEquals("IsInDatabase", true, testJob.IsInDatabase);
				AssertNotNull("Parent", testJob.Parent);
				AssertEquals("JH_JobNum", "S00001000", testJob.JH_JobNum);
				ErrorReporter.Clear();
			}
		}

