		public void TestCheckForChargesDisplaySequenceDuplicates()
		{
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();

			Charge ch1 = job.Charges.AddNew();
			ch1.JR_DisplaySequence = 1;
			Charge ch2 = job.Charges.AddNew();
			ch2.JR_DisplaySequence = 2;
			Charge ch3 = job.Charges.AddNew();
			AccTransactionLines rEVLine = Factory.New<AccTransactionLines>();
			rEVLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			ch3.JR_AL_ARLine = rEVLine.PK;
			ch3.JR_DisplaySequence = 1;
			Charge ch4 = job.Charges.AddNew();
			ch4.JR_DisplaySequence = 1;
			Charge ch5 = job.Charges.AddNew();
			rEVLine = Factory.New<AccTransactionLines>();
			rEVLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
			ch5.JR_AL_ARLine = rEVLine.PK;
			ch5.JR_DisplaySequence = 3;
			Charge ch6 = job.Charges.AddNew();
			ch6.JR_DisplaySequence = 3;

			Assert("Postcondition: The last added charge must be unposted and must have duplicated number to correctly check that we have validation error after changing JR_DisplaySequence value.",
				!job.Charges[job.Charges.Count - 1].IsRevenuePosted);

			string expectedWarningMessage = "Charges with duplicated sequence values will be displayed in the order that they were entered.";
			AssertHasRowWarning("Charge 1 not posted and should have the warning", ch1, expectedWarningMessage);
			AssertNoRowWarnings("Charge 2 shouldn't have any warnings", ch2);
			AssertNoRowWarnings("Charge 3 shouldn't have any warnings because it is already posted", ch3);
			AssertHasRowWarning("Charge 4 not posted and should have the warning", ch4, expectedWarningMessage);
			AssertNoRowWarnings("Charge 5 shouldn't have any warnings because it is already posted", ch5);
			AssertNoRowWarnings("Charge 6 shouldn't have any warnings because dublications with posted charges is allowed.", ch6);
			AssertEquals("Charges collection should not have any errors", false, job.Charges.HasErrors());
		}

		public void TestCheckForChargesDisplaySequenceDuplicatesDisabledInChargeReloaderContext()
		{
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			Charge ch1, ch2, ch3, ch4, ch5, ch6;

			using (new DisposableAction(() => Factory.SetContext(BusinessContext.ChargeReloader), () => Factory.RemoveContext(BusinessContext.ChargeReloader)))
			{
				ch1 = job.Charges.AddNew();
				ch1.JR_DisplaySequence = 1;
				ch2 = job.Charges.AddNew();
				ch2.JR_DisplaySequence = 2;
				ch3 = job.Charges.AddNew();
				AccTransactionLines rEVLine = Factory.New<AccTransactionLines>();
				rEVLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
				ch3.JR_AL_ARLine = rEVLine.PK;
				ch3.JR_DisplaySequence = 1;
				ch4 = job.Charges.AddNew();
				ch4.JR_DisplaySequence = 1;
				ch5 = job.Charges.AddNew();
				rEVLine = Factory.New<AccTransactionLines>();
				rEVLine.AL_LineType = ZArchitecture.Core.TransactionLineTypes.Revenue;
				ch5.JR_AL_ARLine = rEVLine.PK;
				ch5.JR_DisplaySequence = 3;
				ch6 = job.Charges.AddNew();
				ch6.JR_DisplaySequence = 3;

				Assert("Postcondition: The last added charge must be unposted and must have duplicated number.",
					!job.Charges[job.Charges.Count - 1].IsRevenuePosted);

				AssertNoRowWarnings("Charge 2 shouldn't have any warnings as we have ChargeReloader context", ch1);
				AssertNoRowWarnings("Charge 2 shouldn't have any warnings", ch2);
				AssertNoRowWarnings("Charge 3 shouldn't have any warnings because it is already posted", ch3);
				AssertNoRowWarnings("Charge 2 shouldn't have any warnings as we have ChargeReloader context", ch4);
				AssertNoRowWarnings("Charge 5 shouldn't have any warnings because it is already posted", ch5);
				AssertNoRowWarnings("Charge 6 shouldn't have any warnings because dublications with posted charges is allowed.", ch6);
			}

			ch1.JR_DisplaySequence = 0;
			ch1.JR_DisplaySequence = 1;

			string expectedWarningMessage = "Charges with duplicated sequence values will be displayed in the order that they were entered.";
			AssertHasRowWarning("Charge 1 not posted and should have the warning", ch1, expectedWarningMessage);
			AssertNoRowWarnings("Charge 2 shouldn't have any warnings", ch2);
			AssertNoRowWarnings("Charge 3 shouldn't have any warnings because it is already posted", ch3);
			AssertHasRowWarning("Charge 4 not posted and should have the warning", ch4, expectedWarningMessage);
			AssertNoRowWarnings("Charge 5 shouldn't have any warnings because it is already posted", ch5);
			AssertNoRowWarnings("Charge 6 shouldn't have any warnings because dublications with posted charges is allowed.", ch6);
		}

