		public void TestAddingChargesViaDataRefreshBusShouldNotAffectHasChanges_PlugInGUI()
		{
			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			Factory.SetContext(BusinessContext.InvoicingPlugInGUI);
			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			job.JH_GE = Factory.LoadTop1<GlbDepartment>(new ZQuery(GlbDepartmentSchema.GE_IsActive, true)).PK;
			Factory.Save();
			AssertEquals("Job has no changes", false, job.HasChanges);

			BusinessObjectFactory factory2 = new BusinessObjectFactory();
			CommonShipment shipment2 = factory2.Load<CommonShipment>(shipment.PK);
			Job job2 = new Loader(factory2, shipment2).Load();
			AssertEquals("Job2 has no changes", false, job2.HasChanges);
			AssertEquals("Job has no charges", 0, job.Charges.Count);

			JobCharge charge = job2.Charges.AddNew();
			ZQuery query = new ZQuery(AccChargeCodeSchema.AC_IsActive, true);
			query.AddToFilter(AccChargeCodeSchema.AC_GC, GlbCompany.CurrentCompany.PK);
			charge.JR_AC = Factory.LoadTop1<AccChargeCode>(query).PK;
			AssertEquals("Job2 has changes", true, job2.HasChanges);

			factory2.Save();

			AssertEquals("Job2 has 1 charge", 1, job2.Charges.Count);
			AssertEquals("Job has 1 charge", 1, job.Charges.Count);
			AssertEquals("Job has no changes", false, job.HasChanges);
			AssertEquals("Job2 has no changes", false, job2.HasChanges);
		}

