		public void TestSetDefaultValuesForJobUntilFirstUserChange()
		{
			SetUpRegistry(0, 0, 1, 2);
			GlbBranch newBranch = TestObjectCreator.CreateNewBranch(Factory.Load<GlbCompany>(GlbCompany.CurrentCompany.PK), "NB1");
			GlbBranch newBranch2 = TestObjectCreator.CreateNewBranch(Factory.Load<GlbCompany>(GlbCompany.CurrentCompany.PK), "NB2");
			GlbBranch newBranch3 = TestObjectCreator.CreateNewBranch(Factory.Load<GlbCompany>(GlbCompany.CurrentCompany.PK), "NB3");
			GlbBranch newBranch4 = TestObjectCreator.CreateNewBranch(Factory.Load<GlbCompany>(GlbCompany.CurrentCompany.PK), "NB4");
			OrgHeader localClient = Factory.New<OrgHeader>();
			localClient.OH_Code = "LC1";
			localClient.CompanyData.OB_GB_ControllingBranch = newBranch.PK;
			OrgHeader localClient2 = Factory.New<OrgHeader>();
			localClient2.OH_Code = "LC2";
			localClient2.CompanyData.OB_GB_ControllingBranch = newBranch2.PK;
			OrgHeader overseasClient = Factory.New<OrgHeader>();
			overseasClient.OH_Code = "OC1";
			overseasClient.CompanyData.OB_GB_ControllingBranch = newBranch3.PK;
			OrgHeader overseasClient2 = Factory.New<OrgHeader>();
			overseasClient2.OH_Code = "OC2";
			overseasClient2.CompanyData.OB_GB_ControllingBranch = newBranch4.PK;

			var mockSupporter = new Mock<IJobInvoicingSupporter>();
			mockSupporter.Setup(m => m.IsImport).Returns(true);
			mockSupporter.Setup(m => m.IsExport).Returns(false);
			mockSupporter.Setup(m => m.IsDomestic).Returns(false);
			mockSupporter.Setup(m => m.TransportMode).Returns(Core.Constants.TransportModes.Sea);
			mockSupporter.Setup(m => m.OperationsBranch).Returns(newBranch);
			mockSupporter.Setup(m => m.OverriddenDepartmentPK).Returns(ZGuid.Empty);
			mockSupporter.Setup(m => m.ConsumerType).Returns(JobInvoicingConsumerTypes.Shipment);
			mockSupporter.Setup(m => m.EditSecurityLock).Returns(false);
			mockSupporter.Setup(m => m.Origin).Returns(Factory.LoadFromNaturalKey<RefUNLOCO>(RefUNLOCOSchema.RL_Code, "USLAX"));
			mockSupporter.Setup(m => m.Destination).Returns(Factory.LoadFromNaturalKey<RefUNLOCO>(RefUNLOCOSchema.RL_Code, "AUBNE"));
			mockSupporter.Setup(m => m.ContainerMode).Returns("FCL");
			mockSupporter.Setup(m => m.ConsolType).Returns("NCN");
			mockSupporter.Setup(m => m.OperationalJobRef).Returns(ZString.Empty);
			mockSupporter.Setup(m => m.ValidateOnInvoicingSupporter_JH_OA_LocalChargesAddr(It.IsAny<ZGuid>())).Returns(ZString.Empty);
			mockSupporter.Setup(m => m.ValidateOnInvoicingSupporter_JH_OA_AgentCollectAddr(It.IsAny<ZGuid>())).Returns(ZString.Empty);
			mockSupporter.Setup(m => m.CanCreateInvoicingJob).Returns(true);

			var invoicingMock = new Mock<IJobInvoicingPlugIn>();
			invoicingMock.Setup(m => m.InvoicingSupporter).Returns(mockSupporter.Object);
			invoicingMock.Setup(m => m.Factory).Returns(Factory);
			invoicingMock.Setup(m => m.PK).Returns(ZGuid.NewZGuid());
			invoicingMock.Setup(m => m.IsInDatabase).Returns(true);
			invoicingMock.Setup(m => m.IsDeleted).Returns(false);
			Job job = (Job)new JobHeader.Loader(invoicingMock.Object).TryCreateWithoutMutexForTestOnly();
			AssertEquals("JobHeader.Branch", GlbBranch.CurrentBranch.PK, job.JH_GB);
			AssertEquals("Department should be", "FIS", job.Department.GE_Code);
			AssertEquals("Local Client", ZGuid.Empty, job.LocalChargesPK);
			AssertEquals("Overseas Client", ZGuid.Empty, job.AgentCollectPK);

			Charge charge = job.Charges.AddNew();

			mockSupporter.Setup(m => m.TransportMode).Returns(Core.Constants.TransportModes.Air);
			mockSupporter.Setup(m => m.ContainerMode).Returns("LSE");
			mockSupporter.Setup(m => m.Consignee).Returns(localClient2);
			job.Parent = invoicingMock.Object;
			AssertEquals("JobHeader.Branch", newBranch2.PK, job.JH_GB);
			AssertEquals("Department should be", "FIA", job.Department.GE_Code);
			AssertEquals("Local Client", localClient2.PK, job.LocalChargesPK);
			AssertEquals("Overseas Client", ZGuid.Empty, job.AgentCollectPK);

			mockSupporter.Setup(m => m.TransportMode).Returns(Core.Constants.TransportModes.Sea);
			mockSupporter.Setup(m => m.ContainerMode).Returns("FCL");
			mockSupporter.Setup(m => m.Consignee).Returns(localClient);
			mockSupporter.Setup(m => m.EarliestSendingAgent).Returns(overseasClient);
			job.Parent = invoicingMock.Object;
			AssertEquals("JobHeader.Branch", newBranch.PK, job.JH_GB);
			AssertEquals("Department should be", "FIS", job.Department.GE_Code);
			AssertEquals("Local Client", localClient.PK, job.LocalChargesPK);
			AssertEquals("Overseas Client", overseasClient.PK, job.AgentCollectPK);

			charge.JR_OSCostAmt = 10;
			charge.JR_OSSellAmt = 0;

			mockSupporter.Setup(m => m.TransportMode).Returns(Core.Constants.TransportModes.Air);
			mockSupporter.Setup(m => m.ContainerMode).Returns("LSE");
			mockSupporter.Setup(m => m.Consignee).Returns(localClient2);
			mockSupporter.Setup(m => m.EarliestSendingAgent).Returns(overseasClient2);
			job.Parent = invoicingMock.Object;
			AssertEquals("JobHeader.Branch", newBranch.PK, job.JH_GB);
			AssertEquals("Department should be", "FIS", job.Department.GE_Code);
			AssertEquals("Local Client", localClient.PK, job.LocalChargesPK);
			AssertEquals("Overseas Client", overseasClient.PK, job.AgentCollectPK);

			charge.JR_OSCostAmt = 0;
			charge.JR_OSCostAmt = 10;
			job.Parent = invoicingMock.Object;
			AssertEquals("JobHeader.Branch", newBranch.PK, job.JH_GB);
			AssertEquals("Department should be", "FIS", job.Department.GE_Code);
			AssertEquals("Local Client", localClient.PK, job.LocalChargesPK);
			AssertEquals("Overseas Client", overseasClient.PK, job.AgentCollectPK);

			charge.JR_OSCostAmt = 0;
			charge.JR_OSCostAmt = 0;
			job.Parent = invoicingMock.Object;
			AssertEquals("JobHeader.Branch", newBranch2.PK, job.JH_GB);
			AssertEquals("Department should be", "FIA", job.Department.GE_Code);
			AssertEquals("Local Client", localClient2.PK, job.LocalChargesPK);
			AssertEquals("Overseas Client", overseasClient2.PK, job.AgentCollectPK);

			job.LocalChargesPK = ZGuid.Empty;
			job.JH_GB = ZGuid.Empty;
