		public void TestSetDefaultValuesForJobUntilFirstUserChange_SalesRep()
		{
			InvoicingParam plugInData = new InvoicingParam();

			OrgHeader org = Factory.New<OrgHeader>();
			org.OH_Code = "OH1";
			org.Addresses.AddNew(OrgAddressType.Office, true);

			GlbStaff staffARA = Factory.New<GlbStaff>();
			staffARA.GS_Code = "ARA";

			GlbStaff staffARB = Factory.New<GlbStaff>();
			staffARB.GS_Code = "ARB";

			Job job = Factory.NewJobForTesting<Job>();

			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fOrigin = null;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fIsImport = true;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).consumerType = JobInvoicingConsumerTypes.Shipment;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fTransportMode = Core.Constants.TransportModes.Air;
			((InvoicingParamJobInvoicingSupporter)plugInData.InvoicingSupporter).fConsignee = org;

			job.PlugInData = plugInData;

			AssertEquals("Sales Rep should be Empty", ZString.Empty, job.JH_GS_NKRepSales);

			org.StaffAssignments.ImportAirRep = staffARA.GS_Code;
			org.StaffAssignments.ImportSeaRep = "ISR";
			org.StaffAssignments.WarehousingRep = "WHR";
			org.StaffAssignments.OverallSalesRep = "OVR";
			org.CompanyData.OB_GB_ControllingBranch = Factory.New<GlbBranch>().PK;

			job.PlugInData = plugInData;
			AssertEquals("Sales Rep must be Import Air Sales Rep from Local Charges Organization", staffARA.GS_Code, job.JH_GS_NKRepSales);

			org.StaffAssignments.ImportAirRep = staffARB.GS_Code;
			job.PlugInData = plugInData;
			AssertEquals("Sales Rep must be update to another Import Air Sales Rep", staffARB.GS_Code, job.JH_GS_NKRepSales);

			org.StaffAssignments.ImportAirRep = staffARA.GS_Code;
			job.JH_GS_NKRepSales = ZString.Empty;
			job.JH_GS_NKRepSales = staffARA.GS_Code;
			AssertEquals("Sales Rep is updated to the first Import Air Sales Rep around SetDefaultValues", staffARA.GS_Code, job.JH_GS_NKRepSales);

			org.StaffAssignments.ImportAirRep = staffARB.GS_Code;
			job.PlugInData = plugInData;
			AssertEquals("Sales Rep must not be update after setting it around SetDefaultValues", staffARA.GS_Code, job.JH_GS_NKRepSales);
		}

