		public void TestJH_ProfitRevenueMargin()
		{
			Charge testCharge1 = TestJob.Charges.AddNew();
			testCharge1.JR_AC = Margin100Code.PK;
			testCharge1.JR_LocalSellAmt = 20;
			testCharge1.JR_LocalCostAmt = 20;

			Charge testCharge2 = TestJob.Charges.AddNew();
			testCharge2.JR_AC = Margin60Code.PK;
			testCharge2.JR_LocalSellAmt = 140;
			testCharge2.JR_LocalCostAmt = 130;

			AssertEquals(6.25m, TestJob.JH_ProfitRevenueMargin);

			testCharge1.JR_OSSellAmt = 0m;
			testCharge2.JR_OSSellAmt = 0m;

			AssertEquals(0m, TestJob.JH_TotalRevenue);
			Assert(TestJob.JH_TotalCost != 0m);
			AssertEquals(0m, TestJob.JH_ProfitRevenueMargin);
		}

		public void TestJH_ProfitRevenueMarginWithDSBCharge()
		{
			var testCharge1 = TestJob.Charges.AddNew();
			testCharge1.JR_ChargeType = Core.Constants.ChargeType.Disbursement;
			testCharge1.JR_AC = Margin100Code.PK;
			testCharge1.JR_LocalSellAmt = 20;
			testCharge1.JR_LocalCostAmt = 20;

			var testCharge2 = TestJob.Charges.AddNew();
			testCharge2.JR_AC = Margin60Code.PK;
			testCharge2.JR_LocalSellAmt = 140;
			testCharge2.JR_LocalCostAmt = 130;

			AccountingConfigurationRegistry.Instance.IncludeDisbursementsPercentageMarginCalculations.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AssertEquals("DSB Charge (testCharge1) should be included (140+20-130-20)/(140+20) = 6.25", 6.25m, TestJob.JH_ProfitRevenueMargin);

			AccountingConfigurationRegistry.Instance.IncludeDisbursementsPercentageMarginCalculations.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			AssertEquals("DSB Charge (testCharge1) should not be included (140-130)/(140) = 7.14m", 7.14m, TestJob.JH_ProfitRevenueMargin);
		}

		public void TestJH_ProfitRevenueMarginPosted()
		{
			Charge testCharge1 = TestJob.Charges.AddNew();
			testCharge1.JR_AC = Margin100Code.PK;
			testCharge1.JR_LocalSellAmt = 20;
			testCharge1.JR_LocalCostAmt = 20;
			testCharge1.JR_AL_ARLine = Factory.New<ARInvoiceLine>().PK;

			Charge testCharge2 = TestJob.Charges.AddNew();
			testCharge2.JR_AC = Margin60Code.PK;
			testCharge2.JR_LocalSellAmt = 140;
			testCharge2.JR_LocalCostAmt = 130;
			testCharge2.JR_AL_APLine = Factory.New<APInvoiceLine>().PK;

			AssertEquals("JH_ProfitRevenueMargin", 6.25m, TestJob.JH_ProfitRevenueMargin);
			AssertEquals("JH_ProfitRevenueMarginPosted", -550.0m, TestJob.JH_ProfitRevenueMarginPosted);

			var testCharge3 = TestJob.Charges.AddNew();
			testCharge3.JR_ChargeType = Core.Constants.ChargeType.Disbursement;
			testCharge3.JR_AC = Margin60Code.PK;
			testCharge3.JR_LocalSellAmt = 20;
			testCharge3.JR_LocalCostAmt = 20;
			testCharge3.JR_AL_APLine = Factory.New<APInvoiceLine>().PK;
			testCharge3.JR_AL_ARLine = Factory.New<ARInvoiceLine>().PK;

			try
			{
				AccountingConfigurationRegistry.Instance.IncludeDisbursementsPercentageMarginCalculations.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
				AssertEquals("JH_ProfitRevenueMarginPosted", -275.00m, TestJob.JH_ProfitRevenueMarginPosted);
				AccountingConfigurationRegistry.Instance.IncludeDisbursementsPercentageMarginCalculations.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
				AssertEquals("JH_ProfitRevenueMarginPosted", -550.0m, TestJob.JH_ProfitRevenueMarginPosted);
			}
			finally
			{
				AccountingConfigurationRegistry.Instance.IncludeDisbursementsPercentageMarginCalculations.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
			}
		}

