		public void TestUnspecifiedRatesPullThroughToAgentRateBasedOnRegistrySetting_Cost()
		{
			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			Factory.Save();

			TestJob.LocalChargesPK = TestObjectCreator.LocalClient.PK;
			TestObjectCreator.Job1.PlugInData = shipment;
			TestJob.JH_GE = TestObjectCreator.FIADepartment.PK;
			AccChargeCode fRT = Factory.Load<AccChargeCode>(Env.Registry.FreightChargeCode);
			fRT.AC_DepartmentFilterList = "ALL";
			fRT.AC_GC = GlbCompany.CurrentCompany.PK;

			var rates = new AutoRateInfoCollection(Factory);
			AutoRateInfo rate1 = rates.AddNew(fRT, GlbCompany.CurrentCompany.GC_RX_NKLocalCurrency, 100);
			var interactor = new LoggerDecorator();
			var strategy = new AutoRateInvoicingStrategy(shipment, TestJob);
			var operationalJobCodes = new[] { shipment.RatingAdapter.OperationalJobCode };

			RatingDataRegistry.Instance.UnspecifiedCostShouldForceZeroToBePulledThrough.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, false);
			TestJob.Charges.RemoveAndDeleteAll();
			strategy.AddAutoRates(interactor, rates, CostSell.Cost, operationalJobCodes);
			AssertEquals("When no explicit agent cost rate given, and registry is set to not force zero, should see agent cost amount is NOT zero", 100m, TestJob.Charges[0].JR_AgentDeclaredCostAmt);

			RatingDataRegistry.Instance.UnspecifiedCostShouldForceZeroToBePulledThrough.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);
			TestJob.Charges.RemoveAndDeleteAll();
			strategy.AddAutoRates(interactor, rates, CostSell.Cost, operationalJobCodes);
			AssertEquals("When no explicit agent cost rate given, and registry is set to force zero, should see agent sell amount is zero", 0m, TestJob.Charges[0].JR_AgentDeclaredCostAmt);

			rate1.AddAgentFlatPaymentBasis(800, operationalJobCodes[0]);

			RatingDataRegistry.Instance.UnspecifiedCostShouldForceZeroToBePulledThrough.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, false);
			TestJob.Charges.RemoveAndDeleteAll();
			strategy.AddAutoRates(interactor, rates, CostSell.Cost, operationalJobCodes);
			AssertEquals("When agent cost rate is given, should see agent cost amount is NOT zero, regardless of registry", 800m, TestJob.Charges[0].JR_AgentDeclaredCostAmt);

			RatingDataRegistry.Instance.UnspecifiedCostShouldForceZeroToBePulledThrough.SetValue(Env.CurrentCompanyPK, Guid.Empty, Guid.Empty, true);
			TestJob.Charges.RemoveAndDeleteAll();
			strategy.AddAutoRates(interactor, rates, CostSell.Cost, operationalJobCodes);
			AssertEquals("When agent cost rate is given, should see agent cost amount is NOT zero, regardless of registry", 800m, TestJob.Charges[0].JR_AgentDeclaredCostAmt);
		}

