		#region TestIncludeInThePeriodicInvoice

		public void TestIncludeInThePeriodicInvoiceRaiseCollectionEvent()
		{
			bool isIncludeInThePeriodicInvoiceChangedRaised;

			Factory.Save();
			PeriodicInvoiceSelectableJobCollection collection = new PeriodicInvoiceSelectableJobCollection(Factory);
			collection.Add(TestJob);
			var selectableJob = collection[0];
			AssertEquals("Selectable job is for added job", TestJob, selectableJob.Parent);

			collection.IncludeInThePeriodicInvoiceChanged += delegate
			{ isIncludeInThePeriodicInvoiceChangedRaised = true; };

			Assert("Precondition: IncludeInThePeriodicInvoice should be True after adding in a PeriodicInvoiceJobCollection.", selectableJob.IncludeInThePeriodicInvoice);

			isIncludeInThePeriodicInvoiceChangedRaised = false;
			selectableJob.IncludeInThePeriodicInvoice = false;
			Assert("OnIncludingInThePeriodicInvoiceChanged event shuld be raised.", isIncludeInThePeriodicInvoiceChangedRaised);

			isIncludeInThePeriodicInvoiceChangedRaised = false;
			selectableJob.IncludeInThePeriodicInvoice = true;
			Assert("OnIncludingInThePeriodicInvoiceChanged event shuld be raised.", isIncludeInThePeriodicInvoiceChangedRaised);

			isIncludeInThePeriodicInvoiceChangedRaised = false;
			selectableJob.IncludeInThePeriodicInvoice = true;
			Assert("OnIncludingInThePeriodicInvoiceChanged event shuld not be raised if value is not changed.", !isIncludeInThePeriodicInvoiceChangedRaised);
		}

