		public void TestChildJobPKs()
		{
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			Job childJob1 = Factory.NewJobWithValidTestDataForTesting<Job>();
			Job childJob2 = Factory.NewJobWithValidTestDataForTesting<Job>();
			childJob1.JH_JH_ParentJob = job.PK;
			childJob2.JH_JH_ParentJob = job.PK;

			var childJobs = job.ChildJobPKs;
			Assert("ChildJobs contains childJob1", childJobs.Contains(childJob1.PK));
			Assert("ChildJobs contains childJob2", childJobs.Contains(childJob2.PK));

			Factory.Save();
			childJobs = job.ChildJobPKs;
			Assert("ChildJobs contains childJob1", childJobs.Contains(childJob1.PK));
			Assert("ChildJobs contains childJob2", childJobs.Contains(childJob2.PK));

			Job childJob3 = Factory.NewJobWithValidTestDataForTesting<Job>();
			childJob3.JH_JH_ParentJob = job.PK;
			childJobs = job.ChildJobPKs;
			Assert("ChildJobs contains childJob1", childJobs.Contains(childJob1.PK));
			Assert("ChildJobs contains childJob2", childJobs.Contains(childJob2.PK));
			Assert("ChildJobs contains childJob3", childJobs.Contains(childJob3.PK));
		}

		public void TestDeleteRelatedDataWhenJobIsAlreadyDeactivated()
		{
			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.ExchangeRates.AddNew();
			AssertEquals(1, job.ExchangeRates.Count);
			Factory.Save();
			job.MarkAsInactive();
			AssertEquals("Expect exchange rates are cleared on the 1st delete.", 0, job.ExchangeRates.Count);
			job.ExchangeRates.AddNew();
			AssertEquals(1, job.ExchangeRates.Count);
			job.MarkAsInactive();
			AssertEquals("Expect no change made because delete logic should not run for job which has been deleted.", 1, job.ExchangeRates.Count);
		}

		public void TestReopenThenCloseJobWillNotCreateJobChargeRevRecognitionOfTypeJCLAgain()
		{
			bool isAllowed = Env.Security.ReopenJob.IsAllowed;
			try
			{
				Env.Security.ReopenJob.IsAllowed = true;

				ZQuery duplicationsFilter = new ZQuery(JobChargeRevRecognitionSchema.D3_JH, TestJob.PK);
				duplicationsFilter.AddToFilter(JobChargeRevRecognitionSchema.D3_RecognitionType, "JCL");
				JobChargeRevRecognition[] revRecognitions = Factory.Load<JobChargeRevRecognition>(duplicationsFilter);
				AssertEquals("Precondition: should have 0 JobChargeRevRecognition", 0, revRecognitions.Length);

				TestJob.JH_JobNum = TestObjectCreator.GetRandomString(8);
				JobChargeRevRecognition jobChargeRevRecognition = TestObjectCreator.CreateJobChargeRevRecognition(TestJob, RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, ZDateTime.Today);
				Charge charge = TestJob.Charges.AddNew();
				charge.FillWithValidTestData();
				Factory.Save();

				TestJob.JH_Status = JobHeaderStatus.Closed.Code;
				Factory.Save();

				revRecognitions = Factory.Load<JobChargeRevRecognition>(duplicationsFilter);
				AssertEquals("should create a new JobChargeRevRecognition of type JCL", 1, revRecognitions.Length);

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				Job job = newFactory.Load<Job>(TestJob.PK);
				job.JH_Status = JobHeaderStatus.Working.Code;
				newFactory.Save();

				Job job2 = newFactory.Load<Job>(TestJob.PK);
				job2.JH_Status = JobHeaderStatus.Closed.Code;

				revRecognitions = newFactory.Load<JobChargeRevRecognition>(duplicationsFilter);
				AssertEquals("Should NOT create new JobChargeRevRecognition of type JCL as it already exists for this Job", 1, revRecognitions.Length);
			}
			finally
			{
				Env.Security.ReopenJob.IsAllowed = isAllowed;
			}
		}

		public void TestReopeningJobSendsOnlyOneEmail()
		{
			bool isAllowed = Env.Security.ReopenJob.IsAllowed;
			try
			{
				GlbStaff testStaff = Factory.NewWithValidTestData<GlbStaff>();
				testStaff.GS_EmailAddress = "test@test.com";

				GlbGroup testGroup = Factory.NewWithValidTestData<GlbGroup>();
				testGroup.Staff.Add(testStaff);

				var branchPk = TestJob.Branch.PK;

				Env.Security.ReopenJob.IsAllowed = true;
				AccountingConfigurationRegistry.Instance.JobReopenNotifyGroup.SetValue(Guid.Empty, branchPk.ToGuid(), Guid.Empty, testGroup.PK.ToGuid());

				TestJob.JH_Status = JobHeaderStatus.Closed.Code;
				Factory.Save();

				Env.OutgoingMailManager.EmailsCreated.Clear();
				AssertEquals("0 Email should be created", 0, Env.OutgoingMailManager.EmailsCreated.Count);

				BusinessObjectFactory newFactory = new BusinessObjectFactory();
				Job job = newFactory.Load<Job>(TestJob.PK);
				var job3 = newFactory.Load<InvoicingBaseBulkChargeImporterDependentJob>(TestJob.PK);
				Assert("Precondition: another job instance around the row should be created.", job3.GetType().IsSubclassOf(typeof(Job)));
				job.JH_Status = JobHeaderStatus.Working.Code;
				newFactory.Save();
				AssertEquals("1 Email should be created", 1, Env.OutgoingMailManager.EmailsCreated.Count);
			}
			finally
			{
				Env.Security.ReopenJob.IsAllowed = isAllowed;
			}
		}

