		{
			var postDate = ZDateTime.Today.AddDays(-2);

			var shipment = TestObjectCreator.CreateShipment("S001001");
			var job = TestObjectCreator.CreateJob(shipment, false, false);

			var periodManagement = Factory.NewWithValidTestData<AccPeriodManagement>();
			periodManagement.AM_StartDate = ZDateTime.Today.AddDays(-5);
			periodManagement.AM_EndDate = ZDateTime.Today.AddDays(5);
			periodManagement.AM_GC_Company = job.Company.PK;

			JobCharge jobCharge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.FRT, "test charge1", TestObjectCreator.AUD, 120M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 120M, TestObjectCreator.ABIGAS);

			Factory.Save();

			job.Charges.Load();

			InvoicingPostManager postManager = new InvoicingPostManager(job);
			TransactionHeader[] invoicelist = postManager.CreateTransactions(JobInvoicingPostingOption.Revenue).GetAllARTransactions();
