		[TestDate(2015, 03, 20)]
		public void TestRecogniseRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture_JobOpenDate()
		{
			const int jobUpdateFAR_Offset = 5;
			const string recognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

			TestObjectCreator.CreateTestPeriods(new ZDateTime(ZDateTime.Now.Year, 01, 01));
			TestObjectCreator.CC1.RevenueRecOverrides.RemoveAndDeleteAll();
			Factory.Save();

			var valuesForTest = new RevenueRecognitionCollection();
			var setting1 = valuesForTest.AddNew();
			setting1.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting1.RecognitionDateOptionCode = recognitionDateOptionCode;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false))
			{
				AssertJobOpenDateCase("S0A01", ZDateTime.Today.AddDays(10), ZDateTime.Today.AddDays(10));
				AssertJobOpenDateCase("S0A02", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2));
				AssertJobOpenDateCaseUpdateToFAR("S0C01", ZDateTime.Today, ZDateTime.Today.AddDays(10), ZDateTime.Today.AddDays(10), ZDateTime.Today.AddDays(jobUpdateFAR_Offset));
				AssertJobOpenDateCaseUpdateToFAR("S0C02", ZDateTime.Today, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(jobUpdateFAR_Offset));
			}

			using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
			{
				AssertJobOpenDateCase("S0A11", ZDateTime.Today.AddDays(10), ZDateTime.Now);
				AssertJobOpenDateCase("S0A12", ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2));
				AssertJobOpenDateCaseUpdateToFAR("S0C11", ZDateTime.Today, ZDateTime.Today.AddDays(10), ZDateTime.Now, ZDateTime.Now);
				AssertJobOpenDateCaseUpdateToFAR("S0C12", ZDateTime.Today.AddDays(-1).AddDays(jobUpdateFAR_Offset * -1), ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(-1));
			}

			void AssertJobOpenDateCase(string shipmentNum, ZDateTime jobOpenDate, ZDateTime expectedRecognitionDate)
			{
				var newFactory = new BusinessObjectFactory();
				var testObjectCreator = new TestObjectCreator(newFactory);
				var shipment = testObjectCreator.CreateShipment(shipmentNum);
				var job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				job.JH_A_JOP = jobOpenDate;

				AssertInvoiceJobRevenueRecognitionDateInSameJob("Revenue Recognition Date should be filled.", 1, testObjectCreator, job, jobOpenDate.AddDays(-5), expectedRecognitionDate, recognitionDateOptionCode);

				using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
				{
					AssertInvoiceJobRevenueRecognitionDateInSameJob("Same Recognition Type will use first Recognition Date although the registry is on", 2, testObjectCreator, job, jobOpenDate.AddDays(-5), expectedRecognitionDate, recognitionDateOptionCode);
				}
			}

			void AssertJobOpenDateCaseUpdateToFAR(string shipmentNum, ZDateTime linePostDate, ZDateTime jobOpenDate, ZDateTime expectedRecognitionDate, ZDateTime expectedDateFAR)
			{
				var newFactory = new BusinessObjectFactory();
				var testObjectCreator = new TestObjectCreator(newFactory);
				var shipment = testObjectCreator.CreateShipment(shipmentNum);
				var job = new Loader(shipment).TryLoadOrCreateWithoutMutexForTestOnly();
				job.JH_A_JOP = jobOpenDate;
				job.RecognitionDateOffset_NeedToUpdateFAR_ForTestOnly = jobUpdateFAR_Offset;

				AssertInvoiceJobRevenueRecognitionDateInSameJob("Revenue Recognition Date should be filled.", 1, testObjectCreator, job, linePostDate, expectedRecognitionDate, recognitionDateOptionCode, true);

				using (AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true))
				{
					AssertInvoiceJobRevenueRecognitionDateInSameJob("FAR date had recognized by last updating , it will apply same date", 2, testObjectCreator, job, linePostDate.AddDays(-3), expectedDateFAR, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
					AssertInvoiceJobRevenueRecognitionDateInSameJob("FAR date had recognized by last updating , it will apply same date", 2, testObjectCreator, job, linePostDate.AddDays(3), expectedDateFAR, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
				}
			}
		}

