		[TestDate(2015, 03, 20)]
		public void TestRecogniseRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture_EnableDeferredRevenueRecognition()
		{
			const string recognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.EstimatedArrivalDate;

			AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

