			TestObjectCreator.CC1.RevenueRecOverrides.RemoveAndDeleteAll();
			Factory.Save();

			var valuesForTest = new RevenueRecognitionCollection();
			var setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.Mode = RevenueRecognitionLookups.ModeAdditionalCodes.All;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.RecognitionDateOptionCode = recognitionDateOptionCode;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			var shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_E_ARV = ZDateTime.Today.AddMonths(1);

			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_A_JOP = ZDateTime.Now.AddDays(-2);

			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			Factory.Save();

			var invoiceAR = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M);
			invoiceAR.AH_PostDate = ZDateTime.Now.AddDays(-1);
			invoiceAR.AH_FullyPaidDate = ZDateTime.Empty;

			var lineAR = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineAR.AL_JH = job.PK;
			lineAR.AL_RevRecognitionType = recognitionDateOptionCode;

			charge.JR_AL_ARLine = lineAR.PK;
			Factory.Save();

			AssertEquals(ZDateTime.Empty, lineAR.AL_ReverseDate);
			foreach (CodeDescriptionPair status in new JobHeaderStatusList())
			{
				job.JH_Status = status.Code;
				Factory.Save();

				if (job.JH_Status == JobHeaderStatus.Complete.Code)
				{
					AssertEquals(ZDateTime.Today.Date, lineAR.AL_ReverseDate.Date);
				}
			}
		}

		void AssertInvoiceJobRevenueRecognitionDateInSameJob(string comment, int seq, TestObjectCreator testObjectCreator, Job job, ZDateTime linePostDate, ZDateTime expectedDate, string revRecognitionType, bool needToUpdateFAR = false)
		{
			var invoice = testObjectCreator.CreateInvoice(typeof(ARInvoice));
			invoice.AH_TransactionNum = $"{job.JH_JobNum}_INV{seq}";
			invoice.AH_Desc = "Changed Desc";
			invoice.AH_JH = job.PK;

			var aRTransactionLine = invoice.Lines.AddNew() as InvoicingLineBase;
			aRTransactionLine.AL_LineType = TransactionLineTypes.Revenue;
			aRTransactionLine.AL_JH = job.PK;
			aRTransactionLine.AL_AC = testObjectCreator.CC1.PK;
			aRTransactionLine.AL_PostDate = linePostDate;
			testObjectCreator.CreateJobCharge(aRTransactionLine, job, testObjectCreator.CC1, testObjectCreator.AUD);

			AssertEquals("Prerequisite: AL_ReverseDate on APTransactionLine should be empty", ZDateTime.Empty, aRTransactionLine.AL_ReverseDate);
			aRTransactionLine.AL_RevRecognitionType = revRecognitionType;

			if (needToUpdateFAR)
			{
				var apInvoice = testObjectCreator.CreateInvoice(typeof(APInvoice));
				apInvoice.AH_TransactionNum = $"{job.JH_JobNum}_INV{seq}";
				apInvoice.AH_Desc = "Changed Desc";
				apInvoice.AH_JH = job.PK;

				var aPTransactionLine = apInvoice.Lines.AddNew() as InvoicingLineBase;
				aPTransactionLine.AL_LineType = TransactionLineTypes.Cost;
				aPTransactionLine.AL_JH = job.PK;
				aPTransactionLine.AL_AC = testObjectCreator.CC1.PK;
				aPTransactionLine.AL_PostDate = linePostDate;
				aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

				var charge = job.Charges.AddNew();
				charge.JR_AL_APLine = aPTransactionLine.PK;
			}

			job.ClearCacheOfContainsFARCharge_ForTestsOnly(job.PK);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			job.ApplyRevenueRecognitionDate(aRTransactionLine);
			AssertEquals(comment, expectedDate.Date, job.GetRevenueRecognitionDate_ForTestOnly(revRecognitionType).Date);
		}

		public void TestSettingRevenueRecognitionDateUpdatesAL_ReverseDateOnAllRelatedTransactionLinesAndDoesntChangeOnceSet()
		{
			ZDateTime expectedPostDate = ZDateTime.Now.AddDays(10);
			TestJob.JH_JobNum = TestObjectCreator.GetRandomString(8);

			var charge = TestJob.Charges.AddNew();
			charge.FillWithValidTestData();
			charge.JR_OH_CostAccount = ZGuid.Empty;
			charge.JR_OH_SellAccount = ZGuid.Empty;

			ARInvoiceLine aRTransactionLine = Factory.NewWithValidTestData<ARInvoiceLine>();
			aRTransactionLine.AL_LineType = TransactionLineTypes.Revenue;
			aRTransactionLine.AL_JH = TestJob.PK;
			aRTransactionLine.AL_PostDate = expectedPostDate;
			aRTransactionLine.AL_AH = Factory.NewWithValidTestData<ARInvoice>().PK;
			aRTransactionLine.AL_AC = charge.JR_AC;
			TestObjectCreator.CreateJobCharge(aRTransactionLine, TestJob, TestObjectCreator.CC1, TestObjectCreator.AUD);

			APInvoiceLine aPTransactionLine = Factory.NewWithValidTestData<APInvoiceLine>();
			aPTransactionLine.AL_LineType = TransactionLineTypes.Cost;
			aPTransactionLine.AL_JH = TestJob.PK;
			aPTransactionLine.AL_PostDate = expectedPostDate;
			aPTransactionLine.AL_AH = Factory.NewWithValidTestData<APInvoice>().PK;
			aPTransactionLine.AL_AC = charge.JR_AC;
			TestObjectCreator.CreateJobCharge(aPTransactionLine, TestJob, TestObjectCreator.CC1, TestObjectCreator.AUD);

			Accrual acrTransactionLine = Factory.NewWithValidTestData<Accrual>();
			acrTransactionLine.AL_LineType = TransactionLineTypes.Accrual;
			acrTransactionLine.AL_JH = TestJob.PK;
			acrTransactionLine.AL_PostDate = expectedPostDate;
			acrTransactionLine.AL_AC = charge.JR_AC;
			acrTransactionLine.AL_OH = charge.JR_OH_CostAccount;
			WIP wIPTransactionLine = Factory.NewWithValidTestData<WIP>();
			wIPTransactionLine.AL_LineType = TransactionLineTypes.WIP;
			wIPTransactionLine.AL_JH = TestJob.PK;
			wIPTransactionLine.AL_PostDate = expectedPostDate;
			wIPTransactionLine.AL_AC = charge.JR_AC;
			wIPTransactionLine.AL_OH = charge.JR_OH_SellAccount;
			charge.JR_AL_APLine = acrTransactionLine.PK;
			charge.JR_AL_ARLine = wIPTransactionLine.PK;
			Factory.Save();

			AssertEquals("Prerequisite: AL_ReverseDate on ARTransactionLine should be empty", ZDateTime.Empty, aRTransactionLine.AL_ReverseDate);
			AssertEquals("Prerequisite: AL_ReverseDate on APTransactionLine should be empty", ZDateTime.Empty, aPTransactionLine.AL_ReverseDate);
			AssertEquals("Prerequisite: AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("Prerequisite: AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			aRTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			acrTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			wIPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

			TestJob.JH_A_JOP = ZDateTime.BrettsBirthday;
			TestJob.ApplyRevenueRecognitionDate(aPTransactionLine);

			AssertEquals("RevenueRecognitionDate", ZDateTime.BrettsBirthday, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));
			AssertEquals("AL_ReverseDate on ARTransactionLine should be empty because no periods now", ZDateTime.Empty, aRTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on APTransactionLine should be empty because no periods now", ZDateTime.Empty, aPTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);

			aRTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			acrTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			wIPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aRTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			acrTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			wIPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			TestJob.RevenueRecognitionCollection[0].D3_JH = ZGuid.NewZGuid();
			JobChargeRevRecognition jobChargeRevRecognition = TestObjectCreator.CreateJobChargeRevRecognition(TestJob, RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob, AccountingConstants.RevenueRecognitionDateConstants.JobClosure);
			TestJob.ApplyRevenueRecognitionDate(aPTransactionLine);

			AssertEquals("RevenueRecognitionDate", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));
			AssertEquals("AL_ReverseDate on ARTransactionLine should now be empty", ZDateTime.Empty, aRTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on APTransactionLine should now be empty", ZDateTime.Empty, aPTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);

			aRTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			acrTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			wIPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aRTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			acrTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			wIPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			jobChargeRevRecognition.D3_JH = ZGuid.NewZGuid();
			TestJob.JH_A_JOP = ZDateTime.Now;
			TestJob.ApplyRevenueRecognitionDate(aPTransactionLine);

			AssertEquals("RevenueRecognitionDate shouldn't change", ZDateTime.Now.Date, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)).Date);
			AssertEquals("AL_ReverseDate on ARTransactionLine should still be equal to RevenueRecognitionDate", TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)), aRTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on APTransactionLine should still be equal to RevenueRecognitionDate", TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)), aPTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);

			aRTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			acrTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			wIPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aRTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			acrTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			wIPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			aRTransactionLine.AL_ReverseDate = ZDateTime.BrettsBirthday;
			TestJob.Close(null, null);

			AssertEquals("Precondition:", ZDateTime.Now.Date, TestJob.JH_A_JCL.Date);
			AssertEquals("RevenueRecognitionDate shouldn't change", TestJob.JH_A_JCL.Date, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)).Date);
			AssertEquals("AL_ReverseDate on ARTransactionLine should still be not changed", ZDateTime.BrettsBirthday, aRTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on APTransactionLine should still be equal to RevenueRecognitionDate", TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)), aPTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);

			aRTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			acrTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			wIPTransactionLine.AL_ReverseDate = ZDateTime.Empty;
			aRTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			aPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			acrTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			wIPTransactionLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			TestJob.RevenueRecognitionCollection[0].D3_JH = ZGuid.NewZGuid();
			ZDateTime expectedActualArrivalDate = ZDateTime.Today.AddMonths(4);
			TestObjectCreator.CreateJobChargeRevRecognition(TestJob, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, expectedActualArrivalDate);
			TestJob.JH_A_JOP = ZDateTime.MinSmallDateTimeValue.AddYears(10);
			TestJob.ReOpen();
			TestJob.ApplyRevenueRecognitionDate(aPTransactionLine);

			AssertEquals("RevenueRecognitionDate shouldn't change", ZDateTime.MinSmallDateTimeValue.AddYears(10), TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));
			AssertEquals("AL_ReverseDate on ARTransactionLine should still be equal to ActualArrivalDate", expectedActualArrivalDate, aRTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on APTransactionLine should still be empty because JH_A_JOP out of periods.", ZDateTime.Empty, aPTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on AcrTransactionLine should be empty", ZDateTime.Empty, acrTransactionLine.AL_ReverseDate);
			AssertEquals("AL_ReverseDate on WIPTransactionLine should be empty", ZDateTime.Empty, wIPTransactionLine.AL_ReverseDate);
		}

		[TestDate(2005, 05, 20)]
		public void TestSettingRevenueRecognitionDateWithOffset()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			setting1.Offset = 10;
			setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			ZDateTime expectedEndPeriod = new ZDateTime(2005, 07, 25);

			AccountingPeriodTestHelper periodHelper = new AccountingPeriodTestHelper(Factory);
			periodHelper.SetupSinglePeriod(1001, new ZDateTime(2005, 04, 25), new ZDateTime(2005, 05, 25));
			periodHelper.SetupSinglePeriod(2001, new ZDateTime(2005, 05, 25), new ZDateTime(2005, 06, 25));
			periodHelper.SetupSinglePeriod(3001, new ZDateTime(2005, 06, 25), expectedEndPeriod);

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				AssertEquals("Job RevenueRecognitionDate with 10 days offset", ZDateTime.Now.Date.AddDays(10), testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

				setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				AssertEquals("Calculated Job RevenueRecognitionDate without offset", ZDateTime.MinSmallDateTimeValue, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
				AssertEquals("Stored Job Revenue Recognition Date", ZDateTime.Empty, testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				AssertEquals("Calculated Job RevenueRecognitionDate without offset", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
				AssertEquals("Stored Job RevenueRecognitionDate", ZDateTime.Empty, testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				testJob.Charges.AddNew();
				testJob.Close(null, null);
				AssertEquals("Calculated Job RevenueRecognitionDate without offset", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
				AssertEquals("Stored Job RevenueRecognitionDate with 10 days offset", testJob.JH_A_JCL.AddDays(10), testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));
				testJob.Charges.RemoveAndDeleteAll();

				setting1.Offset = 2;
				setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Periods;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				testJob.Charges.AddNew();
				testJob.Close(null, null);
				AssertEquals("Stored Job RevenueRecognitionDate with 2 periods offset", expectedEndPeriod, testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				Charge charge = testJob.Charges.AddNew();
				charge.JR_AC = TestObjectCreator.CC1.PK;
				charge.JR_OSCostAmt = charge.JR_OSSellAmt = 10M;
				AssertEquals("Calculated Job RevenueRecognitionDate with 2 periods offset", expectedEndPeriod, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
				testJob.ApplyRevenueRecognitionDate(charge);
				AssertEquals("Stored Job RevenueRecognitionDate with 2 periods offset.", expectedEndPeriod,
					 testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				setting1.Offset = 3;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				Charge charge = charge = testJob.Charges.AddNew();
				charge.JR_AC = TestObjectCreator.CC1.PK;
				charge.JR_OSCostAmt = charge.JR_OSSellAmt = 10M;
				AssertEquals("Calculated Job RevenueRecognitionDate with 3 periods offset is set Max DateTime value for validation purposes.",
					 DateTime.MaxValue, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
				testJob.ApplyRevenueRecognitionDate(charge);
				AssertEquals("Before saving Job with incorrect Revenue Recognition its value should be reseted.", ZDateTime.Empty,
					 testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
				setting1.Offset = 10;
				setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

				testJob.JH_Status = JobHeaderStatus.WorkOnHold.Code;
				testJob.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals(ZDateTime.Today, testJob.JH_A_JCL.Date);
				AssertEquals("GetRevenueRecognitionDate(TestObjectCreator.CC1) should be set from Close Date + Days Offset", ZDateTime.Now.Date.AddDays(10), testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)).Date);

				setting1.Offset = 2;
				setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Periods;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			}

			using (Job testJob = TestObjectCreator.CreateJob(Factory.New<ForwardingShipment>()))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				Charge charge = charge = testJob.Charges.AddNew();
				testJob.JH_Status = JobHeaderStatus.WorkOnHold.Code;
				testJob.JH_Status = JobHeaderStatus.Closed.Code;
				AssertEquals(ZDateTime.Today, testJob.JH_A_JCL.Date);
				AssertEquals("GetRevenueRecognitionDate(TestObjectCreator.CC1) should be set from Close Date + 2 Accounting Periods", expectedEndPeriod, testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

				setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
				setting1.Mode = RevenueRecognitionLookups.ModeAdditionalCodes.All;
				setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
				setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
				setting1.Offset = 10;
				setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

				DummyJobInvoicingPlugIn parent = new DummyJobInvoicingPlugIn(Factory);
				((DummyJobInvoicingPlugInJobInvoicingSupporter)parent.InvoicingSupporter).OperationsRevenueRecognitionDateByDirectionForTest = new ZDateTime(2005, 5, 10);
				testJob.Parent = parent;
				charge = testJob.Charges.AddNew();
				charge.JR_AC = TestObjectCreator.CC1.PK;
				AssertEquals("GetRevenueRecognitionDate(TestObjectCreator.CC1) should be set from Post Date + Days Offset", new ZDateTime(2005, 5, 20), testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

				setting1.Offset = 2;
				setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Periods;
				AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				AssertEquals("GetRevenueRecognitionDate(TestObjectCreator.CC1) should be set from Post Date + 2 Accounting Periods", expectedEndPeriod, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
			}
		}

		public void TestSettingRevenueRecognitionDate_CustomsCleranceDateWithDirection()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.Mode = Constants.TransportModes.All;
			setting1.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.CustomsClearanceDate;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			var importShipment = TestObjectCreator.CreateShipment("S0001", "KRSEL", "AUSYD");
			importShipment.GetLogs().AddNew(new EventValue(Events.ExportCustomsCleared, eventTime: new ZDateTimeOffset(2014, 3, 11)));
			using (Job testJob = TestObjectCreator.CreateJob(importShipment))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				AssertEquals("Calculated Job RevenueRecognitionDate", ZDateTime.Empty, testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
			}

			importShipment.GetLogs().AddNew(new EventValue(Events.CustomsCleared, eventTime: new ZDateTimeOffset(2014, 5, 18)));
			using (Job testJob = TestObjectCreator.CreateJob(importShipment))
			{
				testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
				AssertEquals("Calculated Job RevenueRecognitionDate", new ZDateTime(2014, 5, 18), testJob.CalculateRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
			}

			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			var exportShipment = TestObjectCreator.CreateShipment("S0002", "AUSYD", "KRSEL");
			exportShipment.GetLogs().AddNew(new EventValue(Events.CustomsCleared, eventTime: new ZDateTimeOffset(2014, 6, 21)));
