		}

		[TestDate(2010, 11, 15)]
		public void TestSetAPLineReversedDateFromARLinePostDateIfAPLineRevRecognitionTypeIsFAR()
		{
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S00001000";
			TestJob.Parent = shipment;
			TestJob.JH_JobNum = TestObjectCreator.GetRandomString(8);
			Factory.Save();

			AccountingPeriodTestHelper testHelper = new AccountingPeriodTestHelper(Factory);
			testHelper.SetupSinglePeriod(200804, new ZDateTime(2008, 4, 1), new ZDateTime(2008, 4, 30));
			ZDateTime expectedDate = new ZDateTime(2008, 4, 4);

			APInvoiceLine apInvoiceLine = (APInvoiceLine)Factory.New<APInvoice>().Lines.AddNew();
			apInvoiceLine.AL_JH = TestJob.PK;
			apInvoiceLine.AL_PostDate = expectedDate;
			apInvoiceLine.AL_LineType = TransactionLineTypes.Cost;
			apInvoiceLine.AL_AC = TestObjectCreator.CC1.PK;
			apInvoiceLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AssertEquals("Prerequisite: AL_ReverseDate on APTransactionLine should be empty", ZDateTime.Empty, apInvoiceLine.AL_ReverseDate);
			ARInvoiceLine arInvoiceLine = (ARInvoiceLine)Factory.New<ARInvoice>().Lines.AddNew();
			arInvoiceLine.AL_JH = TestJob.PK;
			arInvoiceLine.AL_PostDate = expectedDate;
			arInvoiceLine.AL_LineType = TransactionLineTypes.Revenue;
			arInvoiceLine.AL_AC = TestObjectCreator.CC1.PK;
			arInvoiceLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;

			var charge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.FRT, debtor: TestObjectCreator.Debtor);
			charge.JR_AL_APLine = apInvoiceLine.PK;

			TestJob.ApplyRevenueRecognitionDate(arInvoiceLine);
			AssertEquals("AL_ReverseDate on APTransactionLine should be set from the post Date of the ARInvoiceLine since AL_RevRecognitionType is FAR", expectedDate, apInvoiceLine.AL_ReverseDate);
			JobChargeRevRecognition[] revRecognitions = Factory.Load<JobChargeRevRecognition>(new ZQuery(JobChargeRevRecognitionSchema.D3_JH, TestJob.PK));
			AssertEquals("2 JobChargeRevRecognition should be created", 2, revRecognitions.Length);
			var x = from element in revRecognitions
					orderby element.D3_RecognitionType
					select element;
			AssertEquals("D3_RecognitionType should be FAR", "FAR", x.ElementAt(0).D3_RecognitionType);
			AssertEquals("D3_RecognitionType should be IMM", "IMM", x.ElementAt(1).D3_RecognitionType);
		}

