		[TestDate(2011, 05, 08)]
		public void TestSetRevenueRecognitionDateForPostDateOfFirstARTransactionRegistry()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			setting.Offset = 5;
			setting.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S00001000";
			TestJob.Parent = shipment;
			Factory.Save();

			AccountingPeriodTestHelper testHelper = new AccountingPeriodTestHelper(Factory);
			testHelper.SetupSinglePeriod(200804, new ZDateTime(2008, 4, 1), new ZDateTime(2008, 4, 30));

			ZDateTime expectedPostDate = new ZDateTime(2008, 4, 4);
			ZDateTime expectedRecognitionDate = expectedPostDate.AddDays(5);

			APInvoiceLine apInvoiceLine = (APInvoiceLine)Factory.New<APInvoice>().Lines.AddNew();
			apInvoiceLine.AL_JH = TestJob.PK;
			apInvoiceLine.AL_PostDate = expectedPostDate.AddDays(-1);
			apInvoiceLine.AL_LineType = TransactionLineTypes.Cost;
			apInvoiceLine.AL_AC = TestObjectCreator.CC1.PK;
			apInvoiceLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			APCreditNoteLine apCreditNoteLine = (APCreditNoteLine)Factory.New<APCreditNote>().Lines.AddNew();
			apCreditNoteLine.AL_JH = TestJob.PK;
			apCreditNoteLine.AL_PostDate = expectedPostDate.AddDays(-2);
			apCreditNoteLine.AL_LineType = TransactionLineTypes.Cost;
			apCreditNoteLine.AL_AC = TestObjectCreator.CC1.PK;
			apCreditNoteLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			ARInvoiceLine arInvoiceLine = (ARInvoiceLine)Factory.New<ARInvoice>().Lines.AddNew();
			arInvoiceLine.AL_JH = TestJob.PK;
			arInvoiceLine.AL_PostDate = expectedPostDate;
			arInvoiceLine.AL_LineType = TransactionLineTypes.Revenue;
			arInvoiceLine.AL_AC = TestObjectCreator.CC1.PK;
			arInvoiceLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			ARCreditNoteLine arCreditNoteLine = (ARCreditNoteLine)Factory.New<ARCreditNote>().Lines.AddNew();
			arCreditNoteLine.AL_JH = TestJob.PK;
			arCreditNoteLine.AL_PostDate = expectedPostDate.AddDays(-3);
			arCreditNoteLine.AL_LineType = TransactionLineTypes.Revenue;
			arCreditNoteLine.AL_AC = TestObjectCreator.CC1.PK;
			arCreditNoteLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			TestJob.ApplyRevenueRecognitionDate(arInvoiceLine);
			AssertEquals("Revenue Recognition Date  should be set from Post Date", expectedRecognitionDate, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			AssertEquals("APInvoiceLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, apInvoiceLine.AL_ReverseDate);
			AssertEquals("APCreditNoteLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, apCreditNoteLine.AL_ReverseDate);
			AssertEquals("ARInvoiceLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, arInvoiceLine.AL_ReverseDate);
			AssertEquals("ARCreditNoteLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, arCreditNoteLine.AL_ReverseDate);

			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			TestJob.ApplyRevenueRecognitionDate(apInvoiceLine);
			AssertEquals("Revenue Recognition Date  should be not set as RevenueRecognition setting is not PostDateOfFirstARTransaction", ZDateTime.Empty, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(TestObjectCreator.CC1)));

			AssertEquals("APInvoiceLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, apInvoiceLine.AL_ReverseDate);
			AssertEquals("APCreditNoteLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, apCreditNoteLine.AL_ReverseDate);
			AssertEquals("ARInvoiceLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, arInvoiceLine.AL_ReverseDate);
			AssertEquals("ARCreditNoteLine AL_ReverseDate should be set from Revenue Recognition Date ", expectedRecognitionDate, arCreditNoteLine.AL_ReverseDate);
		}

		[TestDate(2009, 10, 27)]
		public void TestSetRevenueRecognitionDateForPostDateOfFirstARTransactionRegistryWhenARInvoiceIsAlreadyPosted()
		{
			ForwardingShipment shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_UniqueConsignRef = "S00001000";
			TestJob.Parent = shipment;
			TestJob.JH_ParentID = shipment.PK;
			TestJob.JH_ParentTableCode = "JS";
			Factory.Save();

			AccountingPeriodTestHelper testHelper = new AccountingPeriodTestHelper(Factory);
			testHelper.SetupSinglePeriod(200804, new ZDateTime(2008, 4, 1), new ZDateTime(2008, 4, 30));

			ZDateTime expectedDate = new ZDateTime(2008, 4, 4);

			Charge charge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, TestObjectCreator.AALSHI,
				TestObjectCreator.AUD, 100M, TestObjectCreator.ABIGAS);

			Factory.Save();

			InvoicingPostManager postManager = new InvoicingPostManager(TestJob);
			TransactionHeader[] invoicelist = postManager.CreateTransactions(JobInvoicingPostingOption.Revenue).GetAllARTransactions();
			ARInvoice firstPostedARInvoice = invoicelist[0] as ARInvoice;
			firstPostedARInvoice.AH_PostDate = expectedDate;

			Factory.Save();

			Assert("Pre-condition:First AR invoice must be posted - Charge must have posted revenue", charge.IsRevenuePosted);
			AssertEquals("Pre-Condition:First AR invoice must be posted - Current Sell recognition must not be FAR", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, charge.SellRecognition);
			AssertEquals("Pre-Condition:First AR invoice must be posted - It will be reconginsed on post date beause it's immediate", expectedDate, charge.ARLine.AL_ReverseDate.Date);

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, TestJob.GetRevenueRecognitionType(charge.ChargeCode));
			ZQuery revRecFilterForFARType = new ZQuery(JobChargeRevRecognitionSchema.D3_JH, TestJob.PK);
			revRecFilterForFARType.AddToFilter(JobChargeRevRecognitionSchema.D3_RecognitionType, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
			JobChargeRevRecognition revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(revRecFilterForFARType);
			AssertNull("Pre-Condition: Job Charge revenue recognition record for FAR must not exist for the job.", revRecognition);

			charge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 200M, TestObjectCreator.AALSHI, "12345",
				TestObjectCreator.AUD, 200M, TestObjectCreator.ABIGAS);
			postManager.CreateTransactions(JobInvoicingPostingOption.Costs);
			Factory.Save();

			Assert("Post Condition: Cost Will be posted", charge.IsCostPosted);
			AssertEquals("Post Condition: Cost will use FAR recognition", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, charge.CostRecognition);
			revRecognition = Factory.LoadTop1<JobChargeRevRecognition>(revRecFilterForFARType);
			AssertEquals("Job Charge revenue recognition record for FAR will now exist and be the date of first AR posting", expectedDate, revRecognition.D3_RecognitionDate);
			AssertEquals("Transaction line will be recongised on date of first AR posting", expectedDate, charge.APLine.AL_ReverseDate.Date);
		}

