		public void TestFindRevenueRecognition()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = "SHP";
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;

			IRevenueRecognition result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.Air, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals("Testing ignore case comparison for Direction", RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate, result.RecognitionDateOptionCode);

			valuesForTest.RemoveAll();
			setting1 = valuesForTest.AddNew();
			setting1.JobType = "SHP";
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;

			RevenueRecognition setting2 = valuesForTest.AddNew();
			setting2.JobType = "CSH";
			setting2.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
			setting2.Mode = Core.Constants.TransportModes.Sea;
			setting2.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;

			RevenueRecognition setting3 = valuesForTest.AddNew();
			setting3.JobType = "SHP";
			setting3.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting3.Mode = Core.Constants.TransportModes.Sea;
			setting3.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			setting3.BrokerCode = RevenueRecognitionLookups.BrokerCodes.Internal;

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.Air, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, null);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.All);
			AssertNull(result);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.External);
			AssertNull(result);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNull(result);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "CSH", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "CSH", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.SeaAir, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNull(result);

			setting2.Mode = RevenueRecognitionLookups.ModeAdditionalCodes.All;
			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "CSH", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.SeaAir, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, result.RecognitionDateOptionCode);

			valuesForTest.RemoveAll();
			valuesForTest.Add(setting3);
			setting3.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting3.DirectionCode = "";
			setting3.Mode = "";
			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "CSH", Constants.FreightShipmentDirection.Code.Import, Core.Constants.TransportModes.SeaAir, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			setting3.JobType = "AWB";
			setting3.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting3.Mode = Core.Constants.TransportModes.Sea;
			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNull(result);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "AWB", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			setting3.JobType = "SHP";
			setting3.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting3.Mode = Core.Constants.TransportModes.Sea;
			setting3.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;
			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.Internal);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, null, Constants.FreightShipmentDirection.Code.Export, Core.Constants.TransportModes.Sea, RevenueRecognitionLookups.BrokerCodes.All);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);

			result = TestJob.FindRevenueRecognition_ForTestOnly(valuesForTest, "SHP", null, null, null);
			AssertNotNull(result);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate, result.RecognitionDateOptionCode);
		}

		public void TestGetRevenueRecognitionOptionForGatewayBillingJob()
		{
			var consol = Factory.NewWithValidTestData<ForwardingConsol>();
			consol.JK_TransportMode = Constants.TransportModes.Sea;
			consol.JK_RL_NKLoadPort = "AUBNE";
			consol.JK_OA_SendingForwarderAddress = GlbCompany.CurrentCompany.OrgProxy.MainAddress.PK;
			consol.JK_AgentType = Constants.AgentType.Agent;
			consol.JK_SendingForwarderHandlingType = ZString.Empty;
			Assert("Pre-condition", !consol.IsGateway());

			var port = Factory.NewWithValidTestData<OrgAppointedAgentPorts>();
			port.O5_PortOrCountry = "AUBNE";
			port.O5_AgentDirection = AgentDirectionList.Codes.Both;
			port.O5_SeaAgentStatus = AgentStatusList.Codes.GatewayAgent;
			consol.SendingForwarder.AppointedGatewayAgentPorts.Add(port);

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.JH_ParentID = consol.PK;
			job.JH_ParentTableCode = JobConsolSchema.Constants.Prefix;
			job.JH_JobNum = "1234" + Constants.GatewaySuffixForJobHeaderDeprecated;
			Factory.Save();

			RevenueRecognitionCollection collection = new RevenueRecognitionCollection();
			var gatewaySetting = collection.AddNew();
			gatewaySetting.JobType = JobInvoicingConsumerTypes.GatewayConsol.Code;
			gatewaySetting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			gatewaySetting.Mode = Constants.TransportModes.All;
			gatewaySetting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, collection);

			var result = job.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertNull(result);

			consol.JK_AgentType = Constants.AgentType.Agent;
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;

			result = job.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);

			Assert("Pre-condition", consol.IsGateway());
			AssertNotNull(result);
		}

