		public void TestRevenueRecognitionCustomClearenceForOldJobs()
		{
			Charge charge = TestObjectCreator.CreateCharge(TestJob, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 10M, TestObjectCreator.AALSHI, TestObjectCreator.AUD, 10M, TestObjectCreator.AALSHI);
			InvoicingBase invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "0001", TestObjectCreator.AUD, 1M, 10M, 0M, 10M, 0M);
			invoice.Lines[0].AL_JH = TestJob.PK;
			invoice.Lines[0].AL_PostDate = ZDateTime.BrettsBirthday;

			DummyJobHeaderParent parent = Factory.New<DummyJobHeaderParent>();
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).ConsumerType = JobInvoicingConsumerTypes.Brokerage;
			TestJob.Parent = parent;

			JobChargeRevRecognition jobChargeRevRec = TestObjectCreator.CreateJobChargeRevRecognition(TestJob, RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob, AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate);
			AssertEquals("Precondition", AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));

			TestJob.ApplyRevenueRecognitionDate(invoice.Lines[0]);
			AssertEquals("Job Charge Revenue recognition should be changed to Job Closure Date.", AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate, jobChargeRevRec.D3_RecognitionDate);
			AssertEquals("Revenue recognition should return Job Closure Date.", AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));

			RevenueRecognitionCollection revenueRecognitions = AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.Value;
			revenueRecognitions[0].JobType = JobInvoicingConsumerTypes.Brokerage.Code;
			revenueRecognitions[0].RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.CustomsClearanceDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, revenueRecognitions);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			jobChargeRevRec.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.JobClosure;
			AssertEquals("Precondition", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).OperationsRevenueRecognitionDateByDirectionForTest = ZDateTime.Now;
			TestJob.ApplyRevenueRecognitionDate(invoice.Lines[0]);
			AssertEquals("Job Charge Revenue recognition should be changed to Job Closure Date.", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, jobChargeRevRec.D3_RecognitionDate);
			AssertEquals("Revenue recognition should return Job Closure Date.", AccountingConstants.RevenueRecognitionDateConstants.JobClosure, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));

			jobChargeRevRec.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate;
			AssertEquals("Precondition", AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));
			TestJob.ApplyRevenueRecognitionDate(invoice.Lines[0]);
			AssertEquals("Job Charge Revenue recognition should be changed to Job Closure Date.", ((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).OperationsRevenueRecognitionDateByDirectionForTest, jobChargeRevRec.D3_RecognitionDate);
			AssertEquals("Revenue recognition should return Job Closure Date.", ((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).OperationsRevenueRecognitionDateByDirectionForTest, TestJob.GetRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionType(charge.ChargeCode)));
		}

