		public void TestGetRevenueRecognitionDates_DbHit()
		{
			var revRec = Factory.NewWithValidTestData<JobChargeRevRecognition>();
			revRec.D3_JH = TestJob.PK;
			revRec.D3_RecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
			revRec.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.Immediate;
			Factory.Save();

			Factory.ResetDatabaseLoadCount();
			var revRecognitions = TestJob.RevenueRecognitionCollection;
			AssertEquals(1, revRecognitions.Count);
			// Please read the following content if changes are required: https://devops.wisetechglobal.com/wtg/CargoWise/_wiki/wikis/CargoWise.wiki?wikiVersion=GBwikiMaster&pagePath=%2FCargoWise%20Wiki%2FAccounting%2FReference%20and%20Checklists%2FAccounting%20DB%20Hits%20(and%20other%20performance%20related%20regressions)&pageId=1538
			AssertDbHits(new Dictionary<string, int> { { JobChargeRevRecognitionSchema.Constants.TableName, 1 } }, Factory);

			Factory.ResetDatabaseLoadCount();
			Factory.ClearQueryCache();
			revRecognitions = TestJob.RevenueRecognitionCollection;
			AssertEquals(1, revRecognitions.Count);
			AssertDbHits(new Dictionary<string, int> { { JobChargeRevRecognitionSchema.Constants.TableName, 0 } }, Factory);

			var newOption = TestJob.GetOrCreateJobChargeRevRecognition_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob, AccountingConstants.RevenueRecognitionDateConstants.Immediate);
			AssertEquals(AccountingConstants.RevenueRecognitionDateConstants.Immediate, newOption.D3_RecognitionDate);
			revRecognitions = TestJob.RevenueRecognitionCollection;
			AssertEquals(2, revRecognitions.Count);

			newOption = TestJob.UpdateJobChargeRevRecognition_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob, new ZDateTime(2021, 2, 20));
			AssertEquals(new ZDateTime(2021, 2, 20), newOption.D3_RecognitionDate);
		}

