		public void TestGetRevenueRecognitionDates_SingleChargeBePostedAndReversed_DbHit()
		{
			TestObjectCreator.CreateTestPeriods(new ZDateTime(2023, 01, 01));
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var revRecognitions = new RevenueRecognitionCollection();
			var setting = revRecognitions.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Enterprise.Core.Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			setting.Offset = 25;
			setting.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, revRecognitions);

			var shipment = TestObjectCreator.CreateShipment("S00001");
			var job = TestObjectCreator.CreateJob(shipment);
			Factory.Save();
			AssertEquals("PreCondition.", 0, job.RevenueRecognitionCollection.Count);

			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.USD, 0m, null, TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS);
			charge.JR_GE = TestObjectCreator.FIADepartment.PK;

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Simulate charge WIP(or ACR) was posted. Should have no extra DB hit.",
				() =>
				{
					new ChargePoster(Factory).Post(charge);
					Factory.Save();
				},
				expectedDbhit: 0,
				expectedRevenueRecognitionCollectionCount: 0
			);

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Should have no touch to RevenueRecognitionCollection when charges is reversed.",
				() =>
				{
					JobInvoicingReverser reverser = new JobInvoicingReverser(job);
					reverser.ReverseAllInvoices("test", "tst");
					reverser.ReversingFactory.Save();
					Factory.Save();
				},
				expectedDbhit: 0,
				expectedRevenueRecognitionCollectionCount: 0
			);
		}

