		public void TestGetRevenueRecognitionDates_WithExternalRevRecognitionDateChange_DbHit()
		{
			TestObjectCreator.CreateTestPeriods(new ZDateTime(2023, 01, 01));
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);

			var valuesForTest = new RevenueRecognitionCollection();
			var setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Enterprise.Core.Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			setting.Offset = 25;
			setting.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			var shipment = TestObjectCreator.CreateShipment("S00001");
			var job = TestObjectCreator.CreateJob(shipment);
			Factory.Save();
			AssertEquals("PreCondition.", 0, job.RevenueRecognitionCollection.Count);

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Should have no touch to RevenueRecognitionCollection when saving the first charge.",
				() =>
				{
					var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.USD, 0m, null, TestObjectCreator.USD, 100m, TestObjectCreator.ABIGAS);
					charge1.JR_GE = TestObjectCreator.FIADepartment.PK;
					Factory.Save();
				},
				expectedDbhit: 0,
				expectedRevenueRecognitionCollectionCount: 0
			);

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Should have no touch to RevenueRecognitionCollection when posting the charge.",
				() =>
				{
					new ChargePoster(Factory).Post(job.Charges[0]);
					Factory.Save();
				},
				expectedDbhit: 0,
				expectedRevenueRecognitionCollectionCount: 0
			);

			var newFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var jobInNewFactory = newFactory.Load<Job>(job.PK);
			jobInNewFactory.ApplyRevenueRecognitionDateForWholeJob_ForTestOnly(new ZDateTime(2023, 02, 01), null, out _);
			newFactory.Save();

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Will have the latest RevenueRecognition after refresh from database(Triggered by before saving lifecycle). And only should have 1 db hit when saving two or more new charges.",
				() =>
				{
					var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.USD, 0m, null, TestObjectCreator.AUD, 200m, TestObjectCreator.ABIGAS);
					charge2.JR_GE = TestObjectCreator.FIADepartment.PK;
					var charge3 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.USD, 0m, null, TestObjectCreator.AUD, 200m, TestObjectCreator.ABIGAS);
					charge3.JR_GE = TestObjectCreator.FIADepartment.PK;
					Factory.Save();
				},
				expectedDbhit: 1,
				expectedRevenueRecognitionCollectionCount: 1
			);

			AssertRevenueRecognitionCollectionCountAndDbHit(job, "Should have no touch to RevenueRecognitionCollection when new charge already can get RevenueRecognitionDate.",
				() =>
				{
					var charge4 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.USD, 0m, null, TestObjectCreator.AUD, 200m, TestObjectCreator.ABIGAS);
					charge4.JR_GE = TestObjectCreator.FIADepartment.PK;
					Factory.Save();
				},
				expectedDbhit: 0,
				expectedRevenueRecognitionCollectionCount: 1
			);
		}

		void AssertRevenueRecognitionCollectionCountAndDbHit(Job job, string comment, Action action, int expectedDbhit, int expectedRevenueRecognitionCollectionCount)
		{
			var oldHit = Factory.GetTableHitCount(AutoJobChargeRevRecognition.Schema.TableName);

			action?.Invoke();

			CombineAssertions(comment,
				() =>
				{
					AssertEquals("Dbhit", expectedDbhit, Factory.GetTableHitCount(AutoJobChargeRevRecognition.Schema.TableName) - oldHit);
					AssertEquals("RevenueRecognitionCollection Count", expectedRevenueRecognitionCollectionCount, job.RevenueRecognitionCollection.Count);
				}
			);
		}

