		public void TestGetOperationsRevenueRecognitionDate_RegistrySettings()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;

			RevenueRecognition setting2 = valuesForTest.AddNew();
			setting2.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting2.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
			setting2.Mode = Core.Constants.TransportModes.Sea;
			setting2.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			setting2.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;

			RevenueRecognition setting3 = valuesForTest.AddNew();
			setting3.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting3.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting3.Mode = Core.Constants.TransportModes.Sea;
			setting3.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			setting3.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			IJobInvoicingPlugIn pluginData = shipment;

			TestJob.PlugInData = pluginData;

			shipment.JS_RL_NKOrigin = "USLAX";
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;

			ZDateTime expectedPickupDate = ZDateTime.Now.AddDays(10);
			ZDateTime expectedDeliveryDate = ZDateTime.Now.AddDays(15);
			ZDateTime expectedActualArrivalDate = ZDateTime.Now.AddDays(20);
			shipment.DocsAndCartage.JP_PickupCartageCompleted = expectedPickupDate;
			shipment.DocsAndCartage.JP_DeliveryCartageCompleted = expectedDeliveryDate;
			shipment.JS_E_ARV = expectedActualArrivalDate;

			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", expectedPickupDate, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "USLAX";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Sea;
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", expectedDeliveryDate, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			shipment.JS_RL_NKOrigin = "USLAX";
			shipment.JS_RL_NKDestination = "AUSYD";
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", expectedActualArrivalDate, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			shipment.JS_TransportMode = Core.Constants.TransportModes.SeaAir;
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", ZDateTime.Empty, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.Other;
			setting2.Mode = RevenueRecognitionLookups.ModeAdditionalCodes.All;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", expectedActualArrivalDate, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			valuesForTest.RemoveAll();
			valuesForTest.Add(setting3);
			setting3.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting3.DirectionCode = "";
			setting3.Mode = "";
			setting3.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin", TestJob.JH_A_JOP, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
		}

		public void TestGetOperationsRevenueRecognitionDate_WithOffset()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting1 = valuesForTest.AddNew();
			setting1.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting1.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting1.Mode = Core.Constants.TransportModes.Air;
			setting1.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;
			setting1.Offset = 10;
			setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			IJobInvoicingPlugIn pluginData = shipment;

			TestJob.PlugInData = pluginData;

			shipment.JS_RL_NKOrigin = "USLAX";
			shipment.JS_RL_NKDestination = "AUSYD";
			shipment.JS_TransportMode = Core.Constants.TransportModes.Air;

			ZDateTime expectedPickupDate = new ZDateTime(2005, 05, 15);
			shipment.DocsAndCartage.JP_PickupCartageCompleted = expectedPickupDate;

			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin with 10 days offset", expectedPickupDate.AddDays(10), TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			setting1.Offset = 2;
			setting1.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Periods;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			AccountingPeriodTestHelper periodHelper = new AccountingPeriodTestHelper(Factory);
			periodHelper.SetupSinglePeriod(1002, new ZDateTime(2005, 04, 25), new ZDateTime(2005, 05, 25));
			periodHelper.SetupSinglePeriod(2003, new ZDateTime(2005, 05, 25), new ZDateTime(2005, 06, 25));
			ZDateTime expectedEndPeriod = new ZDateTime(2005, 07, 25);
			periodHelper.SetupSinglePeriod(3004, new ZDateTime(2005, 06, 25), expectedEndPeriod);

			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin with 2 periods offset", expectedEndPeriod, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));

			setting1.Offset = 3;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			AssertEquals("OperationsRevenueRecognitionDate on IJobInvoicingPlugin with 3 periods offset - there aren't created periods",
				DateTime.MaxValue, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
		}

