			transport1.JW_ETD = ZDateTime.Empty;
			AssertEquals(ZDateTime.Empty, TestJob.CalculateRevenueRecognitionDate_ForTestOnly(TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1)));
		}

