		public void TestGetRevenueRecognitionOption()
		{
			Job testJob = Factory.NewJobForTesting<Job>();
			DummyJobHeaderParent parent = Factory.New<DummyJobHeaderParent>();

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Domestic;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;
			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.CFSShipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Other;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsDomestic = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).TransportMode = Core.Constants.TransportModes.Road;

			IRevenueRecognition testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(null);
			AssertEquals("Should be searched default value", null, testValue);

			testJob.Parent = parent;
			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsDomestic = false;
			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue.RecognitionDateOptionCode);

			testJob = Factory.NewJobForTesting<Job>();
			valuesForTest = new RevenueRecognitionCollection();
			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Brokerage.Code;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(null);
			AssertEquals("Should be searched default value", null, testValue);

			setting.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(null);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, testValue.RecognitionDateOptionCode);

			testJob.Parent = parent;
			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, testValue.RecognitionDateOptionCode);

			RevenueRecognitionByChargeGroupCollection revenueRecognitionByChargeGroupCollection = AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.Value;
			foreach (RevenueRecognitionByChargeGroup revenueRecognitionByChargeGroup in revenueRecognitionByChargeGroupCollection)
			{
				if (revenueRecognitionByChargeGroup.ChargeGroup == ChargeCodeGroupList.Codes.Freight)
				{
					RevenueRecognition revenueRecognition = revenueRecognitionByChargeGroup.ChargeGroupSettings.AddNew();
					revenueRecognition.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
					revenueRecognition.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
					revenueRecognition.Offset = 0;
				}
			}
			AccountingConfigurationRegistry.Instance.RevenueRecognitionByChargeGroupSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(),
				Guid.Empty, Guid.Empty, revenueRecognitionByChargeGroupCollection);
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			setting.Offset = 10;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			TestObjectCreator.CC1.AC_ChargeGroup = ChargeCodeGroupList.Codes.Freight;
			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched by charge code groups.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue.RecognitionDateOptionCode);
			AssertEquals(10, testValue.Offset);

			AccChargeRevRecOverride chargeRevRecOverride = TestObjectCreator.CC1.RevenueRecOverrides.AddNew();
			chargeRevRecOverride.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			chargeRevRecOverride.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			chargeRevRecOverride.Offset = 0;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			setting.Offset = 10;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched by charge code groups.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue.RecognitionDateOptionCode);
			AssertEquals(10, testValue.Offset);

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, "");
			AssertEquals("Invalid parameter value. Should return null", null, testValue);

			testValue = testJob.GetRevenueRecognitionOption_CreateStubIfRecognitionOptionIsNotExist_ForTestOnly(TestObjectCreator.CC1, "");
			AssertEquals("Invalid parameter value. Should return null", null, testValue);

			testValue = testJob.GetRevenueRecognitionOption_CreateStubIfRecognitionOptionIsNotExist_ForTestOnly(TestObjectCreator.CC1, null);
			AssertEquals("Invalid parameter value. Should return null", null, testValue);

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate);
			AssertEquals("Should return null, because registry value is not JobOpenDate.", null, testValue);

			testValue = testJob.GetRevenueRecognitionOption_CreateStubIfRecognitionOptionIsNotExist_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate);
			AssertEquals("Should return stub, because registry value is not JobOpenDate.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue.RecognitionDateOptionCode);
			AssertEquals("Offset can't be found for stub.", 0, testValue.Offset);

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure);
			AssertEquals("Should return null, because registry value is not JobOpenDate.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue.RecognitionDateOptionCode);
			AssertEquals(10, testValue.Offset);
		}

		public void TestGetRevenueRecognitionOption_Booking_CFS()
		{
			var quickBooking = QuotedBooking.New(QuoteBookingType.QuickBooking, Factory);
			var job = TestObjectCreator.CreateJob(quickBooking, false);

			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Quick Booking Job Charge", TestObjectCreator.AUD, 10M, null, TestObjectCreator.AUD, 0M, TestObjectCreator.ABIGAS);
			CombineAssertions("GIVEN QuickBooking non-CFS, THEN CostRecognition should be FAR", () =>
			{
				AssertType("Parent Type", typeof(QuotedBooking), job.Parent);
				AssertEquals("Charge.CostRecognition", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, charge.CostRecognition);
			});

			var org = Factory.NewWithValidTestData<OrgHeader>();
			var newCompany = Factory.New<GlbCompany>();
			newCompany.GC_Code = "DXZ";
			newCompany.GC_Name = "DXZ Enterprises";
			newCompany.GC_RN_NKCountryCode = "AU";
			newCompany.GC_RX_NKLocalCurrency = "AUD";
			newCompany.GC_OH_OrgProxy = org.PK;

			quickBooking.Booking.JS_OA_ExportReceivingDepot = org.MainAddress.PK;

			CombineAssertions("GIVEN QuickBooking CFS, THEN CostRecognition should be FAR", () =>
			{
				AssertType("Before save: Parent Type", typeof(QuotedBooking), job.Parent);
				AssertEquals("Before save: Charge.CostRecognition", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, charge.CostRecognition);

				Factory.Save();
				AssertNotEquals("After save: Parent Type should not QuotedBooking i.e. ForwardingShipment or JASForwardingShipment", typeof(QuotedBooking), job.Parent.GetType());
				AssertEquals("After save: Charge.CostRecognition", RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, charge.CostRecognition);
			});
		}

		public void TestGetRevenueRecognitionOption_QuotedBookings()
		{
			var testJob = Factory.NewJobForTesting<Job>();
			var parent = Factory.New<DummyJobHeaderParent>();

			SetRevenueRecognitionCollectionForRegistry(RevenueRecognitionLookups.JobTypeAdditionalCodes.All, RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			var invoicingSupporter = (DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter;
			invoicingSupporter.ConsumerType = JobInvoicingConsumerTypes.QuotedBooking;
			invoicingSupporter.IsImport = false;
			invoicingSupporter.IsExport = false;
			invoicingSupporter.IsDomestic = true;
			invoicingSupporter.TransportMode = Constants.TransportModes.Sea;

			testJob.Parent = parent;
			var testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			var postDateOfFirstARTransaction = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			AssertEquals("No setting for QSH found. Default fallsback to PostDateOfFirstARTransaction", postDateOfFirstARTransaction, testValue.RecognitionDateOptionCode);

			SetRevenueRecognitionCollectionForRegistry(RevenueRecognitionLookups.JobTypeAdditionalCodes.All, postDateOfFirstARTransaction);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("No setting for QSH found but default value is PostDateOfFirstARTransaction.", postDateOfFirstARTransaction, testValue.RecognitionDateOptionCode);

			SetRevenueRecognitionCollectionForRegistry(JobInvoicingConsumerTypes.Shipment.Code, postDateOfFirstARTransaction);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertNull("No setting for QSH or default found, cannot change if there's no fall back", testValue);

			SetRevenueRecognitionCollectionForRegistry(JobInvoicingConsumerTypes.QuotedBooking.Code, postDateOfFirstARTransaction);
			testJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			testValue = testJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("QSH setting was found", postDateOfFirstARTransaction, testValue.RecognitionDateOptionCode);
		}

		public void TestRevenueRecognitionOptionForQSHAndSHPJob()
		{
			var testQSHJob = Factory.NewJobForTesting<Job>();
			var testSHPJob = Factory.NewJobForTesting<Job>();

			var parentQSH = Factory.New<DummyJobHeaderParent>();
			var parentSHP = Factory.New<DummyJobHeaderParent>();

			SetRevenueRecognitionCollectionForRegistry(RevenueRecognitionLookups.JobTypeAdditionalCodes.All, RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate);

			var invoicingSupporterQSH = (DummyJobHeaderParentJobInvoicingSupporter)parentQSH.InvoicingSupporter;
			invoicingSupporterQSH.ConsumerType = JobInvoicingConsumerTypes.QuotedBooking;
			invoicingSupporterQSH.IsImport = false;
			invoicingSupporterQSH.IsExport = false;
			invoicingSupporterQSH.IsDomestic = true;
			invoicingSupporterQSH.TransportMode = Constants.TransportModes.Sea;

			testQSHJob.Parent = parentQSH;

			var invoicingSupporterSHP = (DummyJobHeaderParentJobInvoicingSupporter)parentSHP.InvoicingSupporter;
			invoicingSupporterSHP.ConsumerType = JobInvoicingConsumerTypes.Shipment;
			invoicingSupporterSHP.IsImport = false;
			invoicingSupporterSHP.IsExport = false;
			invoicingSupporterSHP.IsDomestic = true;
			invoicingSupporterSHP.TransportMode = Constants.TransportModes.Road;

			testSHPJob.Parent = parentSHP;

			var testRevenueRecognition = testQSHJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, testRevenueRecognition.RecognitionDateOptionCode);

			testRevenueRecognition = testQSHJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate);
			AssertNull(testRevenueRecognition);

			testRevenueRecognition = testQSHJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction, testRevenueRecognition.RecognitionDateOptionCode);

			testRevenueRecognition = testSHPJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, testRevenueRecognition.RecognitionDateOptionCode);

			testRevenueRecognition = testSHPJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate);
			AssertEquals(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, testRevenueRecognition.RecognitionDateOptionCode);

			testRevenueRecognition = testSHPJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction);
			AssertNull(testRevenueRecognition);
		}

