		void SetRevenueRecognitionCollectionForRegistry(string jobType, string recognitionCode)
		{
			var valuesForTest = new RevenueRecognitionCollection();
			var setting = valuesForTest.AddNew();

			setting.JobType = jobType;
			if (setting.JobType != RevenueRecognitionLookups.JobTypeAdditionalCodes.All)
			{
				setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
				setting.Mode = Constants.TransportModes.Sea;
			}
			setting.BrokerCode = string.Empty;
			setting.RecognitionDateOptionCode = recognitionCode;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
		}

		[UseSnapshotProtection]
		public void TestRevenueRecognitionDate_BrokerOption()
		{
			OrgHeader internalBroker1 = Factory.New<OrgHeader>();
			GlbCompany.CurrentCompany.GC_OH_OrgProxy = internalBroker1.PK;

			OrgHeader internalBroker2 = Factory.New<OrgHeader>();
			GlbBranch.CurrentBranch.GB_OH_OrgProxy = internalBroker2.PK;

			OrgHeader externalBroker = Factory.New<OrgHeader>();

			DummyJobHeaderParent parent = Factory.New<DummyJobHeaderParent>();

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;
			setting.BrokerCode = RevenueRecognitionLookups.BrokerCodes.Internal;

			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			setting.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;

			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Export;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			setting.BrokerCode = RevenueRecognitionLookups.BrokerCodes.External;

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			TestJob.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).TransportMode = Core.Constants.TransportModes.Road;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).Broker = internalBroker1;

			TestJob.Parent = parent;

			IRevenueRecognition testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).Broker = externalBroker;
			testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).Broker = internalBroker2;
			testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched correct value", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue.RecognitionDateOptionCode);

			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsDomestic = true;
			testValue = TestJob.GetRevenueRecognitionOption_ForTestOnly(TestObjectCreator.CC1);
			AssertEquals("Should be searched default value", null, testValue);
		}

		[TestDate(2005, 05, 20)]
		public void TestOffsetRevenueRecognitionDate()
		{
			RevenueRecognition revenueRecognitionOption = new RevenueRecognition();
			revenueRecognitionOption.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			revenueRecognitionOption.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			revenueRecognitionOption.Offset = 10;
			revenueRecognitionOption.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Days;

			AssertEquals("RevenueRecognitionDate with 10 days offset", ZDateTime.Now.Date.AddDays(10), TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.Now.Date, revenueRecognitionOption));

			AssertEquals("RevenueRecognitionDate without offset", ZDateTime.MinSmallDateTimeValue, TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.MinSmallDateTimeValue, revenueRecognitionOption));

			AssertEquals("RevenueRecognitionDate without offset", ZDateTime.MaxSmallDateTime, TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.MaxSmallDateTime, revenueRecognitionOption));

			revenueRecognitionOption.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate;
			AssertEquals("Job RevenueRecognitionDate without offset", ZDateTime.Now.Date, TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.Now.Date, revenueRecognitionOption));

			revenueRecognitionOption.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			AssertEquals("Job RevenueRecognitionDate with 10 days offset", ZDateTime.Now.Date.AddDays(10), TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.Now.Date, revenueRecognitionOption));

			AccountingPeriodTestHelper periodHelper = new AccountingPeriodTestHelper(Factory);
			periodHelper.SetupSinglePeriod(1001, new ZDateTime(2005, 04, 25), new ZDateTime(2005, 05, 25));
			periodHelper.SetupSinglePeriod(2001, new ZDateTime(2005, 05, 25), new ZDateTime(2005, 06, 25));
			ZDateTime expectedEndPeriod = new ZDateTime(2005, 07, 25);
			periodHelper.SetupSinglePeriod(3001, new ZDateTime(2005, 06, 25), expectedEndPeriod);

			revenueRecognitionOption.Offset = 2;
			revenueRecognitionOption.OffsetType = JobConfigurationSelectorHelper.OffsetTypeCodes.Periods;
			AssertEquals("Job RevenueRecognitionDate with 2 periods offset", expectedEndPeriod, TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.Now.Date, revenueRecognitionOption));

			revenueRecognitionOption.Offset = 3;
			AssertEquals("Job RevenueRecognitionDate with 3 periods offset is set Max DateTime value for validation purposes.",
				DateTime.MaxValue, TestJob.OffsetRevenueRecognitionDate_ForTestOnly(ZDateTime.Now.Date, revenueRecognitionOption));
		}

		public void TestGetRevenueRecognitionDate()
		{
			Job testJob = Factory.NewJobForTesting<Job>();
			DummyJobHeaderParent parent = Factory.New<DummyJobHeaderParent>();

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsDomestic = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).TransportMode = Core.Constants.TransportModes.Road;

			testJob.Parent = parent;

			int dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			ZDateTime testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(null);
			AssertEquals("Should return no value.", ZDateTime.Empty, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should not found any value", ZDateTime.Empty, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			JobChargeRevRecognition chargeRevRecognition = testJob.GetOrCreateJobChargeRevRecognition_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, ZDateTime.BrettsBirthday);
			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should return value from JobChargeRevRecognition.", ZDateTime.BrettsBirthday, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			chargeRevRecognition.D3_JH = ZGuid.NewZGuid();
			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should not found any value", ZDateTime.Empty, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			chargeRevRecognition.D3_JH = testJob.PK;

			AccChargeRevRecOverride chargeRevRecOverride = TestObjectCreator.CC1.RevenueRecOverrides.AddNew();
			chargeRevRecOverride.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			chargeRevRecOverride.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should not found any value", ZDateTime.Empty, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly("", true);
			AssertEquals("Should return old job date from dbo.JobChargeRevRecognition, but it doesn't exist, so value is empty.", ZDateTime.Empty, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			chargeRevRecognition.D3_RecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob;
			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should return old job date from JobChargeRevRecognition.", ZDateTime.BrettsBirthday, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly("", true);
			AssertEquals("Should return value from JobChargeRevRecognition.", ZDateTime.BrettsBirthday, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);

			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly("", false);
			AssertEquals("Invalid parameter. Should return empty value.", ZDateTime.Empty, testValue);
			Assert("Should not make any hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount);

			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly("");
			AssertEquals("Invalid parameter. Should return empty value.", ZDateTime.Empty, testValue);
			Assert("Should not make any hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount);

			chargeRevRecognition.D3_RecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			dbHitsCount = Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName);
			testValue = testJob.GetRevenueRecognitionDate_ForTestOnly(testJob.GetRevenueRecognitionType(TestObjectCreator.CC1));
			AssertEquals("Should return value from JobChargeRevRecognition.", ZDateTime.BrettsBirthday, testValue);
			Assert("Should not make two hits to get Revenue Recognition Date", Factory.GetTableHitCount(JobChargeRevRecognitionSchema.Constants.TableName) <= dbHitsCount + 1);
		}

		public void TestGetRevenueRecognitionType()
		{
			Job testJob = Factory.NewJobForTesting<Job>();
			DummyJobHeaderParent parent = Factory.New<DummyJobHeaderParent>();

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.Road;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).ConsumerType = JobInvoicingConsumerTypes.Shipment;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsImport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsExport = false;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).IsDomestic = true;
			((DummyJobHeaderParentJobInvoicingSupporter)parent.InvoicingSupporter).TransportMode = Core.Constants.TransportModes.Road;

			testJob.Parent = parent;

			JobChargeRevRecognition chargeRevRecognition = testJob.GetOrCreateJobChargeRevRecognition_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.AWBIssueDate, ZDateTime.BrettsBirthday);

			string testValue = testJob.GetRevenueRecognitionType(null);
			AssertEquals("Should return no value.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue);

			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from registry.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue);

			AccChargeRevRecOverride chargeRevRecOverride = TestObjectCreator.CC1.RevenueRecOverrides.AddNew();
			chargeRevRecOverride.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			chargeRevRecOverride.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from charge code.", RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, testValue);

			chargeRevRecognition.D3_RecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from JobChargeRevRecognition.", RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob, testValue);

			chargeRevRecognition.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.CustomsClearanceDate;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from JobChargeRevRecognition.", RevenueRecognitionLookups.RecognitionDateOptionCodes.CustomsClearanceDate, testValue);

			chargeRevRecognition.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.JobClosure;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from JobChargeRevRecognition.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue);
			testValue = testJob.GetRevenueRecognitionType(null);
			AssertEquals("Should return value from JobChargeRevRecognition.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure, testValue);

			chargeRevRecognition.D3_RecognitionDate = AccountingConstants.RevenueRecognitionDateConstants.Immediate;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from JobChargeRevRecognition.", RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate, testValue);

			chargeRevRecognition.D3_RecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			testValue = testJob.GetRevenueRecognitionType(TestObjectCreator.CC1);
			AssertEquals("Should return value from charge code.", RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, testValue);
			testValue = testJob.GetRevenueRecognitionType(null);
			AssertEquals("Should return value from registry.", RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate, testValue);
		}

