		#region TestAskShouldUseImmediateRevenueRecognisedDate

		public void TestAskShouldUseImmediateRevenueRecognisedDate()
		{
			Job testJob = Factory.NewJobForTesting<Job>();
			var parent = Factory.New<ForwardingShipment>();

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			ZDateTime expectedArrivalDate = ZDateTime.Today.AddDays(-10);
			ZDateTime expectedDepartureDate = ZDateTime.Today.AddDays(-20);
			parent.JS_E_ARV = expectedArrivalDate;
			parent.JS_E_DEP = expectedDepartureDate;

			testJob.Parent = parent;
			testJob.ShouldUseImmediateRevenueRecognisedDate += new EventHandler<UserQueryEventArgs>(TestJob_ShouldUseImmediateRevenueRecognisedDate);

			IsShouldUseImmediateRevenueRecognisedDateHandlerCalled = false;
			ShouldUseImmediateRevenueRecognisedDateHandlerResponse = false;
			ZDateTime resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(TestObjectCreator.CC1);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", true, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", ZDateTime.Empty, resultDate);

			IsShouldUseImmediateRevenueRecognisedDateHandlerCalled = false;
			ShouldUseImmediateRevenueRecognisedDateHandlerResponse = true;
			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(TestObjectCreator.CC1);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", false, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", ZDateTime.Empty, resultDate);

			testJob.ResetPreviouseRespose_ShouldUseImmediateRevenueRecognisedDate();
			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", true, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", AccountingConstants.RevenueRecognitionDateConstants.Immediate, resultDate);

			IsShouldUseImmediateRevenueRecognisedDateHandlerCalled = false;
			ShouldUseImmediateRevenueRecognisedDateHandlerResponse = false;
			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", false, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", AccountingConstants.RevenueRecognitionDateConstants.Immediate, resultDate);

			TestObjectCreator.CreateTestPeriods(expectedDepartureDate);
			testJob.ResetPreviouseRespose_ShouldUseImmediateRevenueRecognisedDate();
			IsShouldUseImmediateRevenueRecognisedDateHandlerCalled = false;
			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(TestObjectCreator.CC1);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", false, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", expectedArrivalDate, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null);
			AssertEquals("Recognition date", expectedArrivalDate, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate);
			AssertEquals(ZDateTime.Empty, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(TestObjectCreator.CC1, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate, true);
			AssertEquals(expectedDepartureDate, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate);
			AssertEquals(ZDateTime.Empty, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate, true);
			AssertEquals(expectedDepartureDate, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, null, true);
			AssertEquals("Invalid combination of parameters, should return empty date.", ZDateTime.Empty, resultDate);

			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, null, false);
			AssertEquals("Should be value from registry", expectedArrivalDate, resultDate);

			AssertRecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture();

			void AssertRecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture()
			{
				parent.JS_E_ARV = ZDateTime.Today.AddDays(10);

				AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, false);
				resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, null, false);
				AssertEquals("Should be same as JS_E_ARV", ZDateTime.Today.AddDays(10).Date, resultDate.Date);

				AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, true);
				resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, null, false);
				AssertEquals("Should be today due to RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture is on", ZDateTime.Today.Date, resultDate.Date);

				AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty,
					AccountingConfigurationRegistry.Instance.RecognizeRevenueUsingCurrentDateWhenRevenueRecognitionDateInFuture.DefaultValue);
			}
		}

