			resultDate = testJob.AskShouldUseImmediateRevenueRecognisedDate(null, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate, true);
			AssertEquals("IsShouldUseImmediateRevenueRecognisedDateHandlerCalled", true, IsShouldUseImmediateRevenueRecognisedDateHandlerCalled);
			AssertEquals("Recognition date", AccountingConstants.RevenueRecognitionDateConstants.Immediate, resultDate);
		}

