		string GetStatusTriggerRevenueRecognitionWarning(string jobStatus, string jobNumber)
		{
			return string.Format(@"Setting '{0}' status on the job {1} results in recognizing its revenue.
You would not be able to change this job status until you save or cancel the changes.", jobStatus, jobNumber);
