		public void TestValidateEmptyRecognitionTypesOnJobClosing()
		{
			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);
			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line = invoice.Lines[0];
			line.AL_JH = job.PK;
			line.AL_ReverseDate = ZDateTime.Empty;
			line.AL_RevRecognitionType = "";

			AssertEquals("Precondition: line should not be recognized.", ZDateTime.Empty, line.AL_ReverseDate);

			job.OnCloseJobYesNoQuestion += new EventHandler<UserQueryEventArgs>(TestJob_OnCloseJobYesNoQuestion);
			job.OnCloseJobError += new ErrorMessageHandler(job_OnCloseJobError);

			IsOnCloseJobYesNoQuestionEventHandlerCalled = false;
			isOnCannotChangeStatusUserMessageCalled = false;
			IsOnCloseJobErrorEventHandlerCalled = false;
			job.JH_Status = JobHeaderStatus.Closed.Code;

			AssertEquals("OnCloseJobYesNoQuestion event handler should not be called.", false, IsOnCloseJobYesNoQuestionEventHandlerCalled);
			AssertNoWarnings(job.JH_StatusInfo);

			AssertEquals("isOnCannotChangeStatusUserMessageCalled event handler should not be called.", false, isOnCannotChangeStatusUserMessageCalled);
			AssertEquals("OnCloseJobError event handler should be called.", true, IsOnCloseJobErrorEventHandlerCalled);
			AssertContains("LastErrorMessageOnCloseJob", JobValidation.EmptyRevenueRecognitionTypeOnJobRelatedLineErrorMessage, LastErrorMessageOnCloseJob);
			AssertEquals("job.JH_Status shouldn't be changed due to recognition errors.", JobHeaderStatus.Working.Code, job.JH_Status);
			AssertEquals("line shouldn't be recognized.", ZDateTime.Empty, line.AL_ReverseDate);
		}

		[TestDate(2011, 12, 08)]
		public void TestRecognizeWholeJobOnJobStatusChange()
		{
			var job = Factory.NewJobForTesting<Job>();
			var cacheModifyValue = Env.Security.ModifyChargesforFinancialClosureJob.IsAllowed;
			var cachePostValue = Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed;
			using (new DisposableAction(() => Env.Security.ModifyChargesforFinancialClosureJob.IsAllowed = true, () => Env.Security.ModifyChargesforFinancialClosureJob.IsAllowed = cacheModifyValue))
			using (new DisposableAction(() => Env.Security.AllowPostingChargesforFinancialClosureJob.IsAllowed = true, () => Env.Security.ModifyChargesforFinancialClosureJob.IsAllowed = cachePostValue))
			{
				foreach (CodeDescriptionPair jobStatus in job.JobStatusList)
				{
					var isJobInvoicedStatus = jobStatus.Code == JobHeaderStatus.JobInvoiced.Code;
					var shouldRecognitionApply = jobStatus.Code == JobHeaderStatus.Closed.Code || jobStatus.Code == JobHeaderStatus.Complete.Code || jobStatus.Code == JobHeaderStatus.JobReadyForFinancialClosure.Code;
					AssertJob_OnCloseJobYesNoQuestion(jobStatus: jobStatus.Code, createAllPeriods: false, shouldRecognitionApply: shouldRecognitionApply, isJobInvoiced: isJobInvoicedStatus);
					AssertJob_OnCloseJobYesNoQuestion(jobStatus: jobStatus.Code, createAllPeriods: true, shouldRecognitionApply: shouldRecognitionApply, isJobInvoiced: isJobInvoicedStatus);
				}
			}
		}

		void AssertJob_OnCloseJobYesNoQuestion(string jobStatus, bool createAllPeriods, bool shouldRecognitionApply, bool isJobInvoiced)
		{
			string errorMessagePrefix = string.Format("Job status: '{0}', createAllPeriods: '{1}'. ", jobStatus, createAllPeriods);
			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_E_ARV = ZDateTime.Today.AddMonths(-3);
			if (createAllPeriods)
			{
				TestObjectCreator.CreateTestPeriods(shipment.JS_E_ARV);
			}
			else
			{
				TestObjectCreator.CreateTestPeriods(ZDateTime.Today);
			}

			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line1 = invoice.Lines[0];
			line1.AL_JH = job.PK;
			line1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;

			var line2 = (InvoicingLineBase)invoice.Lines.AddNew();
			line2.AL_JH = job.PK;
			line2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			var lineUnlinkedToCharge1 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge1.AL_JH = job.PK;
			lineUnlinkedToCharge1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.CustomsClearanceDate;

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge1.JR_AL_APLine = line1.PK;
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge2.JR_AL_APLine = line2.PK;

			invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line3 = invoice.Lines[0];
			line3.AL_JH = job.PK;
			line3.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			charge1.JR_AL_ARLine = line3.PK;

			var line4 = (InvoicingLineBase)invoice.Lines.AddNew();
			line4.AL_JH = job.PK;
			line4.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			charge2.JR_AL_ARLine = line4.PK;

			var lineUnlinkedToCharge2 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge2.AL_JH = job.PK;
			lineUnlinkedToCharge2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;

			var charge3 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);

			AssertEquals(errorMessagePrefix + "Precondition: line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
