			IsOnCloseJobYesNoQuestionEventHandlerCalled = false;
			OnCloseJobYesNoQuestionEventHandlerResponse = false;
			isOnCannotChangeStatusUserMessageCalled = false;
			IsOnCloseJobErrorEventHandlerCalled = false;

			string prevStatus = job.JH_Status;
			if (job.JH_Status == jobStatus)
			{
				job.JH_Status = "";
			}

			job.JH_Status = jobStatus;

			ZDateTime expectedFARDate = isJobInvoiced ? ZDateTime.Now : ZDateTime.Empty;

			if (isJobInvoiced)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
			}
			else if (shouldRecognitionApply)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: true, onCannotChangeStatusUserMessageCalled: false, expectedStatus: prevStatus, currentJobStatus: job.JH_Status, statusChanged: false);
			}
			else
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
			}

			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", expectedFARDate, line2.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line3.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line4.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			IsOnCloseJobYesNoQuestionEventHandlerCalled = false;
			OnCloseJobYesNoQuestionEventHandlerResponse = false;
			IsOnCloseJobErrorEventHandlerCalled = false;

			if (!isJobInvoiced)
			{
				line2.AL_ReverseDate = ZDateTime.Empty;
			}

			if (job.JH_Status == jobStatus)
			{
				job.JH_Status = "";
			}
			job.JH_Status = jobStatus;

			if (isJobInvoiced)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
			}
			else if (shouldRecognitionApply)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: true, onCloseJobErrorEventHandlerCalled: true, onCannotChangeStatusUserMessageCalled: false, expectedStatus: prevStatus, currentJobStatus: job.JH_Status, statusChanged: false);
			}
			else
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
			}

			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", expectedFARDate, line2.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line3.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line4.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			IsOnCloseJobYesNoQuestionEventHandlerCalled = false;
			OnCloseJobYesNoQuestionEventHandlerResponse = true;
			isOnCannotChangeStatusUserMessageCalled = false;
			IsOnCloseJobErrorEventHandlerCalled = false;
			if (!isJobInvoiced)
			{
				line2.AL_ReverseDate = ZDateTime.Empty;
			}

			if (job.JH_Status == jobStatus)
			{
				job.JH_Status = "";
			}
			job.JH_Status = jobStatus;

			if (isJobInvoiced)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", expectedFARDate, line2.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line3.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line4.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);
			}
			else if (shouldRecognitionApply)
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: true, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
				AssertHasWarning(job.JH_StatusInfo, GetStatusTriggerRevenueRecognitionWarning(job.JH_Status, job.JH_JobNum));
				ZDateTime expectedArivalDate = createAllPeriods ? shipment.JS_E_ARV : ZDateTime.Today;
				AssertEquals(errorMessagePrefix + "job.JH_Status should be changed.", jobStatus, job.JH_Status);
				AssertEquals(errorMessagePrefix + "line should be recognized.", expectedArivalDate, line1.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line should be recognized.", ZDateTime.Today, line2.AL_ReverseDate.Date);
				AssertEquals(errorMessagePrefix + "line should be recognized.", ZDateTime.Today, line3.AL_ReverseDate.Date);

				if (job.JH_Status == JobHeaderStatus.Complete.Code || job.JH_Status == JobHeaderStatus.JobReadyForFinancialClosure.Code)
				{
					AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line4.AL_ReverseDate.Date);
				}
				else
				{
					AssertEquals(errorMessagePrefix + "line should be recognized.", ZDateTime.Today, line4.AL_ReverseDate.Date);
				}
				AssertEquals(errorMessagePrefix + "line should be recognized.", ZDateTime.Today, lineUnlinkedToCharge1.AL_ReverseDate.Date);
				AssertEquals(errorMessagePrefix + "line should be recognized.", expectedArivalDate, lineUnlinkedToCharge2.AL_ReverseDate.Date);

				AssertEquals(errorMessagePrefix + "recognition date should be added against job.", expectedArivalDate, job.GetRevenueRecognitionDate_ForTestOnly(line1.AL_RevRecognitionType).Date);
				AssertEquals(errorMessagePrefix + "recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line2.AL_RevRecognitionType).Date);
				AssertEquals(errorMessagePrefix + "recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line3.AL_RevRecognitionType).Date);
				if (job.JH_Status == JobHeaderStatus.Complete.Code || job.JH_Status == JobHeaderStatus.JobReadyForFinancialClosure.Code)
				{
					AssertEquals(errorMessagePrefix + "recognition date should not be added against job.", ZDateTime.Empty, job.GetRevenueRecognitionDate_ForTestOnly(line4.AL_RevRecognitionType));
				}
				else
				{
					AssertEquals(errorMessagePrefix + "recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line4.AL_RevRecognitionType).Date);
				}
				AssertEquals(errorMessagePrefix + "recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge1.AL_RevRecognitionType).Date);
				AssertEquals(errorMessagePrefix + "recognition date should be added against job.", expectedArivalDate, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge2.AL_RevRecognitionType).Date);
			}
			else
			{
				AssertEventCalls(errorMessage: errorMessagePrefix, onCloseJobYesNoQuestionEventHandlerCalled: false, onCloseJobErrorEventHandlerCalled: false, onCannotChangeStatusUserMessageCalled: false, expectedStatus: jobStatus, currentJobStatus: job.JH_Status, statusChanged: true);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", expectedFARDate, line2.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line3.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, line4.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
				AssertEquals(errorMessagePrefix + "line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);
			}
		}

		void AssertEventCalls(string errorMessage, bool onCloseJobYesNoQuestionEventHandlerCalled, bool onCloseJobErrorEventHandlerCalled, bool onCannotChangeStatusUserMessageCalled, string expectedStatus, string currentJobStatus, bool statusChanged)
		{
			var onCloseJobYesNoQuestionErrorMsg = onCloseJobYesNoQuestionEventHandlerCalled ? "OnCloseJobYesNoQuestion event handler should be called." : "OnCloseJobYesNoQuestion event handler should not be called.";
			var onCloseJobErrordErrorMsg = onCloseJobErrorEventHandlerCalled ? "OnCloseJobError event handler should be called." : "OnCloseJobYesNoQuestion event handler should not be called.";
			var onCannotChangeStatusUserMessage = onCannotChangeStatusUserMessageCalled ? "isOnCannotChangeStatusUserMessageCalled event handler should be called." : "isOnCannotChangeStatusUserMessageCalled event handler should not be called.";
			var statusChangedMessage = statusChanged ? "job.JH_Status should be changed." : "job.JH_Status shouldn't be changed due to recognition errors.";

			AssertEquals(errorMessage + onCloseJobYesNoQuestionErrorMsg, onCloseJobYesNoQuestionEventHandlerCalled, IsOnCloseJobYesNoQuestionEventHandlerCalled);
			AssertEquals(errorMessage + onCloseJobErrordErrorMsg, onCloseJobErrorEventHandlerCalled, IsOnCloseJobErrorEventHandlerCalled);
			AssertEquals(errorMessage + onCannotChangeStatusUserMessage, onCannotChangeStatusUserMessageCalled, isOnCannotChangeStatusUserMessageCalled);
			AssertEquals(errorMessage + statusChangedMessage, expectedStatus, currentJobStatus);
		}

		void TestJob_OnCloseJobYesNoQuestion(object sender, UserQueryEventArgs e)
		{
			IsOnCloseJobYesNoQuestionEventHandlerCalled = true;
			e.Response = OnCloseJobYesNoQuestionEventHandlerResponse;
		}

		bool IsOnCloseJobYesNoQuestionEventHandlerCalled;
		bool OnCloseJobYesNoQuestionEventHandlerResponse;

		void TestJob_OnCannotChangeStatusUserMessage(object sender, UserMessageEventArgs e)
		{
			isOnCannotChangeStatusUserMessageCalled = true;
		}

		bool isOnCannotChangeStatusUserMessageCalled;

		void job_OnCloseJobError(Job job, string errorMessage)
		{
			IsOnCloseJobErrorEventHandlerCalled = true;
			LastErrorMessageOnCloseJob = errorMessage;
		}
		bool IsOnCloseJobErrorEventHandlerCalled;
		string LastErrorMessageOnCloseJob;

		#endregion

		public void TestJobClosedRevenueRecognitionTypeWhenJobCompletedAndClosed()
		{
			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);
			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line1 = invoice.Lines[0];
			line1.AL_JH = job.PK;
			line1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			var lineUnlinkedToCharge1 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge1.AL_JH = job.PK;
			lineUnlinkedToCharge1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge1.JR_AL_APLine = line1.PK;

			invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line2 = invoice.Lines[0];
			line2.AL_JH = job.PK;
			line2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			charge1.JR_AL_ARLine = line2.PK;

			var lineUnlinkedToCharge2 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge2.AL_JH = job.PK;
			lineUnlinkedToCharge2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, line2.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			job.JH_Status = JobHeaderStatus.Complete.Code;

			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, line2.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			job.JH_Status = JobHeaderStatus.Closed.Code;

			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, line1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, line2.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, lineUnlinkedToCharge1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, lineUnlinkedToCharge2.AL_ReverseDate.Date);

			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line1.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line2.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge1.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge2.AL_RevRecognitionType).Date);

			job.JH_Status = JobHeaderStatus.Complete.Code;
			line1.AL_ReverseDate = ZDateTime.Empty;
			line2.AL_ReverseDate = ZDateTime.Empty;
			lineUnlinkedToCharge1.AL_ReverseDate = ZDateTime.Empty;
			lineUnlinkedToCharge2.AL_ReverseDate = ZDateTime.Empty;
			job.ApplyRevenueRecognitionDateForWholeJob(out _);

			AssertEquals("Line should be recognised after re-completing job because the recognition date was previously set.", ZDateTime.Today, line1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after re-completing job because the recognition date was previously set.", ZDateTime.Today, line2.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after re-completing job because the recognition date was previously set.", ZDateTime.Today, lineUnlinkedToCharge1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after re-completing job because the recognition date was previously set.", ZDateTime.Today, lineUnlinkedToCharge2.AL_ReverseDate.Date);
		}

		[SuspendCriticalValidation]
		public void TestConfirmationToChangeJobStatusToCompletedOrClosed()
		{
			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			TestObjectCreator.CreateTestPeriods(ZDateTime.Today);
			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();

			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line1 = invoice.Lines[0];
			line1.AL_JH = job.PK;
			line1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge1.JR_AL_APLine = line1.PK;
			charge1.SetChargeValuesFromLinkedAPLineForTests();

			invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line2 = invoice.Lines[0];
			line2.AL_JH = job.PK;
			line2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge2.JR_AL_ARLine = line2.PK;
			charge2.SetChargeValuesFromLinkedARLineForTests();

			var lineUnlinkedToCharge1 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge1.AL_JH = job.PK;
			lineUnlinkedToCharge1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			var lineUnlinkedToCharge2 = (InvoicingLineBase)invoice.Lines.AddNew();
			lineUnlinkedToCharge2.AL_JH = job.PK;
			lineUnlinkedToCharge2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;

			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, line2.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = RevenueRecognitionLookups.JobTypeAdditionalCodes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			AssertEquals("job.JH_Status", JobHeaderStatus.Working.Code, job.JH_Status);
			job.OnCloseJobYesNoQuestion += TestJob_OnCloseJobYesNoQuestion;
			job.OnCannotChangeStatusUserMessage += TestJob_OnCannotChangeStatusUserMessage;
			isOnCannotChangeStatusUserMessageCalled = false;

			job.JH_Status = JobHeaderStatus.Complete.Code;
			AssertEquals("job.JH_Status", JobHeaderStatus.Complete.Code, job.JH_Status);
			AssertNoWarnings(job.JH_StatusInfo);
			AssertEquals("Cannot change Status message was not shown", false, isOnCannotChangeStatusUserMessageCalled);

			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, line2.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, lineUnlinkedToCharge2.AL_ReverseDate);

			job.JH_Status = JobHeaderStatus.Working.Code;
			AssertEquals("job.JH_Status", JobHeaderStatus.Working.Code, job.JH_Status);
			AssertNoWarnings(job.JH_StatusInfo);
			AssertEquals("Cannot change Status message was not shown", false, isOnCannotChangeStatusUserMessageCalled);

			line2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			lineUnlinkedToCharge2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			job.JH_Status = JobHeaderStatus.Complete.Code;
			AssertHasWarning(job.JH_StatusInfo, GetStatusTriggerRevenueRecognitionWarning(job.JH_Status, job.JH_JobNum));
			AssertEquals("job.JH_Status", JobHeaderStatus.Complete.Code, job.JH_Status);

			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertNotEquals("Line should be recognised.", ZDateTime.Empty, line2.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognised.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertNotEquals("Line should be recognised.", ZDateTime.Empty, line2.AL_ReverseDate);

			isOnCannotChangeStatusUserMessageCalled = false;

			job.JH_Status = JobHeaderStatus.Complete.Code;
			AssertHasWarning(job.JH_StatusInfo, GetStatusTriggerRevenueRecognitionWarning(job.JH_Status, job.JH_JobNum));
			AssertEquals("Cannot change Status message was not shown", false, isOnCannotChangeStatusUserMessageCalled);
			AssertEquals("job.JH_Status", JobHeaderStatus.Complete.Code, job.JH_Status);

			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, line1.AL_ReverseDate);
			AssertEquals("Line should be recognised after completing job.", ZDateTime.Today, line2.AL_ReverseDate.Date);
			AssertEquals("Line shouldn't be recognised after completing job.", ZDateTime.Empty, lineUnlinkedToCharge1.AL_ReverseDate);
			AssertEquals("Line should be recognised after completing job.", ZDateTime.Today, lineUnlinkedToCharge2.AL_ReverseDate.Date);

			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line2.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge2.AL_RevRecognitionType).Date);

			isOnCannotChangeStatusUserMessageCalled = false;

			job.JH_Status = JobHeaderStatus.Closed.Code;
			AssertHasWarning(job.JH_StatusInfo, GetStatusTriggerRevenueRecognitionWarning(job.JH_Status, job.JH_JobNum));
			AssertEquals("Cannot change Status message was shown", true, isOnCannotChangeStatusUserMessageCalled);
			AssertEquals("job.JH_Status was not changed", JobHeaderStatus.Complete.Code, job.JH_Status);

			isOnCannotChangeStatusUserMessageCalled = false;
			Factory.Save();

			job.JH_Status = JobHeaderStatus.Closed.Code;
			AssertHasWarning(job.JH_StatusInfo, GetStatusTriggerRevenueRecognitionWarning(job.JH_Status, job.JH_JobNum));
			AssertEquals("Cannot change Status message was not shown", false, isOnCannotChangeStatusUserMessageCalled);
			AssertEquals("job.JH_Status", JobHeaderStatus.Closed.Code, job.JH_Status);

			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, line1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised.", ZDateTime.Today, line2.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised after closing job.", ZDateTime.Today, lineUnlinkedToCharge1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognised.", ZDateTime.Today, lineUnlinkedToCharge2.AL_ReverseDate.Date);

			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(line1.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Today, job.GetRevenueRecognitionDate_ForTestOnly(lineUnlinkedToCharge1.AL_RevRecognitionType).Date);
		}

		public void TestIsRevenueRecognitionShouldBeDeferred()
		{
			Job job = Factory.NewJobForTesting<Job>();
			foreach (CodeDescriptionPair status in new JobHeaderStatusList())
			{
				job.JH_Status = status.Code;
				foreach (var field in typeof(RevenueRecognitionLookups.RecognitionDateOptionCodes).GetFields(System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public))
				{
					string recognitionOption = (string)field.GetValue(null);
					bool isJobCompleted = job.JH_Status == JobHeaderStatus.Complete.Code || job.JH_Status == JobHeaderStatus.JobReadyForFinancialClosure.Code;
					bool cantRecognitionCodeBeDeferred =
						new string[]
					{
							RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate,
							RevenueRecognitionLookups.RecognitionDateOptionCodes.JobClosure,
							RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate,
							RevenueRecognitionLookups.RecognitionDateOptionCodes.OldJob,
							RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction,
					}.Contains(recognitionOption) || isJobCompleted;

					string erroPrefix = string.Format("Job status: '{0}'. ", status);
					AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
					AssertEquals(erroPrefix + "EnableDeferredRevenueRecognition registry is true. IsRevenueRecognitionShouldBeDeferred for empty code.", !isJobCompleted, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(""));
					AssertEquals(erroPrefix + "EnableDeferredRevenueRecognition registry is true. IsRevenueRecognitionShouldBeDeferred for null code.", !isJobCompleted, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(null));
					AssertEquals(string.Format(erroPrefix + "EnableDeferredRevenueRecognition registry is true. IsRevenueRecognitionShouldBeDeferred for {0} code.", recognitionOption),
						!cantRecognitionCodeBeDeferred, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(recognitionOption));

					AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, false);
					AssertEquals(erroPrefix + "EnableDeferredRevenueRecognition registry is false. IsRevenueRecognitionShouldBeDeferred for empty code.", !isJobCompleted, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(""));
					AssertEquals(erroPrefix + "EnableDeferredRevenueRecognition registry is false. IsRevenueRecognitionShouldBeDeferred for null code.", !isJobCompleted, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(null));
					AssertEquals(string.Format(erroPrefix + "EnableDeferredRevenueRecognition registry is false. IsRevenueRecognitionShouldBeDeferred for {0} code.", recognitionOption),
						false, job.IsRevenueRecognitionShouldBeDeferred_ForTestOnly(recognitionOption));
				}
			}
		}

