		public void TestApplyRevenueRecognitionDateWithRecognizedCharges()
		{
			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);

			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_E_ARV = ZDateTime.Today.AddMonths(-3);
			shipment.JS_E_DEP = ZDateTime.Today.AddMonths(-3).AddDays(10);
			TestObjectCreator.CreateTestPeriods(shipment.JS_E_ARV);

			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 0M, null, TestObjectCreator.AUD, 0M, null);

			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Charge has zero amounts. Recognition date should not be applied.", 0, job.RevenueRecognitionCollection.Count);

			charge.JR_OSSellAmt = charge.JR_OSCostAmt = 100M;
			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Recognition date should be applied now.", 1, job.RevenueRecognitionCollection.Count);
			AssertEquals("Recognition dates should be correct.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));
			job.RevenueRecognitionCollection[0].Delete();

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, new RevenueRecognitionCollection());
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();
			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Charge recognition type is empty. Recognition date should not be applied.", 0, job.RevenueRecognitionCollection.Count);

			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, valuesForTest);
			job.ClearCacheOfRevenueRecognitionRegistryItems_ForTestsOnly();

			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Recognition date should be applied now.", 1, job.RevenueRecognitionCollection.Count);
			AssertEquals("Recognition dates should be correct.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));
			job.RevenueRecognitionCollection[0].Delete();

			var apLine = TestObjectCreator.CreateCostLine(charge, Factory.New<APInvoice>().PK);
			apLine.AL_ReverseDate = ZDateTime.Empty;
			apLine.AL_RevRecognitionType = "";
			AssertEquals("Precondition: charge.CostRecognition", "", charge.CostRecognition);
			AssertEquals("Precondition: charge.IsCostRecognized", false, charge.IsCostRecognized);
			AssertEquals("Precondition: charge.SellRecognition", RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate, charge.SellRecognition);
			AssertEquals("Precondition: charge.IsSellRecognized", false, charge.IsSellRecognized);
			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Recognition date should be applied now.", 1, job.RevenueRecognitionCollection.Count);
			AssertEquals("Recognition dates should be correct.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));
			job.RevenueRecognitionCollection[0].Delete();

			var arLine = TestObjectCreator.CreateRevenueLine(charge, Factory.New<ARInvoice>().PK);
			arLine.AL_ReverseDate = ZDateTime.Empty;
			arLine.AL_RevRecognitionType = "";
			AssertEquals("Precondition: charge.SellRecognition", "", charge.SellRecognition);
			AssertEquals("Precondition: charge.IsSellRecognized", false, charge.IsSellRecognized);
			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Charge recognition type is empty. Recognition date should not be applied.", 0, job.RevenueRecognitionCollection.Count);

			AssertEquals("Precondition: apLine.AL_ReverseDate", ZDateTime.Empty, apLine.AL_ReverseDate);
			AssertEquals("Precondition: arLine.AL_ReverseDate", ZDateTime.Empty, arLine.AL_ReverseDate);
			apLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			arLine.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate;
			job.ApplyRevenueRecognitionDate(charge);
			AssertEquals("Recognition date should be applied now.", 2, job.RevenueRecognitionCollection.Count);
			AssertEquals("Recognition dates should be correct.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));
			AssertEquals("Recognition dates should be correct.", shipment.JS_E_DEP, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate));
			AssertEquals("apLine.AL_ReverseDate", shipment.JS_E_ARV, apLine.AL_ReverseDate);
			AssertEquals("arLine.AL_ReverseDate", shipment.JS_E_DEP, arLine.AL_ReverseDate);
		}

		[SuspendCriticalValidation]
		public void TestApplyRevenueRecognitionDateForChargeForDeferredRecognition()
		{
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_E_ARV = ZDateTime.Today.AddMonths(-3);
			TestObjectCreator.CreateTestPeriods(shipment.JS_E_ARV);

			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_A_JOP = ZDateTime.Now.AddDays(-2);

			var invoiceAR = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M);
			var invoiceAP = TestObjectCreator.CreateInvoice(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M);

			invoiceAR.AH_PostDate = ZDateTime.Now.AddDays(-1);
			Factory.Save();

			invoiceAR.AH_FullyPaidDate = ZDateTime.Empty;
			invoiceAP.AH_FullyPaidDate = ZDateTime.Empty;

			foreach (var isRevRecognitionDeferred in new[] { false, true })
			{
				foreach (CodeDescriptionPair status in new JobHeaderStatusList())
				{
					AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
					job.JH_Status = status.Code;
					foreach (var revRecDate in job.RevenueRecognitionCollection)
					{
						revRecDate.Delete();
					}
					string errorPrefix = string.Format("Job Status: '{0}', isRevRecognitionDeferred: '{1}'. ", status, isRevRecognitionDeferred);
					AssertEquals(errorPrefix + "Precondition: any dates recognized.", 0, job.RevenueRecognitionCollection.Count);

					var lineAR = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 0M);
					lineAR.AL_JH = job.PK;
					lineAR.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

					var lineAP1 = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 0M);
					lineAP1.AL_JH = job.PK;
					lineAP1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
					var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
					charge1.JR_AL_APLine = lineAP1.PK;
					charge1.JR_AL_ARLine = lineAR.PK;
					Factory.Save();

					var lineAP2 = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 0M);
					lineAP2.AL_JH = job.PK;
					lineAP2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
					var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
					charge2.JR_AL_APLine = lineAP2.PK;

					job.RevenueRecognitionCollection.DeleteAll();
					AssertEquals(errorPrefix + "Precondition: any dates recognized.", 0, job.RevenueRecognitionCollection.Count);
					AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, isRevRecognitionDeferred);
					bool isJobCompleted = job.JH_Status == JobHeaderStatus.Complete.Code;
					bool isJobReadForFinancialColsure = job.JH_Status == JobHeaderStatus.JobReadyForFinancialClosure.Code;
					job.ApplyRevenueRecognitionDate(charge1);
					job.ApplyRevenueRecognitionDate(charge2);
					AssertEquals(errorPrefix + "Some recognition dates should not be applied for deffered recognition but not for CMP job.", !isJobCompleted && !isJobReadForFinancialColsure && isRevRecognitionDeferred ? 3 : 4, job.RevenueRecognitionCollection.Count);
					if (job.RevenueRecognitionCollection.Count == 4)
					{
						AssertEquals(errorPrefix + "ActualArrivalDate recognition date.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));
					}
					AssertEquals(errorPrefix + "Immediate recognition date.", AccountingConstants.RevenueRecognitionDateConstants.Immediate, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.Immediate));
					AssertEquals(errorPrefix + "JobOpenDate recognition date.", ZDateTime.Now.AddDays(-2).Date, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate).Date);
					AssertEquals(errorPrefix + "PostDateOfFirstARTransaction recognition date.", ZDateTime.Now.AddDays(-1).Date, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction).Date);
				}
			}
		}

		public void TestApplyRevenueRecognitionDateForLineForDeferredRecognition()
