		public void TestApplyRevenueRecognitionDateForWholeJob()
		{
			var parent = new DummyJobInvoicingPlugIn(Factory);
			ZDateTime expectedOperationsDate = ZDateTime.Today.AddMonths(-3);
			((DummyJobInvoicingPlugInJobInvoicingSupporter)parent.InvoicingSupporter).OperationsRevenueRecognitionDateByDirectionForTest = expectedOperationsDate;
			TestObjectCreator.CreateTestPeriods(expectedOperationsDate);

			Job job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_A_JOP = ZDateTime.Now.AddDays(-2);

			var invoiceAR = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M);
			var invoiceAP = TestObjectCreator.CreateInvoice(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M);

			invoiceAR.AH_PostDate = ZDateTime.Now.AddDays(-1);

			invoiceAR.AH_FullyPaidDate = ZDateTime.Empty;
			invoiceAP.AH_FullyPaidDate = ZDateTime.Empty;

			var lineAP = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 100M);
			lineAP.AL_JH = job.PK;
			lineAP.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge1.JR_AL_APLine = lineAP.PK;

			var lineAR1 = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineAR1.AL_JH = job.PK;
			lineAR1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.DeliveryDate;
			charge1.JR_AL_ARLine = lineAR1.PK;
			Factory.Save();

			job.PlugInData = parent;

			var lineAPUnlinkedToCharge = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 100M);
			lineAPUnlinkedToCharge.AL_JH = job.PK;
			lineAPUnlinkedToCharge.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			var lineAPUnlinkedToChargeWithEmptyRecType = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 100M);
			lineAPUnlinkedToChargeWithEmptyRecType.AL_JH = job.PK;
			lineAPUnlinkedToChargeWithEmptyRecType.AL_RevRecognitionType = "";

			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			var lineAR2 = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineAR2.AL_JH = job.PK;
			lineAR2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;
			charge2.JR_AL_ARLine = lineAR2.PK;

			var lineARUnlinkedToCharge = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineARUnlinkedToCharge.AL_JH = job.PK;
			lineARUnlinkedToCharge.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PickupDate;

			var lineARUnlinkedToChargeWithEmptyRecType = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineARUnlinkedToChargeWithEmptyRecType.AL_JH = job.PK;
			lineARUnlinkedToChargeWithEmptyRecType.AL_RevRecognitionType = "";

			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineAP.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineAR1.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineAR2.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineAPUnlinkedToCharge.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineARUnlinkedToCharge.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineAPUnlinkedToChargeWithEmptyRecType.AL_ReverseDate);
			AssertEquals("Precondition: line shouldn't be recognized.", ZDateTime.Empty, lineARUnlinkedToChargeWithEmptyRecType.AL_ReverseDate);

			job.ApplyRevenueRecognitionDateForWholeJob(out _);

			AssertEquals("Line should be recognized.", expectedOperationsDate.Date, lineAP.AL_ReverseDate.Date);
			AssertEquals("Line should not be recognized.", expectedOperationsDate.Date, lineAR1.AL_ReverseDate.Date);
			AssertEquals("Line should be recognized.", ZDateTime.Now.AddDays(-2).Date, lineAR2.AL_ReverseDate.Date);
			AssertEquals("Line should be recognized.", ZDateTime.Now.AddDays(-1).Date, lineAPUnlinkedToCharge.AL_ReverseDate.Date);
			AssertEquals("Line should be recognized.", expectedOperationsDate.Date, lineARUnlinkedToCharge.AL_ReverseDate.Date);
			AssertEquals("Line shouldn't be recognized.", ZDateTime.Empty, lineAPUnlinkedToChargeWithEmptyRecType.AL_ReverseDate);
			AssertEquals("Line shouldn't be recognized.", ZDateTime.Empty, lineARUnlinkedToChargeWithEmptyRecType.AL_ReverseDate);

			AssertEquals("Recognition dates should be added against job.", 6, job.RevenueRecognitionCollection.Count);
			AssertEquals("Recognition date should be added against job.", expectedOperationsDate.Date, job.GetRevenueRecognitionDate_ForTestOnly(lineAP.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", expectedOperationsDate.Date, job.GetRevenueRecognitionDate_ForTestOnly(lineAR1.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Now.AddDays(-2).Date, job.GetRevenueRecognitionDate_ForTestOnly(lineAR2.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", ZDateTime.Now.AddDays(-1).Date, job.GetRevenueRecognitionDate_ForTestOnly(lineAPUnlinkedToCharge.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", expectedOperationsDate.Date, job.GetRevenueRecognitionDate_ForTestOnly(lineARUnlinkedToCharge.AL_RevRecognitionType).Date);
			AssertEquals("Recognition date should be added against job.", AccountingConstants.RevenueRecognitionDateConstants.Immediate, job.GetRevenueRecognitionDate_ForTestOnly(charge2.CostRecognition).Date);
		}

