		[TestDate(2016, 04, 13)]
		public void TestApplyRevenueRecognitionWithNoCharges()
		{
			var periodHelper = new AccountingPeriodTestHelper(Factory);
			periodHelper.SetupSinglePeriod(1001, new ZDateTime(2016, 04, 01), new ZDateTime(2016, 04, 30));

			var valuesForTest = new RevenueRecognitionCollection();
			var setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.Import;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, valuesForTest);

			//Export
			var shipment1 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment1.JS_RL_NKOrigin = "AUSYD";
			shipment1.JS_RL_NKDestination = "USLAX";
			var job1 = TestObjectCreator.CreateJob(shipment1, false);
			AssertNotNull(job1.PlugInData);
			AssertEquals(Directions.Export, job1.MovementDirection);

			job1.JH_Status = JobHeaderStatus.InvoiceOnHold.Code;
			AssertEquals("Shouldn't create revenue recognition since JH_Status is not JobInvoiced", 0, job1.RevenueRecognitionCollection.Count);

			job1.JH_Status = JobHeaderStatus.JobInvoiced.Code;
			AssertEquals("Shouldn't create revenue recognition for Export shipment", 0, job1.RevenueRecognitionCollection.Count);

			//Import
			var shipment2 = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment2.JS_RL_NKOrigin = "USLAX";
			shipment2.JS_RL_NKDestination = "AUSYD";
			var job2 = TestObjectCreator.CreateJob(shipment2, false);
			AssertNotNull(job2.PlugInData);
			AssertEquals(Directions.Import, job2.MovementDirection);

			job2.JH_Status = JobHeaderStatus.InvoiceOnHold.Code;
			AssertEquals("Shouldn't create revenue recognition since JH_Status is not JobInvoiced", 0, job2.RevenueRecognitionCollection.Count);

			job2.JH_Status = JobHeaderStatus.JobInvoiced.Code;
			AssertEquals("Should create revenue recognition for Import shipment", 1, job2.RevenueRecognitionCollection.Count);
		}

		public void TestCalculateFARRevenueRecognitionDate_IsCached_UntilFactorySave()
		{
			var readonlyFactory = Factory.GetCachedReadOnlyFactory();
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();

			readonlyFactory.ResetDatabaseLoadCount();
			Factory.ResetDatabaseLoadCount();
			var date = job.CalculateFARRevenueRecognitionDate();
			AssertEquals("CalculateFARRevenueRecognitionDate() should query database on first call", 1, Factory.DatabaseLoadCount + readonlyFactory.DatabaseLoadCount);
			var date2 = job.CalculateFARRevenueRecognitionDate();
			AssertEquals("CalculateFARRevenueRecognitionDate() should be cached on subsequent calls", 1, Factory.DatabaseLoadCount + readonlyFactory.DatabaseLoadCount);
			var date3 = job.CalculateFARRevenueRecognitionDate();
			AssertEquals("CalculateFARRevenueRecognitionDate() should be cached on subsequent calls (really)", 1, Factory.DatabaseLoadCount + readonlyFactory.DatabaseLoadCount);

			Factory.Save();

			readonlyFactory.ResetDatabaseLoadCount();
			Factory.ResetDatabaseLoadCount();
			var date4 = job.CalculateFARRevenueRecognitionDate();
			AssertEquals("CalculateFARRevenueRecognitionDate() cache should be invalidated on Factory.Save()", 1, Factory.DatabaseLoadCount + readonlyFactory.DatabaseLoadCount);
			var date5 = job.CalculateFARRevenueRecognitionDate();
			AssertEquals("CalculateFARRevenueRecognitionDate() should be cached on subsequent calls (even after Factory.Save())", 1, Factory.DatabaseLoadCount + readonlyFactory.DatabaseLoadCount);
		}

		[TestDate(2022, 09, 13)]
		public void TestFARRevenueRecognitionDate_IsRecognized_AfterFactorySave()
		{
			var periodHelper = new AccountingPeriodTestHelper(Factory);
			periodHelper.SetupSinglePeriod(1001, new ZDateTime(2022, 09, 01), new ZDateTime(2022, 09, 30));

			var valuesForTest = new RevenueRecognitionCollection();
			var setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.BrokerCode = RevenueRecognitionLookups.BrokerCodes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, valuesForTest);

			var shipment = Factory.NewWithValidTestData<ForwardingShipment>();
			shipment.JS_RL_NKOrigin = "AUSYD";
			shipment.JS_RL_NKDestination = "USLAX";

			var job = TestObjectCreator.CreateJob(shipment, false);
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "desc", TestObjectCreator.AUD, 10m, null, TestObjectCreator.AUD, 20m, TestObjectCreator.LocalClient);
			Factory.Save();

			AssertEquals("Shouldn't create revenue recognition because no AR invoice is posted", 0, job.RevenueRecognitionCollection.Count);

			var newFactory = new BusinessObjectFactory() { RefreshEnabled = false };
			var newCreator = new TestObjectCreator(newFactory);
			var newJob = newFactory.Load<Job>(job.PK);

			var apInvoice = newCreator.CreateInvoice(typeof(APInvoice), newCreator.AUD, 1.0m, newCreator.AALSHI);
			apInvoice.SubmittedFromInvoicingForm = true;
			var apInvoiceLine = newCreator.CreateInvoiceLine(apInvoice, newCreator.AUD, 1M, 10M, 0M, 0M, 10M, 0M, 0M);
			apInvoiceLine.AL_AC = newCreator.CC1.PK;
			apInvoiceLine.AL_JH = newJob.PK;

			AssertEquals("Shouldn't create revenue recognition because no AR invoice is posted", 0, newJob.RevenueRecognitionCollection.Count);
			AssertEquals("AP line is not recognized", ZDateTime.Empty, apInvoiceLine.AL_ReverseDate);

			var arInvoice = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "AR001", TestObjectCreator.AUD, 20m, TestObjectCreator.LocalClient);
			var arInvoiceLine = TestObjectCreator.CreateRevenueLine(charge, arInvoice.PK);
			arInvoice.Lines.Add(arInvoiceLine);
			AssertEquals("AR line is not recognized", ZDateTime.Empty, arInvoiceLine.AL_ReverseDate);
			Factory.Save();
			AssertEquals("Should create revenue recognition because AR invoice is posted", 1, job.RevenueRecognitionCollection.Count);
			AssertEquals("AR line is recognized", ZDateTime.Today, arInvoiceLine.AL_ReverseDate);

			newFactory.Save();
			AssertEquals("AP line is recognized", ZDateTime.Today, apInvoiceLine.AL_ReverseDate);
		}

