		public void TestDefaultOverseasAgent_QuotedBooking()
		{
			var consignor = Factory.NewWithValidTestData<OrgHeader>();
			var consignorAR = Factory.NewWithValidTestData<OrgHeader>();
			var consignee = Factory.NewWithValidTestData<OrgHeader>();
			var consigneeAR = Factory.NewWithValidTestData<OrgHeader>();
			var deliveryAgent = Factory.NewWithValidTestData<OrgHeader>();
			var deliveryAgentAR = Factory.NewWithValidTestData<OrgHeader>();
			var sendingAgent = Factory.NewWithValidTestData<OrgHeader>();
			var sendingAgentAR = Factory.NewWithValidTestData<OrgHeader>();
			var receivingAgent = Factory.NewWithValidTestData<OrgHeader>();
			var receivingAgentAR = Factory.NewWithValidTestData<OrgHeader>();

			var consol = Factory.New<ForwardingConsol>();
			consol.JK_OA_SendingForwarderAddress = sendingAgent.MainAddress.PK;
			consol.JK_OA_ReceivingForwarderAddress = receivingAgent.MainAddress.PK;

			var shipment = QuotedBooking.CreateNewBooking(Factory);
			var quote = QuotedBooking.CreateNewQuote(Factory, QuotedBooking.QuoteState.ApprovedAndAccepted);
			var quotedBooking = QuotedBooking.New(quote.PK, shipment.PK, Factory);

			var job = new Loader(quotedBooking.Booking).TryLoadOrCreateWithoutMutexForTestOnly();

			// Export
			quotedBooking.Booking.JS_RL_NKOrigin = "AUSYD";
			quotedBooking.Booking.JS_RL_NKDestination = "NZAKL";
			AssertOverseasAgent(job, null);

			quotedBooking.Booking.JS_IsForwardRegistered = true;
			quotedBooking.Booking.Consols.Add(consol);
			AssertOverseasAgent(job, receivingAgent);

			receivingAgent.SetRelatedParty(receivingAgentAR, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			AssertOverseasAgent(job, receivingAgentAR);

			quotedBooking.Booking.JS_OH_DeliveryAgent = deliveryAgent.PK;
			AssertOverseasAgent(job, deliveryAgent);

			deliveryAgent.SetRelatedParty(deliveryAgentAR, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			AssertOverseasAgent(job, deliveryAgentAR);

			quotedBooking.Booking.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			AssertOverseasAgent(job, deliveryAgentAR);

			consol.JK_AgentType = Core.Constants.AgentType.Direct;
			AssertOverseasAgent(job, deliveryAgentAR);

			consignee.OH_IsDebtor = true;
			AssertOverseasAgent(job, consignee);

			consol.JK_AgentType = Core.Constants.AgentType.Agent;
			AssertOverseasAgent(job, deliveryAgentAR);

			consignee.CompanyData.OB_EXBillAgentChargesDirect = true;
			AssertOverseasAgent(job, consignee);

			consignee.SetRelatedParty(consigneeAR, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			AssertOverseasAgent(job, consigneeAR);

			// Import / CrossTrade
			quotedBooking.Booking.JS_RL_NKOrigin = "USLAX";
			quotedBooking.Booking.JS_RL_NKDestination = "AUSYD";
			AssertOverseasAgent(job, sendingAgent);

			sendingAgent.SetRelatedParty(sendingAgentAR, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			AssertOverseasAgent(job, sendingAgentAR);

			quotedBooking.Booking.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			AssertOverseasAgent(job, sendingAgentAR);

			consignor.CompanyData.OB_IMBillAgentChargesDirect = true;
			AssertOverseasAgent(job, consignor);

			consignor.SetRelatedParty(consignorAR, RelatedPartyTypeList.Codes.ARNettingGroup, RelatedPartyDirectionList.Codes.Forwarder);
			AssertOverseasAgent(job, consignorAR);
		}

