		public void AssertDefaultAgentOnCrossTradeWithRegistry(bool isConsignor)
		{
			var job = TestJob;
			var org1 = TestObjectCreator.CreateOrgHeader("ORG1", false, false);
			var org2 = TestObjectCreator.CreateOrgHeader("ORG2", false, false);
			var direction = isConsignor ? RelatedPartyDirectionList.Codes.Pickup : RelatedPartyDirectionList.Codes.Delivery;
			var partyType = RelatedPartyTypeList.Codes.InvoiceFreightJobsTo;

			Consignee = TestObjectCreator.CreateOrgHeader("CNEE", false, true);
			Consignor = TestObjectCreator.CreateOrgHeader("CNOR", false, true);

			Shipment = Factory.New<ForwardingShipment>();
			Shipment.ConsigneeDocumentaryAddress.OrganisationPK = Consignee.PK;
			Shipment.ConsignorDocumentaryAddress.OrganisationPK = Consignor.PK;
			Shipment.JS_RL_NKOrigin = "NZAKL";
			Shipment.JS_RL_NKDestination = "USLAX";
			Shipment.JS_TransportMode = "AIR";
			Shipment.JS_OH_DeliveryAgent = ZGuid.Empty;

			using (AccountingMasterFilesRegistry.Instance.EnableCrossTradeDebtorDefaultingFunctionality.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
			{
				var relateParty1 = isConsignor ? Consignor.AllRelatedParties.AddNew() : Consignee.AllRelatedParties.AddNew();
				relateParty1.PR_PartyType = partyType;
				relateParty1.PR_OH_RelatedParty = org1.PK;
				relateParty1.PR_GC = GlbCompany.CurrentCompany.PK;
				relateParty1.PR_FreightDirection = direction;

				job = Factory.NewJobForTesting<Job>();
				job.PlugInData = Shipment;
				job.SetDefaultsForJob();
				var expectValue = isConsignor ? job.LocalChargesPK : job.AgentCollectPK;
				AssertEquals("Should default to the relatedParty1", org1.PK, expectValue);

				//Same Job Type and Direction of PIC. Different Company Level (COM/ENT)
				var relateParty2 = isConsignor ? Consignor.AllRelatedParties.AddNew() : Consignee.AllRelatedParties.AddNew();
				relateParty2.PR_PartyType = partyType;
				relateParty2.PR_OH_RelatedParty = org2.PK;
				relateParty2.PR_GC = ZGuid.Empty;
				relateParty2.PR_FreightDirection = direction;

				job = Factory.NewJobForTesting<Job>();
				job.PlugInData = Shipment;
				job.SetDefaultsForJob();
				expectValue = isConsignor ? job.LocalChargesPK : job.AgentCollectPK;
				AssertEquals("Should default to the relatedParty which have Company Level of COM", org1.PK, expectValue);

				//Same Job Type and Direction of PAD. Different Company Level (COM/ENT)
				relateParty1.PR_FreightDirection = RelatedPartyDirectionList.Codes.PickupAndDelivery;
				relateParty2.PR_FreightDirection = RelatedPartyDirectionList.Codes.PickupAndDelivery;

				job = Factory.NewJobForTesting<Job>();
				job.PlugInData = Shipment;
				job.SetDefaultsForJob();
				expectValue = isConsignor ? job.LocalChargesPK : job.AgentCollectPK;
				AssertEquals("Should default to the relatedParty which have Company Level of COM", org1.PK, expectValue);

				//Same Job Type and Company Level. Different Direction (PAD/PIC)
				relateParty1.PR_FreightDirection = RelatedPartyDirectionList.Codes.PickupAndDelivery;
				relateParty2.PR_FreightDirection = direction;
				relateParty2.PR_GC = GlbCompany.CurrentCompany.PK;

				job = Factory.NewJobForTesting<Job>();
				job.PlugInData = Shipment;
				job.SetDefaultsForJob();
				expectValue = isConsignor ? job.LocalChargesPK : job.AgentCollectPK;
				AssertEquals("Should defailt to the relatedParty which have direction of PIC", org2.PK, expectValue);
			}
		}

		public void TestGetInvoiceTypeModule()
		{
			foreach (JobInvoicingConsumerType consumerType in JobInvoicingConsumerTypes.New())
			{
				var job = Factory.NewJobForTesting<Job>();
				var plugin = new DummyJobInvoicingPlugIn(Factory);
				var supporter = (DummyJobInvoicingPlugInJobInvoicingSupporter)plugin.InvoicingSupporter;
				supporter.SetConsumerType(consumerType);
				job.PlugInData = plugin;

				if (consumerType == JobInvoicingConsumerTypes.Shipment || consumerType == JobInvoicingConsumerTypes.QuotedBooking)
				{
					AssertEquals(string.Format("Should be FWD for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.FWD, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.Brokerage)
				{
					AssertEquals(string.Format("Should be CUS for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.CUS, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.CFSShipment)
				{
					AssertEquals(string.Format("Should be CFS for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.CFS, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.CFSLoadList)
				{
					AssertEquals(string.Format("Should be CFS for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.CFS, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.TransportBookingConsignment)
				{
					AssertEquals(string.Format("Should be TCN for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.TCN, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.LocalCartage)
				{
					AssertEquals(string.Format("Should be TPT for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.TPT, job.GetInvoiceTypeModule());
				}
				else if (consumerType == JobInvoicingConsumerTypes.ImporterSecurityFiling)
				{
					AssertEquals(string.Format("Should be ISF for the {0} ConsumerType.", supporter.ConsumerType.Code), InvoiceTypeModuleList.Codes.ISF, job.GetInvoiceTypeModule());
				}
				else
				{
					AssertEquals(string.Format("GetInvoiceTypeModule should return empty string for the {0} consumerType", supporter.ConsumerType.Code), string.Empty, job.GetInvoiceTypeModule());
				}
			}
		}

		public void TestMovementDirection()
		{
			AssertMovementDirection("USLAX", "AUSYD", Directions.Import);
			AssertMovementDirection("AUSYD", "USLAX", Directions.Export);
			AssertMovementDirection("AUSYD", "AUMEL", Directions.Domestic);
			AssertMovementDirection("KRSEL", "USLAX", Directions.CrossTrade);

			var countryKR = Factory.LoadTop1<RefCountry>(new ZQuery(RefCountrySchema.RN_Code, Core.Constants.CountryCodes.KoreaSouth));
			FreightDataRegistry.Instance.CommunityRegionsForDirectionCalculation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, new Guid[] { countryKR.PK.ToGuid() });
			AssertMovementDirection("KRSEL", "AEABU", Directions.Export);
			AssertMovementDirection("AEABU", "KRSEL", Directions.Import);

			var countryUS = Factory.LoadTop1<RefCountry>(new ZQuery(RefCountrySchema.RN_Code, Core.Constants.CountryCodes.UnitedStates));
			FreightDataRegistry.Instance.CommunityRegionsForDirectionCalculation.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, new Guid[] { countryUS.PK.ToGuid() });
			AssertMovementDirection("KRSEL", "AEABU", Directions.CrossTrade);
		}

