		public void TestIsJobDescriptionOverridenSetter()
		{
			var jobInvoiceDescriptionConfig = AccountingConfigurationRegistry.Instance.JobInvoiceDescriptionConfiguration.Value;
			var item = jobInvoiceDescriptionConfig.AddNew();
			item.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			item.Mode = Core.Constants.TransportModes.Sea;
			item.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			item.InvoiceDescription = "Defaulted Value";
