			job.IsJobDescriptionOverriden = true;

			AssertEquals("the job description persistent property is now set", "Defaulted Value", job.JH_Description);
			AssertEquals("precondition, the display job description returns the peristent value", "Defaulted Value", job.JobDescription);
		}

