		public void AssertLoadJobWithAdditionalJobsDBHits(int childShipmentsCount, int childJobCount)
		{
			var shipment = TestObjectCreator.CreateShipment("S0000");
			shipment.JS_PackingMode = Constants.ContainerModes.BuyersConsol;
			var job = TestObjectCreator.CreateJob(shipment, false);
			job.JH_OA_LocalChargesAddr = TestObjectCreator.LocalClient.Addresses[0].PK;
			job.LocalCharges.CompanyData.OB_ARBuyersConsolInvoicingStyle = Constants.ConsolInvoicingStyles.Master;
			TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 10, 10);
			var shipments = new List<IJobInvoicingPlugIn>();
			for (int i = 0; i < childShipmentsCount; i++)
			{
				var childShipment = TestObjectCreator.CreateShipment("S0000_" + i);
				var childJob = TestObjectCreator.CreateJob(childShipment, false);
				TestObjectCreator.CreateCharge(childJob, TestObjectCreator.CC1, 10, 10);
				for (int j = 0; j < childJobCount; j++)
				{
					var childJob2 = TestObjectCreator.CreateJob(string.Format("Job {0}_{1}", i, j), TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
					childJob2.JH_JH_ParentJob = childJob.PK;
					TestObjectCreator.CreateCharge(childJob2, TestObjectCreator.CC1, 10, 10);
				}
				shipments.Add(childShipment);
			}
			shipment.CoLoadShipments.AddRange(shipments);
			AssertEquals("Precondition: Count of AdditionalJobsToShowChargesFor", childShipmentsCount, ((IJobInvoicingPlugInAdditionalJobs)shipment).AdditionalJobsToShowChargesFor.Length);

			Factory.SetContext(BusinessContext.InvoicingPlugInGUI);
			Factory.Save();

			var newFactory = new BusinessObjectFactory();
			newFactory.ResetDatabaseLoadCount();
			var jobInNewFactory = new Loader(newFactory, shipment).Load(true);
			AssertEquals("DatabaseLoadCount shouldn't depend on child jobs count", 8, newFactory.DatabaseLoadCount);
			AssertEquals("PostCondition: Charge count", childShipmentsCount * (childJobCount + 1) + 1, jobInNewFactory.Charges.Count);
		}

