		#region Test GetDebtorPK

		public void TestGetDebtorPKForGatewayConsolConsumerType()
		{
			var prepaidCharge = Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_ChargeGroup, ChargeCodeGroupList.Codes.Origin).AddToFilter(AccChargeCodeSchema.AC_GC, GlbCompany.CurrentCompany.PK));
			var collectCharge = Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_ChargeGroup, ChargeCodeGroupList.Codes.Destination).AddToFilter(AccChargeCodeSchema.AC_GC, GlbCompany.CurrentCompany.PK));
			var variableCharge1 = Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_ChargeGroup, ChargeCodeGroupList.Codes.Insurance).AddToFilter(AccChargeCodeSchema.AC_GC, GlbCompany.CurrentCompany.PK));
			var variableCharge2 = Factory.LoadTop1<AccChargeCode>(new ZQuery(AccChargeCodeSchema.AC_ChargeGroup, ChargeCodeGroupList.Codes.Freight).AddToFilter(AccChargeCodeSchema.AC_GC, GlbCompany.CurrentCompany.PK));

			var sendingAgent = GlbCompany.CurrentCompany.OrgProxy;
			var receivingAgent = Factory.NewWithValidTestData<OrgHeader>();
			var localClient = TestObjectCreator.LocalClient;

			var consol = TestObjectCreator.CreateConsol("USCHI", "AUSYD", "C10011991");
			consol.JK_AgentType = Constants.AgentType.Agent;
			consol.JK_OA_ReceivingForwarderAddress = receivingAgent.MainAddress.PK;
			consol.JK_OA_SendingForwarderAddress = sendingAgent.MainAddress.PK;
			consol.JK_SendingForwarderHandlingType = AgentStatusList.Codes.GatewayAgent;
			consol.JK_PrepaidCollect = Constants.PaymentType.Prepaid;

			var port = Factory.NewWithValidTestData<OrgAppointedAgentPorts>();
			port.O5_PortOrCountry = "USCHI";
			port.O5_AgentDirection = AgentDirectionList.Codes.Both;
			port.O5_AirAgentStatus = AgentStatusList.Codes.GatewayAgent;
			consol.SendingForwarder.AppointedGatewayAgentPorts.Add(port);

			new JobHeader.Loader(consol).TryLoadOrCreateWithoutMutexForTestOnly();

			Factory.Save();

			Assert("Pre-condition", consol.IsGateway());

			var job = Factory.LoadTop1<Job>(new ZQuery(JobHeaderSchema.JH_ParentID, consol.PK));

			AssertEquals("Origin charges should always return the sending agent", sendingAgent.PK, job.GetDebtorPK(prepaidCharge, string.Empty));
			AssertEquals("Destination charges should always return the receiving agent", receivingAgent.PK, job.GetDebtorPK(collectCharge, string.Empty));
			AssertEquals("Expected sending agent as the consol payment type is prepaid", sendingAgent.PK, job.GetDebtorPK(variableCharge1, string.Empty));
			AssertEquals(sendingAgent.PK, job.GetDebtorPK(variableCharge2, string.Empty));

			consol.JK_PrepaidCollect = Constants.PaymentType.Collect;

			AssertEquals("Expected receiving agent as the consol payment type is collect", receivingAgent.PK, job.GetDebtorPK(variableCharge1, string.Empty));
			AssertEquals(receivingAgent.PK, job.GetDebtorPK(variableCharge2, string.Empty));

			consol.JK_PrepaidCollect = ZString.Empty;
			job.JH_OA_LocalChargesAddr = localClient.MainAddress.PK;

			AssertEquals("Origin charges should always return the sending agent", sendingAgent.PK, job.GetDebtorPK(prepaidCharge, string.Empty));
			AssertEquals("Destination charges should always return the receiving agent", receivingAgent.PK, job.GetDebtorPK(collectCharge, string.Empty));
			AssertEquals("Cannot default if the consol has no payment mode", ZGuid.Empty, job.GetDebtorPK(variableCharge1, string.Empty));
			AssertEquals(ZGuid.Empty, job.GetDebtorPK(variableCharge2, string.Empty));
		}

