		public void TestDeniedRateSecurityCheckPointDBHitsAndChargeLoading()
		{
			var job = TestObjectCreator.Job1;
			TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, 10, 10);
			TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, 20, 20);
			TestObjectCreator.CreateCharge(job, TestObjectCreator.CC3, 30, 40);

			Factory.Save();

			ReleaseFactory();

			var jobInNewFactory = Factory.Load<Job>(job.PK);
			var anyJobChargeInNewFactory = Factory.Load<Charge>(job.Charges[1].PK);
			AssertNotNull(anyJobChargeInNewFactory);
			var allChargesInFactoryQuery = new ZQuery();
			allChargesInFactoryQuery.FetchOnlyFromLocalCache = true;
			AssertNotNull(anyJobChargeInNewFactory);
			AssertEquals("Precondition: only one charge loaded in Factory", 1, Factory.Load<Charge>(allChargesInFactoryQuery).Length);

			Factory.ResetDatabaseLoadCount();
			var checkPoint = jobInNewFactory.DeniedRateSecurityCheckPoint;
			int cachedDBHitCount = 2;
			int notCachedDbHit = 1;
			AssertEquals("not charge related db hits + db hit to check not loaded charges in db", cachedDBHitCount + notCachedDbHit, Factory.DatabaseLoadCount);

			Factory.ResetDatabaseLoadCount();
			checkPoint = jobInNewFactory.DeniedRateSecurityCheckPoint;
			AssertEquals("DeniedRateSecurityCheckPoint is cached, should not be loaded", 0, Factory.DatabaseLoadCount);
			jobInNewFactory.JH_Description = "update CacheVersion to re-load DeniedRateSecurityCheckPoint";
			AssertEquals(checkPoint, jobInNewFactory.DeniedRateSecurityCheckPoint);
			AssertEquals("DeniedRateSecurityCheckPoint reload; Charges didn't load fully,so it try to load by SQL.", 1, Factory.DatabaseLoadCount);
			AssertEquals("should not load more charges in Factory", 1, Factory.Load<Charge>(allChargesInFactoryQuery).Length);

			AssertEquals(3, jobInNewFactory.Charges.Count);
			Factory.ResetDatabaseLoadCount();
			jobInNewFactory.JH_Description = "update CacheVersion to re-load DeniedRateSecurityCheckPoint";
			AssertEquals("DeniedRateSecurityCheckPoint reload;Charges loaded fully", 0, Factory.DatabaseLoadCount);

			ReleaseFactory();

			var jobInNewFactory2 = Factory.Load<Job>(job.PK);
			AssertEquals("Charges.Count", 3, jobInNewFactory2.Charges.Count);
			AssertEquals("all charges loaded in Factory", 3, Factory.Load<Charge>(allChargesInFactoryQuery).Length);

			Factory.ResetDatabaseLoadCount();
			checkPoint = jobInNewFactory2.DeniedRateSecurityCheckPoint;
			AssertEquals("not charge related db hits only", cachedDBHitCount, Factory.DatabaseLoadCount);

			Factory.ResetDatabaseLoadCount();
			checkPoint = jobInNewFactory2.DeniedRateSecurityCheckPoint;
			AssertEquals("no db hit for charge table if charges already loaded", 0, Factory.DatabaseLoadCount);
		}

		public void TestUnpostedConsolCostsLinkedToThisJob()
		{
			//Setup data
			var shipment1 = TestObjectCreator.CreateShipment("S0001", "AUSYD", "USLAX");
			shipment1.JS_ActualWeight = 151.73m;
			shipment1.JS_ActualChargeable = 13m;
			var job1 = TestObjectCreator.CreateJob(shipment1, TestObjectCreator.LocalClient, 0, TestObjectCreator.Agent, 0);
			job1.Charges.RemoveAll();

			//Creating Consol Test
			var consol = Factory.New<ForwardingConsol>();
			consol.Shipments.Add(shipment1);

			var listing = new ApportionmentListing(Factory, consol);

			//ConsolCost1
			JobConsolCost costCC1 = listing.CostsCollection.TryAddNew();
			costCC1.E6_AC_ChargeCode = TestObjectCreator.CC1.PK;
			costCC1.E6_OSCostAmount = 50m;

			costCC1.ApportionmentCharges[0].JR_IsUsedForApportionment = true;
			costCC1.ApportionmentCharges[0].JR_E6 = costCC1.PK;

			//ConsolCost2
			JobConsolCost costCC2 = listing.CostsCollection.TryAddNew();
			costCC2.E6_AC_ChargeCode = TestObjectCreator.CC2.PK;
			costCC2.E6_OSCostAmount = 50m;

			costCC2.ApportionmentCharges[0].JR_IsUsedForApportionment = true;
			costCC2.ApportionmentCharges[0].JR_E6 = costCC2.PK;

			//ConsolCost3
			JobConsolCost costCC3 = listing.CostsCollection.TryAddNew();
			costCC3.E6_AC_ChargeCode = TestObjectCreator.CC3.PK;
			costCC3.E6_OSCostAmount = 50m;

			costCC3.ApportionmentCharges[0].JR_IsUsedForApportionment = true;
			costCC3.ApportionmentCharges[0].JR_E6 = costCC3.PK;

			//Before Posting
			Factory.Save();
			AssertEquals("UnpostedConsolCost count should be 3", 3, job1.UnpostedConsolCostsLinkedToThisJob.ToList().Count);

			//After Posting one cost
			TestObjectCreator.PostCost(job1.Charges[0], new Guid("3d97ede5-f9a5-4de3-875c-fc6c85debcfb"));
			AssertEquals("UnpostedConsolCost count should be 2", 2, job1.UnpostedConsolCostsLinkedToThisJob.ToList().Count);
		}

		public void TestCompanyDataConcurrencyException_ShouldDisplayWarningMessage()
		{
			var orgFactory = new BusinessObjectFactory();
			var testObjCreator = new TestObjectCreator(orgFactory);
			var newOrganisation = orgFactory.NewWithValidTestData<OrgHeader>();
			newOrganisation.OH_Code = "ABCABC";
			newOrganisation.CompanyData.OB_GC = testObjCreator.NonCurrentCompany.PK;
			orgFactory.Save();

			var shipment = testObjCreator.CreateShipment("", false);
			var shipmentJob = testObjCreator.CreateJob(shipment, false, true);
			var charge = testObjCreator.CreateCharge(shipmentJob, testObjCreator.CC1, 100m, 100m);
			charge.JR_OH_SellAccount = newOrganisation.PK;
			AssertEquals("CompanyData of the sellAccount is not in DB", false, charge.SellAccount.CompanyData.IsInDatabase);

			var newFactory = new BusinessObjectFactory();
			newFactory.RefreshEnabled = false;
			var orgInNewFactory = newFactory.Load<OrgHeader>(newOrganisation.PK);
			orgInNewFactory.CompanyData.OB_IsDebtor = true;
			orgInNewFactory.CompanyData.AccARExchangeRateConfigurations.SetExRate(ledgerCode: "AR", jobType: "SHP", serviceDirection: "ALL", transportMode: "ALL", exRateType: "SEL");
			newFactory.Save();

			var countOfAccARExchangeRateConfigurations = orgInNewFactory.CompanyData.AccARExchangeRateConfigurations.Count;
			Assert("CompanyData has AccARExchangeRateConfiguration", countOfAccARExchangeRateConfigurations > 0);

			try
			{
				orgFactory.Save();
			}
			catch (Exception ex)
			{
				Assert("No notification before handler", UnitTestUserNotification.Instance.LastMessage.WasNone);
				ZExceptionReporting.HandleSaveException(ex);
				Assert("Notification shown after handler", UnitTestUserNotification.Instance.LastMessage.WasInformation);
				AssertEquals("While you were working, the organization ABCABC had its AR/AP information updated. The system will now need to reload this information. Press OK to have this information loaded and then try saving again.", UnitTestUserNotification.Instance.LastMessage.Text);
				UnitTestUserNotification.Instance.ClearMessagesAndAnswers();
				Assert("Shipment is not saved", !shipment.IsInDatabase);
			}

			AssertEquals("AccARExchangeRateConfigurations should not be deleted", countOfAccARExchangeRateConfigurations, orgInNewFactory.CompanyData.AccARExchangeRateConfigurations.Count);

			orgFactory.Save();
			Assert("Shipment is saved successfully", shipment.IsInDatabase);
		}

