		[TestDate(2012, 08, 01)]
		public void TestRevenueIsRecognizedWhenJobStatusIsCompleteAndDeferredRevRecognitionIsEnabled()
		{
			TestObjectCreator.CreateTestPeriods(new ZDateTime(ZDateTime.Today.Year, 1, 1));
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);

			RevenueRecognitionCollection valuesForTest = new RevenueRecognitionCollection();
			RevenueRecognition setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, valuesForTest);

			CommonShipment shipment = Factory.NewWithValidTestData<CommonShipment>();
			shipment.JS_E_ARV = ZDateTime.Today.AddMonths(-3);
			shipment.JS_E_DEP = ZDateTime.Today.AddMonths(-4);

			Job job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_A_JOP = ZDateTime.Now.AddDays(-2);

			var invoiceAR = TestObjectCreator.CreateInvoice(typeof(ARInvoice), "1234", TestObjectCreator.AUD, 1M);
			var invoiceAP = TestObjectCreator.CreateInvoice(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M);

			invoiceAR.AH_PostDate = ZDateTime.Today.AddDays(-1);

			invoiceAR.AH_FullyPaidDate = ZDateTime.Empty;
			invoiceAP.AH_FullyPaidDate = ZDateTime.Empty;

			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, true);
			foreach (var revRecDate in job.RevenueRecognitionCollection)
			{
				revRecDate.Delete();
			}
			string errorPrefix = string.Format("Job Status: '{0}', isRevRecognitionDeferred: {1}.", JobHeaderStatus.Working.Code, true);
			AssertEquals(errorPrefix + "Precondition: any dates recognized.", 0, job.RevenueRecognitionCollection.Count);

			var lineAR = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 100M);
			lineAR.AL_JH = job.PK;
			lineAR.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.JobOpenDate;

			var lineAP1 = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 100M);
			lineAP1.AL_JH = job.PK;
			lineAP1.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;

			var charge1 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge1.JR_AL_APLine = lineAP1.PK;
			charge1.JR_AL_ARLine = lineAR.PK;

			var lineAP2 = TestObjectCreator.CreateInvoiceLine(invoiceAP, TestObjectCreator.AUD, 1M, 100M);
			lineAP2.AL_JH = job.PK;
			lineAP2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate;
			var charge2 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge2.JR_AL_APLine = lineAP2.PK;

			job.JH_Status = JobHeaderStatus.Complete.Code;

			AssertEquals("Revenue Recognition Record  Count", 3, job.RevenueRecognitionCollection.Count);
			AssertEquals("ActualArrivalDate recognition date.", shipment.JS_E_ARV, job.GetRevenueRecognitionDate_ForTestOnly(RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualArrivalDate));

			valuesForTest = new RevenueRecognitionCollection();
			setting = valuesForTest.AddNew();
			setting.JobType = JobInvoicingConsumerTypes.Shipment.Code;
			setting.DirectionCode = Constants.FreightShipmentDirection.Code.All;
			setting.Mode = Core.Constants.TransportModes.All;
			setting.RecognitionDateOptionCode = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate;
			AccountingConfigurationRegistry.Instance.RevenueRecognitionSetup.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, valuesForTest);

			AddChargeAndAssertD3Record(shipment, job, invoiceAR, true, JobHeaderStatus.Complete.Code, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate, shipment.JS_E_DEP);
			AddChargeAndAssertD3Record(shipment, job, invoiceAR, true, JobHeaderStatus.Working.Code, RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate, ZDateTime.Empty);
		}

		void AddChargeAndAssertD3Record(CommonShipment shipment, Job job, InvoicingBase invoiceAR, bool enableDeferedRecognition, string jobStatus, string revRecognitionOption, ZDateTime expectedDate)
		{
			AccountingConfigurationRegistry.Instance.EnableDeferredRevenueRecognition.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, enableDeferedRecognition);
			if (job.JH_Status != jobStatus)
			{
				job.JH_Status = jobStatus;
			}

			var lineAR2 = TestObjectCreator.CreateInvoiceLine(invoiceAR, TestObjectCreator.AUD, 1M, 0M);
			lineAR2.AL_JH = job.PK;
			lineAR2.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.ActualDepartureDate;

			var charge3 = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC2, "Desc 2", TestObjectCreator.AUD, 0M, null, TestObjectCreator.AUD, 0M, null);
			charge3.JR_AL_ARLine = lineAR2.PK;

			AssertEquals("Before saving: JH_Status" + jobStatus, jobStatus, job.JH_Status);
			AssertEquals("Before saving: ActualDepartureDate recognition date.", ZDateTime.Empty, lineAR2.AL_ReverseDate);

			Factory.Save();

			AssertEquals("After saving: JH_Status", jobStatus, job.JH_Status);
			AssertEquals("After saving: ActualDepartureDate recognition date.", expectedDate, lineAR2.AL_ReverseDate);
		}

