			}

			AssertEquals("Before saving: JH_Status", JobHeaderStatus.Complete.Code, job.JH_Status);
			AssertEquals("Before saving: ActualDepartureDate recognition date.", ZDateTime.Empty, lineDEP.AL_ReverseDate);

			Factory.Save();

			AssertEquals("After saving: JH_Status", JobHeaderStatus.Complete.Code, job.JH_Status);
			AssertEquals("After saving: ActualDepartureDate recognition date.", shipment.JS_E_DEP, lineDEP.AL_ReverseDate);
		}

		public void TestIPostingJob_UpdateExchangeRate()
		{
			var chargeCode1 = Factory.New<AccChargeCode>();
			chargeCode1.AC_Code = "ABC";
			var provider = Factory.New<OrgHeader>();
			provider.OH_Code = "PROV1";
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			job.Creditor = provider.PK;

			var chargeGBP = job.Charges.AddNew();
			chargeGBP.JR_AC = chargeCode1.PK;
			chargeGBP.JR_OH_CostAccount = provider.PK;
			chargeGBP.JR_RX_NKCostCurrency = TestObjectCreator.GBP.RX_Code;
			chargeGBP.JR_RX_NKSellCurrency = TestObjectCreator.GBP.RX_Code;
			chargeGBP.JR_InvoiceType = "CUR";

			var postingJob = job as IPostingJob;
			postingJob.UpdateBaseExchangeRate("GBP", ExchangeRateValidLedgerEnum.AR, 1.1234m);
			postingJob.UpdateBaseExchangeRate("GBP", ExchangeRateValidLedgerEnum.AP, 1.1234m);
			AssertEquals(1.1234m, chargeGBP.JR_OSSellExRate);
			AssertEquals(1.1234m, chargeGBP.JR_OSCostExRate);

			var expectedCurrencyCode = "USD";
			Assert("Precondition: currency code in not in ex. rate collection.", !job.ExchangeRates.Cast<ExchangeRate>().Any(x => x.JF_RX_NKRateCurrency == expectedCurrencyCode));
			AssertNoExceptionThrown(() => postingJob.UpdateBaseExchangeRate(expectedCurrencyCode, ExchangeRateValidLedgerEnum.AP, 1.1234m));
		}

