		[DisableZeroExchangeRateOverriding]
		public void TestGetTodayExchangeRate()
		{
			// Arrange
			// System Exchange Rates:
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, 0.1m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, 0.2m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.IATARate, 0.3m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			SetupAccExchangeRateConfiguration(GlbCompany.CurrentCompany.AccExchangeRateConfigurations, Constants.ExchangeRateTypes.Code.BuyRate);
			SetupAccExchangeRateConfiguration(TestObjectCreator.AALSHI.CompanyData.AccAPExchangeRateConfigurations, Constants.ExchangeRateTypes.Code.SellRate);
			SetupAccExchangeRateConfiguration(TestObjectCreator.AALSHI.CompanyData.AccARExchangeRateConfigurations, Constants.ExchangeRateTypes.Code.IATARate);

			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment, false);
			job.PlugInData = shipment;

			// Act & Assert
			AssertEquals(0.1m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, null, ExchangeRateOrgTypeEnum.Creditor.ToLedger()));
			AssertEquals(0.1m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, null, ExchangeRateOrgTypeEnum.Debtor.ToLedger()));
			AssertEquals(0.1m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, null, ExchangeRateOrgTypeEnum.None.ToLedger()));
			AssertEquals(0.1m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, TestObjectCreator.AALSHI, ExchangeRateOrgTypeEnum.None.ToLedger()));
			AssertEquals(0.2m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, TestObjectCreator.AALSHI, ExchangeRateOrgTypeEnum.Creditor.ToLedger()));
			AssertEquals(0.3m, AccExchangeRateConfigurationRateFinder.GetTodaysExchangeRate(job.ExchangeRateConfigurationRateConsumer, TestObjectCreator.USD, TestObjectCreator.AALSHI, ExchangeRateOrgTypeEnum.Debtor.ToLedger()));
		}

