			var electronicProcessingChargeCode = globalChargeCode.ChildChargeCodes.FirstOrDefault(c => c.AC_GC == GlbCompany.CurrentCompany.PK);

			using (AccountingConfigurationRegistry.Instance.JobDeactivationConfiguration.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, JobDeactivationConfigurations.NoActiveWIPACR.Code))
			using (AccountingConfigurationRegistry.Instance.ElectronicProcessingChargeCode.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, globalChargeCode.PK.ToGuid()))
			{
				var jobParentWithSpecialJRJAndReversedWipAcr = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithSpecialJRJAndReversedWipAcr = new Loader(jobParentWithSpecialJRJAndReversedWipAcr).TryLoadOrCreate();

				var chargeWithElectronicProcessingChargeCode = Factory.NewWithValidTestData<JobCharge>();
				chargeWithElectronicProcessingChargeCode.JR_LocalCostAmt = 10m;
				chargeWithElectronicProcessingChargeCode.JR_JH = testJobWithSpecialJRJAndReversedWipAcr.PK;
				chargeWithElectronicProcessingChargeCode.JR_AC = electronicProcessingChargeCode.PK;

				var jobRevenueJournal = Factory.NewWithValidTestData<JobRevenueJournal>();
				jobRevenueJournal.AH_JH = testJobWithSpecialJRJAndReversedWipAcr.PK;

				var wip = Factory.NewWithValidTestData<WIP>();
				wip.AL_JH = testJobWithSpecialJRJAndReversedWipAcr.PK;
				wip.AL_ReverseDate = ZDateTime.Today;
				var acr = Factory.NewWithValidTestData<Accrual>();
				acr.AL_JH = testJobWithSpecialJRJAndReversedWipAcr.PK;
				acr.AL_ReverseDate = ZDateTime.Today;

				var jobRevenueJournalLine = Factory.NewWithValidTestData<AccTransactionLines>();
				jobRevenueJournalLine.AL_LineType = TransactionLineTypes.Revenue;
				jobRevenueJournalLine.AL_AH = jobRevenueJournal.PK;
				jobRevenueJournalLine.AL_JH = testJobWithSpecialJRJAndReversedWipAcr.PK;
				jobRevenueJournalLine.AL_AC = electronicProcessingChargeCode.PK;
				Assert("No error when job with special JRJ and reversed WIP/ACR", testJobWithSpecialJRJAndReversedWipAcr.CheckIfCanDeactiveJobInCurrentCompany().IsEmpty);

				var jobParentWithInvoice = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithInvoice = new Loader(jobParentWithInvoice).TryLoadOrCreate();
				var invoice = Factory.NewWithValidTestData<ARInvoice>();
				invoice.AH_JH = testJobWithInvoice.PK;
				AssertEquals("Should have error when transaction header posted against job", @"This job cannot be deactivated.
Invoice, Credit Note and/or Job Revenue Journal, CFX Journal have been posted against this Invoicing Job.", testJobWithInvoice.CheckIfCanDeactiveJobInCurrentCompany());

				var jobParentWithTransactionLine = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithTransactionLine = new Loader(jobParentWithTransactionLine).TryLoadOrCreate();
				var transactionLine = Factory.NewWithValidTestData<AccTransactionLines>();
				transactionLine.AL_LineType = TransactionLineTypes.Cost;
				transactionLine.AL_JH = testJobWithTransactionLine.PK;
				AssertEquals("Should have error when transaction line posted against job", @"This job cannot be deactivated.
Invoice, Credit Note and/or Job Revenue Journal, CFX Journal have been posted against this Invoicing Job.", testJobWithTransactionLine.CheckIfCanDeactiveJobInCurrentCompany());

				var jobParentWithCharge = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithCharge = new Loader(jobParentWithCharge).TryLoadOrCreate();
				var charge = Factory.NewWithValidTestData<JobCharge>();
				charge.JR_LocalCostAmt = 10m;
				charge.JR_JH = testJobWithCharge.PK;

				var jobParentWithWip = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testjobWithWip = new Loader(jobParentWithWip).TryLoadOrCreate();
				var notReversedWip = Factory.NewWithValidTestData<WIP>();
				notReversedWip.AL_JH = testjobWithWip.PK;

				var jobParentWitAcr = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithAcr = new Loader(jobParentWitAcr).TryLoadOrCreate();
				var notReversedAcr = Factory.NewWithValidTestData<Accrual>();
				notReversedAcr.AL_JH = testJobWithAcr.PK;

				using (AccountingConfigurationRegistry.Instance.EnableElectronicProcessingChargeFunctionality.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, false))
				{
					AssertEquals("Should have error when job charge saved against job", @"This job cannot be deactivated.
Please delete all charges from this Invoicing Job.", testJobWithCharge.CheckIfCanDeactiveJobInCurrentCompany());

					AssertEquals("Should have error when not reversed wip posted against job", @"This job cannot be deactivated.
Please reverse all WIPs and ACRs before deactivating the job.", testjobWithWip.CheckIfCanDeactiveJobInCurrentCompany());

					AssertEquals("Should have error when not reversed acr posted against job", @"This job cannot be deactivated.
Please reverse all WIPs and ACRs before deactivating the job.", testJobWithAcr.CheckIfCanDeactiveJobInCurrentCompany());
				}

				using (AccountingConfigurationRegistry.Instance.EnableElectronicProcessingChargeFunctionality.SetTemporaryValue(Guid.Empty, Guid.Empty, Guid.Empty, true))
				{
					var expectedMessage = @"This job cannot be deactivated.
Please delete all charges excluding system generated JRJ posted against the Electronic Processing Charge (CC1) from this Invoicing Job.
Please reverse the WIP related to the Electronic Processing Charge (CC1).";

					AssertEquals("Should have error when job charge saved against job", expectedMessage, testJobWithCharge.CheckIfCanDeactiveJobInCurrentCompany());
					AssertEquals("Should have error when not reversed wip posted against job", expectedMessage, testjobWithWip.CheckIfCanDeactiveJobInCurrentCompany());
					AssertEquals("Should have error when not reversed acr posted against job", expectedMessage, testJobWithAcr.CheckIfCanDeactiveJobInCurrentCompany());
				}

				var jobParentWithHotCheque = Factory.NewWithValidTestData<DummyJobHeaderParent>();
				var testJobWithHotCheque = new Loader(jobParentWithHotCheque).TryLoadOrCreate();
				var hotCheque = Factory.NewWithValidTestData<AccHotCheque>();
				hotCheque.AQ_JH = testJobWithHotCheque.PK;

				AssertEquals("Should have error when hot cheque posted against job", @"This job cannot be deactivated.
Hot Cheque(s) have been saved against this Invoicing Job Header.", testJobWithHotCheque.CheckIfCanDeactiveJobInCurrentCompany());
			}
		}

		public void TestPropertyMonitoredForChangesNotInSuspendedMode_ValueChanged()
		{
			var shipment = TestObjectCreator.CreateShipment("S001001", "AUSYD", "GBLON", null, true, "AIR");

			var job = new Loader(shipment).TryCreateWithoutMutexForTestOnly();

			AssertNotNull("Precondition: JH_GB is set", job.JH_GB);
			Assert("JH_GB is set from defaulting logic", !job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GBInfo.Name]);

			AssertNotNull("Precondition: JH_GE is set", job.JH_GE);
			Assert("JH_GE is set from defaulting logic", !job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GEInfo.Name]);

			using (job.GetSetJobDefaultsInProgress_ForTestOnly())
			{
				AssertEquals("Precondition: JH_OA_LocalChargesAddr is not set", ZGuid.Empty, job.JH_OA_LocalChargesAddr);
				job.JH_OA_LocalChargesAddr = TestObjectCreator.LocalClient.PK;
				AssertNotEquals("Precondition: JH_OA_LocalChargesAddr is set", ZGuid.Empty, job.JH_OA_LocalChargesAddr);
				Assert("Simulating JH_OA_LocalChargesAddr is set from defaulting logic", !job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_OA_LocalChargesAddrInfo.Name]);

				AssertEquals("Precondition: JH_OA_AgentCollectAddr is not set", ZGuid.Empty, job.JH_OA_AgentCollectAddr);
				job.JH_OA_AgentCollectAddr = TestObjectCreator.Agent.PK;
				AssertNotEquals("Precondition: JH_OA_AgentCollectAddr is set", ZGuid.Empty, job.JH_OA_AgentCollectAddr);
				Assert("Simulating JH_OA_AgentCollectAddr is set from defaulting logic", !job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_OA_AgentCollectAddrInfo.Name]);

				AssertEquals("Precondition: JH_GS_NKRepSales is not set", ZString.Empty, job.JH_GS_NKRepSales);
				job.JH_GS_NKRepSales = "SAL";
				AssertNotEquals("Precondition: JH_GS_NKRepSales is not set", ZString.Empty, job.JH_GS_NKRepSales);
				Assert("Simulating JH_GS_NKRepSales is set from defaulting logic", !job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GS_NKRepSalesInfo.Name]);
			}

			job.JH_GB = job.JH_GB;
			Assert("JH_GB is set outside of defaulting code. Hence, ChangedNotInSuspendedMode should be updated accordingly", job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GBInfo.Name]);

			job.JH_GE = job.JH_GE;
			Assert("JH_GE is set outside of defaulting code. Hence, ChangedNotInSuspendedMode should be updated accordingly", job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GEInfo.Name]);

			job.JH_OA_LocalChargesAddr = job.JH_OA_LocalChargesAddr;
			Assert("JH_OA_LocalChargesAddr is set outside of defaulting code. Hence, ChangedNotInSuspendedMode should be updated accordingly", job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_OA_LocalChargesAddrInfo.Name]);

			job.JH_OA_AgentCollectAddr = job.JH_OA_AgentCollectAddr;
			Assert("JH_OA_AgentCollectAddr is set outside of defaulting code. Hence, ChangedNotInSuspendedMode should be updated accordingly", job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_OA_AgentCollectAddrInfo.Name]);

			job.JH_GS_NKRepSales = job.JH_GS_NKRepSales;
			Assert("JH_GS_NKRepSales is set outside of defaulting code. Hence, ChangedNotInSuspendedMode should be updated accordingly", job.ChangedNotInSuspendedMode_ForTestOnly[job.JH_GS_NKRepSalesInfo.Name]);
		}

