		Job GetTestJobForSettingJobClient(OrgHeader debtor)
		{
			var consignee = TestObjectCreator.Debtor;
			consignee.CompanyData.OB_EXBillAgentChargesDirect = true;
			consignee.CompanyData.OB_RX_NKARDDefltCurrency = TestObjectCreator.LocalCurrency.RX_Code;

			var shipment = TestObjectCreator.CreateShipment(shipmentNum: "1001");
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;

			var job = TestObjectCreator.CreateJob(shipment, TestObjectCreator.LocalClient, 0m, consignee, 0m);

			var entity = job.PlugInData as IDocAddresses;
			if (entity != null)
			{
				entity.DocAddresses.AddNew(TestObjectCreator.LocalClient.MainAddress, DocAddressType.ClientRequestedBillingParty);
			}

			var charge = TestObjectCreator.CreateCharge(parentJob: job, chargeCode: TestObjectCreator.FRT, "desc", sellCurrency: TestObjectCreator.CNY, osSellAmt: 10m, debtor: debtor);
			TestObjectCreator.CreateExchangeRate(TestObjectCreator.CNY, "BUY", 2m);
			AssertEquals("PreCondition: charge has foreign sell currency", TestObjectCreator.CNY.RX_Code, charge.JR_RX_NKSellCurrency);
			AssertEquals("PreCondition: debtor of charge should be set", debtor.PK, charge.JR_OH_SellAccount);

			var exchangeRate = TestObjectCreator.SetExchangeRate(job, TestObjectCreator.CNY, 3m, debtor.PK, ExchangeRateOrgTypeEnum.Debtor);
			AssertEquals("PreCondition: job exchange rate has been added for debtor", debtor.PK, exchangeRate.JF_OH_Org);
			AssertEquals("PreCondition: job exchange buy rate is set correctly", 3m, exchangeRate.JF_BaseRate);
			AssertEquals("PreCondition: job exchange rate has foreign currency", TestObjectCreator.CNY.RX_Code, exchangeRate.JF_RX_NKRateCurrency);
			Factory.Save();
			return new BusinessObjectFactory().Load<Job>(job.PK);
		}

		void AssertNoExceptionDuringSaving(Job job, OrgHeader oldDebtor)
		{
			AssertNoExceptionThrown(job.Factory.Save);

			var charge = job.Charges[0];
			AssertEquals("Charge should retain foreign sell currency", TestObjectCreator.CNY.RX_Code, charge.JR_RX_NKSellCurrency);
			AssertEquals("Debtor of charge should be empty", ZGuid.Empty, charge.JR_OH_SellAccount);

			var jobExRate = job.ExchangeRates.OfType<ExchangeRate>().FirstOrDefault(exchangeRate => exchangeRate.JF_OH_Org == oldDebtor.PK);
			AssertNotNull(jobExRate);
			AssertEquals("Job exchange buy rate equals to the old one", 3m, jobExRate.JF_BaseRate);
			AssertEquals("Job exchange rate currency equals to the old one", TestObjectCreator.CNY.RX_Code, jobExRate.JF_RX_NKRateCurrency);
		}

