		public void TestGetAllPeerJobsThatHaveUnpostedConsolCosts()
		{
			var objectCreator = new TestObjectCreator(Factory);

			var consol1 = objectCreator.CreateConsol(consolNum: "C0001");
			var consol2 = objectCreator.CreateConsol(consolNum: "C0002");
			var consol3 = objectCreator.CreateConsol(consolNum: "C0003");

			var shipment1 = objectCreator.CreateShipment("S001");
			var shipment2 = objectCreator.CreateShipment("S002");
			var shipment3 = objectCreator.CreateShipment("S003");
			var shipment4 = objectCreator.CreateShipment("S004");
			var shipment5 = objectCreator.CreateShipment("S005");

			var job1 = TestObjectCreator.CreateJob(shipment1);
			var job2 = TestObjectCreator.CreateJob(shipment2);
			var job3 = TestObjectCreator.CreateJob(shipment3);
			var job4 = TestObjectCreator.CreateJob(shipment4);
			var job5 = TestObjectCreator.CreateJob(shipment5);

			consol1.Shipments.Add(shipment1);
			consol1.Shipments.Add(shipment2);
			consol1.Shipments.Add(shipment3);

			var c1c1 = objectCreator.CreateConsolCost(consol1, objectCreator.CC1, oSCostAmount: 300M, creditor: objectCreator.Creditor1, apportionToRelatedShipments: true);
			c1c1.E6_ApportionmentMethod = AllocationMethod.Shipment;
			SetIsUsedForApportionmentForJob(c1c1, shipment1, isUsed: true);
			SetIsUsedForApportionmentForJob(c1c1, shipment2, isUsed: true);
			SetIsUsedForApportionmentForJob(c1c1, shipment3, isUsed: false);

			var c1c2 = objectCreator.CreateConsolCost(consol1, objectCreator.CC2, oSCostAmount: 300M, creditor: objectCreator.Creditor1, apportionToRelatedShipments: true);
			c1c2.E6_ApportionmentMethod = AllocationMethod.Shipment;
			SetIsUsedForApportionmentForJob(c1c2, shipment1, isUsed: false);
			SetIsUsedForApportionmentForJob(c1c2, shipment2, isUsed: true);
			SetIsUsedForApportionmentForJob(c1c2, shipment3, isUsed: true);

			consol2.Shipments.Add(shipment3);
			consol2.Shipments.Add(shipment4);
			var c2c1 = objectCreator.CreateConsolCost(consol2, objectCreator.CC1, oSCostAmount: 300M, creditor: objectCreator.Creditor1, apportionToRelatedShipments: true);

			consol3.Shipments.Add(shipment4);
			consol3.Shipments.Add(shipment5);
			var c3c1 = objectCreator.CreateConsolCost(consol3, objectCreator.CC1, oSCostAmount: 400M, creditor: objectCreator.Creditor1, apportionToRelatedShipments: true);

			Factory.Save();

			var peerJobsPKs = new ZGuid[] { job1.PK, job2.PK, job3.PK, job4.PK, job5.PK };
			AssertPeerJobs(job1);
			AssertPeerJobs(job2);
			AssertPeerJobs(job3);
			AssertPeerJobs(job4);
			AssertPeerJobs(job5);

			void AssertPeerJobs(Job job)
			{
				var peerJobs = job.GetAllPeerJobsThatHaveUnpostedConsolCosts();
				var expectedeerJobPKs = peerJobsPKs.Except(new[] { job.PK });
				AssertContainsExactElementsInAnyOrder(expectedeerJobPKs, peerJobs.Select(p => p.PK));
			}

			void SetIsUsedForApportionmentForJob(JobConsolCost cost, ForwardingShipment shipment, bool isUsed)
			{
				foreach (ApportionSplitCharge charge in cost.ApportionmentCharges)
				{
					if (charge.Job.JH_ParentID == shipment.PK)
					{
						charge.JR_IsUsedForApportionment = isUsed;
					}
				}
			}
		}

