		#region UpdateJobReadOnlyStatus

		public void TestUpdateJobReadOnlyStatus_WhenJobIsClosed_ChildCollectionsShouldBeReadOnly()
		{
			var job = Factory.NewJobForTesting<Job>();
			job.SetDefaultsForJob(); // => internally calls UpdateJobReadOnlyStatus

			AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

			job.JH_Status = JobHeaderStatus.Closed.Code; // => internally calls UpdateJobReadOnlyStatus
			AssertJobAndCollectionsReadOnlyStatuses(job, false, true);
		}

		public void TestUpdateJobReadOnlyStatus_WhenJobIsComplete_ChildCollectionsShouldBeReadOnly()
		{
			var job = Factory.NewJobForTesting<Job>();

			var originSecurity = Env.Security.ModifyChargesOfCompleteJobs.IsAllowed;
			try
			{
				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = true;
				AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

				job.JH_Status = JobHeaderStatus.Complete.Code;
				AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = false;
				job.JH_Status = JobHeaderStatus.Working.Code;
				AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

				job.JH_Status = JobHeaderStatus.Complete.Code;
				AssertJobAndCollectionsReadOnlyStatuses(job, false, true);
			}
			finally
			{
				Env.Security.ModifyChargesOfCompleteJobs.IsAllowed = originSecurity;
			}
		}

		public void TestUpdateJobReadOnlyStatus_JobReadOnlyStatusSwitches_InDifferentOrders()
		{
			var job = Factory.NewJobForTesting<Job>();
			AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

			job.SetDefaultsForJob();
			AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

			job.SetReadOnlyIncludingChildren(true);
			AssertJobAndCollectionsReadOnlyStatuses(job, true, true);

			job.SetReadOnlyIncludingChildren(false);
			AssertJobAndCollectionsReadOnlyStatuses(job, false, false);

			job.JH_Status = JobHeaderStatus.Closed.Code;
			AssertJobAndCollectionsReadOnlyStatuses(job, false, true);

			job.SetReadOnlyIncludingChildren(true);
			AssertJobAndCollectionsReadOnlyStatuses(job, true, true);
		}

		void AssertJobAndCollectionsReadOnlyStatuses(Job job, bool expectedJobReadOnlyStatus, bool expectedChildCollectionsReadOnlyStatus)
		{
			CombineAssertions(() =>
			{
				AssertEquals("Job ReadOnly status", expectedJobReadOnlyStatus, job.ReadOnly);
				AssertEquals("JobCharge collection ReadOnly status", expectedChildCollectionsReadOnlyStatus, job.Charges.ReadOnly);
				AssertEquals("ExchangeRates ReadOnly status", expectedChildCollectionsReadOnlyStatus, job.ExchangeRates.ReadOnly);
				AssertEquals("LocalZAddressWithContact ReadOnly status", expectedChildCollectionsReadOnlyStatus, job.LocalZAddressWithContact.ReadOnly);
				AssertEquals("JH_OA_AgentCollectAddr_ZAddress ReadOnly status", expectedChildCollectionsReadOnlyStatus, job.JH_OA_AgentCollectAddr_ZAddress.ReadOnly);
			});
		}

