		#region IsAllowedToViewConsolCostsFromOtherBranchesOrDepartments

		public void TestIsAllowedToViewConsolCostsFromOtherBranchesOrDepartments_PlugInDataIsNotNull()
		{
			var user = Factory.NewWithValidTestData<GlbStaff>();
			user.GS_IsController = false;
			Factory.Save();

			using (Env.SetTemporaryUserContext(user.GS_LoginName, Env.CurrentBranchPK, Env.CurrentDepartmentPK))
			{
				var securityFactory = new BusinessObjectFactory();
				var security = new UserLoginController().GetSecurityForUser(Env.CurrentUser.LoginName, Env.CurrentBranch.PK, Env.CurrentDepartment.PK);
				security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainConsolJobInvoicing, SecurityCore.AllowViewCosts).IsAllowed = true;

				var invoicingSecurity = securityFactory.New<GlbSecurity>();
				invoicingSecurity.GU_GB = Env.CurrentBranch.PK;
				invoicingSecurity.GU_GE = Env.CurrentDepartment.PK;
				invoicingSecurity.GU_GS = Env.CurrentUser.PK;
				invoicingSecurity.GU_SecurityRight = security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainConsolJobInvoicing, SecurityCore.AllowViewCosts).Code;
				invoicingSecurity.GU_SecurityItemIsAllowed = true;
				securityFactory.Save();

				var job = CreateJobWithConsolShipment();
				Factory.Save();

				var reloadedJob = new BusinessObjectFactory().Load<Job>(job.PK);
				AssertNull("PlugInData is null when you load job in new factory", reloadedJob.PlugInData);
				Assert(reloadedJob.IsAllowedToViewConsolCostsFromOtherBranchesOrDepartments);
				AssertNotNull("When checking the secuity point, PlugInData must be initialized", reloadedJob.PlugInData);

				security.GetInvoicingSecurityCheckPoint(Env.Security.MaintainConsolJobInvoicing, SecurityCore.AllowViewCosts).IsAllowed = false;
				securityFactory.Save();

				reloadedJob = new BusinessObjectFactory().Load<Job>(job.PK);
				AssertNull("PlugInData is null when you load job in new factory", reloadedJob.PlugInData);
				Assert(!reloadedJob.IsAllowedToViewConsolCostsFromOtherBranchesOrDepartments);
				AssertNotNull("When checking the secuity point, PlugInData must be initialized", reloadedJob.PlugInData);
			}
		}

		public void TestIsAllowedToViewConsolCostsFromOtherBranchesOrDepartments_ExceptionIsReportedWhenPlugInDataCouldNotBeInitialized()
		{
			var job = CreateJobWithConsolShipment();
			Factory.Save();

			var expectedErrorMessage = ZString.Format(@"Parent of Job {1} is null.
Job Details: PK = {0}, Job Number = {1}, Parent ID = {2}, Parent Table Code = {3}, Parent Job = {4}, Job Status = {5}, IsInDatabase = {6}, BranchPK = {7}, DepartmentPK = {8}, CompanyPK = {9}"
, job.PK, job.JH_JobNum, job.JH_ParentID, job.JH_ParentTableCode, job.JH_JH_ParentJob, job.JH_Status, job.IsInDatabase.ToYesNoString(), job.JH_GB, job.JH_GE, job.JH_GC);

			((IDbConnected)Factory).Connection.ExecuteNonQuery("DELETE from dbo.JobShipment WHERE JS_PK = " + job.JH_ParentID.ToSqlGuid());
			AssertNull(new BusinessObjectFactory().Load<ForwardingShipment>(job.JH_ParentID));

			var reloadedJob = new BusinessObjectFactory().Load<Job>(job.PK);

			ErrorReporter.Clear();

			var result = reloadedJob.IsAllowedToViewConsolCostsFromOtherBranchesOrDepartments;

			AssertNull(reloadedJob.PlugInData);
			AssertEquals("PlugInDataIsNull", ErrorReporter.LastKeyReported);
			AssertEquals(expectedErrorMessage, ErrorReporter.LastMessageReported);

			ErrorReporter.Clear();
		}

