		public void TestResetTaxBranch()
		{
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();
			var boolList = new[] { false, true };

			foreach (var isGSTRegistered in boolList)
			{
				foreach (var enableTaxBranchReporting in boolList)
				{
					GlbCompany.CurrentCompany.GC_IsGSTRegistered = isGSTRegistered;
					AccountingMasterFilesRegistry.Instance.EnableTaxBranchReporting.SetValue(Guid.Empty, Guid.Empty, Guid.Empty, enableTaxBranchReporting);

					job.SetDefaultValueForTaxBranch();

					if (isGSTRegistered && enableTaxBranchReporting)
					{
						AssertEquals("When TaxBranch is enabled, JH_GB_TaxBranche should be reset to current branch.", GlbBranch.CurrentBranch.PK, job.JH_GB_TaxBranch);
					}
					else
					{
						AssertEquals("When TaxBranch is disabled, JH_GB_TaxBranch should be reset to empty.", ZGuid.Empty, job.JH_GB_TaxBranch);
					}
				}
			}
		}

