		public void TestJobIsValidatedInDifferentCompany_JobCreatedInDifferent_ValidatedInCurrentCompany()
		{
			CriticalValidationInfoCollectorService.GetOrCreateService(Factory).GetInfo(ZGuid.NewZGuid(), CriticalValidationInfoCollectorServiceKeyType.JobRegisteredAsEditableChild);

			Job job;
			var nonCurrentCompanyBranch = TestObjectCreator.NonCurrentCompanyBranch;
			using (Env.SetTemporaryUserContext(Env.CurrentUser.LoginName, nonCurrentCompanyBranch.PK.ToGuid(), GlbDepartment.CurrentDepartment.PK.ToGuid()))
			{
				job = TestObjectCreator.CreateJobHeader();
				var charge = job.Charges.AddNew();
				charge.JR_AC = Env.Registry.FreightChargeCode;
				job.Factory.Save();
			}

			var newFactory = new BusinessObjectFactory();
			var jobInCurrentCompany = newFactory.Load<Job>(job.PK);

			Assert(!jobInCurrentCompany.HasChanges);
			jobInCurrentCompany.RunPreSaveValidation();

			Assert("job should have no error messages", !jobInCurrentCompany.HasErrors);
			Assert("job charge should have no error messages", !jobInCurrentCompany.Charges[0].HasErrors);

			AssertEquals("No exception should be thrown.", 0, ExceptionReporterTestListener.Instance.Count);
			Assert("Charges should be registered child of job", jobInCurrentCompany.IsRegisteredEditableChildObject(jobInCurrentCompany.Charges));
		}

