		public void TestCopyJobBillingInformation_BillingExchangeRatesShouldBeCreated_WithARAccExchangeRateConfigurationOverride()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.BuyRate, 0.1m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.SellRate, 0.2m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			creator.CreateExchangeRate(TestObjectCreator.USD, Constants.ExchangeRateTypes.Code.IATARate, 0.3m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment, false);
			job.PlugInData = shipment;

			var charge = job.Charges.AddNew();
			charge.JR_AC = TestObjectCreator.FRT.PK;
			charge.JR_RX_NKSellCurrency = TestObjectCreator.USD.Code;
			var debtorPK = TestObjectCreator.AALSHI.PK;
			charge.JR_OH_SellAccount = debtorPK;

			var billingExchangeRate = (ExchangeRate)job.ExchangeRates.Single();
			// BuyRate is picked by default
			AssertExchangeRate(billingExchangeRate, "USD", ExchangeRateOrgTypeEnum.Debtor, debtorPK, 0.1m);
			// Let's change BaseRate to test that the value is not copied
			billingExchangeRate.JF_BaseRate = 0.15;

			Factory.Save();

			var newShipment = TestObjectCreator.CreateShipment("S00002", "AUBNE", "JPTYO");
			var newJob = TestObjectCreator.CreateJob(newShipment, false);
			newJob.PlugInData = newShipment;
			CopyJobBillingInformation(newJob, shipment);
			var newBillingExchangeRate = (ExchangeRate)newJob.ExchangeRates.Single();
			// BuyRate should be picked instead of being copied from the source job
			AssertExchangeRate(newBillingExchangeRate, "USD", ExchangeRateOrgTypeEnum.Debtor, debtorPK, 0.1m, isTransformed: true);

			newJob.ExchangeRates.RemoveAndDeleteAll();
			// We want to force SellRate to be picked via AccARExchangeRateConfigurations
			SetupAccExchangeRateConfiguration(TestObjectCreator.AALSHI.CompanyData.AccARExchangeRateConfigurations, Constants.ExchangeRateTypes.Code.SellRate);
			CopyJobBillingInformation(newJob, shipment);
			newBillingExchangeRate = (ExchangeRate)newJob.ExchangeRates.Single();
			AssertExchangeRate(newBillingExchangeRate, "USD", ExchangeRateOrgTypeEnum.Debtor, debtorPK, 0.2m, isTransformed: true);
		}

