		public void TestCopyJobBillingInformation_BillingExchangeRatesShouldBeCreatedWithCFXUpliftsOverrides()
		{
			ExchangeRateReader.GetReaderInstance().ClearCache();
			var rateFactory = new BusinessObjectFactory();
			var creator = new TestObjectCreator(rateFactory);
			creator.CreateExchangeRate(TestObjectCreator.USD, ExchangeRateTypes.Code.BuyRate, 0.1m, ZDateTime.Today.AddDays(-2), ZDateTime.Today.AddDays(2));
			rateFactory.Save();

			var currentBranch = Factory.Load<GlbBranch>(Env.CurrentBranchPK);
			var branchCFXConfigurations = currentBranch.AccCFXConfigurations;
			branchCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 10m, 15m);

			var shipment = TestObjectCreator.CreateShipment("S00001", "AUBNE", "JPTYO");
			var job = TestObjectCreator.CreateJob(shipment, false);
			job.PlugInData = shipment;

			var charge = job.Charges.AddNew();
			charge.JR_AC = TestObjectCreator.FRT.PK;
			charge.JR_RX_NKSellCurrency = TestObjectCreator.USD.Code;
			charge.JR_OH_SellAccount = TestObjectCreator.AALSHI.PK;

			var billingExchangeRate = (ExchangeRate)job.ExchangeRates.Single();
			AssertEquals(10m, billingExchangeRate.JF_CFXPercent);
			AssertEquals(15m, billingExchangeRate.JF_CFXMinimum);

			branchCFXConfigurations.SetUplifts("ALL", "ALL", "ALL", 12m, 18m);
			Factory.Save();

			var newShipment = TestObjectCreator.CreateShipment("S00002", "AUBNE", "JPTYO");
			var newJob = TestObjectCreator.CreateJob(newShipment, false);
			newJob.PlugInData = newShipment;
			CopyJobBillingInformation(newJob, shipment);
			var newBillingExchangeRate = (ExchangeRate)newJob.ExchangeRates.Single();
			// CFX config should be copied from the source job instead for be picked from branch level
			AssertEquals(10m, newBillingExchangeRate.JF_CFXPercent);
			AssertEquals(15m, newBillingExchangeRate.JF_CFXMinimum);

			var companyCFXConfiguration = TestObjectCreator.AALSHI.CompanyData.AccCFXConfigurations;
			companyCFXConfiguration.SetUplifts("ALL", "ALL", "ALL", 8m, 11m);
			newJob.ExchangeRates.RemoveAndDeleteAll();
			CopyJobBillingInformation(newJob, shipment);
			newBillingExchangeRate = (ExchangeRate)newJob.ExchangeRates.Single();
			// CFX config should be copied from the source job instead of overriden by company level
			AssertEquals(10m, newBillingExchangeRate.JF_CFXPercent);
			AssertEquals(15m, newBillingExchangeRate.JF_CFXMinimum);
		}

