		[TestDate(2024, 01, 01, 15, 15, 15)]
		public void TestUpdateInvoiceNumberAndDateForCustomsCharge()
		{
			var helper = new TestHelper(Factory);
			var invoiceDate = ZDateTime.Now;
			#region Setup

			OrgHeader consignee = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader consignor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader debtor = Factory.NewWithValidTestData<OrgHeader>();
			OrgHeader overrideDebtor = Factory.NewWithValidTestData<OrgHeader>();

			Factory.Save();

			ForwardingShipment shipment = Factory.New<ForwardingShipment>();
			shipment.ConsigneeDocumentaryAddress.OrganisationPK = consignee.PK;
			shipment.ConsignorDocumentaryAddress.OrganisationPK = consignor.PK;
			TestJob.LocalChargesPK = debtor.PK;

			TestObjectCreator.Job1.PlugInData = shipment;

			#endregion

			AutoRateInfo info = new AutoRateInfo(Factory);
			info.ChargeCode = DisbursementChargeCode;
			info.Currency = "EUR";
			info.DebtorOverridePK = overrideDebtor.PK;
			info.InvoiceNumber = "ATC400000400520225875";

			TestObjectCreator.Job1.Charges.RemoveAndDeleteAll();

			var newCharge = TestObjectCreator.Job1.Charges.AddNew();
			newCharge.JR_AC = DisbursementChargeCode.PK;
			AssertEquals("Precondition", false, newCharge.IsCustomsCharge);
			newCharge.JR_AC = helper.ChargeCodes["CUSDSB"].PK;
			AssertEquals("Precondition", true, newCharge.IsCustomsCharge);
			CombineAssertions(() =>
			{
				//default registry value
				TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Cost);
				AssertEquals("InvoiceDate is empty for default registry value", ZDateTime.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
				AssertEquals("InvoiceNumber is empty for default registry value", ZString.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);
				TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);
				AssertEquals("InvoiceDate is empty for default registry value", ZDateTime.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
				AssertEquals("InvoiceNumber is empty for default registry value", ZString.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);

				//registry value = 'FUL'
				using (RatingDataRegistry.Instance.PopulateEntryRefAsInvoiceNo.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, RateEntryReferenceTypeList.Codes.FullReference))
				{
					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Cost);
					AssertEquals("InvoiceDate is not empty for registry value 'FUL'", invoiceDate, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is not empty and full lenght for registry value 'FUL'", "ATC400000400520225875", TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);
					newCharge.JR_APInvoiceNum = ZString.Empty;
					newCharge.JR_APInvoiceDate = ZDateTime.Empty;
					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);
					AssertEquals("InvoiceDate is not empty for registry value 'FUL'", invoiceDate, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is not empty and full lenght for registry value 'FUL'", "ATC400000400520225875", TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);

					newCharge.JR_APInvoiceNum = ZString.Empty;
					newCharge.JR_APInvoiceDate = ZDateTime.Empty;
					newCharge.JR_AC = DisbursementChargeCode.PK;
					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);

					AssertEquals("InvoiceDate is empty for registry value 'FUL' when not IsCustomsCharge", ZDateTime.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is empty and full lenght for registry value 'FUL'  when not IsCustomsCharge", ZString.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);
				}

				//registry value = 'SHT'
				using (RatingDataRegistry.Instance.PopulateEntryRefAsInvoiceNo.SetTemporaryValue(GlbCompany.CurrentCompany.PK.ToGuid(), Guid.Empty, Guid.Empty, RateEntryReferenceTypeList.Codes.ShortenedReference))
				{
					newCharge.JR_AC = helper.ChargeCodes["CUSDSB"].PK;
					newCharge.JR_APInvoiceDate = ZDateTime.Empty;

					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Cost);
					AssertEquals("InvoiceDate is not empty for registry value 'SHT'", invoiceDate, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is not empty and shortened for registry value 'SHT'", "400000400520225875", TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);

					newCharge.JR_APInvoiceNum = ZString.Empty;
					newCharge.JR_APInvoiceDate = ZDateTime.Empty;

					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);
					AssertEquals("InvoiceDate is not empty for registry value 'SHT'", invoiceDate, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is not empty and shortened for registry value 'SHT'", "400000400520225875", TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);

					newCharge.JR_APInvoiceNum = ZString.Empty;
					newCharge.JR_APInvoiceDate = ZDateTime.Empty;
					newCharge.JR_AC = DisbursementChargeCode.PK;
					TestObjectCreator.Job1.SetAmountsOnCharge(newCharge, info, CostSell.Revenue);
					AssertEquals("InvoiceDate is empty for registry value 'SHT' when not IsCustomsCharge", ZDateTime.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceDate);
					AssertEquals("InvoiceNumber is empty and shortened for registry value 'SHT' when not IsCustomsCharge", ZString.Empty, TestObjectCreator.Job1.Charges[0].JR_APInvoiceNum);
				}
			});
		}

		public void TestValidationWhenStatusChangedTwiceInTheSameSessionAndCheckTheTriggeringofRevenueRecognitionValidation()
		{
			var job = Factory.NewJobForTesting<Job>();
			foreach (CodeDescriptionPair jobStatus in job.JobStatusList)
			{
				bool shouldTriggerRevenueRecognitionValidation = jobStatus.Code == JobHeaderStatus.Closed.Code || jobStatus.Code == JobHeaderStatus.Complete.Code || jobStatus.Code == JobHeaderStatus.JobReadyForFinancialClosure.Code || jobStatus.Code == JobHeaderStatus.JobInvoiced.Code;
				AssertValidationWhenStatusChangedTwiceInTheSameSession(jobStatus.Code, shouldTriggerRevenueRecognitionValidation);
			}
		}

		void AssertValidationWhenStatusChangedTwiceInTheSameSession(string firstStatus, bool validationShouldTrigger)
		{
			var shipment = Factory.NewWithValidTestData<CommonShipment>();

			var job = new Loader(Factory, shipment).TryCreateWithoutMutexForTestOnly();
			job.JH_GE = GlbDepartment.CurrentDepartment.PK;
			job.JH_GB = GlbBranch.CurrentBranch.PK;
			job.JH_OA_LocalChargesAddr = TestObjectCreator.LocalClient.MainAddress.PK;
			var invoice = TestObjectCreator.CreateInvoiceWithLine(typeof(APInvoice), "1234", TestObjectCreator.AUD, 1M, 100M, 0M, 100M, 0M, TestObjectCreator.AALSHI, TestObjectCreator.CC1.PK);
			var line = invoice.Lines[0];
			line.AL_JH = job.PK;
			line.AL_RevRecognitionType = RevenueRecognitionLookups.RecognitionDateOptionCodes.PostDateOfFirstARTransaction;
			var charge = TestObjectCreator.CreateCharge(job, TestObjectCreator.CC1, "Desc", TestObjectCreator.AUD, 100M, null, TestObjectCreator.AUD, 100M, null);
			charge.JR_AL_APLine = line.PK;
			line.AL_AT = ZGuid.Empty;
			line.AL_OSAmount = line.AL_LineAmount = -charge.JR_OSCostAmt;

			string errMsg = null;
			job.OnCannotChangeStatusUserMessage += (object sender, UserMessageEventArgs e) => { errMsg = e.Message; };

			job.JH_Status = firstStatus;
			AssertNull(errMsg);

			if (firstStatus != JobHeaderStatus.Working.Code)
			{
				job.JH_Status = JobHeaderStatus.Working.Code;
			}
			else
			{
				job.JH_Status = JobHeaderStatus.CustomsProcessActive.Code;
			}

			if (validationShouldTrigger)
			{
				AssertEquals(string.Format(@"You have changed the status of this job to '{0}' before saving. This will trigger revenue recognition.
If you did not intend to recognize revenue, please close the job without saving.
If you intended to recognize revenue, please change the status back to '{0}' and save.", firstStatus), errMsg);
			}
			else
			{
				AssertNull("Expect no error message shown when the status doesn't trigger revenue recognition", errMsg);
			}
		}

