		void AssertPreCondition(decimal amount)
		{
			AssertEquals("Charge Count", 1, TestJob.Charges.Count);
			AssertEquals("Local Sell Amount", amount, TestJob.Charges[0].JR_LocalSellAmt);
			AssertEquals("Local Cost Amount", amount, TestJob.Charges[0].JR_LocalCostAmt);
			AssertEquals("OS Sell Amount", amount, TestJob.Charges[0].JR_OSSellAmt);
			AssertEquals("OS Cost Amount", amount, TestJob.Charges[0].JR_OSCostAmt);
			AssertEquals("Charge Description", "Original DSB Charge", TestJob.Charges[0].JR_Desc);
		}

		void AssertExchangeRate(string message, ExchangeRatesCollection exchangeRates, RefCurrency currency, ZDecimal exchangeRate)
		{
			AssertEquals(message + ": collection should contain 1 item", 1, exchangeRates.Count);
			AssertEquals(message + ": currency", currency.RX_Code, exchangeRates[0].JF_RX_NKRateCurrency);
			AssertEquals(message + ": exchange Rate", exchangeRate, exchangeRates[0].JF_SellRate);
		}

		AutoRateInfoCollection GetRateInfoCollection(decimal amount, AccChargeCode dSBCharge)
		{
			var rates = new AutoRateInfoCollection(Factory);
			var rateInfo = rates.AddNew(dSBCharge, AUD.RX_Code, amount);
			rateInfo.InvoiceLineDescription = dSBCharge.AC_Desc;
			rateInfo.AdditionalInvoiceLineDescription = "Additional Description";

			return rates;
		}

		void SetDSBChargeLineOnJob(AccTransactionLines line, AccChargeCode dSBCharge, decimal existingChargeAmount, string operationalJobCode)
		{
			var existingDSBCharge = TestJob.Charges.AddNew();

			if (line != null)
			{
				if (line.AL_LineType == TransactionLineTypes.Cost)
				{
					existingDSBCharge.JR_AL_APLine = line.PK;
				}
				else if (line.AL_LineType == TransactionLineTypes.Revenue)
				{
					existingDSBCharge.JR_AL_ARLine = line.PK;
				}
			}

			existingDSBCharge.JR_AC = dSBCharge.PK;
			existingDSBCharge.JR_OSSellAmt = existingChargeAmount;
			existingDSBCharge.JR_OSCostAmt = existingChargeAmount;
			existingDSBCharge.JR_OSCostExRate = 1m;
			existingDSBCharge.JR_OSSellExRate = 1m;
			existingDSBCharge.JR_Desc = "Original DSB Charge";
			existingDSBCharge.JR_CostRatingOverride = false;
			existingDSBCharge.JR_SellRatingOverride = false;

			var paymentBases = new[] { TestObjectCreator.CreatePaymentBasis(existingChargeAmount, operationalJobCode) };
			existingDSBCharge.AddPaymentBases(paymentBases, true);
			existingDSBCharge.AddPaymentBases(paymentBases, false);
		}

		AccChargeCode fDSBCharge;
		AccChargeCode DSBCharge
		{
			get
			{
				if (fDSBCharge == null)
				{
					fDSBCharge = Factory.New<AccChargeCode>();
					fDSBCharge.AC_ChargeType = Core.Constants.ChargeType.Disbursement;
					fDSBCharge.AC_Code = "ZUB11";
					fDSBCharge.AC_Desc = "RAKHSH CHARGE";
				}
				return fDSBCharge;
			}
		}

		AccTransactionLines GetTransactionLine(string lineType)
		{
			AccTransactionLines costLine;
			if (lineType == ZArchitecture.Core.TransactionLineTypes.Cost)
			{
				costLine = Factory.NewWithValidTestData<APInvoice>().Lines.AddNew();
			}
			else
			{
				costLine = Factory.NewWithValidTestData<ARInvoice>().Lines.AddNew();
			}

			costLine.AL_GE = GlbDepartment.CurrentDepartment.PK;
			costLine.AL_GB = GlbBranch.CurrentBranch.PK;
			costLine.AL_LineType = lineType;
			costLine.AL_AG = TestObjectCreator.GLHeader1.PK;
			return costLine;
		}

