		public void TestOnJobDeleted()
		{
			var job = Factory.NewJobWithValidTestDataForTesting<Job>();

			job.OnJobDeleted += new EventHandler(Job_OnDeleted);

			var jobIsDeleted = false;

			Assert("Predition", !jobIsDeleted);

			job.Delete();

			Assert("Predition", jobIsDeleted);

			void Job_OnDeleted(object sender, EventArgs e)
			{
				jobIsDeleted = true;
			}
		}

