			config.JCE_JobType = JobTypeALL;
			config.JCE_ServiceDirection = JobTypeALL;
			config.JCE_TransportMode = JobTypeALL;
			config.GetCurrencyConfig(ZString.Empty, ZDate.Empty).JCT_ExRateType = exRateType;
		}

		class TestJobClass : Job
		{
			public TestJobClass(BusinessObjectFactory factory, DataRow row)
				: base(factory, row)
			{
				this.UpdateExchangeRateAdd = false;
				this.UpdateExchangeRateRemove = false;
			}

			protected override void RefreshBindingTotalFields()
			{
				base.RefreshBindingTotalFields();
				RefreshBindingTotalFieldsCalled = true;
			}

			public bool RefreshBindingTotalFieldsCalled;

			public bool IsSetReopenUserCalled { get; set; }
			protected override void SetReopenedUser()
			{
				IsSetReopenUserCalled = true;
				base.SetReopenedUser();
			}

			public bool UpdateExchangeRateAdd { get; set; }

			public bool UpdateExchangeRateRemove { get; set; }

			protected override void UpdateExchangeRate(ExchangeRate exchangeRate, bool updateEmptyExchangeRates)
			{
				if (UpdateExchangeRateAdd)
				{
					var refCurrency = Factory.LoadFromNaturalKey<RefCurrency>(RefCurrencySchema.RX_Code, "TWD");
					AddCurrency(refCurrency, ExchangeRateValidLedgerEnum.AR);
				}
				else if (UpdateExchangeRateRemove)
				{
					ExchangeRates.Remove(ExchangeRates[0]);
				}
				base.UpdateExchangeRate(exchangeRate, updateEmptyExchangeRates);
			}
		}

